fn install_host_boundary(engine: &mut lumen::Engine) {
    install_agent_host_hooks(engine);
    for &(name, len, host_fn) in LUMEN_HOST_FUNCTIONS {
        engine.define_global(name, len, host_fn);
    }
}

/// The Agent-wide half of the host boundary: HostState tracing and the
/// settings-object job hooks. It installs nothing in any Realm.
fn install_agent_host_hooks(engine: &mut lumen::Engine) {
    engine.ctx().op_state().register_gc::<HostState>();
    debug_assert!(lumen_registry_matches_canonical_boundary());
    engine.set_host_job_context_hooks(host_enter_job_context, host_leave_job_context);
    engine.set_job_callback_script_caller_capture(true);
}

fn host_image_data_slots(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    // Called only while installing the prelude, which immediately deletes this global hook.
    // The first Realm supplies a pristine native WeakMap; later Realms reuse that private map.
    let candidate = args.first().cloned().unwrap_or(Value::Undefined);
    Ok(ctx
        .host_mut::<HostState>()
        .expect("ImageData bindings require a HostState")
        .image_data_slots
        .get_or_insert(candidate)
        .clone())
}

fn host_wasm_module_binding(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    // Private internal slots are shared across same-Agent Realms, not author properties.
    let candidate = args.first().cloned().unwrap_or(Value::Undefined);
    let state = ctx
        .host_mut::<HostState>()
        .expect("Wasm requires HostState");
    let slots = state.wasm_module_slots.get_or_insert(candidate).clone();
    let cluster = Value::from_string(state.agent_cluster.to_string());
    Ok(ctx.make_array(vec![slots, cluster]))
}

/// CSSOM View client-window origin. All Window Realms in this page share the
/// native window, not the origin of their individual iframe viewport.
fn host_window_screen_coordinate(
    ctx: &mut Ctx,
    _this: Value,
    args: &[Value],
) -> Result<Value, Value> {
    let (x, y) = ctx
        .host_mut::<HostState>()
        .expect("Window coordinates require HostState")
        .screen_position
        .get();
    Ok(Value::Num(f64::from(
        if matches!(args.first(), Some(Value::Bool(true))) {
            y
        } else {
            x
        },
    )))
}

/// Private per-Agent Web IDL brands; values remain owned by the creating
/// environment, while borrowed getters accept same-Agent Realms.
fn host_navigator_binding(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let value = args.first().cloned().unwrap_or(Value::Undefined);
    let state = ctx
        .host_mut::<HostState>()
        .expect("Navigator requires HostState");
    Ok(state.navigator_slots.get_or_insert(value).clone())
}

/// CSSOM View/Web IDL brands shared by Window Realms, retaining the private
/// WeakMap rather than its Screen and Window keys.
fn host_screen_binding(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let value = args.first().cloned().unwrap_or(Value::Undefined);
    let state = ctx
        .host_mut::<HostState>()
        .expect("Screen requires HostState");
    Ok(state.screen_slots.get_or_insert(value).clone())
}

/// CSSOM View #resizing-viewports: the same browsing-context dimensions
/// govern layout, media queries and Window getters before resize dispatch.
/// A child navigable derives its viewport from the embedding content box;
/// only the top-level controller invokes this private resize operation.
fn host_set_viewport(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let dimensions = [0, 1].map(|index| args.get(index).and_then(Value::as_num_opt));
    if let [Some(width), Some(height)] = dimensions
        && [width, height]
            .into_iter()
            .all(|value| value.is_finite() && value >= 0. && value <= f32::MAX as f64)
    {
        let state = ctx
            .host_mut::<HostState>()
            .expect("viewport requires HostState");
        let viewport = crate::layout2::Viewport::new(width as f32, height as f32);
        state.viewport.set(viewport);
        state
            .dom
            .borrow_mut()
            .set_viewport_px(viewport.width, viewport.height);
    }
    Ok(Value::Undefined)
}

/// DOM #concept-live-range: discovery spans all this Agent's Window Realms.
/// Native weak handles have no JavaScript prototype that can root a retired Realm.
fn host_live_range_register(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let Some(range) = args
        .first()
        .and_then(|value| ctx.downgrade_object_value(value))
    else {
        return Err(ctx.make_error("TypeError", "Expected a Range object"));
    };
    ctx.host_mut::<HostState>()
        .expect("Range bindings require HostState")
        .live_ranges
        .register(range);
    Ok(Value::Undefined)
}

fn host_live_range_snapshot(ctx: &mut Ctx, _this: Value, _args: &[Value]) -> Result<Value, Value> {
    let ranges = ctx
        .host_mut::<HostState>()
        .expect("Range bindings require HostState")
        .live_ranges
        .snapshot();
    // The common no-Range DOM mutation does not allocate an empty JS array.
    Ok(if ranges.is_empty() {
        Value::Undefined
    } else {
        ctx.make_array(ranges)
    })
}

/// Bootstrap-only rendezvous for platform-private, same-Agent WeakMaps. The first Realm's
/// candidate becomes the Agent's map and later Realms reuse it, as for `__element_slots`. The
/// prelude captures this function lexically and the bootstrap deletes the global before author
/// code runs, so page script can neither obtain a map nor register a control object.
fn host_platform_slots(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let kind = host_arg_string(ctx, args, 0);
    let candidate = args.get(1).cloned().unwrap_or(Value::Undefined);
    if !matches!(candidate, Value::Obj(_)) {
        return Err(ctx.make_error("TypeError", "platform slots require a WeakMap"));
    }
    let Some(state) = ctx.host_mut::<HostState>() else {
        return Err(ctx.make_error("InvalidStateError", "missing browser host state"));
    };
    let slot = match kind.as_str() {
        "controls" => &mut state.platform_controls,
        "nodes" => &mut state.platform_nodes,
        "internals" => &mut state.platform_internals,
        _ => return Err(ctx.make_error("TypeError", "unknown platform slot")),
    };
    Ok(slot.get_or_insert(candidate).clone())
}

/// This Realm's private platform control object: the Window prelude's `trust` or the worker
/// loop. Bootstraps register it in the host-rooted `controls` WeakMap keyed by their global, so
/// it is never an author-visible property. Fails before the Realm's bootstrap has registered.
fn platform_control(ctx: &mut Ctx) -> Result<Value, Value> {
    let global = ctx.global_this();
    platform_control_of(ctx, &global)
}

fn platform_control_of(ctx: &mut Ctx, global: &Value) -> Result<Value, Value> {
    let map = ctx
        .host_mut::<HostState>()
        .and_then(|state| state.platform_controls.clone());
    match map.map(|map| ctx.weak_map_get(&map, global)).transpose()? {
        Some(control @ Value::Obj(_)) => Ok(control),
        _ => Err(ctx.make_error(
            "InvalidStateError",
            "this Realm has no platform control object",
        )),
    }
}

fn host_element_slots(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let value = args.first().cloned().unwrap_or(Value::Undefined);
    let state = ctx
        .host_mut::<HostState>()
        .expect("Element bindings require HostState");
    Ok(state.element_slots.get_or_insert(value).clone())
}

// Same-Agent pointer-event brands/list backing, without rooting event keys.
// Each Window deletes this installation hook before running author scripts.
fn host_pointer_event_slots(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let value = args.first().cloned().unwrap_or(Value::Undefined);
    let state = ctx
        .host_mut::<HostState>()
        .expect("PointerEvent bindings require HostState");
    Ok(state.pointer_event_slots.get_or_insert(value).clone())
}

// Performance entries and observers use private per-Agent weak identity slots,
// shared by Window Realms without rooting dead entry/observer keys.
fn host_performance_binding(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let value = args.first().cloned().unwrap_or(Value::Undefined);
    let Some(state) = ctx.host_mut::<HostState>() else {
        return Ok(Value::Undefined);
    };
    Ok(state.performance_slots.get_or_insert(value).clone())
}

/// Private per-Agent interface slots and Window lifecycle check. No permission
/// grant or capability is inferred from a descriptor supplied by page script.
fn host_permissions_binding(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let op = host_arg_string(ctx, args, 0);
    if op == "state" || op == "set" {
        // Permissions #get-a-permission-store-entry / #set-a-permission-store-entry. Only the
        // states a TRust request can produce are recorded; anything else is ignored.
        let entry = host_arg_string(ctx, args, 1);
        let store = ctx
            .host_mut::<HostState>()
            .expect("Permissions require HostState")
            .permission_store
            .clone();
        let mut store = store.lock().unwrap_or_else(|e| e.into_inner());
        if op == "state" {
            return Ok(store.get(&entry).map_or(Value::Undefined, |state| {
                Value::from_string(state.to_string())
            }));
        }
        if let Some((key, decision)) = entry.rsplit_once('\0') {
            let decision = match decision {
                "denied" => "denied",
                "granted" => "granted",
                _ => return Ok(Value::Undefined),
            };
            store.insert(key.to_string(), decision);
        }
        return Ok(Value::Undefined);
    }
    let value = args.get(1).cloned().unwrap_or(Value::Undefined);
    let state = ctx
        .host_mut::<HostState>()
        .expect("Permissions require HostState");
    if op == "slots" {
        return Ok(state.permission_slots.get_or_insert(value).clone());
    }
    // HTML #fully-active: Window environments are retired together with their
    // navigable subtree. A retained object does not reactivate its Document.
    // The top-level actor and independent worker agent have context zero.
    let context = value.as_num_opt().unwrap_or(0.) as u64;
    Ok(Value::Bool(
        context == 0 || state.window_realms.contains_key(&context),
    ))
}

/// Pointer Lock has one target and request queue across the page's Window Realms.
fn host_pointer_lock_state(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let candidate = args.first().cloned().unwrap_or(Value::Undefined);
    Ok(ctx
        .host_mut::<HostState>()
        .expect("Pointer Lock requires HostState")
        .pointer_lock_state
        .get_or_insert(candidate)
        .clone())
}

/// History operations may be borrowed from another Window Realm. Share the
/// receiver brand without rooting History objects, and check the receiver's
/// Document lifecycle rather than the Realm that supplied the method.
fn host_history_binding(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let op = host_arg_string(ctx, args, 0);
    let value = args.get(1).cloned().unwrap_or(Value::Undefined);
    let state = ctx
        .host_mut::<HostState>()
        .expect("History requires HostState");
    if op == "slots" {
        return Ok(state.history_slots.get_or_insert(value).clone());
    }
    if op == "traverse" {
        let delta = value.as_num_opt().unwrap_or(0.) as i32;
        let context = args.get(2).and_then(Value::as_num_opt).unwrap_or(0.) as u64;
        state.history_traversals.push((context, delta));
        return Ok(Value::Undefined);
    }
    let context = value.as_num_opt().unwrap_or(0.) as u64;
    Ok(Value::Bool(
        context == 0 || state.window_realms.contains_key(&context),
    ))
}

/// Web Audio context brands are shared by same-Agent Window Realms. Retain
/// only the WeakMap, and check the associated Document on lifecycle operations.
fn host_audio_context_binding(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let op = host_arg_string(ctx, args, 0);
    let value = args.get(1).cloned().unwrap_or(Value::Undefined);
    let state = ctx
        .host_mut::<HostState>()
        .expect("AudioContext requires HostState");
    if op == "slots" {
        return Ok(state.audio_context_slots.get_or_insert(value).clone());
    }
    if op == "active" {
        let context = value.as_num_opt().unwrap_or(0.) as u64;
        return Ok(Value::Bool(
            context == 0 || state.window_realms.contains_key(&context),
        ));
    }
    webaudio_host::binding(ctx, &op, args)
}

/// A native Window operation observes its script caller BEFORE entering the
/// self-hosted implementation in the receiver's Realm. Otherwise parent.postMessage
/// incorrectly reports the parent's origin/source for a message sent by its child.
fn host_window_message_binding(
    ctx: &mut Ctx,
    _this: Value,
    args: &[Value],
) -> Result<Value, Value> {
    let candidate = args.first().cloned().unwrap_or(Value::Undefined);
    let slots = ctx
        .host_mut::<HostState>()
        .expect("Window bindings require HostState")
        .window_message_slots
        .get_or_insert(candidate)
        .clone();
    let operation = args.get(1).cloned().unwrap_or(Value::Undefined);
    let post = ctx.new_native_fn_with_captures(
        "postMessage",
        1,
        |ctx, this, args, captures| {
            let source = ctx.script_caller_global();
            let target = if matches!(this, Value::Null | Value::Undefined) {
                ctx.global_this()
            } else {
                this
            };
            let arguments = ctx.make_array(args.to_vec());
            ctx.invoke(
                captures[0].clone(),
                Value::Undefined,
                &[target, source, arguments],
            )
        },
        vec![operation],
    );
    Ok(ctx.make_array(vec![slots, post]))
}

/// Capture Web IDL callback context at the native API boundary, BEFORE the receiver Realm's
/// self-hosted implementation is entered. In particular, otherWindow.setTimeout(boundNative)
/// must retain the registering script's incumbent, not otherWindow or the native's own Realm.
/// The operation receives (sourceGlobal, receiver, argumentsArray) privately.
fn host_callback_api(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let operation = args.first().cloned().unwrap_or(Value::Undefined);
    let name = host_arg_string(ctx, args, 1);
    let length = args.get(2).and_then(Value::as_num_opt).unwrap_or(0.) as usize;
    let entry_settings = matches!(args.get(3), Some(Value::Bool(true)));
    // Engine-owned captures participate in cycle collection. Keeping the
    // self-hosted operation only in an opaque Rust closure would root its
    // entire Realm after iframe navigation (ECMA-262 #sec-liveness).
    Ok(ctx.new_native_fn_with_captures(
        &name,
        length,
        |ctx, this, args, captures| {
            let incumbent = ctx.script_caller_global();
            let source = if matches!(captures[1], Value::Bool(true)) {
                ctx.script_entry_global()
            } else {
                incumbent.clone()
            };
            let arguments = ctx.make_array(args.to_vec());
            ctx.invoke(
                captures[0].clone(),
                Value::Undefined,
                &[source, this, arguments, incumbent],
            )
        },
        vec![operation, Value::Bool(entry_settings)],
    ))
}

/// JavaScript-driven task fallback uses the same source boundary as the native event loop.
/// This hook is captured privately and removed from the global during platform installation.
fn host_invoke_callback(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let callback = args.first().cloned().unwrap_or(Value::Undefined);
    let this = args.get(1).cloned().unwrap_or(Value::Undefined);
    let list = args.get(2).cloned().unwrap_or(Value::Undefined);
    let source = args.get(3).cloned().unwrap_or(Value::Undefined);
    let length = ctx
        .member_get(&list, "length")?
        .as_num_opt()
        .unwrap_or(f64::NAN);
    if !length.is_finite() || length < 0. || length.fract() != 0. || length > usize::MAX as f64 {
        return Err(ctx.make_error("RangeError", "invalid host callback argument list"));
    }
    let mut arguments = Vec::with_capacity(length as usize);
    for index in 0..length as usize {
        arguments.push(ctx.member_get(&list, &index.to_string())?);
    }
    ctx.with_callback_script_caller(&source, |ctx| {
        ctx.invoke_callback_entry(callback, this, &arguments)
    })
}

fn lumen_registry_matches_canonical_boundary() -> bool {
    let canonical: std::collections::HashMap<_, _> =
        crate::js::host_boundary_signatures().collect();
    let mut implemented = std::collections::HashSet::new();
    LUMEN_HOST_FUNCTIONS.iter().all(|(name, len, _)| {
        implemented.insert(*name) && canonical.get(name).copied() == Some(*len)
    })
}

fn host_dom(ctx: &mut Ctx) -> Rc<RefCell<Dom>> {
    ctx.host_mut::<HostState>()
        .expect("HostState installed before any Lumen host call")
        .dom
        .clone()
}

/// Node id from a JS argument; `None` for null, undefined, non-numbers, negatives, and stale ids.
fn host_arg_node(dom: &Dom, args: &[Value], index: usize) -> Option<usize> {
    let number = args.get(index)?.as_num_opt()?;
    let id = number as usize;
    (number.is_finite() && number >= 0.0 && number.fract() == 0.0 && dom.is_valid(id)).then_some(id)
}

/// The origin of a Window Realm's environment settings object. The top-level Window's is
/// derived (once) from its creation URL; child Window Realms record theirs when created.
fn realm_origin(state: &mut HostState, context: u64) -> url::Origin {
    realm_origin_ref(state, context).clone()
}

/// HTML #meta-referrer: apply the `<meta name=referrer>` changes the DOM recorded to their
/// Documents' policy containers, in the order they happened.
fn apply_referrer_meta_updates(state: &mut HostState) {
    let updates = state.dom.borrow_mut().take_referrer_meta_updates();
    if updates.is_empty() {
        return;
    }
    let dom = state.dom.clone();
    let dom = dom.borrow();
    for (document, policy) in updates {
        if let Some(context) = node_window_context(state, &dom, document) {
            state.referrer_policies.insert(context, policy);
        }
    }
}

/// The referrer policy of the environment `context` names (its policy container's): a
/// worker's own, or the Window Realm's Document's.
fn environment_referrer_policy(
    state: &mut HostState,
    context: u64,
) -> crate::referrer_policy::ReferrerPolicy {
    if let Some(worker) = state.worker_self.as_ref() {
        return worker.referrer_policy;
    }
    apply_referrer_meta_updates(state);
    state
        .referrer_policies
        .get(&context)
        .copied()
        .unwrap_or_default()
}

/// Fetch #determine-requests-referrer, request's referrer "client": a worker's creation URL,
/// or the Window's Document's URL (none for an opaque origin; an iframe srcdoc document's
/// container document's URL instead).
fn environment_referrer_source(state: &mut HostState, context: u64) -> Option<url::Url> {
    if state.worker_self.is_some() {
        return Some(state.base.clone());
    }
    if !realm_origin_ref(state, context).is_tuple() {
        return None;
    }
    let document_url = state
        .window_cookie_contexts
        .get(&context)
        .filter(|_| context != 0)
        .map(|(_, url, _)| url.clone());
    match document_url {
        Some(url) if url.as_str() != "about:srcdoc" => Some(url),
        _ => Some(
            state
                .window_request_urls
                .get(&context)
                .unwrap_or(&state.base)
                .clone(),
        ),
    }
}

/// The request referrer and referrer policy a script fetch passed at `index` and `index + 1`.
fn script_request_referrer(
    ctx: &mut Ctx,
    args: &[Value],
    index: usize,
) -> (
    RequestReferrer,
    Option<crate::referrer_policy::ReferrerPolicy>,
) {
    let referrer = RequestReferrer::parse(&host_arg_usv(ctx, args, index));
    let policy =
        crate::referrer_policy::ReferrerPolicy::parse(&host_arg_string(ctx, args, index + 1));
    (referrer, policy)
}

/// A request's referrer (Fetch #concept-request-referrer).
#[derive(Clone, Debug)]
enum RequestReferrer {
    Client,
    NoReferrer,
    Url(url::Url),
}

impl RequestReferrer {
    /// The JavaScript request record's value: "client", "no-referrer" or a URL.
    fn parse(value: &str) -> Self {
        match value {
            "" | "client" => Self::Client,
            "no-referrer" => Self::NoReferrer,
            other => url::Url::parse(other).map_or(Self::Client, Self::Url),
        }
    }
}

/// Fetch #main-fetch steps 7-8 for a request of the environment `context`: an empty request
/// referrer policy becomes the environment's, then #determine-requests-referrer runs.
fn determine_request_referrer(
    state: &mut HostState,
    context: u64,
    referrer: &RequestReferrer,
    request_policy: Option<crate::referrer_policy::ReferrerPolicy>,
    target: &url::Url,
) -> (Option<url::Url>, crate::referrer_policy::ReferrerPolicy) {
    let policy = match request_policy {
        Some(policy) => policy,
        None => environment_referrer_policy(state, context),
    };
    let source = match referrer {
        RequestReferrer::NoReferrer => None,
        RequestReferrer::Url(url) => Some(url.clone()),
        RequestReferrer::Client => environment_referrer_source(state, context),
    };
    (
        source.and_then(|source| policy.determine(&source, target)),
        policy,
    )
}

/// Set `request`'s `Referer` (and the referrer policy its redirects use) as
/// Fetch #main-fetch steps 7-8 determine it for the environment `context`.
fn apply_request_referrer(
    state: &mut HostState,
    context: u64,
    referrer: &RequestReferrer,
    request_policy: Option<crate::referrer_policy::ReferrerPolicy>,
    request: &mut crate::http::Request,
) {
    let (referrer, policy) =
        determine_request_referrer(state, context, referrer, request_policy, &request.url);
    crate::http::replace_referrer(request, referrer.as_ref(), policy);
}

fn realm_origin_ref(state: &mut HostState, context: u64) -> &url::Origin {
    if !state.realm_origins.contains_key(&context) {
        let origin = state
            .window_request_urls
            .get(&context)
            .unwrap_or(&state.base)
            .origin();
        state.realm_origins.insert(context, origin);
    }
    &state.realm_origins[&context]
}

/// The Window Realm whose Document contains `node`: the top-level Document belongs to context
/// zero and a navigable's Document to the newest Realm created for its container. Documents
/// outside any navigable (DOMParser, templates, createDocument) have none.
fn node_window_context(state: &HostState, dom: &Dom, node: usize) -> Option<u64> {
    let document = if matches!(dom.node(node).data, NodeData::Document) {
        node
    } else {
        dom.owner_document(node)?
    };
    if document == DOCUMENT {
        return Some(0);
    }
    let container = dom.node(document).parent?;
    state.frame_contexts.get(&container).copied()
}

/// Defense in depth for DOM host operations (HTML #same-origin-domain, applied as
/// IsPlatformObjectSameOrigin would to the node's relevant settings object): the calling
/// Window Realm may act on a node only when the node's Document is same origin-domain with it.
/// `document.domain` has no effect in TRust, so every origin's domain is null and this is the
/// same-origin check. A Realm may also administer its own navigable container element.
fn node_accessible(state: &mut HostState, dom: &Dom, caller: u64, node: usize) -> bool {
    let Some(target) = node_window_context(state, dom, node) else {
        return true;
    };
    if target == caller
        || state
            .window_cookie_contexts
            .get(&caller)
            .is_some_and(|(container, _, _)| *container == node)
    {
        return true;
    }
    realm_origin_ref(state, target);
    realm_origin_ref(state, caller);
    state.realm_origins.get(&caller) == state.realm_origins.get(&target)
}

/// Bit `i` is set when the node id at `indices[i]` names a node the calling Realm may not
/// access. A page with one Window Realm, and a worker, take the fast path.
fn inaccessible_node_arguments(
    ctx: &mut Ctx,
    operation: &str,
    args: &[Value],
    indices: &[usize],
) -> u32 {
    let caller = ctx.host_job_context();
    let Some(state) = ctx.host_mut::<HostState>() else {
        return 0;
    };
    if state.window_realms.is_empty() {
        return 0;
    }
    let handle = state.dom.clone();
    let Ok(dom) = handle.try_borrow() else {
        return 0;
    };
    let mut denied = 0;
    for (bit, &index) in indices.iter().enumerate() {
        if let Some(node) = host_arg_node(&dom, args, index)
            && !node_accessible(state, &dom, caller, node)
        {
            if std::env::var_os("TRUST_TRACE_NODE_ACCESS").is_some() {
                eprintln!("[node-access] {operation}: context {caller} denied node {node}");
            }
            denied |= 1 << bit;
        }
    }
    denied
}

/// How a guarded DOM host operation treats a node the calling Realm may not access.
#[derive(Clone, Copy)]
enum NodeDenial {
    /// Substitute an invalid id: the operation behaves as for a stale or missing node.
    Invalidate,
    /// The operation would otherwise fall back to the top-level Document; refuse it.
    Throw,
}

fn guard_node_arguments(
    ctx: &mut Ctx,
    this: Value,
    args: &[Value],
    (name, indices, denial): (&str, &[usize], NodeDenial),
    operation: NativeFn,
) -> Result<Value, Value> {
    let denied = inaccessible_node_arguments(ctx, name, args, indices);
    if denied == 0 {
        return operation(ctx, this, args);
    }
    match denial {
        NodeDenial::Throw => Err(ctx.make_error(
            "SecurityError",
            "the node belongs to a cross-origin Document",
        )),
        NodeDenial::Invalidate => {
            let mut args = args.to_vec();
            for (bit, &index) in indices.iter().enumerate() {
                if denied & (1 << bit) != 0 {
                    args[index] = Value::Num(f64::NAN);
                }
            }
            operation(ctx, this, &args)
        }
    }
}

/// Wrap content-bearing DOM host operations: their node-id arguments must be accessible to the
/// calling Window Realm. Structural queries the platform needs to route native input across
/// navigables (parent, children, node type and name, owner/frame Document) stay unguarded.
macro_rules! node_access_guards {
    ($($guard:ident = $operation:path, [$($index:literal),*], $denial:ident;)*) => {
        $(
            fn $guard(ctx: &mut Ctx, this: Value, args: &[Value]) -> Result<Value, Value> {
                let guard = (stringify!($operation), &[$($index),*][..], NodeDenial::$denial);
                guard_node_arguments(ctx, this, args, guard, $operation)
            }
        )*
    };
}

node_access_guards! {
    guarded_create_element = host_create_element, [1], Throw;
    guarded_create_element_ns = host_create_element_ns, [3], Throw;
    guarded_create_text = host_create_text, [1], Throw;
    guarded_create_comment = host_create_comment, [1], Throw;
    guarded_create_cdata = host_create_cdata, [1], Throw;
    guarded_create_processing_instruction = host_create_processing_instruction, [2], Throw;
    guarded_create_doctype = host_create_doctype, [3], Throw;
    guarded_doctype = host_doctype, [0], Invalidate;
    guarded_create_fragment = host_create_fragment, [0], Throw;
    guarded_elements_from_point = host_elements_from_point, [0], Throw;
    guarded_append = host_append, [0, 1], Invalidate;
    guarded_insert_before = host_insert_before, [0, 1, 2], Invalidate;
    guarded_adopt = host_adopt, [0, 1], Invalidate;
    guarded_clone = host_clone, [0, 2], Invalidate;
    guarded_get_attr = host_get_attr, [0], Invalidate;
    guarded_set_attr = host_set_attr, [0], Invalidate;
    guarded_remove_attr = host_remove_attr, [0], Invalidate;
    guarded_attr_names = host_attr_names, [0], Invalidate;
    guarded_attr_ns = host_attr_ns, [0], Invalidate;
    guarded_text = host_text, [0], Invalidate;
    guarded_set_text = host_set_text, [0], Invalidate;
    guarded_inner_html = host_inner_html, [0], Invalidate;
    guarded_set_inner_html = host_set_inner_html, [0, 3], Invalidate;
    guarded_outer_html = host_outer_html, [0], Invalidate;
    guarded_xml_serialize = host_xml_serialize, [0], Invalidate;
    guarded_insert_adjacent = host_insert_adjacent, [0], Invalidate;
    guarded_query = host_query, [0], Invalidate;
    guarded_elements_by_tag = host_elements_by_tag, [0], Invalidate;
    guarded_elements_by_class = host_elements_by_class, [0], Invalidate;
    guarded_matches = host_matches, [0], Invalidate;
    guarded_upgrade_candidates = host_upgrade_candidates, [0], Invalidate;
    guarded_ce_candidates = host_ce_candidates, [0], Invalidate;
    guarded_input = host_input, [0], Invalidate;
    guarded_computed_style = host_computed_style, [0], Invalidate;
    guarded_editable_model = host_editable_model, [0, 1, 3], Invalidate;
    guarded_offset_style = host_offset_style, [0], Invalidate;
    guarded_rect = host_rect, [0], Invalidate;
    guarded_svg_geometry = svg_geometry_host::call, [0], Invalidate;
    guarded_scroll_get = host_scroll_get, [0], Invalidate;
    guarded_scroll_set = host_scroll_set, [0], Invalidate;
    guarded_set_hover = host_set_hover, [0], Invalidate;
    guarded_focus = host_focus, [0, 1], Invalidate;
    guarded_popover = host_dom_popover, [0], Invalidate;
    guarded_marquee = host_dom_marquee, [0], Invalidate;
    guarded_dialog_modal = host_dom_dialog_modal, [0], Invalidate;
    guarded_fullscreen = host_dom_fullscreen, [0], Invalidate;
    guarded_top_layer = host_dom_top_layer, [0], Invalidate;
    guarded_inert = host_dom_inert, [0], Invalidate;
    guarded_open_dialogs = host_dom_open_dialogs, [0], Invalidate;
    guarded_user_select = host_user_select, [0], Invalidate;
    guarded_template_content = host_template_content, [0], Invalidate;
    guarded_shadow_root = host_shadow_root, [0], Invalidate;
    guarded_attach_shadow = host_attach_shadow, [0], Invalidate;
    guarded_adopt_styles = host_adopt_styles, [0], Invalidate;
    guarded_slot_assigned = host_slot_assigned, [0], Invalidate;
    guarded_assigned_slot = host_assigned_slot, [0], Invalidate;
    guarded_slot_assign = host_slot_assign, [0], Invalidate;
    guarded_slot_check = host_slot_check, [0], Invalidate;
    guarded_move_before = host_move_before, [0, 1, 2], Invalidate;
    guarded_custom_registry = host_custom_registry, [1], Invalidate;
    guarded_form_owner = host_form_owner, [0], Invalidate;
    guarded_form_named_items = host_form_named_items, [0], Invalidate;
    guarded_window_named_items = host_window_named_items, [0], Invalidate;
    guarded_pi_target = host_pi_target, [0], Invalidate;
    guarded_css_sheet = host_css_sheet, [0], Invalidate;
    guarded_image_current_src = host_image_current_src, [0], Invalidate;
    guarded_media_failed = host_media_failed, [0], Invalidate;
    guarded_media_load = media_host::load, [0], Invalidate;
    guarded_media_control = media_host::control, [0], Invalidate;
    guarded_media_attach = media_host::attach, [0], Invalidate;
    guarded_load_frame = host_load_frame, [0], Invalidate;
    guarded_create_window_realm = host_create_window_realm, [1], Invalidate;
    guarded_run_injected_script = host_run_injected_script, [0], Invalidate;
    guarded_script_started = host_script_started, [0], Invalidate;
    guarded_insertion_resources = host_insertion_resources, [0], Invalidate;
    guarded_run_classic_script = host_run_classic_script, [0], Invalidate;
    guarded_fetch_classic_script = host_fetch_classic_script, [0], Invalidate;
    guarded_load_injected_stylesheet = host_load_injected_stylesheet, [0], Invalidate;
    guarded_preload_link = host_preload_link, [0], Invalidate;
}

/// Detaching a navigable's Document is its container's operation (HTML #destroy-a-child-
/// navigable), so the embedder may detach a cross-origin child Document but nothing inside it.
fn guarded_detach(ctx: &mut Ctx, this: Value, args: &[Value]) -> Result<Value, Value> {
    let container = {
        let dom = host_dom(ctx);
        let dom = dom.borrow();
        host_arg_node(&dom, args, 0)
            .filter(|&node| matches!(dom.node(node).data, NodeData::Document))
            .and_then(|document| dom.node(document).parent)
            .filter(|&parent| matches!(dom.tag_name(parent), Some("iframe" | "frame")))
    };
    match container {
        Some(container) => {
            let checked = [Value::Num(container as f64)];
            if inaccessible_node_arguments(ctx, "host_detach", &checked, &[0]) != 0 {
                return Ok(Value::Undefined);
            }
            host_detach(ctx, this, args)
        }
        None => {
            let guard = ("host_detach", &[0][..], NodeDenial::Invalidate);
            guard_node_arguments(ctx, this, args, guard, host_detach)
        }
    }
}

/// Canvas and WebGL operations take a canvas element id, or zero for agent-wide operations
/// (private slots, capability probes). Zero names a Document, never a canvas, so it is not a
/// node argument here.
fn guarded_canvas_operation(
    ctx: &mut Ctx,
    this: Value,
    args: &[Value],
    name: &str,
    operation: NativeFn,
) -> Result<Value, Value> {
    if args.first().and_then(Value::as_num_opt) == Some(DOCUMENT as f64) {
        return operation(ctx, this, args);
    }
    guard_node_arguments(
        ctx,
        this,
        args,
        (name, &[0], NodeDenial::Invalidate),
        operation,
    )
}

fn guarded_canvas_2d(ctx: &mut Ctx, this: Value, args: &[Value]) -> Result<Value, Value> {
    guarded_canvas_operation(ctx, this, args, "canvas_host::call", canvas_host::call)
}

fn guarded_webgl(ctx: &mut Ctx, this: Value, args: &[Value]) -> Result<Value, Value> {
    // An OffscreenCanvas's context belongs to no Document.
    if webgl_host::is_offscreen_argument(args.first()) {
        return webgl_host::call(ctx, this, args);
    }
    guarded_canvas_operation(ctx, this, args, "webgl_host::call", webgl_host::call)
}

/// Operations that implicitly address the top-level Document.
fn top_document_accessible(ctx: &mut Ctx, operation: &str) -> bool {
    let checked = [Value::Num(DOCUMENT as f64)];
    inaccessible_node_arguments(ctx, operation, &checked, &[0]) == 0
}

fn guarded_get_by_id(ctx: &mut Ctx, this: Value, args: &[Value]) -> Result<Value, Value> {
    if !top_document_accessible(ctx, "host_get_by_id") {
        return Ok(Value::Null);
    }
    host_get_by_id(ctx, this, args)
}

fn guarded_doc_element(ctx: &mut Ctx, this: Value, args: &[Value]) -> Result<Value, Value> {
    if !top_document_accessible(ctx, "host_doc_element") {
        return Ok(Value::Null);
    }
    host_doc_element(ctx, this, args)
}

/// Web IDL DOMString argument, kept as Lumen engine text: TRust stores DOM strings (text,
/// attributes, CSSOM, storage, messages) in that form, so lone surrogates and plane-16
/// private-use characters round-trip exactly. Return such strings with
/// `Value::from_engine_text`; convert with `lumen::embed::engine_to_text` before treating them
/// as Rust text (rendering, URLs, network, encoders). See `host_arg_usv` and `dom_text_in`.
fn host_arg_string(ctx: &mut Ctx, args: &[Value], index: usize) -> String {
    args.get(index)
        .and_then(|value| ctx.coerce_engine_text(value).ok())
        .map(|value| value.to_string())
        .unwrap_or_default()
}

/// Web IDL USVString argument as Rust text: lone surrogates become U+FFFD. For URLs, network
/// requests, cookies, encoders, script source and other consumers of scalar values.
fn host_arg_usv(ctx: &mut Ctx, args: &[Value], index: usize) -> String {
    args.get(index)
        .and_then(|value| ctx.coerce_usv_string(value).ok())
        .unwrap_or_default()
}

/// Rust text entering DOM storage (a decoded document or message) in engine text form; see
/// `host_arg_string`.
pub(crate) fn dom_text_in(text: &str) -> std::borrow::Cow<'_, str> {
    lumen::embed::text_to_engine(text)
}

/// DOM engine text as Rust text for rendering and other text consumers; see `host_arg_string`.
pub(crate) fn dom_text_out(text: &str) -> std::borrow::Cow<'_, str> {
    lumen::embed::engine_to_text(text)
}

fn host_id_value(id: Option<usize>) -> Value {
    id.map_or(Value::Null, |id| Value::Num(id as f64))
}

fn host_ids_array(ctx: &mut Ctx, ids: Vec<usize>) -> Value {
    let array = ctx.make_array(ids.iter().map(|&id| Value::Num(id as f64)).collect());
    if let Some(state) = ctx.host_mut::<HostState>() {
        state
            .dom_gc
            .retain(array.clone(), ids, DomGcOwnerKind::IdArray);
    }
    array
}

fn host_register_dom_wrapper(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let Some(wrapper @ Value::Obj(_)) = args.get(1) else {
        return Ok(Value::Undefined);
    };
    let state = ctx.host_mut::<HostState>().expect("DOM host");
    let mut dom = state.dom.borrow_mut();
    if let Some(node) = host_arg_node(&dom, args, 0) {
        if native_wrapper_cache_enabled()
            && let Some(entry) = state
                .dom_gc
                .wrappers
                .get(&node)
                .and_then(|identity| state.dom_gc.owners.get(identity))
        {
            return Ok(entry.value.clone());
        }
        if matches!(dom.node(node).data, NodeData::Document) {
            if let Some(entry) = state
                .dom_gc
                .documents
                .get(&node)
                .and_then(|owner| state.dom_gc.owners.get(owner))
            {
                return Ok(entry.value.clone());
            }
            let Value::Obj(object) = wrapper else {
                unreachable!()
            };
            state
                .dom_gc
                .documents
                .insert(node, Rc::as_ptr(object) as usize);
        }
        state
            .dom_gc
            .retain(wrapper.clone(), vec![node], DomGcOwnerKind::Wrapper);
        if native_wrapper_cache_enabled() {
            state
                .dom_gc
                .wrappers
                .insert(node, Rc::as_ptr(wrapper.as_obj().unwrap()) as usize);
        }
        dom.release_gc_allocation(node);
    }
    Ok(wrapper.clone())
}

fn native_wrapper_cache_enabled() -> bool {
    static ENABLED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ENABLED.get_or_init(|| std::env::var("TRUST_NATIVE_WRAPPERS").as_deref() != Ok("0"))
}

fn host_dom_wrapper_cache_enabled(
    _ctx: &mut Ctx,
    _this: Value,
    _args: &[Value],
) -> Result<Value, Value> {
    Ok(Value::Bool(native_wrapper_cache_enabled()))
}

fn host_cached_dom_wrapper(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let state = ctx.host_mut::<HostState>().expect("DOM host");
    let Some(number) = args.first().and_then(Value::as_num_opt) else {
        return Ok(Value::Null);
    };
    let node = number as usize;
    if !number.is_finite() || number < 0. || node as f64 != number {
        return Ok(Value::Null);
    }
    Ok(state
        .dom_gc
        .wrappers
        .get(&node)
        .and_then(|identity| state.dom_gc.owners.get(identity))
        .filter(|entry| {
            matches!(entry.kind, DomGcOwnerKind::Wrapper) && entry.nodes.as_slice() == [node]
        })
        .map_or(Value::Null, |entry| entry.value.clone()))
}

fn host_dom_wrapper_cache_state(
    ctx: &mut Ctx,
    _this: Value,
    _args: &[Value],
) -> Result<Value, Value> {
    let state = ctx.host_mut::<HostState>().expect("DOM host");
    let dom = state.dom.borrow();
    let entries = state.dom_gc.wrappers.len();
    let live = state
        .dom_gc
        .wrappers
        .values()
        .filter(|identity| state.dom_gc.owners.contains_key(identity))
        .count();
    let connected = state
        .dom_gc
        .wrappers
        .keys()
        .filter(|&&node| dom.is_connected(node))
        .count();
    drop(dom);
    Ok(ctx.make_array(vec![
        Value::Num(entries as f64),
        Value::Num(live as f64),
        Value::Num(connected as f64),
    ]))
}

fn native_dom_traversal_enabled() -> bool {
    static ENABLED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ENABLED.get_or_init(|| std::env::var("TRUST_NATIVE_DOM_TRAVERSAL").as_deref() != Ok("0"))
}

fn host_dom_traversal_enabled(
    _ctx: &mut Ctx,
    _this: Value,
    _args: &[Value],
) -> Result<Value, Value> {
    Ok(Value::Bool(native_dom_traversal_enabled()))
}

/// DOM a2331a45 #dom-node-firstchild / #dom-node-parentnode and the
/// ParentNode/NonDocumentTypeChildNode getters read the native light tree.
/// Do not materialize a retained ID array for a single edge, or consult
/// author-overridable nodeType/children/parentNode properties. Web IDL
/// 8f182624 #dfn-attribute-getter requires the actual platform receiver.
/// Whether `value` is an Attr platform object: its internal-slot record (the
/// prelude's shared `internals` WeakMap) carries Attr state.
fn is_attr_node(ctx: &mut Ctx, value: &Value) -> bool {
    if !matches!(value, Value::Obj(_)) {
        return false;
    }
    let Some(map) = ctx
        .host_mut::<HostState>()
        .and_then(|state| state.platform_internals.clone())
    else {
        return false;
    };
    match ctx.weak_map_get(&map, value) {
        Ok(record @ Value::Obj(_)) => {
            matches!(ctx.member_get(&record, "attrNode"), Ok(Value::Obj(_)))
        }
        _ => false,
    }
}

fn host_dom_relative(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let state = ctx.host_mut::<HostState>().expect("DOM host");
    let edge = args.get(1).and_then(Value::as_num_opt).unwrap_or(-1.0) as i32;
    let Some(id) = args
        .first()
        .and_then(|value| state.dom_gc.node_identity(value))
    else {
        // DOM #interface-attr: an Attr is a Node without an arena node. It
        // has no parent, children or siblings, and no tree index.
        if is_attr_node(ctx, args.first().unwrap_or(&Value::Undefined)) {
            return Ok(match edge {
                10 => Value::Num(0.0),
                11 => Value::Num(-1.0),
                _ => Value::Null,
            });
        }
        return Err(ctx.make_error("TypeError", "Node getter requires a Node receiver"));
    };
    let dom = state.dom.borrow();
    if !dom.is_valid(id) {
        drop(dom);
        return Err(ctx.make_error("TypeError", "Node receiver is no longer live"));
    }
    let node = dom.node(id);
    if edge == 11 {
        // Internal Range index: only preceding light-tree siblings matter.
        // DOM #concept-tree-index. Never allocate all of the parent's IDs.
        if node.parent.is_none() || matches!(node.data, NodeData::Document) {
            return Ok(Value::Num(-1.0));
        }
        let mut index = 0;
        let mut previous = node.prev_sibling;
        while let Some(sibling) = previous {
            let sibling = dom.node(sibling);
            if !matches!(sibling.data, NodeData::Document) {
                index += 1;
            }
            previous = sibling.prev_sibling;
        }
        return Ok(Value::Num(index as f64));
    }
    if edge == 10 {
        return Ok(Value::Num(
            dom.child_iter(id)
                .filter(|&child| matches!(dom.node(child).data, NodeData::Element { .. }))
                .count() as f64,
        ));
    }
    let document = matches!(node.data, NodeData::Document);
    let mut target = match edge {
        0 | 1 if !document => node.parent,
        2 | 4 => node.first_child,
        3 | 5 => node.last_child,
        6 | 8 if !document => node.next_sibling,
        7 | 9 if !document => node.prev_sibling,
        _ => None,
    };
    if edge == 1 {
        target = target.filter(|&parent| matches!(dom.node(parent).data, NodeData::Element { .. }));
    } else if edge >= 2 {
        // Frame Documents are stored as native arena children for lifetime
        // ownership, but are separate DOM trees. Shadow/template contents
        // likewise have their own roots, never substituted for light children.
        let elements_only = matches!(edge, 4 | 5 | 8 | 9);
        while let Some(candidate) = target {
            let candidate = dom.node(candidate);
            if !matches!(candidate.data, NodeData::Document)
                && (!elements_only || matches!(candidate.data, NodeData::Element { .. }))
            {
                break;
            }
            target = if matches!(edge, 3 | 5 | 7 | 9) {
                candidate.prev_sibling
            } else {
                candidate.next_sibling
            };
        }
    }
    Ok(target.map_or(Value::Null, |node| {
        state
            .dom_gc
            .wrappers
            .get(&node)
            .and_then(|identity| state.dom_gc.owners.get(identity))
            .map_or(Value::Num(node as f64), |entry| entry.value.clone())
    }))
}

fn native_live_collections_enabled() -> bool {
    static ENABLED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ENABLED.get_or_init(|| std::env::var("TRUST_NATIVE_LIVE_COLLECTIONS").as_deref() != Ok("0"))
}

fn live_collection_length(ctx: &Ctx, root: &Value, elements: bool) -> u32 {
    let Some(state) = ctx.host::<HostState>() else {
        return 0;
    };
    let Some(root) = state.dom_gc.node_identity(root) else {
        return 0;
    };
    state
        .dom
        .borrow()
        .child_collection_len(root, elements)
        .min(u32::MAX as usize) as u32
}

fn live_node_list_length(ctx: &Ctx, root: &Value) -> u32 {
    live_collection_length(ctx, root, false)
}

fn live_element_list_length(ctx: &Ctx, root: &Value) -> u32 {
    live_collection_length(ctx, root, true)
}

fn host_child_collection_length(
    ctx: &mut Ctx,
    _this: Value,
    args: &[Value],
) -> Result<Value, Value> {
    let root = args.first().unwrap_or(&Value::Undefined);
    Ok(Value::Num(
        live_collection_length(ctx, root, matches!(args.get(1), Some(Value::Bool(true)))) as f64,
    ))
}

fn live_element_list_names(ctx: &Ctx, root: &Value) -> Vec<String> {
    let Some(state) = ctx.host::<HostState>() else {
        return Vec::new();
    };
    let Some(root) = state.dom_gc.node_identity(root) else {
        return Vec::new();
    };
    let dom = state.dom.borrow();
    collection_supported_names(&dom, dom.child_iter(root))
}

/// DOM #ref-for-dfn-supported-property-names (HTMLCollection): each member's
/// non-empty ID, then its name attribute when it is in the HTML namespace,
/// in tree order without duplicates.
fn collection_supported_names(dom: &Dom, members: impl Iterator<Item = usize>) -> Vec<String> {
    let mut seen = rustc_hash::FxHashSet::default();
    let mut names = Vec::new();
    for member in members {
        if !matches!(dom.node(member).data, NodeData::Element { .. }) {
            continue;
        }
        let html = dom.namespace_uri(member) == Some("http://www.w3.org/1999/xhtml");
        for name in [
            dom.get_attribute(member, "id"),
            html.then(|| dom.get_attribute(member, "name")).flatten(),
        ]
        .into_iter()
        .flatten()
        .filter(|name| !name.is_empty())
        {
            if seen.insert(name) {
                names.push(name.to_owned());
            }
        }
    }
    names
}

/// DOM #dom-htmlcollection-nameditem-key: the first member whose ID is
/// `name`, or an HTML-namespace member whose name attribute is `name`.
fn collection_named_item(
    dom: &Dom,
    mut members: impl Iterator<Item = usize>,
    name: &str,
) -> Option<usize> {
    members.find(|&member| {
        matches!(dom.node(member).data, NodeData::Element { .. })
            && (dom.get_attribute(member, "id") == Some(name)
                || (dom.namespace_uri(member) == Some("http://www.w3.org/1999/xhtml")
                    && dom.get_attribute(member, "name") == Some(name)))
    })
}

/// A collection member's canonical wrapper, creating it through the page's
/// wrapper callback only when the node has none.
fn collection_member_wrapper(ctx: &mut Ctx, member: usize, wrap: &Value) -> Result<Value, Value> {
    let state = ctx.host::<HostState>().expect("DOM host");
    let cached = state
        .dom_gc
        .wrappers
        .get(&member)
        .and_then(|identity| state.dom_gc.owners.get(identity))
        .map(|entry| entry.value.clone());
    if let Some(wrapper) = cached {
        return Ok(wrapper);
    }
    ctx.invoke(wrap.clone(), Value::Undefined, &[Value::Num(member as f64)])
}

/// Native membership never manufactures a JS ID array. Only a consumed node
/// obtains a wrapper; its identity still belongs to the canonical mixed heap.
fn live_child_collection_get(
    ctx: &mut Ctx,
    _this: Value,
    args: &[Value],
    captures: &[Value],
) -> Result<Value, Value> {
    let elements = matches!(captures.get(2), Some(Value::Bool(true)));
    let state = ctx.host::<HostState>().expect("DOM host");
    let Some(root) = state.dom_gc.node_identity(&captures[0]) else {
        return Ok(Value::Null);
    };
    let dom = state.dom.borrow();
    let target = match args.first() {
        Some(Value::Num(index)) if index.is_finite() && *index >= 0.0 && index.fract() == 0.0 => {
            dom.child_collection_item(root, *index as usize, elements)
        }
        Some(Value::Str(name)) if elements && !name.is_empty() => {
            // Attribute values are DOM engine text, like the payload (see `host_arg_string`).
            collection_named_item(&dom, dom.child_iter(root), name.as_str())
        }
        _ => None,
    };
    drop(dom);
    let Some(target) = target else {
        return Ok(Value::Null);
    };
    collection_member_wrapper(ctx, target, &captures[1])
}

fn host_install_live_collection(
    ctx: &mut Ctx,
    _this: Value,
    args: &[Value],
) -> Result<Value, Value> {
    if !native_live_collections_enabled() {
        return Ok(Value::Bool(false));
    }
    let target = args.first().cloned().unwrap_or(Value::Undefined);
    let root = args.get(1).cloned().unwrap_or(Value::Undefined);
    let elements = matches!(args.get(2), Some(Value::Bool(true)));
    let wrap = args.get(3).cloned().unwrap_or(Value::Undefined);
    if ctx
        .host::<HostState>()
        .and_then(|state| state.dom_gc.node_identity(&root))
        .is_none()
        || !wrap.is_callable()
    {
        return Err(ctx.make_error(
            "TypeError",
            "live collection requires a Node and wrapper callback",
        ));
    }
    let getter = ctx.new_native_fn_with_captures(
        "collection item",
        1,
        live_child_collection_get,
        vec![root.clone(), wrap, Value::Bool(elements)],
    );
    let length = if elements {
        live_element_list_length
    } else {
        live_node_list_length
    };
    let named = elements.then(|| {
        (
            live_element_list_names as fn(&Ctx, &Value) -> Vec<String>,
            getter.clone(),
        )
    });
    ctx.install_live_readonly_indexed_properties(&target, root, length, getter.clone(), named)?;
    Ok(getter)
}

/// The members of the tag/class collection whose membership state is `key`.
fn live_query_members(ctx: &Ctx, key: &Value) -> Option<Rc<[usize]>> {
    let Value::Str(key) = key else {
        return None;
    };
    let state = ctx.host::<HostState>()?;
    Some(state.dom.borrow().query_collection(key.as_str()))
}

fn live_query_length(ctx: &Ctx, key: &Value) -> u32 {
    live_query_members(ctx, key).map_or(0, |members| members.len().min(u32::MAX as usize) as u32)
}

fn live_query_names(ctx: &Ctx, key: &Value) -> Vec<String> {
    let (Some(members), Some(state)) = (live_query_members(ctx, key), ctx.host::<HostState>())
    else {
        return Vec::new();
    };
    collection_supported_names(&state.dom.borrow(), members.iter().copied())
}

/// Captures: membership key, wrapper callback, and the root wrapper, which
/// keeps the root node (and with it the key's identity) alive with the view.
fn live_query_collection_get(
    ctx: &mut Ctx,
    _this: Value,
    args: &[Value],
    captures: &[Value],
) -> Result<Value, Value> {
    let Some(members) = live_query_members(ctx, &captures[0]) else {
        return Ok(Value::Null);
    };
    let target = match args.first() {
        Some(Value::Num(index)) if index.is_finite() && *index >= 0.0 && index.fract() == 0.0 => {
            members.get(*index as usize).copied()
        }
        Some(Value::Str(name)) if !name.is_empty() => {
            let state = ctx.host::<HostState>().expect("DOM host");
            collection_named_item(&state.dom.borrow(), members.iter().copied(), name.as_str())
        }
        _ => None,
    };
    let Some(target) = target else {
        return Ok(Value::Null);
    };
    collection_member_wrapper(ctx, target, &captures[1])
}

fn live_query_collection_length(
    ctx: &mut Ctx,
    _this: Value,
    _args: &[Value],
    captures: &[Value],
) -> Result<Value, Value> {
    Ok(Value::Num(live_query_length(ctx, &captures[0]) as f64))
}

/// `__dom_install_query_collection(target, root, classes, query, extra, wrap)`
/// installs a live getElementsByTagName(NS)/getElementsByClassName view on a
/// fresh HTMLCollection. `extra` is the tag query's namespace (undefined for
/// the non-NS form, null for the null namespace) or whether a class query's
/// root is a Document. Returns `[item getter, length function]`, or false when
/// native collections are disabled.
fn host_install_query_collection(
    ctx: &mut Ctx,
    _this: Value,
    args: &[Value],
) -> Result<Value, Value> {
    if !native_live_collections_enabled() {
        return Ok(Value::Bool(false));
    }
    let target = args.first().cloned().unwrap_or(Value::Undefined);
    let root_wrapper = args.get(1).cloned().unwrap_or(Value::Undefined);
    let classes = matches!(args.get(2), Some(Value::Bool(true)));
    let query = host_arg_string(ctx, args, 3);
    let namespace = match args.get(4) {
        _ if classes => None,
        None | Some(Value::Undefined) => None,
        Some(Value::Null) => Some(String::new()),
        _ => Some(host_arg_string(ctx, args, 4)),
    };
    let wrap = args.get(5).cloned().unwrap_or(Value::Undefined);
    let root = ctx
        .host::<HostState>()
        .and_then(|state| state.dom_gc.node_identity(&root_wrapper));
    let (Some(root), true) = (root, wrap.is_callable()) else {
        return Err(ctx.make_error(
            "TypeError",
            "live collection requires a Node and wrapper callback",
        ));
    };
    let key = if classes {
        crate::dom::CollectionQuery::Class {
            names: &query,
            document_root: matches!(args.get(4), Some(Value::Bool(true))),
        }
    } else {
        crate::dom::CollectionQuery::Tag {
            qualified: &query,
            namespace: namespace.as_deref(),
        }
    }
    .key(root);
    // The key carries DOM engine text and is read back as-is (see `host_arg_string`).
    let key = Value::from_engine_text(key);
    let getter = ctx.new_native_fn_with_captures(
        "collection item",
        1,
        live_query_collection_get,
        vec![key.clone(), wrap, root_wrapper],
    );
    let length = ctx.new_native_fn_with_captures(
        "collection length",
        0,
        live_query_collection_length,
        vec![key.clone()],
    );
    ctx.install_live_readonly_indexed_properties(
        &target,
        key,
        live_query_length,
        getter.clone(),
        Some((
            live_query_names as fn(&Ctx, &Value) -> Vec<String>,
            getter.clone(),
        )),
    )?;
    Ok(ctx.make_array(vec![getter, length]))
}

fn host_node_identity(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let state = ctx.host_mut::<HostState>().expect("DOM host");
    Ok(host_id_value(
        args.first()
            .and_then(|value| state.dom_gc.node_identity(value)),
    ))
}

fn host_dom_observer_targets(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let observer = args.first().cloned().unwrap_or(Value::Undefined);
    let array = args.get(1).cloned().unwrap_or(Value::Undefined);
    // The private prelude passes distinct node IDs. Read ordinary own numeric
    // elements only: no accessor/proxy reentrancy while replacing graph edges,
    // and no attacker-controlled sparse-array length can force an unbounded loop.
    let limit = ctx
        .host_mut::<HostState>()
        .expect("DOM host")
        .dom
        .borrow()
        .node_count();
    let Some(numbers) = ctx.copy_numeric_array(&array, limit) else {
        return Err(ctx.make_error("TypeError", "Invalid observer target ID list"));
    };
    let mut nodes: Vec<_> = numbers
        .into_iter()
        .filter(|number| number.is_finite() && *number >= 0.0 && number.fract() == 0.0)
        .map(|number| number as usize)
        .collect();
    let state = ctx.host_mut::<HostState>().expect("DOM host");
    nodes.retain(|node| state.dom.borrow().is_valid(*node));
    nodes.sort_unstable();
    nodes.dedup();
    state
        .dom_gc
        .retain(observer, nodes, DomGcOwnerKind::Observer);
    Ok(Value::Undefined)
}

/// Fetch Standard §2.2.1 method normalization plus the byte-string request-body,
/// header, mode, and credentials transport contract shared with the platform
/// prelude.
#[allow(clippy::type_complexity)]
/// The fetch arguments, or the message of a request body that could not be read.
type HostFetchArgs = (
    String,
    String,
    Option<(String, Vec<u8>)>,
    Vec<(String, String)>,
    Option<(crate::http::RequestMode, crate::http::CredentialsMode)>,
);

/// A request body from the prelude: bytes (a BufferSource or a byte string),
/// or a list of byte chunks and `[file id, start, end]` ranges of
/// user-selected files, which are read now against their snapshot state
/// (File API #snapshot-state) within the request limit, so an upload is never
/// copied into script memory.
fn host_request_body(
    ctx: &mut Ctx,
    args: &[Value],
    index: usize,
) -> Result<Option<Vec<u8>>, String> {
    let Some(value) = args
        .get(index)
        .filter(|value| !matches!(value, Value::Null | Value::Undefined))
        .cloned()
    else {
        return Ok(None);
    };
    if let Some(bytes) = ctx.buffer_source_bytes(&value, false) {
        return Ok(Some(bytes));
    }
    if !matches!(value, Value::Obj(_)) {
        return Ok(Some(host_latin1_bytes(ctx, args, index)));
    }
    let number = |ctx: &mut Ctx, object: &Value, key: &str| {
        ctx.member_get(object, key)
            .ok()
            .and_then(|value| value.as_num_opt())
            .filter(|number| number.is_finite() && *number >= 0.0)
            .unwrap_or(0.0)
    };
    let length = number(ctx, &value, "length") as usize;
    let mut segments = Vec::with_capacity(length);
    for index in 0..length {
        let segment = ctx
            .member_get(&value, &index.to_string())
            .map_err(|_| String::from("unreadable request body"))?;
        segments.push(match ctx.buffer_source_bytes(&segment, false) {
            Some(bytes) => crate::file_select::BodySegment::Bytes(bytes),
            None => crate::file_select::BodySegment::File {
                id: number(ctx, &segment, "0") as u64,
                start: number(ctx, &segment, "1") as u64,
                end: number(ctx, &segment, "2") as u64,
            },
        });
    }
    let state = ctx
        .host_mut::<HostState>()
        .ok_or_else(|| String::from("missing browser host state"))?;
    state
        .user_files
        .assemble(&segments, crate::file_select::MAX_READ_BYTES)
        .map(Some)
        .map_err(|error| error.message().to_string())
}

/// The request's use-CORS-preflight flag (Fetch #use-cors-preflight-flag),
/// argument 10 of `__http_fetch`/`__http_fetch_async`: XHR send() sets it when
/// its upload object has event listeners, the Request constructor for a
/// ReadableStream body.
fn host_fetch_use_cors_preflight(args: &[Value]) -> bool {
    matches!(args.get(10), Some(Value::Bool(true)))
}

fn host_fetch_args(ctx: &mut Ctx, args: &[Value]) -> Result<HostFetchArgs, String> {
    let target = host_arg_usv(ctx, args, 0);
    let mut method: String = host_arg_usv(ctx, args, 1)
        .chars()
        .filter(|ch| ch.is_ascii_alphanumeric() || "!#$%&'*+-.^_`|~".contains(*ch))
        .collect();
    if ["DELETE", "GET", "HEAD", "OPTIONS", "POST", "PUT"]
        .iter()
        .any(|known| method.eq_ignore_ascii_case(known))
    {
        method.make_ascii_uppercase();
    }
    if method.is_empty() {
        method = String::from("GET");
    }
    let body = host_request_body(ctx, args, 2)?;
    let content_type = args
        .get(3)
        .filter(|value| !matches!(value, Value::Null | Value::Undefined))
        .map(|_| host_arg_usv(ctx, args, 3));
    // BodyInit extraction already chose the inferred type. A null type is
    // significant for BufferSource and untyped Blob bodies (Fetch §5.2).
    let body = body.map(|bytes| (content_type.unwrap_or_default(), bytes));
    let headers = args
        .get(4)
        .filter(|value| !matches!(value, Value::Null | Value::Undefined))
        .map(|_| crate::js::parse_header_blob(&host_arg_usv(ctx, args, 4)))
        .unwrap_or_default();
    let policy = args.get(5).map(|_| {
        let mode = match host_arg_usv(ctx, args, 5).to_ascii_lowercase().as_str() {
            "no-cors" => crate::http::RequestMode::NoCors,
            "same-origin" => crate::http::RequestMode::SameOrigin,
            _ => crate::http::RequestMode::Cors,
        };
        let credentials = match host_arg_usv(ctx, args, 6).to_ascii_lowercase().as_str() {
            "omit" => crate::http::CredentialsMode::Omit,
            "include" => crate::http::CredentialsMode::Include,
            _ => crate::http::CredentialsMode::SameOrigin,
        };
        (mode, credentials)
    });
    Ok((target, method, body, headers, policy))
}

#[cfg(test)]
fn prepare_host_request(
    state: &mut HostState,
    target: &str,
    method: String,
    body: Option<(String, Vec<u8>)>,
    headers: Vec<(String, String)>,
    fetch_policy: Option<(crate::http::RequestMode, crate::http::CredentialsMode)>,
) -> Option<(
    tokio::runtime::Handle,
    Arc<crate::http::PageCache>,
    crate::http::Request,
)> {
    let page = state.base.clone();
    prepare_client_request(state, &page, target, method, body, headers, fetch_policy)
}

fn request_client_url(ctx: &mut Ctx) -> url::Url {
    let context = ctx.host_job_context();
    request_context_url(ctx, context)
}

fn request_context_url(ctx: &mut Ctx, context: u64) -> url::Url {
    let state = ctx
        .host_mut::<HostState>()
        .expect("request settings require HostState");
    state
        .window_request_urls
        .get(&context)
        .unwrap_or(&state.base)
        .clone()
}

fn request_cookie_context(ctx: &mut Ctx) -> crate::http::CookieContext {
    let id = ctx.host_job_context();
    cookie_context_for_id(ctx, id)
}

fn cookie_context_for_id(ctx: &mut Ctx, id: u64) -> crate::http::CookieContext {
    let state = ctx
        .host_mut::<HostState>()
        .expect("cookie settings require HostState");
    if let Some((_, _, context)) = state.window_cookie_contexts.get(&id) {
        return context.clone();
    }
    let mut context = crate::http::CookieContext::subresource(
        state.window_request_urls.get(&0).unwrap_or(&state.base),
    );
    context.cross_site_ancestor = id != 0;
    context
}

// Fetch §5.4 and XHR §3.5.6 assign the request client from the API object's
// relevant environment settings. In particular a child Window's own-origin
// request must not acquire the embedder's Origin/CORS/credentials context.
fn prepare_client_request(
    state: &mut HostState,
    page: &url::Url,
    target: &str,
    method: String,
    body: Option<(String, Vec<u8>)>,
    headers: Vec<(String, String)>,
    fetch_policy: Option<(crate::http::RequestMode, crate::http::CredentialsMode)>,
) -> Option<(
    tokio::runtime::Handle,
    Arc<crate::http::PageCache>,
    crate::http::Request,
)> {
    let prepared =
        prepare_uncounted_client_request(state, page, target, method, body, headers, fetch_policy)?;
    // Fetch Standard §5.6 invokes Fetch for every successfully constructed request. A count of
    // earlier page requests is neither a network error nor a specified rejection condition.
    state
        .network
        .as_ref()?
        .fetched
        .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    Some(prepared)
}

/// `prepare_client_request` without counting toward the page's speculative
/// prefetch budget (`MAX_PAGE_FETCHES_WITH_SPECULATION`). Document image
/// requests, which frontends used to make, keep that budget for scripts.
fn prepare_uncounted_client_request(
    state: &mut HostState,
    page: &url::Url,
    target: &str,
    method: String,
    body: Option<(String, Vec<u8>)>,
    headers: Vec<(String, String)>,
    fetch_policy: Option<(crate::http::RequestMode, crate::http::CredentialsMode)>,
) -> Option<(
    tokio::runtime::Handle,
    Arc<crate::http::PageCache>,
    crate::http::Request,
)> {
    let resolved = page.join(target).ok()?;
    // Fetch #populate-request-from-client uses the settings ORIGIN, not the
    // scheme/host of the API base URL (notably blob: dedicated workers).
    let origin = state
        .worker_self
        .as_ref()
        .map_or(page, |worker| &worker.origin);
    let network = state.network.as_mut()?;
    if !matches!(resolved.scheme(), "http" | "https" | "file")
        || !crate::http::subresource_allowed(origin, &resolved)
    {
        return None;
    }
    if fetch_policy.as_ref().is_some_and(|(mode, _)| {
        *mode == crate::http::RequestMode::SameOrigin
            && !crate::http::same_origin_for_host(origin, &resolved)
    }) {
        return None;
    }
    let mut request = crate::http::Request {
        method,
        url: resolved,
        body,
        headers,
        fetch_metadata: None,
        cookie_context: None,
        timing_client: None,
        use_cors_preflight: false,
        referrer_policy: None,
        fetch_policy: fetch_policy.map(|(mode, credentials)| crate::http::FetchPolicy {
            origin: origin.clone(),
            mode,
            credentials,
        }),
    };
    let mode = fetch_policy.map_or(crate::http::RequestMode::NoCors, |(mode, _)| mode);
    crate::http::set_fetch_metadata(&mut request, origin, "empty", mode.as_str());
    match state
        .worker_self
        .as_ref()
        .map(|worker| worker.referrer_policy)
    {
        // Fetch #determine-requests-referrer for a worker client: its creation URL (`page`,
        // the worker's URL) under its policy container's referrer policy.
        Some(policy) => {
            if !request
                .headers
                .iter()
                .any(|(name, _)| name.eq_ignore_ascii_case("referer"))
                && let Some(referrer) = policy.determine(page, &request.url)
            {
                request
                    .headers
                    .push((String::from("Referer"), referrer.to_string()));
            }
        }
        None => crate::http::set_referrer(&mut request, page),
    }
    if let Some(context) = request.cookie_context.as_mut() {
        context.top_level_site = state.window_cookie_contexts.get(&0).map_or_else(
            || {
                crate::http::CookieContext::subresource(
                    state.window_request_urls.get(&0).unwrap_or(&state.base),
                )
                .top_level_site
            },
            |(_, _, owner)| owner.top_level_site.clone(),
        );
        context.cross_site_ancestor = state
            .window_cookie_contexts
            .values()
            .any(|(_, _, c)| c.client.as_ref() == Some(page) && c.cross_site_ancestor)
            || !crate::site_storage::same_site(
                state.window_request_urls.get(&0).unwrap_or(&state.base),
                page,
            );
    }
    Some((network.handle.clone(), network.cache.clone(), request))
}

fn lumen_fetch_result(response: crate::http::Response) -> LumenFetchResult {
    if std::env::var_os("TRUST_TRACE_FETCH").is_some() {
        eprintln!(
            "[fetch-trace] result status={} type={} len={}",
            response.status,
            response.content_type.split(';').next().unwrap_or(""),
            response.body.len()
        );
    }
    Some((
        response.status,
        response.content_type,
        response.body,
        crate::js::headers_to_blob(&response.headers),
        response.url.to_string(),
        response.status_text,
    ))
}

fn lumen_cached_result(response: &crate::http::CachedResp) -> LumenFetchResult {
    if std::env::var_os("TRUST_TRACE_FETCH").is_some() {
        eprintln!(
            "[fetch-trace] cached status={} type={} len={}",
            response.status,
            response.content_type.split(';').next().unwrap_or(""),
            response.body.len()
        );
    }
    Some((
        response.status,
        response.content_type.clone(),
        response.body.clone(),
        crate::js::headers_to_blob(&response.headers),
        response
            .url_list
            .last()
            .map_or_else(String::new, |url| url.to_string()),
        response.status_text.clone(),
    ))
}

fn host_fetch_result_value(ctx: &mut Ctx, result: LumenFetchResult) -> Value {
    let Some((status, content_type, body, headers, url, status_text)) = result else {
        return Value::Null;
    };
    let text = if crate::js::response_body_is_binary(&content_type) {
        Value::Undefined
    } else {
        Value::from_string(String::from_utf8_lossy(&body).into_owned())
    };
    // Fetch Body is a byte sequence. An ordinary ArrayBuffer crosses the host boundary without
    // depending on the realm's typed-array view bookkeeping; the prelude turns it into a view at
    // the point where the Fetch Body algorithms need one. Retain the legacy one-code-point-per-
    // byte string only as an allocation-failure fallback.
    let bytes = ctx
        .make_array_buffer(&body)
        .unwrap_or_else(|_| Value::from_string(body.iter().copied().map(char::from).collect()));
    // [status, Content-Type, text, bytes, headers, final URL, -, status
    // message]: Fetch's response URL list ends with the URL that answered
    // after redirects; the header list keeps its order and duplicates (Fetch
    // #concept-header-list) and the status message is the reason phrase
    // (Fetch #concept-response-status-message). Index 6 is the navigation
    // result's referrer (`navigation_result_value`).
    ctx.make_array(vec![
        Value::Num(f64::from(status)),
        Value::from_string(content_type),
        text,
        bytes,
        Value::from_string(headers),
        Value::from_string(url),
        Value::Undefined,
        Value::from_string(status_text),
    ])
}

fn timed_fetch_result(
    result: Result<crate::http::Response, crate::http::TimedFetchError>,
    name: String,
    initiator: &'static str,
    started: f64,
) -> (LumenFetchResult, Option<LumenResourceTiming>) {
    let (result, timing) = match result {
        Ok(mut response) => {
            let timing = response.timing.take();
            (lumen_fetch_result(response), timing)
        }
        Err(error) => (None, error.timing),
    };
    let timing = timing.filter(|_| !initiator.is_empty()).map(|mut timing| {
        // Fetch begins in the initiating API task, before scheduling the
        // parallel I/O. Include queue time without changing wire boundaries.
        timing.start_time = started;
        if timing.redirect_start == 0.0 {
            timing.fetch_start = started;
        } else {
            timing.redirect_start = started;
        }
        LumenResourceTiming {
            name,
            initiator,
            timing,
            cached: false,
        }
    });
    (result, timing)
}

fn resource_initiator(ctx: &mut Ctx, args: &[Value]) -> &'static str {
    match host_arg_string(ctx, args, 7).as_str() {
        "fetch" => "fetch",
        "xmlhttprequest" => "xmlhttprequest",
        "beacon" => "beacon",
        // HTML #dom-eventsource: an EventSource request's initiator type.
        "other" => "other",
        _ => "",
    }
}

fn record_resource_timing(ctx: &mut Ctx, report: Option<LumenResourceTiming>) {
    let Some(report) = report else { return };
    record_resource_timing_ref(ctx, &report);
}

/// Resource Timing #marking-resource-timing in the global of settings context
/// `context` (a request's client), which can differ from the running Realm.
/// A retired Document's global no longer receives entries.
fn record_resource_timing_in(
    engine: &mut lumen::Engine,
    context: u64,
    report: Option<LumenResourceTiming>,
) -> Result<(), String> {
    let Some(report) = report else {
        return Ok(());
    };
    if context == engine.ctx().host_job_context() {
        record_resource_timing_ref(engine.ctx(), &report);
        return Ok(());
    }
    let realm = engine
        .ctx()
        .host_mut::<HostState>()
        .and_then(|state| state.window_realms.get(&context).cloned());
    let Some(realm) = realm else { return Ok(()) };
    engine
        .with_embed_realm(&realm, move |engine| {
            record_resource_timing_ref(engine.ctx(), &report);
        })
        .map_err(|_| String::from("resource timing Realm is unavailable"))
}

fn record_resource_timing_ref(ctx: &mut Ctx, report: &LumenResourceTiming) {
    let data = report.data();
    // Resource Timing #marking-resource-timing creates the entry in the
    // initiating global, including WorkerGlobalScope (not its owner Window).
    let value = host_resource_timing_value(ctx, &data);
    let _ = platform_control(ctx).and_then(|host| {
        let function = ctx.member_get(&host, "recordResourceTimingPacked")?;
        ctx.invoke(function, host, &[value])
    });
}

/// XMLHttpRequest's synchronous flag uses HTML's pause semantics. The network future runs on the
/// application runtime while only this page thread waits, avoiding a nested Tokio `block_on`.
fn host_http_fetch(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let started = crate::performance::now_ms();
    // A body whose selected file can no longer be read is a network error.
    let Ok((target, method, body, headers, policy)) = host_fetch_args(ctx, args) else {
        return Ok(Value::Null);
    };
    let initiator = resource_initiator(ctx, args);
    let client = request_client_url(ctx);
    let cookie_context = request_cookie_context(ctx);
    let (referrer, referrer_policy) = script_request_referrer(ctx, args, 12);
    let context = ctx.host_job_context();
    if std::env::var_os("TRUST_TRACE_FETCH").is_some() {
        eprintln!(
            "[fetch-trace] @{:>6}ms sync {method} {target}",
            crate::http::trace_ms()
        );
    }
    let use_cors_preflight = host_fetch_use_cors_preflight(args);
    let work = ctx.host_mut::<HostState>().and_then(|state| {
        let prepared =
            prepare_client_request(state, &client, &target, method, body, headers, policy);
        prepared.map(|(handle, cache, mut request)| {
            request.cookie_context = Some(cookie_context);
            request.use_cors_preflight = use_cors_preflight;
            apply_request_referrer(state, context, &referrer, referrer_policy, &mut request);
            (handle, cache, request)
        })
    });
    let (result, timing) = match work {
        Some((handle, cache, request)) => {
            let (sender, receiver) = std::sync::mpsc::channel();
            cache.spawn(&handle, async move {
                let name = request.url.to_string();
                let result = crate::http::fetch_script_with_timing(&request).await;
                let _ = sender.send(timed_fetch_result(result, name, initiator, started));
            });
            receiver.recv().unwrap_or((None, None))
        }
        None => (None, None),
    };
    record_resource_timing(ctx, timing);
    Ok(host_fetch_result_value(ctx, result))
}

/// HTML's Document-creation steps retain the navigation request's final
/// referrer. Keep it alongside Fetch's final URL, not a guessed parent URL.
/// A prepared nested-navigable navigation request (HTML #navigate-fetch).
struct NavigationFetch {
    handle: tokio::runtime::Handle,
    cache: Arc<crate::http::PageCache>,
    request: crate::http::Request,
    policy: crate::referrer_policy::ReferrerPolicy,
    node: Option<usize>,
    target: String,
    destination: &'static str,
}

fn prepare_navigation_fetch(ctx: &mut Ctx, args: &[Value]) -> Option<NavigationFetch> {
    use crate::referrer_policy::ReferrerPolicy;
    let target = host_arg_usv(ctx, args, 0);
    // The container's referrer policy attribute (reflected, limited to known values); the
    // empty string uses the navigating Document's policy container's policy.
    let attribute_policy = ReferrerPolicy::parse(&host_arg_usv(ctx, args, 2));
    let calling = ctx.host_job_context();
    let node = {
        let dom = host_dom(ctx);
        let dom = dom.borrow();
        host_arg_node(&dom, args, 3)
    };
    let client = match node {
        Some(node) => element_request_client_url(ctx, node),
        None => request_client_url(ctx),
    };
    let cookie_context = match node {
        Some(node) => element_cookie_context(ctx, node),
        None => request_cookie_context(ctx),
    };
    let destination =
        if node.is_some_and(|node| host_dom(ctx).borrow().tag_name(node) == Some("frame")) {
            "frame"
        } else {
            "iframe"
        };
    let state = ctx.host_mut::<HostState>()?;
    let context = match node {
        Some(node) => {
            let dom = state.dom.clone();
            let dom = dom.borrow();
            node_window_context(state, &dom, node).unwrap_or(calling)
        }
        None => calling,
    };
    let (handle, cache, mut request) = prepare_client_request(
        state,
        &client,
        &target,
        "GET".into(),
        None,
        Vec::new(),
        None,
    )?;
    crate::http::set_fetch_metadata(&mut request, &client, destination, "navigate");
    request.cookie_context = Some(cookie_context);
    apply_request_referrer(
        state,
        context,
        &RequestReferrer::Client,
        attribute_policy,
        &mut request,
    );
    let policy = attribute_policy.unwrap_or_else(|| environment_referrer_policy(state, context));
    Some(NavigationFetch {
        handle,
        cache,
        request,
        policy,
        node,
        target,
        destination,
    })
}

/// A synchronous navigation fetch, for one-shot document transforms and a
/// script's first read of a frame that has not been navigated yet.
fn host_http_navigate(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let Some(navigation) = prepare_navigation_fetch(ctx, args) else {
        return Ok(Value::Null);
    };
    let NavigationFetch {
        handle,
        cache,
        request,
        policy,
        node,
        target,
        destination,
    } = navigation;
    let (sender, receiver) = std::sync::mpsc::channel();
    cache.spawn(&handle, async move {
        let _ = sender.send(
            crate::http::fetch_with_metadata(&request, policy)
                .await
                .ok(),
        );
    });
    let Some(details) = receiver.recv().ok().flatten() else {
        return Ok(Value::Null);
    };
    navigation_result_value(ctx, details, node, &target, destination)
}

/// HTML #navigate: the fetch runs in parallel and its response is processed
/// by a later task, so a slow frame server never blocks the parent's event
/// loop (ad iframes held hanime.moe's page thread, and its clicks, for
/// seconds). Resolves with the same record as `__http_navigate`, or null.
fn host_http_navigate_async(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let (promise, resolve, _reject) = ctx.new_promise_with_resolvers();
    let context = ctx.host_job_context();
    let navigation = prepare_navigation_fetch(ctx, args);
    let dispatch = navigation.and_then(|navigation| {
        let state = ctx.host_mut::<HostState>()?;
        let events = state.task_events.clone()?;
        let network = state.network.as_mut()?;
        let id = network.next_fetch_id;
        network.next_fetch_id += 1;
        network.pending_fetches.insert(
            id,
            LumenPendingFetch {
                context,
                resolve: resolve.clone(),
                native_lease: None,
                keepalive: false,
                task: None,
            },
        );
        Some((id, events, navigation))
    });
    let Some((id, events, navigation)) = dispatch else {
        let _ = ctx.invoke(resolve, Value::Undefined, &[Value::Null]);
        return Ok(promise);
    };
    let NavigationFetch {
        handle,
        cache,
        request,
        policy,
        node,
        target,
        destination,
    } = navigation;
    let work = async move {
        let details = crate::http::fetch_with_metadata(&request, policy)
            .await
            .ok()
            .map(Box::new);
        let _ = events.send(LumenHostTask::NavigateDone {
            id,
            details,
            node,
            target,
            destination,
        });
    };
    // The navigation request's client is the navigating Document: stopping
    // it aborts this fetch (HTML #abort-a-document, `abort_document_fetches`).
    let task = cache.task_scope().spawn_abortable(&handle, work, false);
    if let Some(pending) = ctx
        .host_mut::<HostState>()
        .and_then(|state| state.network.as_mut())
        .and_then(|network| network.pending_fetches.get_mut(&id))
    {
        pending.task = task;
    }
    Ok(promise)
}

fn navigation_result_value(
    ctx: &mut Ctx,
    details: crate::http::FetchResponseDetails,
    node: Option<usize>,
    target: &str,
    destination: &str,
) -> Result<Value, Value> {
    let final_url = details.response.url.to_string();
    let referrer = details.referrer;
    // HTML #creating-a-policy-container-from-a-fetch-response: the response's
    // `Referrer-Policy` (Referrer Policy #parse-referrer-policy-from-header).
    let response_policy =
        crate::referrer_policy::ReferrerPolicy::from_headers(&details.response.headers)
            .map_or("", crate::referrer_policy::ReferrerPolicy::as_str);
    let timing = match details.response.timing.as_ref() {
        Some(timing) => host_navigation_timing_value(ctx, timing, &final_url)?,
        None => Value::Null,
    };
    // HTML #create-navigation-params-by-fetching / #iframe-load-event-steps:
    // permitted navigation timings report at Fetch completion; otherwise the
    // container measures only its fallback lifetime at the element load task.
    // The child's NavigationTiming has different exposure rules and MUST NOT
    // be reused as the parent's ResourceTiming entry.
    let resource_timing = match details.response.timing.as_ref() {
        Some(timing) if node.is_some() && timing.resource_timing_allowed => {
            host_timing_data_value(ctx, &timing.resource_data(target, destination))?
        }
        _ => Value::Null,
    };
    let result = lumen_fetch_result(details.response);
    let result = host_fetch_result_value(ctx, result);
    ctx.member_set(&result, "5", Value::from_string(final_url))?;
    ctx.member_set(&result, "6", Value::from_string(referrer))?;
    ctx.member_set(&result, "7", timing)?;
    ctx.member_set(&result, "8", resource_timing)?;
    ctx.member_set(
        &result,
        "9",
        Value::from_string(String::from(response_policy)),
    )?;
    Ok(result)
}

fn host_navigation_timing_value(
    ctx: &mut Ctx,
    timing: &crate::http::FetchTiming,
    url: &str,
) -> Result<Value, Value> {
    let data = timing.navigation_data(url);
    host_timing_data_value(ctx, &data)
}

fn host_timing_data_value(ctx: &mut Ctx, data: &serde_json::Value) -> Result<Value, Value> {
    let object = ctx.new_object_with_proto(&Value::Null);
    // Closed native scalar record: no author getters, response header objects,
    // source evaluation, or public JSON.parse operation is involved.
    if let Some(fields) = data.as_object() {
        for (key, field) in fields {
            let value = match field {
                serde_json::Value::Number(number) => Value::Num(number.as_f64().unwrap_or(0.0)),
                serde_json::Value::String(text) => Value::from_string(text.clone()),
                _ => Value::Null,
            };
            ctx.member_set(&object, key, value)?;
        }
    }
    Ok(object)
}

fn host_resource_timing_value(ctx: &mut Ctx, data: &serde_json::Value) -> Value {
    // Private, ownership-transferred scalar tuple, matching resourceNumbers /
    // resourceStrings in js_platform.js. The shared native privacy filter has
    // already coarsened timestamps and applied TAO/body/status restrictions.
    // Avoid named property insertion and a second per-field JS copy for every
    // completed request, even when no author ever inspects its timing entry.
    const NUMBERS: [&str; 19] = [
        "startTime",
        "workerStart",
        "redirectStart",
        "redirectEnd",
        "fetchStart",
        "domainLookupStart",
        "domainLookupEnd",
        "connectStart",
        "connectEnd",
        "secureConnectionStart",
        "requestStart",
        "firstInterimResponseStart",
        "finalResponseHeadersStart",
        "responseStart",
        "responseEnd",
        "transferSize",
        "encodedBodySize",
        "decodedBodySize",
        "responseStatus",
    ];
    const STRINGS: [&str; 6] = [
        "initiatorType",
        "deliveryType",
        "nextHopProtocol",
        "renderBlockingStatus",
        "contentType",
        "contentEncoding",
    ];
    let mut fields = Vec::with_capacity(26);
    fields.push(Value::from_string(
        data["name"].as_str().unwrap_or("").to_owned(),
    ));
    fields.extend(
        NUMBERS
            .iter()
            .map(|name| Value::Num(data[name].as_f64().unwrap_or(0.0))),
    );
    fields.extend(
        STRINGS
            .iter()
            .map(|name| Value::from_string(data[name].as_str().unwrap_or("").to_owned())),
    );
    ctx.make_array(fields)
}

enum AsyncFetchSource {
    Cached(crate::http::SharedFetch),
    Request(Box<crate::http::Request>),
}

/// Fetch API §5.6 creates and returns a Promise before Fetch runs in parallel. Only Send response
/// data crosses the runtime channel; the resolving function remains rooted in the page realm and
/// is invoked later when the browser selects the networking task.
fn host_http_fetch_async(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    // A body whose selected file can no longer be read is a network error.
    let Ok((target, method, body, headers, policy)) = host_fetch_args(ctx, args) else {
        let (promise, resolve, _reject) = ctx.new_promise_with_resolvers();
        let _ = ctx.invoke(resolve, Value::Undefined, &[Value::Null]);
        return Ok(promise);
    };
    let initiator = resource_initiator(ctx, args);
    // The caller reads the response body as it arrives (Fetch
    // #concept-http-network-fetch); otherwise it needs the whole body at once.
    let stream_body = matches!(args.get(8), Some(Value::Bool(true)));
    // Fetch #concept-request-cache-mode: these modes never use a stored
    // response, including one the document's own loads put in the page cache.
    let bypass_cache = matches!(
        host_arg_string(ctx, args, 9).as_str(),
        "no-store" | "reload" | "no-cache"
    );
    let use_cors_preflight = host_fetch_use_cors_preflight(args);
    // Argument 11: the request's keepalive (Fetch #request-keepalive-flag).
    let keepalive = matches!(args.get(11), Some(Value::Bool(true)));
    // Arguments 12 and 13: the request's referrer and referrer policy.
    let (referrer, referrer_policy) = script_request_referrer(ctx, args, 12);
    let started = crate::performance::now_ms();
    let client = request_client_url(ctx);
    let cookie_context = request_cookie_context(ctx);
    let resource_name = client
        .join(&target)
        .map_or_else(|_| String::new(), |url| url.to_string());
    if std::env::var_os("TRUST_TRACE_FETCH").is_some() {
        eprintln!(
            "[fetch-trace] @{:>6}ms async {method} {target}",
            crate::http::trace_ms()
        );
    }
    let (promise, resolve, _reject) = ctx.new_promise_with_resolvers();
    let context = ctx.host_job_context();

    let dispatch = {
        let Some(state) = ctx.host_mut::<HostState>() else {
            let _ = ctx.invoke(resolve, Value::Undefined, &[Value::Null]);
            return Ok(promise);
        };
        // Script Fetch requests carry mode/credentials and therefore need the
        // response CORS/opaque filtering below. The generic page cache stores
        // only wire bytes, so bypass it here rather than accidentally exposing
        // an unfiltered cached cross-origin response. Browser-owned resource
        // fetches continue to use the cache through `spawn_resource_fetch`.
        let cache_safe_for_policy = policy.is_none()
            || client
                .join(&target)
                .ok()
                .is_some_and(|url| crate::http::same_origin_for_host(&client, &url));
        let cached =
            if cache_safe_for_policy && !cookie_context.cross_site_ancestor && !bypass_cache {
                state.network.as_ref().and_then(|network| {
                    (method.eq_ignore_ascii_case("GET") && body.is_none())
                        .then(|| client.join(&target).ok())
                        .flatten()
                        .and_then(|url| network.cache.peek(&url))
                        .filter(|shared| {
                            policy.is_none()
                                || shared.peek().is_some_and(|result| {
                                    result.as_ref().is_ok_and(|response| {
                                        !response.url_list.is_empty()
                                            && response.url_list.iter().all(|url| {
                                                crate::http::same_origin_for_host(&client, url)
                                            })
                                    })
                                })
                        })
                })
            } else {
                None
            };
        let source = match cached {
            Some(shared) => Some(AsyncFetchSource::Cached(shared)),
            None => prepare_client_request(state, &client, &target, method, body, headers, policy)
                .map(|(_, _, mut request)| {
                    request.cookie_context = Some(cookie_context);
                    request.use_cors_preflight = use_cors_preflight;
                    apply_request_referrer(
                        state,
                        context,
                        &referrer,
                        referrer_policy,
                        &mut request,
                    );
                    AsyncFetchSource::Request(Box::new(request))
                }),
        };
        let events = state.task_events.clone();
        match (state.network.as_mut(), source, events) {
            (Some(network), Some(source), Some(events)) => {
                let id = network.next_fetch_id;
                network.next_fetch_id += 1;
                network.pending_fetches.insert(
                    id,
                    LumenPendingFetch {
                        context,
                        resolve: resolve.clone(),
                        native_lease: None,
                        keepalive,
                        task: None,
                    },
                );
                Some((
                    id,
                    network.handle.clone(),
                    network.cache.clone(),
                    events,
                    source,
                ))
            }
            _ => None,
        }
    };

    let Some((id, handle, cache, events, source)) = dispatch else {
        let _ = ctx.invoke(resolve, Value::Undefined, &[Value::Null]);
        return Ok(promise);
    };
    let work = async move {
        let (result, timing) = match source {
            AsyncFetchSource::Cached(shared) => match shared.await {
                Ok(response) => {
                    let timing = response
                        .timing
                        .clone()
                        .filter(|_| !initiator.is_empty())
                        .map(|previous| {
                            // A new script Fetch using a completed page-cache body
                            // has its own lifetime, not the old connection's times.
                            let timing = Box::new(crate::http::FetchTiming {
                                start_time: started,
                                fetch_start: started,
                                domain_lookup_start: started,
                                domain_lookup_end: started,
                                connect_start: started,
                                connect_end: started,
                                request_start: started,
                                final_response_start: started,
                                response_end: crate::performance::now_ms(),
                                encoded_body_size: previous.encoded_body_size,
                                decoded_body_size: previous.decoded_body_size,
                                content_type: previous.content_type,
                                content_encoding: previous.content_encoding,
                                resource_timing_allowed: true,
                                resource_body_exposed: true,
                                resource_response_status: response.status,
                                ..Default::default()
                            });
                            LumenResourceTiming {
                                name: resource_name,
                                initiator,
                                timing,
                                cached: true,
                            }
                        });
                    (lumen_cached_result(&response), timing)
                }
                Err(()) => (None, None),
            },
            AsyncFetchSource::Request(request) if stream_body => {
                let name = request.url.to_string();
                match crate::http::fetch_script_streaming(&request).await {
                    Ok((response, Some(body))) => {
                        let (result, timing) =
                            timed_fetch_result(Ok(response), name, initiator, started);
                        stream_fetch_body(id, result, timing, body, events).await;
                        return;
                    }
                    Ok((response, None)) => {
                        timed_fetch_result(Ok(response), name, initiator, started)
                    }
                    Err(error) => timed_fetch_result(Err(error), name, initiator, started),
                }
            }
            AsyncFetchSource::Request(request) => {
                let name = request.url.to_string();
                timed_fetch_result(
                    crate::http::fetch_script_with_timing(&request).await,
                    name,
                    initiator,
                    started,
                )
            }
        };
        let _ = events.send(LumenHostTask::FetchDone { id, result, timing });
    };
    let task = cache.task_scope().spawn_abortable(&handle, work, keepalive);
    // HTML #abort-a-document aborts this task with the document's other
    // fetches (`abort_document_fetches`).
    if let Some(pending) = ctx
        .host_mut::<HostState>()
        .and_then(|state| state.network.as_mut())
        .and_then(|network| network.pending_fetches.get_mut(&id))
    {
        pending.task = task;
    }
    Ok(promise)
}

/// Fetch #concept-http-network-fetch's in-parallel body steps for a response
/// that has been handed to script: queue the head, then each decoded piece
/// of the body, then its end, as networking tasks for the fetch's global.
/// The transfer suspends while the body's stream leaves too many bytes
/// unpulled, and stops when the fetch is aborted or its stream canceled.
async fn stream_fetch_body(
    id: usize,
    result: LumenFetchResult,
    timing: Option<LumenResourceTiming>,
    mut body: crate::http::BodyStream,
    events: LumenTaskSender,
) {
    /// A transfer abandoned by its task (the document stopped loading or
    /// was unloaded) ends its body with a network error, as Fetch
    /// #fetch-controller-terminate requires, instead of leaving it pending.
    struct EndOnDrop {
        id: usize,
        events: Option<LumenTaskSender>,
    }
    impl Drop for EndOnDrop {
        fn drop(&mut self) {
            if let Some(events) = self.events.take() {
                let _ = events.send(LumenHostTask::FetchBodyEnd {
                    id: self.id,
                    ok: false,
                    timing: None,
                });
            }
        }
    }
    let flow = crate::http::BodyFlow::new();
    if events
        .send(LumenHostTask::FetchHead {
            id,
            result,
            flow: flow.clone(),
        })
        .is_err()
    {
        return;
    }
    let mut guard = EndOnDrop {
        id,
        events: Some(events.clone()),
    };
    let outcome = crate::http::pump(&mut body, &flow, |bytes| {
        events
            .send(LumenHostTask::FetchBodyChunk { id, bytes })
            .is_ok()
    })
    .await;
    guard.events = None;
    if std::env::var_os("TRUST_TRACE_FETCH").is_some() {
        eprintln!(
            "[fetch-trace] body id={id} end={outcome:?} encoded={} decoded={}",
            body.encoded_size(),
            body.decoded_size()
        );
    }
    let ok = match outcome {
        // Canceled: the consumer is gone and nothing more is queued.
        Ok(false) => return,
        Ok(true) => true,
        Err(_) => false,
    };
    let timing = timing.map(|mut report| {
        report.timing.response_end = crate::performance::now_ms();
        report.timing.encoded_body_size = body.encoded_size();
        report.timing.decoded_body_size = body.decoded_size();
        report
    });
    let _ = events.send(LumenHostTask::FetchBodyEnd { id, ok, timing });
}

fn body_stream_id(args: &[Value]) -> Option<usize> {
    args.first()
        .and_then(Value::as_num_opt)
        .and_then(|id| (id.is_finite() && id >= 0.0 && id.fract() == 0.0).then_some(id as usize))
}

/// The response body stream's pullAlgorithm (Fetch #concept-http-network-fetch):
/// a promise for the bytes buffered for fetch `id` (an ArrayBuffer), once there
/// are any; `null` at the end of the body; `false` after a network error or
/// when the transfer no longer exists.
fn host_http_fetch_pull(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    enum Ready {
        Bytes(Vec<u8>),
        End(bool),
        Wait(Option<Value>),
    }
    let (promise, resolve, _reject) = ctx.new_promise_with_resolvers();
    let id = body_stream_id(args);
    let ready = match ctx
        .host_mut::<HostState>()
        .and_then(|state| state.network.as_mut())
        .zip(id)
    {
        None => Ready::End(false),
        Some((network, id)) => match network.body_streams.get_mut(&id) {
            None => Ready::End(false),
            Some(stream) if !stream.buffer.is_empty() => {
                let bytes = std::mem::take(&mut stream.buffer);
                stream.flow.taken(bytes.len());
                Ready::Bytes(bytes)
            }
            Some(stream) => match stream.end {
                Some(ok) => {
                    network.body_streams.remove(&id);
                    Ready::End(ok)
                }
                None => Ready::Wait(stream.pull.replace(resolve.clone())),
            },
        },
    };
    match ready {
        Ready::Bytes(bytes) => {
            let value = ctx.make_array_buffer(&bytes).unwrap_or(Value::Bool(false));
            ctx.invoke(resolve, Value::Undefined, &[value])?;
        }
        Ready::End(ok) => {
            let value = if ok { Value::Null } else { Value::Bool(false) };
            ctx.invoke(resolve, Value::Undefined, &[value])?;
        }
        // A stream has one pull in flight; a superseded one fails.
        Ready::Wait(Some(previous)) => {
            ctx.invoke(previous, Value::Undefined, &[Value::Bool(false)])?;
        }
        Ready::Wait(None) => {}
    }
    Ok(promise)
}

/// Abort or terminate fetch `id`'s transfer: its body's stream was canceled,
/// the fetch was aborted, or the stream was garbage collected.
fn host_http_fetch_cancel(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let stream = ctx
        .host_mut::<HostState>()
        .and_then(|state| state.network.as_mut())
        .zip(body_stream_id(args))
        .and_then(|(network, id)| network.body_streams.remove(&id));
    if let Some(mut stream) = stream {
        stream.flow.cancel();
        if let Some(pull) = stream.pull.take() {
            ctx.invoke(pull, Value::Undefined, &[Value::Bool(false)])?;
        }
    }
    Ok(Value::Undefined)
}

/// HTML #dom-window-stop: "If this's navigable is null, then return" ran in
/// the prelude; stop loading this Window's navigable.
fn host_stop_loading(ctx: &mut Ctx, _this: Value, _args: &[Value]) -> Result<Value, Value> {
    let context = ctx.host_job_context();
    stop_loading_navigable(ctx, context);
    Ok(Value::Undefined)
}

/// HTML #nav-stop ("stop loading", local whatwg/html@e5071a2) for the
/// navigable whose active Document belongs to Window `context`, run in a task
/// of that Document's event loop, from `window.stop()` or the user agent's
/// stop for the top-level navigable (`PageCmd::StopLoading`). Returns whether
/// anything was loading.
fn stop_loading_navigable(ctx: &mut Ctx, context: u64) -> bool {
    // Step 2: TRust's ongoing navigation of this navigable is the one its
    // Window requested in the running task (the frontend starts it only after
    // the task), so setting the ongoing navigation to null discards that
    // request. TRust runs no unload steps in a live Document: its unload
    // counter is 0.
    let navigation = call_trust_in_context(ctx, context, "cancelNavigation")
        .is_some_and(|value| ctx.to_boolean(&value));
    // Step 3, #abort-a-document-and-its-descendants: queue a global task on
    // the navigation and traversal task source to abort each descendant
    // navigable's active Document, then abort this Document.
    let (descendants, events) = match ctx.host_mut::<HostState>() {
        Some(state) => (
            descendant_contexts(state, context),
            state.task_events.clone(),
        ),
        None => (Vec::new(), None),
    };
    if let Some(events) = events {
        for descendant in descendants {
            let _ = events.send(LumenHostTask::AbortDocument {
                context: descendant,
            });
        }
    }
    abort_document(ctx, context) || navigation
}

/// The descendant navigables of Window `context`'s Document (HTML
/// #descendant-navigables), as the Window Realms of their active Documents:
/// each child, in creation order, followed by its own descendants.
fn descendant_contexts(state: &HostState, context: u64) -> Vec<u64> {
    fn visit(children: &[(u64, u64)], parent: u64, root: u64, found: &mut Vec<u64>) {
        for &(owner, child) in children {
            if owner == parent && child != root && !found.contains(&child) {
                found.push(child);
                visit(children, child, root, found);
            }
        }
    }
    let mut children: Vec<_> = state
        .window_parents
        .iter()
        .filter(|&(child, _)| state.window_realms.contains_key(child))
        .map(|(&child, &parent)| (parent, child))
        .collect();
    children.sort_unstable();
    let mut found = Vec::new();
    visit(&children, context, context, &mut found);
    found
}

/// Call a platform-control operation of Window `context`'s Realm.
fn call_trust_in_context(ctx: &mut Ctx, context: u64, name: &str) -> Option<Value> {
    if context == ctx.host_job_context() {
        return host_call_trust(ctx, name, &[]).ok();
    }
    let realm = ctx
        .host_mut::<HostState>()
        .and_then(|state| state.window_realms.get(&context).cloned())?;
    ctx.with_embed_realm(&realm, |realm_ctx| {
        host_call_trust(realm_ctx, name, &[]).ok()
    })
    .ok()
    .flatten()
}

/// HTML #abort-a-document for Window `context`'s Document, in a task of its
/// event loop. Returns whether this canceled anything.
fn abort_document(ctx: &mut Ctx, context: u64) -> bool {
    // Step 2: cancel the fetches in the context of the document. Its Realm
    // aborts its fetch group first, producing the script-visible results
    // (fetch() rejects with an "AbortError" DOMException, XMLHttpRequest
    // runs its request error steps for "abort", an EventSource fails its
    // connection, a connecting WebSocket fails); the host then stops their
    // network work and discards their queued networking tasks.
    let mut canceled = call_trust_in_context(ctx, context, "abortDocumentFetches")
        .is_some_and(|value| ctx.to_boolean(&value));
    canceled |= abort_document_fetches(ctx, context);
    // A worker's own script fetch stays: its request is a non-subresource
    // request (destination "worker"/"sharedworker") whose reserved client
    // is the worker's environment, so Fetch #concept-fetch never
    // records it in this Document's fetch group (#concept-fetch-group); it
    // belongs to the worker being created, as a navigation's fetch belongs
    // to its navigable, and HTML #run-a-worker continues.
    // (Step 3 concerns WebDriver BiDi, which TRust does not implement.)
    // Step 4: the active parser, which only the top-level Document's
    // `load_page` runs.
    if context == 0 {
        canceled |= abort_active_parser(ctx);
    }
    canceled
}

/// The host half of HTML #abort-a-document step 2 for Window `context`'s
/// Document: abort the network tasks of its fetches (keepalive ones excepted,
/// Fetch #concept-fetch-group-terminate), discard their queued networking
/// tasks by forgetting them (a `FetchHead`/`FetchDone`/`NavigateDone`/
/// `ImageDone` for a forgotten id is inert), and settle each fetch's waiting
/// consumer as a network failure. Response bodies still arriving stop. The
/// top-level Document also cancels the browser's own subresource fetches and
/// image requests (`PageCache::stop_loading`).
fn abort_document_fetches(ctx: &mut Ctx, context: u64) -> bool {
    let Some(network) = ctx
        .host_mut::<HostState>()
        .and_then(|state| state.network.as_mut())
    else {
        return false;
    };
    let ids: Vec<usize> = network
        .pending_fetches
        .iter()
        .filter(|(_, pending)| pending.context == context && !pending.keepalive)
        .map(|(&id, _)| id)
        .collect();
    let pending: Vec<LumenPendingFetch> = ids
        .iter()
        .filter_map(|id| network.pending_fetches.remove(id))
        .collect();
    let streams: Vec<LumenBodyStream> = {
        let ids: Vec<usize> = network
            .body_streams
            .iter()
            .filter(|(_, stream)| stream.context == context)
            .map(|(&id, _)| id)
            .collect();
        ids.iter()
            .filter_map(|id| network.body_streams.remove(id))
            .collect()
    };
    let resources = context == 0 && network.cache.stop_loading();
    let canceled = resources || !pending.is_empty() || !streams.is_empty();
    for mut stream in streams {
        stream.flow.cancel();
        if let Some(pull) = stream.pull.take() {
            let _ = ctx.invoke(pull, Value::Undefined, &[Value::Bool(false)]);
        }
    }
    for pending in pending {
        if let Some(task) = &pending.task {
            task.abort();
        }
        // A network error for a consumer that has not settled it already
        // (fetch, XMLHttpRequest and EventSource settled theirs as aborted).
        let _ = ctx.invoke(pending.resolve, Value::Undefined, &[Value::Null]);
        drop(pending.native_lease);
    }
    canceled
}

/// HTML #abort-a-document step 4 for the top-level Document: if it has an
/// active parser, set its active parser was aborted to true and abort that
/// parser (#abort-a-parser). Returns whether there was one.
fn abort_active_parser(ctx: &mut Ctx) -> bool {
    let (position, watermark) = {
        let Some(state) = ctx.host_mut::<HostState>() else {
            return false;
        };
        let parser = &mut state.parser;
        if !parser.active || parser.aborted {
            return false;
        }
        parser.aborted = true;
        (parser.position, parser.watermark)
    };
    // #abort-a-parser step 1: throw away any pending content in the input
    // stream. The tree builder already consumed all of it, so remove the
    // nodes it built after the parser's position (the script it last
    // reached): they would not exist yet. Nodes scripts created stay.
    if let Some(position) = position {
        let pending = |id: usize| id > position && id < watermark;
        let handle = host_dom(ctx);
        let mut dom = handle.borrow_mut();
        let roots: Vec<usize> = (position + 1..watermark)
            .filter(|&id| {
                dom.is_valid(id) && dom.node(id).parent.is_some_and(|parent| !pending(parent))
            })
            .collect();
        for root in roots {
            dom.detach(root);
        }
    }
    // Step 2 stops the speculative parser: TRust's speculative fetches are
    // the document's fetches step 2 of #abort-a-document canceled. Steps 3-5
    // update the current document readiness to "interactive" and then
    // "complete" (each firing readystatechange) around popping the stack of
    // open elements, which the tree builder already did.
    let _ = call_trust_in_context(ctx, 0, "abortParser");
    true
}

/// Run `run` in the Realm of the environment `context`; a task for an
/// environment whose Document is no longer active does not run.
fn run_in_context_realm(
    engine: &mut lumen::Engine,
    context: u64,
    label: &str,
    run: impl FnOnce(&mut lumen::Engine) -> Result<(), String>,
) -> Result<(), String> {
    if context == engine.ctx().host_job_context() {
        return run(engine);
    }
    let realm = engine
        .ctx()
        .host_mut::<HostState>()
        .and_then(|state| state.window_realms.get(&context).cloned());
    let Some(realm) = realm else {
        return Ok(());
    };
    match engine.with_embed_realm(&realm, run) {
        Ok(result) => result,
        Err(error) => {
            let message = engine
                .ctx()
                .coerce_string(&error)
                .map(|message| message.to_string())
                .unwrap_or_else(|_| String::from("unknown Window Realm"));
            Err(format!("{label} Realm: {message}"))
        }
    }
}

/// Settle fetch `id`'s pending body pull when bytes or the end are available
/// (#concept-http-network-fetch pullAlgorithm: pull from bytes into stream).
fn settle_body_pull(engine: &mut lumen::Engine, id: usize) -> Result<(), String> {
    let ready = {
        let Some(network) = engine
            .ctx()
            .host_mut::<HostState>()
            .and_then(|state| state.network.as_mut())
        else {
            return Ok(());
        };
        let Some(stream) = network.body_streams.get_mut(&id) else {
            return Ok(());
        };
        let context = stream.context;
        match stream.pull.take() {
            None => return Ok(()),
            Some(pull) if !stream.buffer.is_empty() => {
                let bytes = std::mem::take(&mut stream.buffer);
                stream.flow.taken(bytes.len());
                (context, pull, Ok(bytes))
            }
            Some(pull) => match stream.end {
                Some(ok) => {
                    network.body_streams.remove(&id);
                    (context, pull, Err(ok))
                }
                None => {
                    stream.pull = Some(pull);
                    return Ok(());
                }
            },
        }
    };
    let (context, pull, ready) = ready;
    run_in_context_realm(engine, context, "fetch body task", move |engine| {
        let value = match ready {
            Ok(bytes) => engine
                .ctx()
                .make_array_buffer(&bytes)
                .unwrap_or(Value::Bool(false)),
            Err(true) => Value::Null,
            Err(false) => Value::Bool(false),
        };
        engine
            .call_function_interruptible(&pull, Value::Undefined, &[value])
            .map(|_| ())
            .map_err(|error| describe_eval_error(engine, error, "fetch body task"))
    })
}

fn host_trust(ctx: &mut Ctx) -> Result<Value, Value> {
    platform_control(ctx)
}

fn host_call_trust(ctx: &mut Ctx, name: &str, args: &[Value]) -> Result<Value, Value> {
    let trust = host_trust(ctx)?;
    let function = ctx.member_get(&trust, name)?;
    ctx.invoke(function, trust, args)
}

/// [`host_call_trust`] for a host task outside any native function, where a host interruption
/// must stay distinct from a JavaScript throw.
fn host_call_trust_interruptible(
    ctx: &mut Ctx,
    name: &str,
    args: &[Value],
) -> Result<Value, EvalError> {
    let trust = host_trust(ctx).map_err(EvalError::Throw)?;
    let function = ctx.member_get(&trust, name).map_err(EvalError::Throw)?;
    ctx.invoke_interruptible(function, trust, args)
}

/// A host task's JavaScript failure as its error report: a throw is described; an interruption
/// is reported unless it is a navigation or cancellation, which ends the task silently.
fn host_task_failure(ctx: &mut Ctx, error: EvalError, label: &str) -> Result<(), String> {
    match error {
        EvalError::Interrupted(
            lumen::InterruptReason::UserNavigation | lumen::InterruptReason::Cancelled,
        ) => Ok(()),
        EvalError::Interrupted(reason) => Err(format!("{label} interrupted: {}", reason.message())),
        EvalError::Throw(error) => Err(ctx
            .coerce_string(&error)
            .map(|message| format!("{label}: {message}"))
            .unwrap_or_else(|_| format!("{label} failed"))),
    }
}

fn host_allocate_job_context(ctx: &mut Ctx, _this: Value, _args: &[Value]) -> Result<Value, Value> {
    const MAX_SAFE_INTEGER: u64 = (1_u64 << 53) - 1;
    let Some(state) = ctx.host_mut::<HostState>() else {
        return Err(ctx.make_error("InvalidStateError", "missing browser host state"));
    };
    let context = state.next_window_context;
    if context > MAX_SAFE_INTEGER {
        return Err(ctx.make_error(
            "QuotaExceededError",
            "exhausted HTML environment-settings identifiers",
        ));
    }
    state.next_window_context = context.saturating_add(1);
    Ok(Value::Num(context as f64))
}

/// Developer traces a main Window's platform bootstrap reads from `__trust_cfg`.
#[derive(Clone, Copy, Default)]
struct MainWindowTraces {
    frames: bool,
    challenge_messages: bool,
}

impl MainWindowTraces {
    fn from_environment() -> Self {
        Self {
            frames: std::env::var_os("TRUST_TRACE_FRAMES").is_some(),
            challenge_messages: std::env::var_os("TRUST_TRACE_CHALLENGE_MESSAGES").is_some(),
        }
    }
}

fn json_string(value: &str) -> String {
    serde_json::to_string(value).unwrap_or_else(|_| String::from("\"\""))
}

/// The `__trust_cfg` script a top-level Window Realm's platform bootstrap consumes.
#[allow(clippy::too_many_arguments)]
fn main_window_config(
    response_url: &url::Url,
    referrer: &str,
    viewport: crate::layout2::Viewport,
    device_pixel_ratio: f32,
    navigation_timing: serde_json::Value,
    last_modified: Option<f64>,
    fullscreen_supported: bool,
    inline_media: bool,
    traces: MainWindowTraces,
) -> String {
    format!(
        "globalThis.__trust_cfg = {{ url: {}, referrer: {}, ua: {}, navigatorMode: {}, platform: {}, language: {}, languages: [{}, {}], width: {}, height: {}, devicePixelRatio: {}, hardwareConcurrency: {}, globalPrivacyControl: {}, secureContext: {}, frameTrace: {}, challengeMessageTrace: {}, navigationTiming: {}, lastModified: {}, fullscreenSupported: {}, inlineMedia: {} }};",
        json_string(response_url.as_str()),
        json_string(referrer),
        json_string(crate::http::user_agent()),
        json_string(crate::http::navigator_compatibility_mode().as_str()),
        json_string(crate::http::navigator_platform()),
        json_string(crate::locale::LANGUAGE),
        json_string(crate::locale::LANGUAGES[0]),
        json_string(crate::locale::LANGUAGES[1]),
        viewport.width,
        viewport.height,
        device_pixel_ratio,
        std::thread::available_parallelism()
            .map(|parallelism| parallelism.get())
            .unwrap_or(8),
        crate::http::GLOBAL_PRIVACY_CONTROL,
        lumen_potentially_trustworthy(response_url),
        traces.frames,
        traces.challenge_messages,
        navigation_timing,
        last_modified.map_or_else(|| String::from("null"), |time| time.to_string()),
        fullscreen_supported,
        inline_media,
    )
}

fn platform_prelude_snapshot() -> Result<&'static [u8], String> {
    static SNAPSHOT: std::sync::OnceLock<Result<Vec<u8>, String>> = std::sync::OnceLock::new();
    // Web IDL platform functions use NativeFunction source syntax. The bootstrap
    // is implementation code, not an author script; do not expose its JS bodies.
    // This policy also follows nested functions created after initial bootstrap.
    match SNAPSHOT.get_or_init(|| {
        lumen::compile_host_snapshot(&crate::js::private_bootstrap(platform_prelude()))
    }) {
        Ok(snapshot) => Ok(snapshot.as_slice()),
        Err(error) => Err(error.clone()),
    }
}

fn eval_platform_prelude(engine: &mut lumen::Engine) -> Result<(), String> {
    let snapshot = platform_prelude_snapshot()?;
    #[cfg(test)]
    let config = test_bootstrap_config(engine.ctx());
    eval_bootstrap_snapshot(engine, snapshot, "TRust platform prelude")?;
    #[cfg(test)]
    expose_platform_internals_for_tests(engine.ctx(), false, config);
    Ok(())
}

/// The configuration object a test fixture installed for the bootstrap to consume.
#[cfg(test)]
fn test_bootstrap_config(ctx: &mut Ctx) -> Value {
    let global = ctx.global_this();
    ctx.member_get(&global, "__trust_cfg")
        .unwrap_or(Value::Undefined)
}

/// Host functions that unit tests call directly from their JavaScript fixtures.
#[cfg(test)]
const TEST_EXPOSED_HOST_FUNCTIONS: &[&str] = &[
    "__dom_allocate_job_context",
    "__dom_create_window_realm",
    "__dom_load_frame",
    "__dom_release_job_context",
    "__dom_rendering_frames",
    "__http_fetch",
];

/// Unit-test fixtures drive the platform through its private control object (`__trust`, or
/// `__wkr` in a worker) and a few host functions. Production bootstraps never do this: only an
/// engine whose test factory set `TestHooks::internals` republishes them, after the
/// private bootstrap has removed the host boundary from the global.
#[cfg(test)]
fn expose_platform_internals_for_tests(ctx: &mut Ctx, worker: bool, config: Value) {
    if !ctx
        .host_mut::<HostState>()
        .is_some_and(|state| state.test_hooks.internals)
    {
        return;
    }
    let Ok(control) = platform_control(ctx) else {
        return;
    };
    let global = ctx.global_this();
    let _ = ctx.member_set(&global, if worker { "__wkr" } else { "__trust" }, control);
    if worker {
        return;
    }
    if matches!(config, Value::Obj(_)) {
        let _ = ctx.member_set(&global, "__trust_cfg", config);
    }
    for &(name, len, host_fn) in LUMEN_HOST_FUNCTIONS {
        if TEST_EXPOSED_HOST_FUNCTIONS.contains(&name) {
            ctx.define_embed_global(name, len, host_fn);
        }
    }
    // Fixtures address nodes by arena id and inspect navigable state through the former
    // property names. The platform itself only reads its internal slots.
    static ACCESSORS: std::sync::OnceLock<Vec<u8>> = std::sync::OnceLock::new();
    let accessors = ACCESSORS.get_or_init(|| {
        lumen::compile_host_snapshot(TEST_INTERNAL_ACCESSORS).expect("test accessors parse")
    });
    let maps = ctx.host_mut::<HostState>().map(|state| {
        [
            state.platform_nodes.clone().unwrap_or(Value::Undefined),
            state.platform_internals.clone().unwrap_or(Value::Undefined),
        ]
    });
    if let (Some(maps), Ok(Ok(installer))) =
        (maps, ctx.eval_classic_snapshot_interruptible(accessors))
    {
        let _ = ctx.invoke(installer, Value::Undefined, &maps);
    }
    ctx.define_embed_global("__window_named_exports", 0, |ctx, _, _| {
        Ok(Value::Num(
            ctx.host_mut::<HostState>()
                .map_or(0, |state| state.test_hooks.window_named_exports) as f64,
        ))
    });
}

/// Test-only accessors for the former wrapper properties. Writing `__id` creates an own data
/// property, as on the old platform, so fixtures can still check that forged ids are ignored;
/// the navigable fields write the platform's internal record, as fixtures set up frame state.
#[cfg(test)]
const TEST_INTERNAL_ACCESSORS: &str = r#"(function (nodeIds, internals) {
    "use strict";
    const get = WeakMap.prototype.get, apply = Reflect.apply, define = Object.defineProperty;
    function shadow(object, name, value) {
        define(object, name, {value, writable: true, enumerable: true, configurable: true});
    }
    if (typeof Node === "function") define(Node.prototype, "__id", {
        configurable: true,
        get() { return apply(get, nodeIds, [this]); },
        set(value) { shadow(this, "__id", value); },
    });
    for (const name of ["contentRealmWindow", "contentDoc", "contentWin", "frame",
        "trustParentWindow", "trustTopWindow", "sr", "frameUrl"]) {
        define(Object.prototype, "__" + name, {
            configurable: true,
            get() {
                const record = apply(get, internals, [this]);
                return record ? record[name] : undefined;
            },
            set(value) {
                let record = apply(get, internals, [this]);
                if (!record) {
                    record = Object.create(null);
                    apply(WeakMap.prototype.set, internals, [this, record]);
                }
                record[name] = value;
            },
        });
    }
})"#;

/// Evaluate a platform prelude source as the private bootstrap does, for tests that assemble
/// their own Realm instead of using `eval_platform_prelude`.
#[cfg(test)]
fn eval_test_bootstrap(
    engine: &mut lumen::Engine,
    source: &str,
    label: &str,
    worker: bool,
) -> Result<(), String> {
    let config = test_bootstrap_config(engine.ctx());
    eval(engine, &crate::js::private_bootstrap(source), label)?;
    expose_platform_internals_for_tests(engine.ctx(), worker, config);
    Ok(())
}

fn worker_prelude_snapshot() -> Result<&'static [u8], String> {
    static SNAPSHOT: std::sync::OnceLock<Result<Vec<u8>, String>> = std::sync::OnceLock::new();
    match SNAPSHOT.get_or_init(|| {
        let override_source = std::env::var_os("TRUST_WORKER_PRELUDE_FILE")
            .and_then(|path| std::fs::read_to_string(path).ok());
        lumen::compile_host_snapshot(&crate::js::private_bootstrap(
            override_source
                .as_deref()
                .unwrap_or_else(|| crate::js::worker_prelude()),
        ))
    }) {
        Ok(snapshot) => Ok(snapshot.as_slice()),
        Err(error) => Err(error.clone()),
    }
}

/// HTML §7.2.2/§7.5.1 creates a fresh Window Realm for a new Document while
/// retaining the browsing context's WindowProxy identity. The native DOM arena
/// remains shared, but author globals, intrinsics, platform prototypes, module
/// maps, and promise-job settings belong to this newly-created Realm.
fn host_create_window_realm(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let context = args
        .first()
        .and_then(Value::as_num_opt)
        .filter(|value| value.is_finite() && *value > 0.0)
        .map_or(0, |value| value as u64);
    if context == 0 {
        return Err(ctx.make_error(
            "InvalidStateError",
            "a Window Realm requires a live environment-settings object",
        ));
    }
    let frame_id = {
        let dom = host_dom(ctx);
        let dom = dom.borrow();
        let Some(frame_id) = host_arg_node(&dom, args, 1) else {
            return Err(ctx.make_error("InvalidStateError", "invalid navigable container"));
        };
        if !matches!(dom.tag_name(frame_id), Some("iframe" | "frame")) {
            return Err(ctx.make_error("InvalidStateError", "invalid navigable container"));
        }
        frame_id
    };

    let url = host_arg_usv(ctx, args, 2);
    let parent_cookie_context = request_cookie_context(ctx);
    let creator_url = request_client_url(ctx);
    let creator_context = ctx.host_job_context();
    let parsed_url = url::Url::parse(&url).unwrap_or_else(|_| creator_url.clone());
    let inherits_origin =
        parsed_url.scheme() == "about" && matches!(parsed_url.path(), "blank" | "srcdoc");
    let client_url = if inherits_origin {
        creator_url
    } else {
        parsed_url.clone()
    };
    let cookie_opaque = host_dom(ctx)
        .borrow()
        .attr(frame_id, "sandbox")
        .is_some_and(|flags| {
            !flags
                .split_ascii_whitespace()
                .any(|flag| flag.eq_ignore_ascii_case("allow-same-origin"))
        });
    let source_config = args.get(3).cloned().unwrap_or(Value::Undefined);
    let parent_window = args.get(4).cloned().unwrap_or(Value::Undefined);
    let top_window = args.get(5).cloned().unwrap_or(Value::Undefined);
    let frame_element = args.get(6).cloned().unwrap_or(Value::Undefined);
    let agent_time_offset = args
        .get(7)
        .and_then(Value::as_num_opt)
        .filter(|value| value.is_finite() && *value >= 0.0)
        .unwrap_or(0.0);
    let referrer = if args
        .get(8)
        .is_some_and(|value| matches!(value, Value::Str(_)))
    {
        host_arg_string(ctx, args, 8)
    } else {
        String::new()
    };
    // Optional document metadata accompanies non-HTML navigations. Keep the
    // required host arity at nine for existing initial about:blank callers.
    let content_type = match args.get(9) {
        Some(value @ Value::Str(_)) => value.as_text().unwrap_or_default().into_owned(),
        _ => String::from("text/html"),
    };
    let navigation_timing = args.get(10).cloned().unwrap_or(Value::Null);
    let about_base_url = args.get(11).cloned().unwrap_or(Value::Null);
    // The navigation response's `Referrer-Policy`, when the document came from one.
    let response_policy =
        crate::referrer_policy::ReferrerPolicy::parse(&host_arg_string(ctx, args, 12));
    let snapshot = platform_prelude_snapshot().map_err(|error| {
        ctx.make_error(
            "SyntaxError",
            format!("compile TRust platform prelude: {error}"),
        )
    })?;
    // Realm creation and bootstrap form one synchronous publication operation.
    // Defer collection across both phases so partially initialized intrinsics
    // cannot be swept before the new global is published.
    ctx.suspend_gc();
    let realm = ctx.create_embed_realm();
    // Root the new Window Realm before running its platform bootstrap. The
    // bootstrap allocates a complete set of intrinsics and may cross an
    // allocation/GC safepoint; the host owns the nascent environment from the
    // moment HTML creates its navigable, even before the child global is
    // published through the iframe element.
    if let Some(state) = ctx.host_mut::<HostState>() {
        state.window_realms.insert(context, realm.clone());
        // HTML #determining-the-origin: about:blank and about:srcdoc inherit their creator's
        // origin; a sandboxed browsing context without allow-same-origin gets a fresh opaque
        // origin; other URLs use their own (blob: URLs their creator's; data: a new opaque one).
        let origin = if cookie_opaque {
            url::Origin::new_opaque()
        } else if inherits_origin {
            realm_origin(state, creator_context)
        } else {
            parsed_url.origin()
        };
        state.realm_origins.insert(context, origin);
        state.frame_contexts.insert(frame_id, context);
        state.window_parents.insert(context, creator_context);
        let mut cookie_context = crate::http::CookieContext::subresource(&client_url);
        cookie_context
            .top_level_site
            .clone_from(&parent_cookie_context.top_level_site);
        cookie_context.cross_site_ancestor = parent_cookie_context.cross_site_ancestor
            || parent_cookie_context
                .client
                .as_ref()
                .is_none_or(|parent| !crate::site_storage::same_site(parent, &client_url));
        if state
            .dom
            .borrow()
            .attr(frame_id, "sandbox")
            .is_some_and(|flags| {
                !flags
                    .split_ascii_whitespace()
                    .any(|flag| flag.eq_ignore_ascii_case("allow-same-origin"))
            })
        {
            cookie_context.cross_site_ancestor = true;
        }
        state
            .dom
            .borrow_mut()
            .set_frame_cookie_restriction(frame_id, cookie_context.cross_site_ancestor);
        // HTML #hostloadimportedmodule for this Window too: its import()s
        // start their fetches as they run (`begin_dynamic_module_fetch`),
        // with the settings `queue_dynamic_module_load` will use.
        if let (Some(network), Some(events)) = (state.network.as_ref(), state.task_events.clone()) {
            let loader = LumenDynamicModuleLoader {
                context,
                page: client_url.clone(),
                cookie_context: cookie_context.clone(),
                // Its storage key and referrer policy are known once the Realm's URL and
                // policy container are (below).
                environment: ModuleFetchEnvironment::default(),
                events,
                import_map: state.import_maps.entry(context).or_default().clone(),
                network: Some(LumenDynamicModuleNetwork {
                    handle: network.handle.clone(),
                    cache: network.cache.clone(),
                    fetched: network.fetched.clone(),
                }),
            };
            state.early_imports.borrow_mut().insert(context, loader);
        }
        state.window_cookie_contexts.insert(
            context,
            (
                frame_id,
                url::Url::parse(&url).unwrap_or_else(|_| client_url.clone()),
                cookie_context,
            ),
        );
        state.window_request_urls.insert(context, client_url);
        // HTML #determining-navigation-params-policy-container: an about:srcdoc document and
        // a local URL's (about:, blob:, data:) clone the navigating Document's policy
        // container; another document creates one from its response. Then the parser
        // inserted the document's `<meta name=referrer>` elements (#meta-referrer).
        let policy = if matches!(parsed_url.scheme(), "about" | "blob" | "data") {
            environment_referrer_policy(state, creator_context)
        } else {
            response_policy.unwrap_or_default()
        };
        let policy = {
            let dom = state.dom.borrow();
            dom.frame_document(frame_id)
                .and_then(|document| dom.parsed_referrer_meta_policy(document))
                .unwrap_or(policy)
        };
        state.referrer_policies.insert(context, policy);
        let environment = ModuleFetchEnvironment {
            blobs: state.blobs.clone(),
            storage_key: blob_storage_key(&realm_origin(state, context)),
            referrer_policy: policy,
        };
        if let Some(loader) = state.early_imports.borrow_mut().get_mut(&context) {
            loader.environment = environment;
        }
    }
    let installed = ctx.with_embed_realm(&realm, |realm_ctx| {
        realm_ctx.set_host_job_context(context);
        for &(name, len, host_fn) in LUMEN_HOST_FUNCTIONS {
            realm_ctx.define_embed_global(name, len, host_fn);
        }

        let config = realm_ctx.new_object_with_proto(&Value::Null);
        for name in [
            "ua",
            "navigatorMode",
            "platform",
            "language",
            "languages",
            "width",
            "height",
            "devicePixelRatio",
            "hardwareConcurrency",
            "globalPrivacyControl",
            "secureContext",
            "frameTrace",
            "challengeMessageTrace",
            "fullscreenSupported",
            "inlineMedia",
        ] {
            if let Ok(value) = realm_ctx.member_get(&source_config, name) {
                realm_ctx.member_set(&config, name, value)?;
            }
        }
        realm_ctx.member_set(&config, "cookieOpaque", Value::Bool(cookie_opaque))?;
        realm_ctx.member_set(&config, "url", Value::from_string(url.clone()))?;
        realm_ctx.member_set(&config, "referrer", Value::from_string(referrer.clone()))?;
        realm_ctx.member_set(&config, "navigationTiming", navigation_timing.clone())?;
        realm_ctx.member_set(&config, "aboutBaseURL", about_base_url.clone())?;
        realm_ctx.member_set(
            &config,
            "documentContentType",
            Value::from_string(content_type.clone()),
        )?;
        realm_ctx.member_set(&config, "frameId", Value::Num(frame_id as f64))?;
        realm_ctx.member_set(&config, "hostSettingsContext", Value::Num(context as f64))?;
        realm_ctx.member_set(&config, "frameElement", frame_element.clone())?;
        realm_ctx.member_set(&config, "parentWindow", parent_window.clone())?;
        realm_ctx.member_set(&config, "topWindow", top_window.clone())?;
        realm_ctx.member_set(&config, "agentTimeOffset", Value::Num(agent_time_offset))?;
        let global = realm_ctx.global_this();
        #[cfg(test)]
        let config_for_tests = config.clone();
        realm_ctx.member_set(&global, "__trust_cfg", config)?;

        // HTML §7.2.2/§7.5.1 create-a-new-browsing-context runs the platform bootstrap as a
        // fresh ScriptEvaluation in the new Realm. The engine shares the decoded program and
        // its compiled code with the page's other Window Realms; every object it creates
        // belongs to this Realm alone.
        let bootstrap_result = realm_ctx.eval_shared_classic_snapshot_interruptible(snapshot);
        match bootstrap_result {
            Ok(Ok(_)) => {
                #[cfg(test)]
                expose_platform_internals_for_tests(realm_ctx, false, config_for_tests);
                Ok(())
            }
            Ok(Err(EvalError::Throw(error))) => Err(error),
            Ok(Err(EvalError::Interrupted(reason))) => Err(realm_ctx.make_error(
                "AbortError",
                format!("Window Realm bootstrap interrupted: {}", reason.message()),
            )),
            Err(error) => Err(realm_ctx.make_error(
                "SyntaxError",
                format!(
                    "Window Realm bootstrap parse error at line {}: {}",
                    error.line, error.message
                ),
            )),
        }
    });
    ctx.resume_gc();
    match installed {
        Ok(Ok(())) => {}
        Ok(Err(error)) | Err(error) => {
            if let Some(state) = ctx.host_mut::<HostState>() {
                state.import_maps.remove(&context);
                state.window_realms.remove(&context);
                state.window_request_urls.remove(&context);
                state.window_cookie_contexts.remove(&context);
                state.forget_realm_origin(context);
            }
            return Err(error);
        }
    }
    Ok(realm)
}

fn host_set_job_context(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let context = args
        .first()
        .and_then(Value::as_num_opt)
        .filter(|value| value.is_finite() && *value >= 0.0)
        .map_or(0, |value| value as u64);
    ctx.set_host_job_context(context);
    Ok(Value::Undefined)
}

fn host_release_job_context(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let context = args
        .first()
        .and_then(Value::as_num_opt)
        .filter(|value| value.is_finite() && *value > 0.0)
        .map_or(0, |value| value as u64);
    if context == 0 {
        return Ok(Value::Bool(false));
    }
    if let Some(state) = ctx.host_mut::<HostState>() {
        state.import_maps.remove(&context);
        state.window_realms.remove(&context);
        state.message_ports.release(Some(context));
        state.indexed_db.release(Some(context));
        state.webaudio.release_realm(context);
        // File API #lifeTime: the Window's entries go away with its Document.
        state
            .blobs
            .remove_environment(state.blob_agent, Some(context));
        state.window_request_urls.remove(&context);
        state.window_cookie_contexts.remove(&context);
        state.forget_realm_origin(context);
        if let Some(network) = state.network.as_mut() {
            network
                .pending_fetches
                .retain(|_, pending| pending.context != context);
            // HTML #unload-a-document aborts the Document's fetches
            // (Fetch #fetch-controller-abort): stop its response bodies'
            // transfers, which may otherwise never end (event streams).
            network.body_streams.retain(|_, stream| {
                let keep = stream.context != context;
                if !keep {
                    stream.flow.cancel();
                }
                keep
            });
        }
        if let Some(workers) = state.workers.as_mut() {
            // Removing the sole owner closes these dedicated workers. Dropping
            // their handles interrupts execution; late queued replies are inert.
            workers
                .workers
                .retain(|_, worker| worker.context != context);
        }
    }
    Ok(Value::Bool(ctx.release_host_job_context(context)))
}

fn host_enter_job_context(ctx: &mut Ctx, context: u64) {
    let _ = host_call_trust(ctx, "bindWindowSettings", &[Value::Num(context as f64)]);
}

fn host_leave_job_context(ctx: &mut Ctx) {
    let _ = host_call_trust(ctx, "restoreFrame", &[]);
}

fn host_resource_url(ctx: &mut Ctx, node_id: usize, fallback: Option<String>) -> Option<String> {
    host_call_trust(ctx, "resourceURL", &[Value::Num(node_id as f64)])
        .ok()
        .and_then(|value| ctx.coerce_string(&value).ok())
        .map(|value| value.to_string())
        .filter(|value| !value.trim().is_empty())
        .or_else(|| fallback.filter(|value| !value.trim().is_empty()))
}

fn element_request_client_url(ctx: &mut Ctx, node: usize) -> url::Url {
    let context = host_call_trust(ctx, "resourceClientContext", &[Value::Num(node as f64)])
        .ok()
        .and_then(|value| value.as_num_opt())
        .unwrap_or(0.0) as u64;
    request_context_url(ctx, context)
}

fn element_cookie_context(ctx: &mut Ctx, node: usize) -> crate::http::CookieContext {
    let id = host_call_trust(ctx, "resourceClientContext", &[Value::Num(node as f64)])
        .ok()
        .and_then(|v| v.as_num_opt())
        .map_or(u64::MAX, |v| v as u64);
    cookie_context_for_id(ctx, id)
}

fn prepare_element_request(
    ctx: &mut Ctx,
    node: usize,
    target: &str,
    destination: &'static str,
    module: bool,
) -> Option<crate::http::Request> {
    let client = element_request_client_url(ctx, node);
    let cookie_context = element_cookie_context(ctx, node);
    let calling = ctx.host_job_context();
    let (credentials, referrer_policy, context) = {
        let dom = host_dom(ctx);
        let dom = dom.borrow();
        let state = ctx.host_mut::<HostState>()?;
        (
            crate::js::element_cors_credentials(dom.attr(node, "crossorigin"), module),
            // HTML #referrer-policy-attributes: the element's attribute, or the
            // empty string for the Document's policy container's policy.
            dom.attr(node, "referrerpolicy")
                .and_then(crate::referrer_policy::ReferrerPolicy::parse_attribute),
            node_window_context(state, &dom, node).unwrap_or(calling),
        )
    };
    let state = ctx.host_mut::<HostState>()?;
    let (_, _, mut request) = prepare_client_request(
        state,
        &client,
        target,
        "GET".into(),
        None,
        vec![],
        credentials.map(|credentials| (crate::http::RequestMode::Cors, credentials)),
    )?;
    crate::http::set_fetch_metadata(
        &mut request,
        &client,
        destination,
        if credentials.is_some() {
            "cors"
        } else {
            "no-cors"
        },
    );
    request.cookie_context = Some(cookie_context);
    apply_request_referrer(
        state,
        context,
        &RequestReferrer::Client,
        referrer_policy,
        &mut request,
    );
    Some(request)
}

/// Parser-blocking nested scripts keep HTML's synchronous script ordering but
/// fetch as script elements, not as an empty-destination script Fetch request.
fn host_fetch_classic_script(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let started = crate::performance::now_ms();
    let node = {
        let dom = host_dom(ctx);
        let dom = dom.borrow();
        host_arg_node(&dom, args, 0).filter(|node| dom.tag_name(*node) == Some("script"))
    };
    let request = node.and_then(|node| {
        let target = host_resource_url(ctx, node, None)?;
        prepare_element_request(ctx, node, &target, "script", false)
    });
    let network = ctx
        .host_mut::<HostState>()
        .and_then(|state| state.network.as_ref())
        .map(|network| (network.handle.clone(), network.cache.clone()));
    let (result, timing) = if let (Some(request), Some((handle, cache))) = (request, network) {
        let (sender, receiver) = std::sync::mpsc::channel();
        cache.spawn(&handle, async move {
            let name = request.url.to_string();
            let result = crate::http::fetch_with_timing(&request, Default::default())
                .await
                .map(|details| details.response);
            let _ = sender.send(timed_fetch_result(result, name, "script", started));
        });
        receiver.recv().unwrap_or((None, None))
    } else {
        (None, None)
    };
    record_resource_timing(ctx, timing);
    Ok(host_fetch_result_value(ctx, result))
}

/// HTML §8.1.4.6 #report-the-exception for a script's uncaught exception:
/// the platform fires the cancelable `error` ErrorEvent at the Window. Returns
/// whether the exception remains "not handled" (to be logged by the caller).
/// HTML #report-an-exception for a script the host ran: `location` is the
/// script's URL and, for a parse error, its line, which locate the
/// ErrorEvent when the exception carries no stack frame. Returns whether the
/// exception was not handled (the caller then logs it).
fn host_report_exception(
    ctx: &mut Ctx,
    exception: Value,
    label: &str,
    muted: bool,
    location: Option<(&str, u32)>,
) -> bool {
    let (filename, lineno) = location.unwrap_or(("", 0));
    match host_call_trust(
        ctx,
        "reportException",
        &[
            exception,
            Value::from_string(label.to_string()),
            Value::Bool(muted),
            Value::from_string(filename.to_string()),
            Value::Num(f64::from(lineno)),
        ],
    ) {
        Ok(Value::Bool(not_handled)) => not_handled,
        _ => true,
    }
}

fn host_push_injected_error(ctx: &mut Ctx, message: impl Into<String>) {
    let Ok(trust) = host_trust(ctx) else {
        return;
    };
    let Ok(errors) = ctx.member_get(&trust, "errors") else {
        return;
    };
    let Ok(push) = ctx.member_get(&errors, "push") else {
        return;
    };
    let _ = ctx.invoke(push, errors, &[Value::from_string(message.into())]);
}

fn host_fire_script_event(ctx: &mut Ctx, node_id: usize, event_type: &str) {
    let _ = host_call_trust(ctx, "bindFrameForNode", &[Value::Num(node_id as f64)]);
    let _ = host_call_trust(
        ctx,
        "scriptEvent",
        &[
            Value::Num(node_id as f64),
            Value::from_string(event_type.to_string()),
        ],
    );
    let _ = host_call_trust(ctx, "restoreFrame", &[]);
}

/// The media type metadata of a `data:` URL. Fetch's data-URL processor defaults an omitted type
/// to `text/plain;charset=US-ASCII`; module-script fetching subsequently rejects that default
/// because it is not a JavaScript MIME type.
fn data_url_content_type(url: &str) -> String {
    let mut metadata = url
        .strip_prefix("data:")
        .and_then(|rest| rest.split_once(',').map(|(metadata, _)| metadata))
        .unwrap_or_default()
        .trim();
    if metadata
        .get(metadata.len().saturating_sub(";base64".len())..)
        .is_some_and(|suffix| suffix.eq_ignore_ascii_case(";base64"))
    {
        metadata = &metadata[..metadata.len() - ";base64".len()];
    }
    if metadata.is_empty() {
        String::from("text/plain;charset=US-ASCII")
    } else if metadata.starts_with(';') {
        format!("text/plain{metadata}")
    } else {
        metadata.to_string()
    }
}

fn data_resource_result(url: &str) -> LumenResourceResult {
    crate::img::decode_data_url(url.trim())
        .map(|body| (200, data_url_content_type(url), body, Vec::new()))
}

/// Fetch #scheme-fetch "blob" for an element's resource (a script, style sheet or preload),
/// whose URL was parsed when the element was prepared: the element's environment obtains the
/// blob URL entry (File API #blob-url-obtain-object, same partition only) and the response is
/// the Blob's byte sequence with its Content-Length and Content-Type. A missing entry, another
/// partition's entry or an unreadable selected file is a network error.
fn blob_resource_result(ctx: &mut Ctx, node_id: usize, url: &str) -> LumenResourceResult {
    let calling = ctx.host_job_context();
    let state = ctx.host_mut::<HostState>()?;
    let context = {
        let dom = state.dom.clone();
        let dom = dom.borrow();
        node_window_context(state, &dom, node_id).unwrap_or(calling)
    };
    let key = blob_storage_key(&realm_origin(state, context));
    let entry = state.blobs.obtain(url.trim(), Some(&key))?;
    let body = entry.read().ok()?;
    Some((
        200,
        entry.content_type.clone(),
        body,
        vec![
            (String::from("Content-Length"), entry.size().to_string()),
            (String::from("Content-Type"), entry.content_type.clone()),
        ],
    ))
}

fn send_resource_completion(
    ctx: &mut Ctx,
    node_id: usize,
    name: String,
    kind: LumenResourceKind,
    result: LumenResourceResult,
    external: bool,
) -> bool {
    let context = ctx.host_job_context();
    let text = match (&kind, &result) {
        (LumenResourceKind::ClassicScript, Some((_, content_type, body, _))) => {
            let fallback = dom_fallback_encoding(&host_dom(ctx).borrow(), node_id);
            Some(crate::document_encoding::decode_classic_script(
                content_type,
                body,
                fallback,
            ))
        }
        _ => None,
    };
    let Some(events) = ctx.host_mut::<HostState>().and_then(|state| {
        let events = state.task_events.clone()?;
        if kind.delays_load() {
            state.pending_resources += 1;
        } else {
            state.pending_preloads += 1;
        }
        state.dom_gc.start_resource(node_id);
        Some(events)
    }) else {
        return false;
    };
    if events
        .send(LumenHostTask::ResourceDone {
            context,
            node_id,
            name,
            kind,
            result,
            text,
            sheet: None,
            timing: None,
            external,
        })
        .is_err()
    {
        if let Some(state) = ctx.host_mut::<HostState>() {
            if kind.delays_load() {
                state.pending_resources = state.pending_resources.saturating_sub(1);
            } else {
                state.pending_preloads = state.pending_preloads.saturating_sub(1);
            }
            state.dom_gc.finish_resource(node_id);
        }
        return false;
    }
    true
}

/// HTML #link-type-preload "fetch and process the linked resource": the
/// `as` attribute's preload destination selects the request destination
/// (#translate-a-preload-destination), a `type` that does not match it skips
/// the preload (#match-preload-type), and so does a `media` query that does
/// not match the environment (#processing-the-media-attribute). The response
/// enters the document's map of preloaded resources; `error` fires at the
/// element for a network error and `load` for any other response. Unlike
/// style sheets and scripts, a preload does not delay the load event.
fn host_preload_link(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let (node_id, href, destination, type_matches) = {
        let dom = host_dom(ctx);
        let dom = dom.borrow();
        let Some(node_id) = host_arg_node(&dom, args, 0) else {
            return Ok(Value::Undefined);
        };
        if dom
            .attr(node_id, "media")
            .is_some_and(|media| !media.trim().is_empty() && !dom.media_matches(media))
        {
            return Ok(Value::Undefined);
        }
        let Some(destination) = dom.attr(node_id, "as").and_then(preload_destination) else {
            return Ok(Value::Undefined);
        };
        (
            node_id,
            dom.attr(node_id, "href").map(str::to_string),
            destination,
            preload_type_matches(dom.attr(node_id, "type").unwrap_or(""), destination),
        )
    };
    if !type_matches {
        return Ok(Value::Undefined);
    }
    let Some(href) = host_resource_url(ctx, node_id, href) else {
        return Ok(Value::Undefined);
    };
    let local = href.trim_start();
    if local.starts_with("data:") || local.starts_with("blob:") {
        let result = if local.starts_with("data:") {
            data_resource_result(href.trim())
        } else {
            blob_resource_result(ctx, node_id, &href)
        };
        if !send_resource_completion(ctx, node_id, href, LumenResourceKind::Preload, result, true) {
            host_fire_script_event(ctx, node_id, "error");
        }
        return Ok(Value::Undefined);
    }
    let fetched = prepare_element_request(ctx, node_id, &href, destination, false)
        .is_some_and(|request| spawn_preload_fetch(ctx, node_id, destination, request));
    if !fetched {
        queue_resource_error(ctx, node_id, LumenResourceKind::Preload, href);
    }
    Ok(Value::Undefined)
}

/// HTML #translate-a-preload-destination: the `as` keywords (an enumerated
/// attribute without missing or invalid value defaults) that are preload
/// destinations, translated by Fetch #concept-potential-destination-translate.
fn preload_destination(value: &str) -> Option<&'static str> {
    [
        ("fetch", ""),
        ("font", "font"),
        ("image", "image"),
        ("script", "script"),
        ("style", "style"),
        ("track", "track"),
    ]
    .into_iter()
    .find_map(|(keyword, destination)| value.eq_ignore_ascii_case(keyword).then_some(destination))
}

/// HTML #match-preload-type, with MIME Sniffing's MIME type groups.
fn preload_type_matches(type_: &str, destination: &str) -> bool {
    if type_.is_empty() || destination.is_empty() {
        return true;
    }
    let Some((kind, subtype)) = type_.split(';').next().and_then(|essence| {
        let (kind, subtype) = essence.trim().split_once('/')?;
        (!kind.is_empty() && !subtype.trim().is_empty()).then(|| {
            (
                kind.to_ascii_lowercase(),
                subtype.trim().to_ascii_lowercase(),
            )
        })
    }) else {
        return false;
    };
    let essence = format!("{kind}/{subtype}");
    match destination {
        "script" => crate::http::is_javascript_mime_type(&essence),
        "image" => {
            matches!(
                subtype.as_str(),
                "png"
                    | "apng"
                    | "jpeg"
                    | "pjpeg"
                    | "gif"
                    | "webp"
                    | "avif"
                    | "bmp"
                    | "svg+xml"
                    | "x-icon"
                    | "vnd.microsoft.icon"
            ) && kind == "image"
        }
        "font" => {
            kind == "font"
                || matches!(
                    essence.as_str(),
                    "application/font-cff"
                        | "application/font-off"
                        | "application/font-sfnt"
                        | "application/font-ttf"
                        | "application/font-woff"
                        | "application/vnd.ms-fontobject"
                        | "application/vnd.ms-opentype"
                )
        }
        "style" => essence == "text/css",
        "track" => essence == "text/vtt",
        _ => false,
    }
}

/// HTML #preload: fetch into the page's preload map without delaying the
/// load event, then queue the element's `load`/`error` on its own Realm.
fn spawn_preload_fetch(
    ctx: &mut Ctx,
    node_id: usize,
    destination: &'static str,
    request: crate::http::Request,
) -> bool {
    let started = crate::performance::now_ms();
    let name = request.url.to_string();
    let client = element_request_client_url(ctx, node_id);
    let credentials = request
        .fetch_policy
        .as_ref()
        .map(|policy| policy.credentials);
    let context = ctx.host_job_context();
    let Some((handle, cache, events)) = ctx.host_mut::<HostState>().and_then(|state| {
        let events = state.task_events.clone()?;
        let network = state.network.as_ref()?;
        state.pending_preloads += 1;
        state.dom_gc.start_resource(node_id);
        Some((network.handle.clone(), network.cache.clone(), events))
    }) else {
        return false;
    };
    let (shared, preloaded) =
        cache.preload_resource(&handle, request, &client, destination, credentials);
    cache.spawn(&handle, async move {
        let (result, timing) = match shared.await {
            Ok(response) => {
                // Resource Timing: a preload that started the fetch reports it
                // with the `link` initiator type; its consumer reports none.
                let timing = if preloaded {
                    LumenResourceTiming::fetched(
                        name.clone(),
                        "link",
                        response.timing.clone(),
                        started,
                    )
                } else {
                    None
                };
                (
                    Some((
                        response.status,
                        response.content_type.clone(),
                        Vec::new(),
                        response.headers.clone(),
                    )),
                    timing,
                )
            }
            Err(()) => (None, None),
        };
        let _ = events.send(LumenHostTask::ResourceDone {
            context,
            node_id,
            name,
            kind: LumenResourceKind::Preload,
            result,
            text: None,
            sheet: None,
            timing,
            external: true,
        });
    });
    true
}

fn spawn_resource_fetch(
    ctx: &mut Ctx,
    node_id: usize,
    kind: LumenResourceKind,
    request: crate::http::Request,
) -> bool {
    let started = crate::performance::now_ms();
    let name = request.url.to_string();
    let client = element_request_client_url(ctx, node_id);
    // Preloads use `spawn_preload_fetch`; navigation obtained parsed sheets.
    let (destination, initiator) = match kind {
        LumenResourceKind::Stylesheet
        | LumenResourceKind::ParsedStylesheet { .. }
        | LumenResourceKind::Preload => ("style", "css"),
        LumenResourceKind::ClassicScript | LumenResourceKind::ModuleScript => ("script", "script"),
    };
    let credentials = request
        .fetch_policy
        .as_ref()
        .map(|policy| policy.credentials);
    let context = ctx.host_job_context();
    let Some((handle, cache, events)) = ctx.host_mut::<HostState>().and_then(|state| {
        let events = state.task_events.clone()?;
        let network = state.network.as_ref()?;
        state.pending_resources += 1;
        state.dom_gc.start_resource(node_id);
        Some((network.handle.clone(), network.cache.clone(), events))
    }) else {
        return false;
    };
    let shared = cache.consume_resource(&request.url, &client, destination, credentials);
    let trace_fetch = std::env::var_os("TRUST_TRACE_FETCH").is_some();
    let environment = dom_fallback_encoding(&host_dom(ctx).borrow(), node_id);
    let cors_mode = credentials.is_some();
    // A module script's descendants are fetched when its own fetch completes
    // (`speculate_module_graph`), as `speculate_engine_imports` permits.
    let module_graph = (matches!(kind, LumenResourceKind::ModuleScript)
        && !request_cookie_context(ctx).cross_site_ancestor)
        .then(|| {
            let state = ctx.host_mut::<HostState>()?;
            let fetched = state.network.as_ref()?.fetched.clone();
            Some((state.base.clone(), fetched, handle.clone(), cache.clone()))
        })
        .flatten();
    // Referrer Policy #integration-with-css: the sheet's imports use its
    // location and its own policy, else its document's.
    let document_policy = ctx
        .host_mut::<HostState>()
        .map(|state| {
            let dom = state.dom.clone();
            let context = node_window_context(state, &dom.borrow(), node_id).unwrap_or(0);
            environment_referrer_policy(state, context)
        })
        .unwrap_or_default();
    cache.spawn(&handle, async move {
        let mut response_url = request.url.clone();
        let (result, timing) = match shared {
            Some((shared, preloaded)) => match shared.await {
                Ok(response) => {
                    let timing = if preloaded {
                        None
                    } else {
                        LumenResourceTiming::cached(
                            name.clone(),
                            initiator,
                            response.timing.as_deref(),
                            started,
                        )
                    };
                    if let Some(url) = response.url_list.last() {
                        response_url = url.clone();
                    }
                    (
                        Some((
                            response.status,
                            response.content_type.clone(),
                            response.body.clone(),
                            response.headers.clone(),
                        )),
                        timing,
                    )
                }
                Err(()) => (None, None),
            },
            None => match crate::http::fetch_with_timing(&request, Default::default()).await {
                Ok(details) => {
                    let response = details.response;
                    let timing = LumenResourceTiming::fetched(
                        name.clone(),
                        initiator,
                        response.timing,
                        started,
                    );
                    response_url = response.url;
                    (
                        Some((
                            response.status,
                            response.content_type,
                            response.body,
                            response.headers,
                        )),
                        timing,
                    )
                }
                Err(error) => (
                    None,
                    LumenResourceTiming::fetched(name.clone(), initiator, error.timing, started),
                ),
            },
        };
        let (text, sheet) = match &result {
            Some((status, content_type, body, headers))
                if matches!(kind, LumenResourceKind::Stylesheet)
                    && crate::http::stylesheet_response_allowed(*status, content_type, headers) =>
            {
                let (css, encoding) = crate::document_encoding::decode_stylesheet(
                    content_type,
                    body,
                    Some(environment),
                );
                let sheet = crate::http::fetched_stylesheet(
                    css,
                    request.url.clone(),
                    response_url,
                    client,
                    cors_mode,
                    encoding,
                    crate::http::SheetReferrer::located(&request.url, headers, document_policy),
                    crate::referrer_policy::ReferrerPolicy::from_headers(headers),
                )
                .await;
                (None, Some(Box::new(sheet)))
            }
            // The script's charset attribute and node document were read
            // when the element was prepared, as the fallback encoding is.
            Some((_, content_type, body, _))
                if matches!(kind, LumenResourceKind::ClassicScript) =>
            {
                (
                    Some(crate::document_encoding::decode_classic_script(
                        content_type,
                        body,
                        environment,
                    )),
                    None,
                )
            }
            _ => (None, None),
        };
        if let (Some((page, fetched, runtime, graph_cache)), Some((status, content_type, body, _))) =
            (module_graph, &result)
            && crate::http::module_script_response_allowed(*status, content_type)
        {
            speculate_module_graph(
                page,
                runtime,
                graph_cache,
                fetched,
                request.url.clone(),
                body,
            );
        }
        if trace_fetch {
            match &result {
                Some((status, ctype, body, _)) => eprintln!(
                    "[fetch-trace] resource-done url={name} status={status} type={} len={}",
                    ctype.split(';').next().unwrap_or(""),
                    body.len()
                ),
                None => eprintln!("[fetch-trace] resource-done url={name} FAILED"),
            }
        }
        let _ = events.send(LumenHostTask::ResourceDone {
            context,
            node_id,
            name,
            kind,
            result,
            text,
            sheet,
            timing,
            external: true,
        });
    });
    true
}

fn queue_resource_error(ctx: &mut Ctx, node_id: usize, kind: LumenResourceKind, name: String) {
    if !send_resource_completion(ctx, node_id, name, kind, None, true) {
        host_fire_script_event(ctx, node_id, "error");
    }
}

fn classic_current_script(ctx: &mut Ctx, node_id: usize) -> Value {
    // HTML #execute-the-script-element snapshots null for a classic script
    // whose root is a shadow root, even if script later moves the element.
    if host_dom(ctx).borrow().in_shadow_tree(node_id) {
        Value::Null
    } else {
        Value::Num(node_id as f64)
    }
}

fn host_eval_inline_classic(ctx: &mut Ctx, node_id: usize, name: &str, source: String) {
    let _ = host_call_trust(ctx, "bindFrameForNode", &[Value::Num(node_id as f64)]);
    let trust = host_trust(ctx).ok();
    let old_current = trust
        .as_ref()
        .and_then(|trust| ctx.member_get(trust, "currentScript").ok());
    if let Some(trust) = trust.as_ref() {
        let current = classic_current_script(ctx, node_id);
        let _ = ctx.member_set(trust, "currentScript", current);
    }
    // Error stacks name an inline script by its document's URL, as browsers do. The element's
    // starting line within the document is not recorded, so lines count from the script text.
    let document_url = element_request_client_url(ctx, node_id).to_string();
    let origin = lumen::SourceOrigin::new(&document_url);
    match ctx.eval_classic_script_interruptible_with_origin(&source, Some(&origin)) {
        Ok(Ok(_)) => {}
        Ok(Err(EvalError::Throw(error))) => {
            let message = ctx
                .coerce_string(&error)
                .map(|message| message.to_string())
                .unwrap_or_else(|_| String::from("classic script threw"));
            if host_report_exception(ctx, error, name, false, Some((&document_url, 0))) {
                host_push_injected_error(ctx, format!("{name}: {message}"));
            }
        }
        Ok(Err(EvalError::Interrupted(reason))) => {
            host_push_injected_error(ctx, format!("{name}: {}", reason.message()));
        }
        Err(error) => {
            // HTML #run-a-classic-script: a script's parse error is reported
            // as a SyntaxError of its realm.
            let syntax_error = ctx.make_error("SyntaxError", error.message.clone());
            if host_report_exception(
                ctx,
                syntax_error,
                name,
                false,
                Some((&document_url, error.line)),
            ) {
                host_push_injected_error(
                    ctx,
                    format!(
                        "{name} parse error at line {}: {}",
                        error.line, error.message
                    ),
                );
            }
        }
    }
    if let (Some(trust), Some(old_current)) = (trust.as_ref(), old_current) {
        let _ = ctx.member_set(trust, "currentScript", old_current);
    }
    let _ = host_call_trust(ctx, "restoreFrame", &[]);
}

/// HTML §8.1.4.4 "run a classic script": nested-document parser scripts are Script Records,
/// not indirect eval code. This synchronous entry is safe from a native platform callback and
/// retains the Realm's persistent global lexical environment across sibling script elements.
fn host_run_classic_script(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let node_id = {
        let dom = host_dom(ctx);
        let dom = dom.borrow();
        let Some(node_id) = host_arg_node(&dom, args, 0) else {
            return Ok(Value::Undefined);
        };
        node_id
    };
    // Script source is text for Lumen's source entry point, not a DOM string.
    let source = host_arg_usv(ctx, args, 1);
    let name = host_arg_string(ctx, args, 2);
    host_eval_inline_classic(ctx, node_id, &name, source);
    Ok(Value::Undefined)
}

/// `__dom_script_started(script)`: set the element's "already started" flag
/// (HTML #already-started) when the prelude prepares it to run.
fn host_script_started(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let dom = host_dom(ctx);
    let mut dom = dom.borrow_mut();
    if let Some(id) = host_arg_node(&dom, args, 0) {
        dom.mark_script_started(id);
    }
    Ok(Value::Undefined)
}

/// `__dom_insertion_resources(node)`: see [`Dom::connected_insertion_resources`].
fn host_insertion_resources(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let ids = {
        let dom = host_dom(ctx);
        let dom = dom.borrow();
        host_arg_node(&dom, args, 0)
            .map(|root| dom.connected_insertion_resources(root))
            .unwrap_or_default()
    };
    Ok(host_ids_array(ctx, ids))
}

/// HTML §4.12.1.1 post-connection and prepare-the-script-element steps for scripts inserted
/// through the live DOM. The prelude owns the already-started/type/connected gates; this host owns
/// source acquisition and execution.
fn host_run_injected_script(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let (node_id, src, text, module) = {
        let dom = host_dom(ctx);
        let dom = dom.borrow();
        let Some(node_id) = host_arg_node(&dom, args, 0) else {
            return Ok(Value::Undefined);
        };
        (
            node_id,
            dom.attr(node_id, "src").map(str::to_string),
            // Script source is text for Lumen's source entry points (see `dom_text_out`).
            dom_text_out(&dom.text_content(node_id)).into_owned(),
            dom.attr(node_id, "type")
                .is_some_and(|value| value.trim().eq_ignore_ascii_case("module")),
        )
    };
    if host_dom(ctx)
        .borrow()
        .attr(node_id, "type")
        .is_some_and(|t| t.trim().eq_ignore_ascii_case("importmap"))
    {
        if src.is_some() {
            queue_resource_error(
                ctx,
                node_id,
                LumenResourceKind::ClassicScript,
                String::new(),
            );
            return Ok(Value::Undefined);
        }
        let context = host_call_trust(ctx, "resourceClientContext", &[Value::Num(node_id as f64)])
            .ok()
            .and_then(|v| v.as_num_opt())
            .unwrap_or(0.) as u64;
        let base = host_call_trust(ctx, "resourceBaseURL", &[Value::Num(node_id as f64)])
            .ok()
            .and_then(|v| ctx.coerce_string(&v).ok())
            .and_then(|s| url::Url::parse(&s).ok())
            .unwrap_or_else(|| request_context_url(ctx, context));
        match crate::import_maps::ImportMap::parse(&text, &base) {
            Ok(map) => context_import_map(ctx, context)
                .lock()
                .unwrap_or_else(|e| e.into_inner())
                .merge(map),
            Err(e) => host_push_injected_error(ctx, format!("Import map: {e}")),
        }
        return Ok(Value::Undefined);
    }
    let has_src = src.is_some();
    let src = host_resource_url(ctx, node_id, src);
    // HTML #prepare-the-script-element queues an error for an empty src;
    // it must not fall through to the inline path or strand a parser wait.
    if has_src && src.is_none() {
        queue_resource_error(
            ctx,
            node_id,
            if module {
                LumenResourceKind::ModuleScript
            } else {
                LumenResourceKind::ClassicScript
            },
            String::new(),
        );
        return Ok(Value::Undefined);
    }
    if std::env::var_os("TRUST_TRACE_FETCH").is_some() {
        eprintln!(
            "[fetch-trace] @{:>6}ms injected script src={src:?} module={module} node={node_id}",
            crate::http::trace_ms()
        );
    }

    if let Some(src) = src {
        let local = src.trim_start();
        if local.starts_with("data:") || local.starts_with("blob:") {
            let result = if local.starts_with("data:") {
                data_resource_result(src.trim())
            } else {
                blob_resource_result(ctx, node_id, &src)
            };
            if !send_resource_completion(
                ctx,
                node_id,
                src,
                if module {
                    LumenResourceKind::ModuleScript
                } else {
                    LumenResourceKind::ClassicScript
                },
                result,
                true,
            ) {
                host_fire_script_event(ctx, node_id, "error");
            }
            return Ok(Value::Undefined);
        }
        let request = prepare_element_request(ctx, node_id, &src, "script", module);
        if std::env::var_os("TRUST_TRACE_FETCH").is_some() {
            eprintln!(
                "[fetch-trace] injected request prepared={}",
                request.is_some()
            );
        }
        let kind = if module {
            LumenResourceKind::ModuleScript
        } else {
            LumenResourceKind::ClassicScript
        };
        match request {
            Some(request) => {
                if !spawn_resource_fetch(ctx, node_id, kind, request) {
                    queue_resource_error(ctx, node_id, kind, src);
                }
            }
            None => queue_resource_error(ctx, node_id, kind, src),
        }
    } else if module {
        let base = state_base(ctx);
        // HTML §4.12.1.1 creates a new JavaScript module script for each
        // inline script element. Its document URL is the base URL used to
        // resolve imports, not a shared module-map identity. Give Lumen a
        // stable per-element fragment so sibling inline modules cannot alias
        // one another while relative imports still resolve against `base`.
        let name = url::Url::parse(&base)
            .map(|mut url| {
                url.set_fragment(Some(&format!("inline-module-{node_id}")));
                url.to_string()
            })
            .unwrap_or_else(|_| format!("{base}#inline-module-{node_id}"));
        if !send_resource_completion(
            ctx,
            node_id,
            name,
            LumenResourceKind::ModuleScript,
            Some((
                200,
                String::from("text/javascript"),
                text.into_bytes(),
                Vec::new(),
            )),
            false,
        ) {
            host_push_injected_error(ctx, "inline module could not enter the host task queue");
        }
    } else if !text.is_empty() {
        // A non-parser-inserted inline classic script executes immediately in the element's
        // post-connection steps. Its exception is reported, not rethrown from appendChild().
        let name = state_base(ctx);
        host_eval_inline_classic(ctx, node_id, &name, text);
    }
    Ok(Value::Undefined)
}

fn state_base(ctx: &mut Ctx) -> String {
    ctx.host_mut::<HostState>()
        .map(|state| state.base.to_string())
        .unwrap_or_else(|| String::from("about:blank"))
}

/// HTML stylesheet-link processing: fetching is parallel, while attaching the CSSStyleSheet and
/// firing `load`/`error` occur in the later resource task.
fn host_load_injected_stylesheet(
    ctx: &mut Ctx,
    _this: Value,
    args: &[Value],
) -> Result<Value, Value> {
    let (node_id, href) = {
        let dom = host_dom(ctx);
        let dom = dom.borrow();
        let Some(node_id) = host_arg_node(&dom, args, 0) else {
            return Ok(Value::Undefined);
        };
        (node_id, dom.attr(node_id, "href").map(str::to_string))
    };
    let Some(href) = host_resource_url(ctx, node_id, href) else {
        return Ok(Value::Undefined);
    };
    let local = href.trim_start();
    if local.starts_with("data:") || local.starts_with("blob:") {
        let result = if local.starts_with("data:") {
            data_resource_result(href.trim())
        } else {
            blob_resource_result(ctx, node_id, &href)
        };
        if !send_resource_completion(
            ctx,
            node_id,
            href.clone(),
            LumenResourceKind::Stylesheet,
            result,
            true,
        ) {
            host_fire_script_event(ctx, node_id, "error");
        }
        return Ok(Value::Undefined);
    }
    let request = prepare_element_request(ctx, node_id, &href, "style", false);
    match request {
        Some(request) => {
            if !spawn_resource_fetch(ctx, node_id, LumenResourceKind::Stylesheet, request) {
                queue_resource_error(ctx, node_id, LumenResourceKind::Stylesheet, href);
            }
        }
        None => queue_resource_error(ctx, node_id, LumenResourceKind::Stylesheet, href),
    }
    Ok(Value::Undefined)
}

/// WebSockets §3.1 constructor boundary: the prelude performs Web IDL/URL/subprotocol
/// validation synchronously; this host applies the page's private-network policy and starts the
/// RFC 6455 connection in parallel. Protocol feedback returns as WebSocket-task-source work.
fn host_ws_open(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let target = host_arg_usv(ctx, args, 0);
    let protocols = host_arg_usv(ctx, args, 1);
    let Some(protocols) = crate::ws::parse_protocols(&protocols) else {
        return Ok(Value::Num(-1.0));
    };
    let cookie_context = request_cookie_context(ctx);
    let client = request_client_url(ctx);
    let connection = ctx.host_mut::<HostState>().and_then(|state| {
        let sockets = state.websockets.as_mut()?;
        let resolved = client.join(&target).ok()?;
        if !matches!(resolved.scheme(), "ws" | "wss") || resolved.fragment().is_some() {
            return None;
        }
        let mut http_equivalent = resolved.clone();
        http_equivalent
            .set_scheme(if resolved.scheme() == "wss" {
                "https"
            } else {
                "http"
            })
            .ok()?;
        if !crate::http::subresource_allowed(&sockets.page, &http_equivalent) {
            return None;
        }
        let id = sockets.next_id;
        sockets.next_id += 1;
        let origin = client.origin().ascii_serialization();
        let mut cookie_request = crate::http::Request::get(http_equivalent);
        cookie_request.cookie_context = Some(cookie_context);
        let (sender, task) = crate::ws::connect(
            resolved,
            protocols,
            origin,
            Some(cookie_request),
            &sockets.handle,
            id,
            sockets.events.clone(),
        );
        sockets.tasks.track(task);
        sockets.sockets.insert(id, sender);
        Some(id)
    });
    Ok(connection.map_or(Value::Num(-1.0), |id| Value::Num(id as f64)))
}

/// WebSockets §3.1 `send()`: queue one complete text or binary message without blocking the
/// page thread. `bufferedAmount` is maintained in the prelude and decremented only by the later
/// [`crate::ws::WsIn::Sent`] task after the transport accepts these application bytes.
fn host_ws_send(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let id = args
        .first()
        .and_then(Value::as_num_opt)
        .and_then(|id| (id.is_finite() && id >= 0.0 && id.fract() == 0.0).then_some(id as usize));
    // A binary message is a BufferSource copy of the Blob or buffer bytes.
    let message = match args.get(1) {
        Some(value) if matches!(args.get(2), Some(Value::Bool(true))) => {
            crate::ws::WsOut::Binary(ctx.buffer_source_bytes(value, true).unwrap_or_default())
        }
        _ => crate::ws::WsOut::Text(host_arg_usv(ctx, args, 1)),
    };
    let sent = ctx
        .host_mut::<HostState>()
        .and_then(|state| state.websockets.as_mut())
        .and_then(|sockets| id.and_then(|id| sockets.sockets.get(&id)))
        .is_some_and(|sender| sender.try_send(message).is_ok());
    Ok(Value::Bool(sent))
}

/// WebSockets §3.1 `close()`: code zero is the boundary sentinel for an omitted status code,
/// whose RFC 6455 Close frame has an empty body. Validation and the synchronous CLOSING state
/// transition happen in the shared prelude before this non-blocking transport command.
fn host_ws_close(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let id = args
        .first()
        .and_then(Value::as_num_opt)
        .and_then(|id| (id.is_finite() && id >= 0.0 && id.fract() == 0.0).then_some(id as usize));
    let code = args
        .get(1)
        .and_then(Value::as_num_opt)
        .filter(|code| code.is_finite() && *code >= 0.0 && *code <= f64::from(u16::MAX))
        .unwrap_or_default() as u16;
    let reason = host_arg_usv(ctx, args, 2);
    if let Some(sender) = ctx
        .host_mut::<HostState>()
        .and_then(|state| state.websockets.as_mut())
        .and_then(|sockets| id.and_then(|id| sockets.sockets.get(&id)))
    {
        let _ = sender.try_send(crate::ws::WsOut::Close(code, reason));
    }
    Ok(Value::Undefined)
}

fn lumen_potentially_trustworthy(url: &url::Url) -> bool {
    match url.scheme() {
        "https" | "wss" | "file" => true,
        "http" => url.host_str().is_some_and(|host| {
            host.eq_ignore_ascii_case("localhost")
                || host
                    .strip_suffix(".localhost")
                    .is_some_and(|prefix| !prefix.is_empty())
                || host
                    .parse::<std::net::IpAddr>()
                    .is_ok_and(|address| address.is_loopback())
        }),
        _ => false,
    }
}

/// HTML §10.2.6 `Worker()` construction: URL parsing is synchronous in the shared prelude; the
/// worker realm, script fetch, and evaluation start in parallel on a dedicated agent thread.
fn host_worker_spawn(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let target = host_arg_usv(ctx, args, 0);
    // "shared:classic" / "shared:module" request a SharedWorkerGlobalScope.
    let requested = host_arg_string(ctx, args, 1);
    let (shared, kind) = match requested.strip_prefix("shared:") {
        Some(kind) => (true, kind),
        None => (false, requested.as_str()),
    };
    let kind = if kind == "module" {
        LumenWorkerKind::Module
    } else {
        LumenWorkerKind::Classic
    };
    let name = host_arg_string(ctx, args, 2);
    let context = ctx.host_job_context();
    // A nested worker's outside settings object is its owning worker's: the
    // creator origin and secure-context state that worker inherited itself,
    // and, for its script fetch's referrer, the owning worker's URL (its
    // creation URL) and referrer policy (Fetch #determine-requests-referrer).
    let nested_owner = ctx.host_mut::<HostState>().and_then(|state| {
        let base = state.base.clone();
        state.worker_self.as_ref().map(|worker| {
            (
                worker.origin.clone(),
                worker.secure_context,
                base,
                worker.referrer_policy,
            )
        })
    });
    let (owner_page, owner_secure, referrer_source, referrer_policy) = match nested_owner {
        Some((origin, secure, base, policy)) => (origin, secure, Some(base), policy),
        None => {
            let page = request_client_url(ctx);
            let secure = lumen_potentially_trustworthy(&page);
            // Fetch #determine-requests-referrer for the owning Window's environment: its
            // Document's URL (none for an opaque origin) under its policy container's policy.
            let (source, policy) = ctx
                .host_mut::<HostState>()
                .map(|state| {
                    (
                        environment_referrer_source(state, context),
                        environment_referrer_policy(state, context),
                    )
                })
                .unwrap_or((Some(page.clone()), Default::default()));
            (page, secure, source, policy)
        }
    };
    let cookie_context = request_cookie_context(ctx);
    let script_url = owner_page
        .join(&target)
        .map_err(|_| ctx.make_error("SyntaxError", "invalid worker script URL"))?;
    let secure_context = owner_secure
        && (script_url.scheme() == "blob" || lumen_potentially_trustworthy(&script_url));
    // URL #concept-url-parser: parsing the script URL resolved its blob URL entry; the
    // worker's script fetch obtains the Blob for the outside settings (File API
    // #blob-url-obtain-object), so another partition's URL is a network error.
    let (_, _, storage_key) = blob_environment(ctx);
    let script_blob = (script_url.scheme() == "blob")
        .then(|| {
            ctx.host_mut::<HostState>()
                .and_then(|state| state.blobs.obtain(script_url.as_str(), Some(&storage_key)))
        })
        .flatten();
    let Some(state) = ctx
        .host_mut::<HostState>()
        .filter(|state| state.workers.is_some())
    else {
        return Err(ctx.make_error("InvalidStateError", "worker host is unavailable"));
    };
    let workers = state.workers.as_mut().unwrap();
    // HTML #dom-sharedworker: match an existing shared worker global scope by constructor
    // storage key, constructor URL and name. A type or secure-context mismatch is reported
    // to the constructor as -1, after which it fires error without connecting.
    let shared_key = shared.then(|| {
        format!(
            "{}\0{}\0{}",
            owner_page.origin().ascii_serialization(),
            script_url.as_str(),
            name
        )
    });
    if let Some(key) = &shared_key
        && let Some(&(id, existing_kind, existing_secure)) = workers.shared.get(key)
        && workers.workers.contains_key(&id)
    {
        let matches = existing_kind == kind && existing_secure == secure_context;
        return Ok(Value::Num(if matches { id as f64 } else { -1.0 }));
    }
    if let Err(error) = workers.workers.try_reserve(1) {
        return Err(ctx.make_error(
            "QuotaExceededError",
            format!("worker allocation failed: {error}"),
        ));
    }
    let id = workers.next_id;
    workers.next_id += 1;
    if let Some(key) = shared_key {
        workers.shared.insert(key, (id, kind, secure_context));
    }
    let (ctl, ctl_rx) = LumenWorkerInbox::new();
    let launch = LumenWorkerLaunch {
        id,
        owner_page,
        cookie_context,
        script_url,
        kind,
        name,
        script_blob,
        blobs: state.blobs.clone(),
        referrer_source,
        referrer_policy,
        secure_context,
        shared,
        agent_cluster: state.agent_cluster,
        port_registry: state.message_ports.registry.clone(),
        port_wake: message_port_host::Wake::Worker(Arc::downgrade(&ctl)),
        task_sender: LumenTaskSender::Worker(Arc::downgrade(&ctl)),
        storage: state.storage.clone(),
        permission_store: state.permission_store.clone(),
    };
    let handle = workers.handle.clone();
    let tasks = workers.tasks.child();
    let events = workers.events.clone();

    let interrupt = Arc::new(lumen::RuntimeInterrupt::default());
    let worker_interrupt = interrupt.clone();
    // Register the outside port before starting the agent, including on failure:
    // its asynchronous error task must reach the constructor's owning Realm.
    workers.workers.insert(
        id,
        LumenWorkerHandle {
            ctl,
            interrupt,
            tasks: tasks.clone(),
            context,
        },
    );
    let thread_events = events.clone();
    let spawned = spawn_lumen_worker_thread(id, move || {
        let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            run_lumen_worker(
                launch,
                handle,
                tasks,
                thread_events.clone(),
                ctl_rx,
                worker_interrupt,
            );
        }));
        if result.is_err() {
            send_lumen_worker_error(&thread_events, id, "Lumen worker engine panic");
        }
        let _ = thread_events.send(LumenHostTask::WorkerExited { id });
    });
    if let Err(error) = spawned {
        // HTML #worker-processing-model startup failure is an asynchronous error,
        // not a successful constructor returning an inert, unregistered Worker.
        send_lumen_worker_error(
            &events,
            id,
            format!("worker thread creation failed: {error}"),
        );
        let _ = events.send(LumenHostTask::WorkerExited { id });
    }
    Ok(Value::Num(id as f64))
}

#[cfg(test)]
thread_local! {
    // Deterministic OS-resource failure coverage without exhausting real threads
    // or interfering with workers created by tests on other owner threads.
    static WORKER_SPAWN_FAILURE: std::cell::Cell<Option<std::io::ErrorKind>> = const { std::cell::Cell::new(None) };
}

fn spawn_lumen_worker_thread(
    id: usize,
    task: impl FnOnce() + Send + 'static,
) -> std::io::Result<()> {
    #[cfg(test)]
    if let Some(error) = WORKER_SPAWN_FAILURE.take() {
        return Err(error.into());
    }
    // No worker-count quota or oversized per-worker stack reservation. Use the
    // platform/Rust thread default; Lumen grows native execution stack segments
    // only when needed and releases them on return (ECMA-262 #sec-execution-contexts).
    // Each agent remains independently schedulable and blocks on its inbox when
    // idle. Thread creation is constrained by actual OS/memory resources.
    std::thread::Builder::new()
        .name(format!("trust-lumen-worker-{id}"))
        .spawn(task)
        .map(drop)
}

/// MessagePort post-message steps serialize in the sender's realm before this call; the wire
/// snapshot is queued FIFO and deserialized only when the worker selects its message task.
fn host_worker_post(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let id = args
        .first()
        .and_then(Value::as_num_opt)
        .and_then(|id| (id.is_finite() && id >= 0.0 && id.fract() == 0.0).then_some(id as usize));
    let message = host_arg_string(ctx, args, 1);
    let sent = ctx
        .host_mut::<HostState>()
        .and_then(|state| state.workers.as_mut())
        .and_then(|workers| id.and_then(|id| workers.workers.get(&id)))
        .is_some_and(|worker| {
            worker
                .ctl
                .sender
                .send(LumenWorkerCtl::Message(message))
                .is_ok()
        });
    Ok(Value::Bool(sent))
}

/// HTML §10.2.4 terminate-a-worker: discard queued messages and interrupt author code even when
/// the worker is currently executing instead of parked on its inbox.
fn host_worker_terminate(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let id = args
        .first()
        .and_then(Value::as_num_opt)
        .and_then(|id| (id.is_finite() && id >= 0.0 && id.fract() == 0.0).then_some(id as usize));
    if let Some(workers) = ctx
        .host_mut::<HostState>()
        .and_then(|state| state.workers.as_mut())
        && let Some(id) = id
    {
        workers.workers.remove(&id);
    }
    Ok(Value::Undefined)
}

fn host_worker_self_post(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let message = host_arg_string(ctx, args, 0);
    if let Some(worker) = ctx
        .host_mut::<HostState>()
        .and_then(|state| state.worker_self.as_ref())
    {
        let _ = worker.events.send(LumenHostTask::Worker {
            id: worker.id,
            event: crate::js::WorkerOut::Message(message),
        });
    }
    Ok(Value::Undefined)
}

/// HTML #run-a-classic-script with "rethrow errors" set, for the platform's own script sources:
/// `importScripts()` in workers and string TimerHandlers in both realms. The source is a
/// ScriptEvaluation in the current Realm (global declarations and the global lexical scope
/// persist), not indirect eval code. A parse failure is the SyntaxError to rethrow; an
/// uncaught exception propagates to the caller, which reports or rethrows it.
fn host_classic_script_run(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let source = host_arg_usv(ctx, args, 0);
    let url = host_arg_string(ctx, args, 1);
    let origin = lumen::SourceOrigin::new(&url);
    match ctx.eval_classic_script_interruptible_with_origin(&source, Some(&origin)) {
        Ok(Ok(_)) => Ok(Value::Undefined),
        Ok(Err(EvalError::Throw(error))) => Err(error),
        Ok(Err(EvalError::Interrupted(reason))) => Err(ctx.make_error("Error", reason.message())),
        Err(error) => Err(ctx.make_error(
            "SyntaxError",
            format!("{} (line {})", error.message, error.line),
        )),
    }
}

fn host_worker_self_close(ctx: &mut Ctx, _this: Value, _args: &[Value]) -> Result<Value, Value> {
    if let Some(worker) = ctx
        .host_mut::<HostState>()
        .and_then(|state| state.worker_self.as_mut())
    {
        worker.closed = true;
    }
    Ok(Value::Undefined)
}

fn install_lumen_worker_boundary(engine: &mut lumen::Engine) {
    engine.define_global("__geometry_bind", 2, geometry_host::bind);
    engine.define_global("__message_port_binding", 3, message_port_host::call);
    engine.ctx().op_state().register_gc::<HostState>();
    engine.define_global("__image_data_slots", 1, host_image_data_slots);
    engine.define_global("__image_binding", 2, image_host::call);
    engine.define_global("__image_bitmap_binding", 3, image_bitmap_host::call);
    // HTML OffscreenCanvas and WebGL are [Exposed=(Window,Worker)].
    engine.define_global("__offscreen_canvas", 5, canvas_host::offscreen_call);
    engine.define_global("__webgl", 4, webgl_host::call);
    engine.define_global("__wasm_module_binding", 1, host_wasm_module_binding);
    engine.define_global("__permissions_binding", 2, host_permissions_binding);
    engine.define_global("__navigator_binding", 1, host_navigator_binding);
    engine.define_global("__performance_binding", 1, host_performance_binding);
    engine.define_global("__platform_slots", 2, host_platform_slots);
    engine.define_global("__promise_is_handled", 1, host_promise_is_handled);
    engine.define_global(
        "__promise_mark_outstanding",
        1,
        host_promise_mark_outstanding,
    );
    engine.define_global("__promise_react", 3, host_promise_react);
    engine.define_global("__promise_resolved_with", 1, host_promise_resolved_with);
    // DedicatedWorkerGlobalScope is DOM-less. Install only the operations the
    // shared worker prelude can reach, including its independent per-agent
    // WebAssembly store.
    for &(name, len, function) in &[
        ("__clock_now", 0, host_clock_now as NativeFn),
        ("__url_parse", 2, host_url_parse as NativeFn),
        ("__url_set", 3, host_url_set as NativeFn),
        ("__http_fetch", 5, host_http_fetch as NativeFn),
        ("__http_fetch_async", 5, host_http_fetch_async as NativeFn),
        ("__http_fetch_pull", 1, host_http_fetch_pull as NativeFn),
        ("__http_fetch_cancel", 1, host_http_fetch_cancel as NativeFn),
        ("__ws_open", 2, host_ws_open as NativeFn),
        ("__ws_send", 3, host_ws_send as NativeFn),
        ("__ws_close", 3, host_ws_close as NativeFn),
        ("__worker_self_post", 1, host_worker_self_post as NativeFn),
        ("__worker_self_close", 0, host_worker_self_close as NativeFn),
        ("__worker_spawn", 3, host_worker_spawn as NativeFn),
        ("__worker_post", 2, host_worker_post as NativeFn),
        ("__worker_terminate", 1, host_worker_terminate as NativeFn),
        ("__storage_manager", 2, host_storage_manager as NativeFn),
        // The origin's Indexed Database and Cache Storage bottles in the
        // owner's storage shed (Storage #storage-shed), shared with Windows.
        ("__storage_get", 2, host_storage_get as NativeFn),
        ("__storage_set", 3, host_storage_set as NativeFn),
        ("__storage_cas", 4, host_storage_cas as NativeFn),
        ("__storage_remove", 2, host_storage_remove as NativeFn),
        ("__storage_key", 2, host_storage_key as NativeFn),
        ("__storage_len", 1, host_storage_len as NativeFn),
        ("__indexed_db", 2, indexed_db_host::call as NativeFn),
        ("__blob_url", 4, host_blob_url as NativeFn),
        ("__file_read", 3, host_file_read as NativeFn),
        (
            "__crypto_sha256_digest",
            1,
            host_crypto_sha256_digest as NativeFn,
        ),
        ("__crypto_operation", 2, host_crypto_operation as NativeFn),
        ("__crypto_digest", 2, host_crypto_digest as NativeFn),
        (
            "__crypto_random_bytes",
            1,
            host_crypto_random_bytes as NativeFn,
        ),
        (
            "__compression_context",
            4,
            host_compression_context as NativeFn,
        ),
        (
            "__classic_script_run",
            2,
            host_classic_script_run as NativeFn,
        ),
        ("__text_encode", 1, host_text_encode as NativeFn),
        ("__text_decode_utf8", 3, host_text_decode_utf8 as NativeFn),
        (
            "__text_encoding_name",
            1,
            host_text_encoding_name as NativeFn,
        ),
        ("__text_decode", 6, host_text_decode as NativeFn),
        ("__body_buffer", 1, host_body_buffer as NativeFn),
        ("__base64_convert", 2, host_base64_convert as NativeFn),
        ("__wasm_validate", 1, lumen_wasm::host_validate as NativeFn),
        ("__wasm_compile", 1, lumen_wasm::host_compile as NativeFn),
        (
            "__wasm_module_imports",
            1,
            lumen_wasm::host_module_imports as NativeFn,
        ),
        (
            "__wasm_module_exports",
            1,
            lumen_wasm::host_module_exports as NativeFn,
        ),
        (
            "__wasm_module_custom_sections",
            2,
            lumen_wasm::host_module_custom_sections as NativeFn,
        ),
        (
            "__wasm_instantiate",
            3,
            lumen_wasm::host_instantiate as NativeFn,
        ),
        (
            "__wasm_instance_exports",
            2,
            lumen_wasm::host_instance_exports as NativeFn,
        ),
        (
            "__wasm_call_export",
            2,
            lumen_wasm::host_call_export as NativeFn,
        ),
        (
            "__wasm_function_cache",
            2,
            lumen_wasm::host_function_cache as NativeFn,
        ),
        (
            "__wasm_global_new",
            3,
            lumen_wasm::host_global_new as NativeFn,
        ),
        (
            "__wasm_global_get",
            1,
            lumen_wasm::host_global_get as NativeFn,
        ),
        (
            "__wasm_global_set",
            2,
            lumen_wasm::host_global_set as NativeFn,
        ),
        (
            "__wasm_memory_new",
            2,
            lumen_wasm::host_memory_new as NativeFn,
        ),
        (
            "__wasm_memory_size",
            1,
            lumen_wasm::host_memory_size as NativeFn,
        ),
        (
            "__wasm_memory_grow",
            2,
            lumen_wasm::host_memory_grow as NativeFn,
        ),
        (
            "__wasm_memory_buffer",
            1,
            lumen_wasm::host_memory_buffer as NativeFn,
        ),
        (
            "__wasm_table_new",
            4,
            lumen_wasm::host_table_new as NativeFn,
        ),
        (
            "__wasm_table_length",
            1,
            lumen_wasm::host_table_length as NativeFn,
        ),
        (
            "__wasm_table_get",
            2,
            lumen_wasm::host_table_get as NativeFn,
        ),
        (
            "__wasm_table_set",
            3,
            lumen_wasm::host_table_set as NativeFn,
        ),
        (
            "__wasm_table_grow",
            3,
            lumen_wasm::host_table_grow as NativeFn,
        ),
        (
            "__wasm_exception_binding",
            3,
            lumen_wasm::host_exception_binding as NativeFn,
        ),
    ] {
        engine.define_global(name, len, function);
    }
}

fn lumen_same_origin(left: &url::Url, right: &url::Url) -> bool {
    left.scheme() == right.scheme()
        && left.host_str() == right.host_str()
        && left.port_or_known_default() == right.port_or_known_default()
}

struct LumenWorkerScript {
    url: url::Url,
    source: String,
    /// HTML #run-a-worker: the policy container's referrer policy from the script response
    /// (Referrer Policy #parse-referrer-policy-from-header); None for a local scheme.
    referrer_policy: Option<crate::referrer_policy::ReferrerPolicy>,
}

struct LumenWorkerModuleFetch {
    page: url::Url,
    cookie_context: crate::http::CookieContext,
    handle: tokio::runtime::Handle,
    cache: Arc<crate::http::PageCache>,
    fetched: Arc<std::sync::atomic::AtomicUsize>,
    environment: ModuleFetchEnvironment,
}

/// HTML §8.1.4.2 classic/module worker fetch. Top-level HTTP(S) worker requests are same-origin;
/// classic HTTP(S) responses and all module responses require a JavaScript MIME type. `data:` and
/// active same-partition `blob:` entries are fetched without applying the HTTP MIME gate.
fn fetch_lumen_worker_script(
    launch: &LumenWorkerLaunch,
    handle: &tokio::runtime::Handle,
    cache: &Arc<crate::http::PageCache>,
) -> Option<LumenWorkerScript> {
    if launch.script_url.scheme() == "blob" {
        // Fetch #scheme-fetch "blob": the entry the constructor's URL parse resolved; a
        // selected file's range is read now. Without one, a network error.
        let entry = launch.script_blob.as_ref()?;
        if launch.kind == LumenWorkerKind::Module
            && !crate::http::module_script_response_allowed(200, &entry.content_type)
        {
            return None;
        }
        let body = entry.read().ok()?;
        return Some(LumenWorkerScript {
            url: launch.script_url.clone(),
            source: String::from_utf8_lossy(&body).into_owned(),
            // HTML #initialize-worker-policy-container: a blob: worker's container is the
            // entry's environment's (#creating-a-policy-container-from-a-fetch-response).
            referrer_policy: Some(entry.referrer_policy),
        });
    }
    if launch.script_url.scheme() == "data" {
        let content_type = data_url_content_type(launch.script_url.as_str());
        if launch.kind == LumenWorkerKind::Module
            && !crate::http::module_script_response_allowed(200, &content_type)
        {
            return None;
        }
        let body = crate::img::decode_data_url(launch.script_url.as_str())?;
        return Some(LumenWorkerScript {
            url: launch.script_url.clone(),
            source: String::from_utf8_lossy(&body).into_owned(),
            referrer_policy: None,
        });
    }
    if !matches!(launch.script_url.scheme(), "http" | "https")
        || !lumen_same_origin(&launch.owner_page, &launch.script_url)
        || !crate::http::subresource_allowed(&launch.owner_page, &launch.script_url)
    {
        return None;
    }

    let mut request = crate::http::Request::get(launch.script_url.clone());
    crate::http::set_fetch_metadata(&mut request, &launch.owner_page, "worker", "same-origin");
    request.cookie_context = Some(launch.cookie_context.clone());
    // HTML #fetch-a-classic-worker-script: the request's client is the outside settings, so
    // Fetch #determine-requests-referrer uses its creation URL (the owning Window's document
    // or, for a nested worker, the owning worker's URL) under its referrer policy.
    crate::http::set_request_referrer(
        &mut request,
        launch.referrer_source.as_ref(),
        launch.referrer_policy,
    );
    request.fetch_policy = Some(crate::http::FetchPolicy {
        origin: launch.owner_page.clone(),
        mode: crate::http::RequestMode::SameOrigin,
        credentials: crate::http::CredentialsMode::SameOrigin,
    });
    let (sender, receiver) = std::sync::mpsc::channel();
    cache.spawn(handle, async move {
        let result = crate::http::fetch(&request).await.ok().map(|response| {
            (
                response.url,
                response.status,
                response.content_type,
                response.body,
                crate::referrer_policy::ReferrerPolicy::from_headers(&response.headers),
            )
        });
        let _ = sender.send(result);
    });
    let (response_url, status, content_type, body, policy) = receiver.recv().ok().flatten()?;
    if !lumen_same_origin(&launch.owner_page, &response_url)
        || !crate::http::module_script_response_allowed(status, &content_type)
    {
        return None;
    }
    Some(LumenWorkerScript {
        url: response_url,
        source: String::from_utf8_lossy(&body).into_owned(),
        referrer_policy: Some(policy.unwrap_or_default()),
    })
}

fn send_lumen_worker_error(events: &LumenTaskSender, id: usize, message: impl Into<String>) {
    let _ = events.send(LumenHostTask::Worker {
        id,
        event: crate::js::WorkerOut::Error(message.into()),
    });
}

/// Trusted bootstrap runs before author code but still observes a cancellation which raced with
/// realm construction. `Ok(false)` is the silent HTML termination path; parse/throw failures are
/// genuine platform bootstrap defects and are reported to the owner.
fn eval_lumen_worker_setup(
    engine: &mut lumen::Engine,
    source: &str,
    label: &str,
) -> Result<bool, String> {
    match engine.eval_value_interruptible(source) {
        Err(error) => Err(format!(
            "{label} parse error at line {}: {}",
            error.line, error.message
        )),
        Ok(Err(EvalError::Throw(error))) => Err(describe_throw(engine, error, label)),
        Ok(Err(EvalError::Interrupted(_))) => Ok(false),
        Ok(Ok(_)) => Ok(true),
    }
}

fn eval_lumen_worker_platform_setup(engine: &mut lumen::Engine) -> Result<bool, String> {
    let snapshot = worker_prelude_snapshot()?;
    const LABEL: &str = "worker platform prelude";
    match engine.eval_snapshot_value_interruptible(snapshot) {
        Err(error) => Err(format!(
            "{LABEL} parse error at line {}: {}",
            error.line, error.message
        )),
        Ok(Err(EvalError::Throw(error))) => Err(describe_throw(engine, error, LABEL)),
        Ok(Err(EvalError::Interrupted(_))) => Ok(false),
        Ok(Ok(_)) => {
            #[cfg(test)]
            expose_platform_internals_for_tests(engine.ctx(), true, Value::Undefined);
            Ok(true)
        }
    }
}

/// `label` is the worker script's URL, which its stack frames report.
fn eval_lumen_worker_classic(
    engine: &mut lumen::Engine,
    source: &str,
    label: &str,
    events: &LumenTaskSender,
    id: usize,
) -> bool {
    let origin = lumen::SourceOrigin::new(label);
    match engine.eval_value_interruptible_with_origin(source, Some(&origin)) {
        // HTML #run-a-worker: a script whose error to rethrow is a parse error
        // fires a plain "error" event at the Worker object.
        Err(error) => {
            send_lumen_worker_error(
                events,
                id,
                format!(
                    "\u{1}fail {label} parse error at line {}: {}",
                    error.line, error.message
                ),
            );
        }
        // An uncaught exception is reported in the worker global first.
        Ok(Err(EvalError::Throw(error))) => {
            match lumen_worker_internal_call(
                engine,
                "reportException",
                std::slice::from_ref(&error),
            ) {
                Ok(_) => {}
                Err(EvalError::Interrupted(_)) => return false,
                Err(EvalError::Throw(_)) => {
                    send_lumen_worker_error(events, id, describe_throw(engine, error, label));
                }
            }
        }
        Ok(Err(EvalError::Interrupted(_))) => return false,
        Ok(Ok(_)) => {}
    }
    if engine.run_microtasks_interruptible().is_err() {
        return false;
    }
    true
}

fn eval_lumen_worker_module(
    engine: &mut lumen::Engine,
    script: &LumenWorkerScript,
    fetch: LumenWorkerModuleFetch,
    events: &LumenTaskSender,
    id: usize,
) -> bool {
    let loader_page = fetch.page;
    let cookie_context = fetch.cookie_context;
    let loader_handle = fetch.handle;
    let loader_cache = fetch.cache;
    let loader_fetched = fetch.fetched;
    let environment = fetch.environment;
    // A dependency that cannot be fetched leaves the module graph without a
    // result: #run-a-worker then fires a plain error event, not a report.
    let missing_dependency = Arc::new(std::sync::atomic::AtomicBool::new(false));
    let loader_missing = missing_dependency.clone();
    match engine.eval_module_attrs_interruptible(
        &script.source,
        script.url.as_str(),
        move |specifier, referrer, _attributes| {
            let loaded = module_dependency_loader(
                &loader_page,
                &cookie_context,
                &loader_handle,
                &loader_cache,
                &loader_fetched,
                None,
                &environment,
                specifier,
                referrer,
            );
            if loaded.is_none() {
                loader_missing.store(true, std::sync::atomic::Ordering::Relaxed);
            }
            loaded
        },
    ) {
        Err(error) => send_lumen_worker_error(
            events,
            id,
            format!(
                "\u{1}fail {} parse error at line {}: {}",
                script.url, error.line, error.message
            ),
        ),
        // HTML #run-a-worker runs the module script, which reports its exception.
        Ok(lumen::ExecutionOutcome::Throw { name, message })
            if missing_dependency.load(std::sync::atomic::Ordering::Relaxed) =>
        {
            send_lumen_worker_error(
                events,
                id,
                format!("\u{1}fail {} threw {name}: {message}", script.url),
            );
        }
        Ok(lumen::ExecutionOutcome::Throw { name, message }) => {
            let error = engine.ctx().make_error(&name, message.clone());
            if lumen_worker_internal_call(engine, "reportException", &[error]).is_err() {
                send_lumen_worker_error(
                    events,
                    id,
                    format!("{} threw {name}: {message}", script.url),
                );
            }
        }
        Ok(lumen::ExecutionOutcome::Interrupted { .. }) => return false,
        Ok(lumen::ExecutionOutcome::Value(_)) => {}
    }
    true
}

fn lumen_worker_internal_call(
    engine: &mut lumen::Engine,
    name: &str,
    args: &[Value],
) -> Result<Value, EvalError> {
    let worker = platform_control(engine.ctx()).map_err(EvalError::Throw)?;
    let function = engine
        .ctx()
        .member_get(&worker, name)
        .map_err(EvalError::Throw)?;
    engine.call_function_interruptible(&function, worker, args)
}

fn lumen_worker_report_buffered_errors(
    engine: &mut lumen::Engine,
    events: &LumenTaskSender,
    id: usize,
) -> bool {
    // HTML #notify-about-rejected-promises after the task's microtask checkpoint.
    let rejections = engine.take_unhandled_rejections_full();
    if !rejections.is_empty() {
        let pairs: Vec<Value> = rejections
            .into_iter()
            .flat_map(|(promise, reason)| [promise, reason])
            .collect();
        let list = engine.ctx().make_array(pairs);
        if let Err(EvalError::Interrupted(_)) =
            lumen_worker_internal_call(engine, "notifyRejectedPromises", &[list])
        {
            return false;
        }
    }
    // HostPromiseRejectionTracker "handle" for the outstanding rejected promises weak set.
    let handled = engine.take_handled_rejections();
    if !handled.is_empty() {
        let pairs: Vec<Value> = handled
            .into_iter()
            .flat_map(|(promise, reason)| [promise, reason])
            .collect();
        let list = engine.ctx().make_array(pairs);
        if let Err(EvalError::Interrupted(_)) =
            lumen_worker_internal_call(engine, "notifyHandledPromises", &[list])
        {
            return false;
        }
    }
    match lumen_worker_internal_call(engine, "takeConsole", &[]) {
        Ok(value) => {
            let lines = value_string(engine, &value);
            if !lines.is_empty() {
                let _ = events.send(LumenHostTask::Worker {
                    id,
                    event: crate::js::WorkerOut::Console(lines),
                });
            }
        }
        Err(EvalError::Interrupted(_)) => return false,
        Err(EvalError::Throw(_)) => {}
    }
    match lumen_worker_internal_call(engine, "takeErrors", &[]) {
        Ok(value) => {
            let errors = value_string(engine, &value);
            for error in errors.split('\u{1e}').filter(|error| !error.is_empty()) {
                send_lumen_worker_error(events, id, error.to_string());
            }
            true
        }
        Err(EvalError::Interrupted(_)) => false,
        Err(EvalError::Throw(error)) => {
            send_lumen_worker_error(
                events,
                id,
                describe_throw(engine, error, "worker error reporting"),
            );
            true
        }
    }
}

fn lumen_worker_closed(engine: &mut lumen::Engine) -> bool {
    engine
        .ctx()
        .host_mut::<HostState>()
        .and_then(|state| state.worker_self.as_ref())
        .is_some_and(|worker| worker.closed)
}

fn lumen_worker_deadline(engine: &mut lumen::Engine) -> Option<f64> {
    match lumen_worker_internal_call(engine, "nextDeadline", &[]) {
        Ok(Value::Num(deadline)) if deadline.is_finite() => Some(deadline),
        _ => None,
    }
}

/// HTML #event-loop-processing-model (worker event loop): the next rendering
/// opportunity of a DedicatedWorkerGlobalScope with animation frame
/// callbacks (HTML #animationframeprovider).
fn lumen_worker_frame_deadline(engine: &mut lumen::Engine) -> Option<f64> {
    match lumen_worker_internal_call(engine, "animationFrameDeadline", &[]) {
        Ok(Value::Num(deadline)) if deadline.is_finite() => Some(deadline),
        _ => None,
    }
}

/// "Update the rendering of that dedicated worker": run the context lost
/// steps of its 2D OffscreenCanvas contexts, then present WebGL frames and
/// push changed bitmaps to their placeholder canvas elements. Returns false
/// when the worker was interrupted.
fn lumen_worker_update_rendering(engine: &mut lumen::Engine) -> bool {
    let lost = engine.ctx().host_mut::<HostState>().is_some_and(|state| {
        state.offscreen_canvases.values().any(|canvas| {
            let canvas = canvas.borrow();
            canvas.mode == crate::canvas_offscreen::Mode::TwoD
                && canvas
                    .canvas
                    .as_ref()
                    .is_some_and(|canvas| canvas.lost() && !canvas.lost_notified)
        })
    });
    if lost {
        if let Err(EvalError::Interrupted(_)) =
            lumen_worker_internal_call(engine, "runCanvasContextLost", &[])
        {
            return false;
        }
        if engine.run_microtasks_interruptible().is_err() {
            return false;
        }
    }
    if canvas_host::placeholders_dirty(engine.ctx())
        || engine
            .ctx()
            .host_mut::<HostState>()
            .is_some_and(|state| !state.webgl.is_empty())
    {
        webgl_host::publish(engine.ctx(), true, None);
        canvas_host::push_placeholders(engine.ctx());
    }
    true
}

fn lumen_worker_now(engine: &mut lumen::Engine) -> f64 {
    match lumen_worker_internal_call(engine, "now", &[]) {
        Ok(Value::Num(now)) if now.is_finite() => now,
        _ => 0.0,
    }
}

/// One Lumen realm per dedicated worker agent. No engine value crosses the thread boundary;
/// messages are structured-clone wire strings, and every selected message/timer task is followed
/// by its own microtask checkpoint before the loop parks or selects another task.
fn run_lumen_worker(
    launch: LumenWorkerLaunch,
    handle: tokio::runtime::Handle,
    tasks: Arc<crate::http::PageTaskScope>,
    events: LumenTaskSender,
    ctl_rx: std::sync::mpsc::Receiver<LumenWorkerCtl>,
    interrupt: Arc<lumen::RuntimeInterrupt>,
) {
    let _task_lifetime = LumenWorkerTaskLifetime(tasks.clone());
    let nested_tasks = tasks.clone();
    let cache = Arc::new(crate::http::PageCache::with_task_scope(tasks));
    let clock = Rc::new(RealmClock::new());
    let mut state = HostState::new(Rc::new(RefCell::new(Dom::new())), clock.clone());
    state.base = launch.script_url.clone();
    state.task_events = Some(launch.task_sender.clone());
    state.window_cookie_contexts.insert(
        0,
        (
            DOCUMENT,
            launch.script_url.clone(),
            launch.cookie_context.clone(),
        ),
    );
    state.agent_cluster = launch.agent_cluster;
    state.storage = launch.storage.clone();
    // File API #url-model: one blob URL store for the page and all of its agents; this
    // worker's entries leave it when the worker ends (#lifeTime).
    state.blobs = launch.blobs.clone();
    state.blob_release = Some(crate::blob_url_store::EnvironmentRelease {
        store: launch.blobs.clone(),
        agent: state.blob_agent,
    });
    state.permission_store = launch.permission_store.clone();
    state.message_ports.registry = launch.port_registry.clone();
    state.message_ports.wake = launch.port_wake.clone();
    state.network = Some(LumenNetwork {
        handle: handle.clone(),
        cache: cache.clone(),
        fetched: Arc::new(std::sync::atomic::AtomicUsize::new(0)),
        next_fetch_id: 0,
        pending_fetches: HashMap::new(),
        body_streams: HashMap::new(),
    });
    // WebSocket is [Exposed=(Window,Worker)]: the worker's connections follow
    // its owner document's subresource policy and wake this worker's loop.
    state.enable_websockets(
        launch.owner_page.clone(),
        &handle,
        &cache,
        launch.task_sender.clone(),
    );
    let worker_origin = if launch.script_url.scheme() == "data" {
        launch.script_url.clone()
    } else {
        launch.owner_page.clone()
    };
    // HTML #dedicated-workers-and-the-worker-interface: Worker is exposed in
    // DedicatedWorker and SharedWorker globals. A nested worker's outside
    // settings are this worker's: its tasks go to this agent's inbox, its
    // fetches use this worker's origin, and it lives in this worker's owner
    // set, so ending this agent (dropping its handles) terminates it too
    // (#the-worker's-lifetime: an orphan is no longer permissible).
    state.workers = Some(LumenPageWorkers {
        handle: handle.clone(),
        page: worker_origin.clone(),
        tasks: nested_tasks,
        events: launch.task_sender.clone(),
        workers: HashMap::new(),
        next_id: 1,
        shared: HashMap::new(),
    });
    state.worker_self = Some(LumenWorkerSelf {
        id: launch.id,
        events: events.clone(),
        closed: false,
        settings_origin: worker_origin.origin(),
        origin: worker_origin,
        secure_context: launch.secure_context,
        // Until the script response is known, the outside settings' policy (HTML
        // #run-a-worker inherits it for a local-scheme script URL).
        referrer_policy: launch.referrer_policy,
    });

    let mut engine = lumen::Engine::new_with_interrupt(interrupt);
    let engine_clock = clock.clone();
    engine.set_wall_clock(move || engine_clock.now_ms());
    state.configure_module_loading(&mut engine);
    engine
        .ctx()
        .op_state()
        .put_retained_memory_with_external_memory(state);
    install_lumen_worker_boundary(&mut engine);

    let worker_type = if launch.kind == LumenWorkerKind::Module {
        "module"
    } else {
        "classic"
    };
    let config = format!(
        "globalThis.__worker_cfg = {{ id: {}, name: {}, type: {}, url: {}, ua: {}, navigatorMode: {}, platform: {}, language: {}, languages: [{}, {}], hwc: {}, globalPrivacyControl: {}, secureContext: {}, timeOrigin: {}, shared: {} }};",
        launch.id,
        serde_json::to_string(&launch.name).unwrap_or_else(|_| String::from("\"\"")),
        serde_json::to_string(worker_type).expect("static worker type serializes"),
        serde_json::to_string(launch.script_url.as_str()).expect("URL serializes"),
        serde_json::to_string(crate::http::user_agent()).expect("static User-Agent serializes"),
        serde_json::to_string(crate::http::navigator_compatibility_mode().as_str())
            .expect("static compatibility mode serializes"),
        serde_json::to_string(crate::http::navigator_platform())
            .expect("static platform serializes"),
        serde_json::to_string(crate::locale::LANGUAGE).expect("locale serializes"),
        serde_json::to_string(crate::locale::LANGUAGES[0]).expect("locale serializes"),
        serde_json::to_string(crate::locale::LANGUAGES[1]).expect("locale serializes"),
        std::thread::available_parallelism()
            .map(|parallelism| parallelism.get())
            .unwrap_or(8),
        crate::http::GLOBAL_PRIVACY_CONTROL,
        launch.secure_context,
        clock.origin_ms,
        launch.shared,
    );
    for platform in [false, true] {
        let setup = if platform {
            eval_lumen_worker_platform_setup(&mut engine)
        } else {
            eval_lumen_worker_setup(&mut engine, &config, "worker configuration")
        };
        match setup {
            Ok(true) => {}
            Ok(false) => return,
            Err(error) => {
                send_lumen_worker_error(&events, launch.id, error);
                return;
            }
        }
    }

    let Some(script) = fetch_lumen_worker_script(&launch, &handle, &cache) else {
        send_lumen_worker_error(
            &events,
            launch.id,
            format!(
                "\u{1}fail worker script failed to load: {}",
                launch.script_url
            ),
        );
        return;
    };
    engine.set_import_base(script.url.as_str());
    if let Some(policy) = script.referrer_policy
        && let Some(worker) = engine
            .ctx()
            .host_mut::<HostState>()
            .and_then(|state| state.worker_self.as_mut())
    {
        worker.referrer_policy = policy;
    }
    let continued = match launch.kind {
        LumenWorkerKind::Classic => eval_lumen_worker_classic(
            &mut engine,
            &script.source,
            script.url.as_str(),
            &events,
            launch.id,
        ),
        LumenWorkerKind::Module => {
            let fetched = engine
                .ctx()
                .host_mut::<HostState>()
                .and_then(|state| state.network.as_ref())
                .map(|network| network.fetched.clone())
                .unwrap_or_default();
            let environment = ModuleFetchEnvironment::of(engine.ctx(), 0);
            eval_lumen_worker_module(
                &mut engine,
                &script,
                LumenWorkerModuleFetch {
                    page: launch.owner_page.clone(),
                    cookie_context: launch.cookie_context.clone(),
                    handle: handle.clone(),
                    cache: cache.clone(),
                    fetched,
                    environment,
                },
                &events,
                launch.id,
            )
        }
    };
    if !continued
        || !lumen_worker_report_buffered_errors(&mut engine, &events, launch.id)
        || lumen_worker_closed(&mut engine)
    {
        return;
    }
    // HTML #report-an-exception: once a shared worker's script has run, its uncaught
    // errors are reported within the worker (and possibly a developer console), never to
    // the SharedWorker objects. Their channel is closed, so those reports are discarded.
    let events = if launch.shared {
        LumenTaskSender::Worker(std::sync::Weak::new())
    } else {
        events
    };
    enum WorkerTask {
        Command(LumenWorkerCtl),
        Timer,
        Port,
        Bitmap,
        Performance,
        Platform,
        Frame,
    }
    let wall_origin = Instant::now();
    let virtual_origin = lumen_worker_now(&mut engine);
    let mut queued_command = None;
    let mut source_cursor = 0;
    loop {
        let now = virtual_origin + wall_origin.elapsed().as_secs_f64() * 1000.0;
        let deadline = lumen_worker_deadline(&mut engine);
        let frame = lumen_worker_frame_deadline(&mut engine);
        if queued_command.is_none() {
            queued_command = match ctl_rx.try_recv() {
                Ok(command) => Some(command),
                Err(std::sync::mpsc::TryRecvError::Empty) => None,
                Err(std::sync::mpsc::TryRecvError::Disconnected) => break,
            };
        }
        let port_ready = matches!(
            lumen_worker_internal_call(&mut engine, "hasPortTask", &[]),
            Ok(Value::Bool(true))
        );
        let bitmap_ready = matches!(
            lumen_worker_internal_call(&mut engine, "hasBitmapTask", &[]),
            Ok(Value::Bool(true))
        );
        let performance_ready = matches!(
            lumen_worker_internal_call(&mut engine, "hasPerformanceTask", &[]),
            Ok(Value::Bool(true))
        );
        let platform_ready = matches!(
            lumen_worker_internal_call(&mut engine, "hasPlatformTask", &[]),
            Ok(Value::Bool(true))
        );
        // Distinct task sources all make progress. A busy implicit worker port
        // must not starve transferred channels or an already-due timer.
        let mut task = None;
        for offset in 0..7 {
            let source = (source_cursor + offset) % 7;
            task = match source {
                0 => queued_command.take().map(WorkerTask::Command),
                1 if deadline.is_some_and(|deadline| deadline <= now) => Some(WorkerTask::Timer),
                2 if port_ready => Some(WorkerTask::Port),
                3 if bitmap_ready => Some(WorkerTask::Bitmap),
                4 if performance_ready => Some(WorkerTask::Performance),
                5 if platform_ready => Some(WorkerTask::Platform),
                6 if frame.is_some_and(|frame| frame <= now) => Some(WorkerTask::Frame),
                _ => None,
            };
            if task.is_some() {
                source_cursor = (source + 1) % 7;
                break;
            }
        }
        let task = match task {
            Some(task) => task,
            None => {
                let wake = match (deadline, frame) {
                    (Some(deadline), Some(frame)) => Some(deadline.min(frame)),
                    (deadline, frame) => deadline.or(frame),
                };
                if wake.is_none() {
                    engine.collect_garbage_at_idle();
                }
                match wake {
                    Some(wake) => match ctl_rx
                        .recv_timeout(Duration::from_secs_f64((wake - now).max(0.0) / 1000.0))
                    {
                        Ok(command) => WorkerTask::Command(command),
                        Err(std::sync::mpsc::RecvTimeoutError::Timeout)
                            if frame.is_some_and(|frame| frame <= wake) =>
                        {
                            WorkerTask::Frame
                        }
                        Err(std::sync::mpsc::RecvTimeoutError::Timeout) => WorkerTask::Timer,
                        Err(std::sync::mpsc::RecvTimeoutError::Disconnected) => break,
                    },
                    None => match ctl_rx.recv() {
                        Ok(command) => WorkerTask::Command(command),
                        Err(_) => break,
                    },
                }
            }
        };
        let now = virtual_origin + wall_origin.elapsed().as_secs_f64() * 1000.0;
        let _ = lumen_worker_internal_call(&mut engine, "advanceClock", &[Value::Num(now)]);
        let task_result = match task {
            WorkerTask::Command(LumenWorkerCtl::Terminate) => break,
            WorkerTask::Command(LumenWorkerCtl::PortReady(pending)) => {
                pending.store(false, std::sync::atomic::Ordering::Release);
                Ok(Value::Undefined)
            }
            WorkerTask::Command(LumenWorkerCtl::Message(message)) => lumen_worker_internal_call(
                &mut engine,
                "message",
                &[Value::from_engine_text(message)],
            ),
            WorkerTask::Command(LumenWorkerCtl::HostTask(task)) => {
                if let Err(error) = dispatch_host_task(&mut engine, *task) {
                    send_lumen_worker_error(&events, launch.id, error);
                }
                Ok(Value::Undefined)
            }
            WorkerTask::Port => lumen_worker_internal_call(&mut engine, "runPortTask", &[]),
            WorkerTask::Bitmap => lumen_worker_internal_call(&mut engine, "runBitmapTask", &[]),
            WorkerTask::Performance => {
                lumen_worker_internal_call(&mut engine, "runPerformanceTask", &[])
            }
            WorkerTask::Platform => lumen_worker_internal_call(&mut engine, "runPlatformTask", &[]),
            WorkerTask::Timer => {
                lumen_worker_internal_call(&mut engine, "tick", &[Value::Num(now)])
            }
            WorkerTask::Frame => {
                lumen_worker_internal_call(&mut engine, "runAnimationFrames", &[Value::Num(now)])
            }
        };
        match task_result {
            Ok(_) => {}
            Err(EvalError::Interrupted(_)) => break,
            Err(EvalError::Throw(error)) => send_lumen_worker_error(
                &events,
                launch.id,
                describe_throw(&mut engine, error, "worker task"),
            ),
        }
        if engine.run_microtasks_interruptible().is_err()
            || !lumen_worker_report_buffered_errors(&mut engine, &events, launch.id)
            || lumen_worker_closed(&mut engine)
            || !lumen_worker_update_rendering(&mut engine)
        {
            break;
        }
    }
}

fn install_context_module_loader(engine: &mut lumen::Engine, context: u64) {
    let import_map = context_import_map(engine.ctx(), context);
    let page = request_context_url(engine.ctx(), context);
    let cookie_context = cookie_context_for_id(engine.ctx(), context);
    let environment = ModuleFetchEnvironment::of(engine.ctx(), context);
    let work = engine.ctx().host_mut::<HostState>().and_then(|state| {
        state
            .network
            .as_ref()
            .map(|n| (n.handle.clone(), n.cache.clone(), n.fetched.clone()))
    });
    if let Some((handle, cache, fetched)) = work {
        engine.set_module_loader(move |specifier, referrer| {
            module_dependency_loader(
                &page,
                &cookie_context,
                &handle,
                &cache,
                &fetched,
                Some(&import_map),
                &environment,
                specifier,
                referrer,
            )
        });
    }
}

fn context_import_map(ctx: &mut Ctx, context: u64) -> crate::import_maps::Handle {
    ctx.host_mut::<HostState>()
        .expect("module host state")
        .import_maps
        .entry(context)
        .or_default()
        .clone()
}

#[allow(clippy::too_many_arguments)]
fn module_dependency_loader(
    page: &url::Url,
    cookie_context: &crate::http::CookieContext,
    handle: &tokio::runtime::Handle,
    cache: &Arc<crate::http::PageCache>,
    fetched: &std::sync::atomic::AtomicUsize,
    import_map: Option<&crate::import_maps::Handle>,
    environment: &ModuleFetchEnvironment,
    specifier: &str,
    referrer: &str,
) -> Option<(String, String)> {
    let base = url::Url::parse(referrer).unwrap_or_else(|_| page.clone());
    let resolved = if let Some(map) = import_map {
        map.lock()
            .unwrap_or_else(|e| e.into_inner())
            .resolve(specifier, &base)?
    } else {
        resolve_module_specifier(page, specifier, referrer)?
    };
    let integrity = import_map
        .map(|m| {
            m.lock()
                .unwrap_or_else(|e| e.into_inner())
                .integrity(&resolved)
                .to_owned()
        })
        .unwrap_or_default();
    if resolved.scheme() == "data" {
        let content_type = data_url_content_type(resolved.as_str());
        if !crate::http::module_script_response_allowed(200, &content_type) {
            return None;
        }
        let body = crate::img::decode_data_url(resolved.as_str())?;
        if !crate::import_maps::integrity_matches(&integrity, &body) {
            return None;
        }
        return Some((
            resolved.to_string(),
            crate::document_encoding::decode_utf8(&body),
        ));
    }
    if resolved.scheme() == "blob" {
        return environment.blob_module(&resolved, &integrity);
    }
    if !matches!(resolved.scheme(), "http" | "https")
        || !crate::http::subresource_allowed(page, &resolved)
    {
        return None;
    }
    let response = if let Some(shared) = (!cookie_context.cross_site_ancestor)
        .then(|| {
            cache.peek_resource(
                &resolved,
                page,
                "script",
                Some(crate::http::CredentialsMode::SameOrigin),
            )
        })
        .flatten()
    {
        crate::http::PageCache::block_on_fetch(Some(handle), shared)?
    } else {
        // HTML's fetch-a-module-script graph algorithm requires this dependency. Keep the count
        // as diagnostics, but never turn historical activity into a synthetic load failure.
        fetched.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        let request = environment.module_request(resolved.clone(), page, referrer, cookie_context);
        let shared = cache.fetch_prepared_resource(
            handle,
            request,
            page,
            "script",
            Some(crate::http::CredentialsMode::SameOrigin),
        );
        crate::http::PageCache::block_on_fetch(Some(handle), shared)?
    };
    (crate::http::module_script_response_allowed(response.status, &response.content_type)
        && crate::import_maps::integrity_matches(&integrity, &response.body))
    .then(|| {
        if !cookie_context.cross_site_ancestor && cache.claim_module_import_scan(&resolved) {
            speculate_module_imports(page, handle, cache, fetched, &resolved, &response.body);
        }
        (
            resolved.to_string(),
            crate::document_encoding::decode_utf8(&response.body),
        )
    })
}

/// Resolve a module specifier without an import map. HTML's resolve-a-module-specifier algorithm
/// accepts URL-like specifiers here; a bare specifier is a failure rather than a path relative to
/// the referrer. Workers use this URL-only path; Window loaders first apply their import map.
fn resolve_module_specifier(page: &url::Url, specifier: &str, referrer: &str) -> Option<url::Url> {
    if !(specifier.starts_with('/')
        || specifier.starts_with("./")
        || specifier.starts_with("../")
        || url::Url::parse(specifier).is_ok())
    {
        return None;
    }
    let base = url::Url::parse(referrer).unwrap_or_else(|_| page.clone());
    base.join(specifier).ok()
}

fn data_dynamic_module_result(resolved: &url::Url) -> Option<(String, String)> {
    let content_type = data_url_content_type(resolved.as_str());
    crate::http::module_script_response_allowed(200, &content_type)
        .then(|| crate::img::decode_data_url(resolved.as_str()))
        .flatten()
        .map(|body| {
            (
                resolved.to_string(),
                crate::document_encoding::decode_utf8(&body),
            )
        })
}

/// Start one dynamic module fetch and report only Send data back to the owning page thread. Fetch
/// and HTML module-script MIME checks happen off-thread; parsing, linking, evaluation, promise
/// settlement, and the following microtask checkpoint remain serialized in the JS realm.
fn queue_dynamic_module_load(
    loader: &LumenDynamicModuleLoader,
    request_id: u64,
    specifier: &str,
    referrer: &str,
) {
    let base = url::Url::parse(referrer).unwrap_or_else(|_| loader.page.clone());
    let Some(resolved) = loader
        .import_map
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .resolve(specifier, &base)
    else {
        let _ = loader.events.send(LumenHostTask::DynamicModule {
            context: loader.context,
            request_id,
            result: None,
        });
        return;
    };
    let integrity = loader
        .import_map
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .integrity(&resolved)
        .to_owned();
    if resolved.scheme() == "data" {
        let result = data_dynamic_module_result(&resolved).filter(|_| {
            crate::img::decode_data_url(resolved.as_str())
                .is_some_and(|bytes| crate::import_maps::integrity_matches(&integrity, &bytes))
        });
        let _ = loader.events.send(LumenHostTask::DynamicModule {
            context: loader.context,
            request_id,
            result,
        });
        return;
    }
    if resolved.scheme() == "blob" {
        // Resolving the specifier parsed the URL and resolved its blob URL entry now.
        let result = loader.environment.blob_module(&resolved, &integrity);
        let _ = loader.events.send(LumenHostTask::DynamicModule {
            context: loader.context,
            request_id,
            result,
        });
        return;
    }
    let Some(network) = loader.network.as_ref() else {
        let _ = loader.events.send(LumenHostTask::DynamicModule {
            context: loader.context,
            request_id,
            result: None,
        });
        return;
    };
    if !matches!(resolved.scheme(), "http" | "https")
        || !crate::http::subresource_allowed(&loader.page, &resolved)
    {
        let _ = loader.events.send(LumenHostTask::DynamicModule {
            context: loader.context,
            request_id,
            result: None,
        });
        return;
    }

    let shared = if let Some(shared) = (!loader.cookie_context.cross_site_ancestor)
        .then(|| {
            network.cache.peek_resource(
                &resolved,
                &loader.page,
                "script",
                Some(crate::http::CredentialsMode::SameOrigin),
            )
        })
        .flatten()
    {
        shared
    } else {
        // ECMA-262 HostLoadImportedModule plus HTML's module-script fetch do not permit a host to
        // fail a required dynamic import merely because this Document made earlier requests.
        network
            .fetched
            .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        let request = loader.environment.module_request(
            resolved.clone(),
            &loader.page,
            referrer,
            &loader.cookie_context,
        );
        network.cache.fetch_prepared_resource(
            &network.handle,
            request,
            &loader.page,
            "script",
            Some(crate::http::CredentialsMode::SameOrigin),
        )
    };
    let events = loader.events.clone();
    let context = loader.context;
    network.cache.spawn(&network.handle, async move {
        let result = shared.await.ok().and_then(|response| {
            (crate::http::module_script_response_allowed(response.status, &response.content_type)
                && crate::import_maps::integrity_matches(&integrity, &response.body))
            .then(|| {
                (
                    resolved.to_string(),
                    crate::document_encoding::decode_utf8(&response.body),
                )
            })
        });
        let _ = events.send(LumenHostTask::DynamicModule {
            context,
            request_id,
            result,
        });
    });
}

/// HTML #hostloadimportedmodule: import() fetches the imported module script
/// at once ("fetch a single imported module script", whose network work runs
/// in parallel); only processing its response waits for a task. The engine's
/// loader queues `DynamicModuleStart` for the page thread, which can be busy
/// for seconds (the parser's scripts, the first rendering) before it reaches
/// that task. Start the same request here, as import() runs, so the task's
/// `queue_dynamic_module_load` joins it in the page cache; its static graph
/// is fetched as the response arrives.
fn begin_dynamic_module_fetch(loader: &LumenDynamicModuleLoader, specifier: &str, referrer: &str) {
    let Some(network) = loader.network.as_ref() else {
        return;
    };
    if loader.cookie_context.cross_site_ancestor {
        // `queue_dynamic_module_load` does not share these requests.
        return;
    }
    let base = url::Url::parse(referrer).unwrap_or_else(|_| loader.page.clone());
    let Some(resolved) = loader
        .import_map
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .resolve(specifier, &base)
    else {
        return;
    };
    if !matches!(resolved.scheme(), "http" | "https")
        || !crate::http::subresource_allowed(&loader.page, &resolved)
        || network
            .cache
            .peek_resource(
                &resolved,
                &loader.page,
                "script",
                Some(crate::http::CredentialsMode::SameOrigin),
            )
            .is_some()
    {
        return;
    }
    if std::env::var_os("TRUST_NET_TRACE").is_some() {
        eprintln!(
            "lumen: @{:>6}ms dynamic import {resolved}",
            crate::http::trace_ms()
        );
    }
    network
        .fetched
        .fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    let request = loader.environment.module_request(
        resolved.clone(),
        &loader.page,
        referrer,
        &loader.cookie_context,
    );
    let shared = network.cache.fetch_prepared_resource(
        &network.handle,
        request,
        &loader.page,
        "script",
        Some(crate::http::CredentialsMode::SameOrigin),
    );
    let (page, handle, cache, fetched) = (
        loader.page.clone(),
        network.handle.clone(),
        network.cache.clone(),
        network.fetched.clone(),
    );
    network.cache.spawn(&network.handle, async move {
        let Ok(response) = shared.await else {
            return;
        };
        if crate::http::module_script_response_allowed(response.status, &response.content_type)
            && cache.claim_module_import_scan(&resolved)
        {
            speculate_module_graph(page, handle, cache, fetched, resolved, &response.body);
        }
    });
}

fn speculate_engine_imports(engine: &mut lumen::Engine, base: &url::Url, body: &[u8]) {
    if request_cookie_context(engine.ctx()).cross_site_ancestor {
        return;
    }
    let Some((page, handle, cache, fetched)) =
        engine.ctx().host_mut::<HostState>().and_then(|state| {
            let network = state.network.as_ref()?;
            Some((
                state.base.clone(),
                network.handle.clone(),
                network.cache.clone(),
                network.fetched.clone(),
            ))
        })
    else {
        return;
    };
    speculate_module_imports(&page, &handle, &cache, &fetched, base, body);
}

/// HTML §4.12.1 fetches a module script and its dependencies in parallel. Lumen's graph loader
/// intentionally stays synchronous and atomic, so warm every statically named dependency in the
/// shared page cache before that loader asks for them in source order.
///
/// Returns each statically named dependency's shared fetch, whether this
/// started it or found it in the cache.
fn speculate_module_imports(
    page: &url::Url,
    handle: &tokio::runtime::Handle,
    cache: &Arc<crate::http::PageCache>,
    fetched: &std::sync::atomic::AtomicUsize,
    base: &url::Url,
    body: &[u8],
) -> Vec<(url::Url, crate::http::SharedFetch)> {
    let mut dependencies = Vec::new();
    for specifier in crate::js::scan_module_imports(body)
        .into_iter()
        .take(crate::js::MAX_SPECULATIVE_IMPORTS)
    {
        let Some(resolved) = base
            .join(&specifier)
            .ok()
            .filter(|url| matches!(url.scheme(), "http" | "https"))
        else {
            continue;
        };
        if let Some(shared) = cache.peek_resource(
            &resolved,
            page,
            "script",
            Some(crate::http::CredentialsMode::SameOrigin),
        ) {
            dependencies.push((resolved, shared));
            continue;
        }
        if !crate::http::subresource_allowed(page, &resolved)
            || fetched
                .try_update(
                    std::sync::atomic::Ordering::Relaxed,
                    std::sync::atomic::Ordering::Relaxed,
                    |count| {
                        (count < crate::js::MAX_PAGE_FETCHES_WITH_SPECULATION).then_some(count + 1)
                    },
                )
                .is_err()
        {
            continue;
        }
        if std::env::var_os("TRUST_NET_TRACE").is_some() {
            eprintln!(
                "lumen: @{:>6}ms module prefetch {resolved}",
                crate::http::trace_ms()
            );
        }
        let shared = cache.fetch_resource(
            handle,
            resolved.clone(),
            page,
            "script",
            Some(crate::http::CredentialsMode::SameOrigin),
        );
        dependencies.push((resolved, shared));
    }
    dependencies
}

/// HTML #fetch-a-module-script-tree (local whatwg/html@e5071a2): as soon as a
/// module script's own fetch completes, "fetch the descendants of and link"
/// it fetches each of its static dependencies, and theirs in turn, in
/// parallel with the parser and every other script; only linking waits for
/// the whole graph. Lumen's graph loader fetches and links when the module
/// is about to run, which for a deferred module is after the parser's last
/// script. Walk the static graph here instead, on the network runtime as each
/// response arrives, so the loader finds every dependency already fetched.
/// Each module is scanned once (`claim_module_import_scan`), within the
/// speculative-fetch bounds of `speculate_module_imports`.
pub(crate) fn speculate_module_graph(
    page: url::Url,
    handle: tokio::runtime::Handle,
    cache: Arc<crate::http::PageCache>,
    fetched: Arc<std::sync::atomic::AtomicUsize>,
    base: url::Url,
    body: &[u8],
) {
    for (url, shared) in speculate_module_imports(&page, &handle, &cache, &fetched, &base, body) {
        let (page, runtime, graph_cache, fetched) =
            (page.clone(), handle.clone(), cache.clone(), fetched.clone());
        cache.spawn(&handle, async move {
            let Ok(response) = shared.await else {
                return;
            };
            if crate::http::module_script_response_allowed(response.status, &response.content_type)
                && graph_cache.claim_module_import_scan(&url)
            {
                speculate_module_graph(page, runtime, graph_cache, fetched, url, &response.body);
            }
        });
    }
}

fn push_engine_error(engine: &mut lumen::Engine, message: String) {
    host_push_injected_error(engine.ctx(), message);
}

/// HTML #muted-errors: a classic script's errors are muted when its response
/// was CORS-cross-origin, i.e. an HTTP(S) or file script of another origin
/// fetched without a `crossorigin` attribute (a CORS-mode fetch that failed
/// its check never runs). data: and blob: responses are basic, not opaque.
fn classic_script_errors_muted(ctx: &mut Ctx, node_id: usize, url: &str) -> bool {
    let Ok(script) = url::Url::parse(url) else {
        return false;
    };
    if !matches!(script.scheme(), "http" | "https" | "file") {
        return false;
    }
    let document = element_request_client_url(ctx, node_id);
    let cors = host_dom(ctx)
        .borrow()
        .attr(node_id, "crossorigin")
        .is_some();
    !cors && !crate::http::same_origin_for_host(&document, &script)
}

fn fire_engine_script_event(engine: &mut lumen::Engine, node_id: usize, event_type: &str) {
    host_fire_script_event(engine.ctx(), node_id, event_type);
}

/// HTML's run-a-module-script completion steps wait for the module's evaluation promise, including
/// top-level await. Retaining this as a pending resource also keeps the document load event behind
/// parser-inserted module evaluation. Each reaction runs during the owning realm's microtask
/// checkpoint and performs the element's success/failure steps exactly once.
fn track_module_evaluation(engine: &mut lumen::Engine, node_id: usize, name: &str) -> bool {
    let Some(promise) = engine.module_evaluation_promise(name) else {
        return false;
    };
    if let Some(state) = engine.ctx().host_mut::<HostState>() {
        state.pending_resources += 1;
        state.pending_module_evaluations += 1;
        state.dom_gc.start_resource(node_id);
    } else {
        return false;
    }

    let fulfilled = engine.ctx().new_native_fn(
        "",
        0,
        Rc::new(move |ctx, _this, _args| {
            let _lease = ctx
                .host_mut::<HostState>()
                .map(|state| state.dom_gc.resource_lease(node_id));
            if let Some(state) = ctx.host_mut::<HostState>() {
                state.pending_resources = state.pending_resources.saturating_sub(1);
                state.pending_module_evaluations =
                    state.pending_module_evaluations.saturating_sub(1);
            }
            host_fire_script_event(ctx, node_id, "load");
            Ok(Value::Undefined)
        }),
    );
    let failed_name = name.to_string();
    let rejected = engine.ctx().new_native_fn(
        "",
        1,
        Rc::new(move |ctx, _this, args| {
            let _lease = ctx
                .host_mut::<HostState>()
                .map(|state| state.dom_gc.resource_lease(node_id));
            if let Some(state) = ctx.host_mut::<HostState>() {
                state.pending_resources = state.pending_resources.saturating_sub(1);
                state.pending_module_evaluations =
                    state.pending_module_evaluations.saturating_sub(1);
            }
            // HTML #run-a-module-script reports the rejected evaluation;
            // #execute-the-script-element then fires load at an external
            // script, whose fetch and parse succeeded.
            let exception = args.first().cloned().unwrap_or(Value::Undefined);
            if host_report_exception(ctx, exception.clone(), &failed_name, false, None) {
                let reason = ctx
                    .coerce_string(&exception)
                    .map(|value| value.to_string())
                    .unwrap_or_else(|_| String::from("module evaluation failed"));
                host_push_injected_error(ctx, format!("module {failed_name}: {reason}"));
            }
            let external = host_dom(ctx).borrow().attr(node_id, "src").is_some();
            if external {
                host_fire_script_event(ctx, node_id, "load");
            }
            Ok(Value::Undefined)
        }),
    );
    let attached = engine
        .ctx()
        .member_get(&promise, "then")
        .map_err(EvalError::Throw)
        .and_then(|then| {
            engine
                .ctx()
                .invoke_interruptible(then, promise, &[fulfilled, rejected])
        })
        .is_ok();
    if !attached && let Some(state) = engine.ctx().host_mut::<HostState>() {
        state.pending_resources = state.pending_resources.saturating_sub(1);
        state.pending_module_evaluations = state.pending_module_evaluations.saturating_sub(1);
        state.dom_gc.finish_resource(node_id);
    }
    attached
}

/// Run a parser-inserted or fetched classic script. `url` is what its stack frames report: the
/// script's URL, or the document's for an inline script.
fn run_injected_classic_task(
    engine: &mut lumen::Engine,
    node_id: usize,
    name: &str,
    url: &str,
    source: &str,
) -> Result<(), String> {
    let trust = host_trust(engine.ctx()).map_err(|_| "read the platform control".to_string())?;
    let document_base = state_base(engine.ctx());
    // HTML #prepare-the-script-element: a fetched classic script's base URL is its URL; an
    // inline one's is its node document's document base URL. Lumen keeps it as the referrer of
    // the script's import() calls, including later ones from functions the script created.
    let script_base = if name == url {
        name.to_string()
    } else {
        host_call_trust_interruptible(
            engine.ctx(),
            "resourceBaseURL",
            &[Value::Num(node_id as f64)],
        )
        .ok()
        .and_then(|base| engine.ctx().coerce_string(&base).ok())
        .map_or_else(|| document_base.clone(), |base| base.to_string())
    };
    engine.set_import_base(&script_base);
    let old_current = engine
        .ctx()
        .member_get(&trust, "currentScript")
        .unwrap_or(Value::Null);
    let _ = host_call_trust(
        engine.ctx(),
        "bindFrameForNode",
        &[Value::Num(node_id as f64)],
    );
    let current = classic_current_script(engine.ctx(), node_id);
    let _ = engine.ctx().member_set(&trust, "currentScript", current);
    let origin = lumen::SourceOrigin::new(url);
    let evaluated = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        engine.eval_value_interruptible_with_origin(source, Some(&origin))
    }));
    let muted = classic_script_errors_muted(engine.ctx(), node_id, url);
    match evaluated {
        Ok(Ok(Ok(_))) => {}
        Ok(Ok(Err(EvalError::Throw(error)))) => {
            if host_report_exception(engine.ctx(), error.clone(), name, muted, Some((url, 0))) {
                let message = describe_throw(engine, error, name);
                push_engine_error(engine, message);
            }
        }
        Ok(Ok(Err(error))) => {
            let message = describe_eval_error(engine, error, name);
            push_engine_error(engine, message);
        }
        Ok(Err(error)) => {
            let syntax_error = engine
                .ctx()
                .make_error("SyntaxError", error.message.clone());
            if host_report_exception(
                engine.ctx(),
                syntax_error,
                name,
                muted,
                Some((url, error.line)),
            ) {
                push_engine_error(
                    engine,
                    format!(
                        "{name} parse error at line {}: {}",
                        error.line, error.message
                    ),
                );
            }
        }
        Err(_) => push_engine_error(engine, format!("{name}: Lumen engine panic")),
    }
    // HTML clean-up after running script performs a checkpoint once the script stack is empty.
    let checkpoint = engine
        .run_microtasks_interruptible()
        .map_err(|reason| format!("{name} microtasks interrupted: {}", reason.message()));
    let _ = engine
        .ctx()
        .member_set(&trust, "currentScript", old_current);
    let _ = host_call_trust(engine.ctx(), "restoreFrame", &[]);
    engine.set_import_base(&document_base);
    checkpoint
}

fn run_injected_module_task(
    engine: &mut lumen::Engine,
    node_id: usize,
    name: &str,
    source: &str,
) -> Result<(), String> {
    let context = host_call_trust(
        engine.ctx(),
        "resourceClientContext",
        &[Value::Num(node_id as f64)],
    )
    .ok()
    .and_then(|v| v.as_num_opt())
    .unwrap_or(0.) as u64;
    let import_map = context_import_map(engine.ctx(), context);
    let cookie_context = element_cookie_context(engine.ctx(), node_id);
    let client = element_request_client_url(engine.ctx(), node_id);
    let environment = ModuleFetchEnvironment::of(engine.ctx(), context);
    let snapshot = engine.ctx().host_mut::<HostState>().and_then(|state| {
        let network = state.network.as_ref()?;
        Some((
            client,
            network.handle.clone(),
            network.cache.clone(),
            network.fetched.clone(),
        ))
    });
    // HTML runs a module with its preparation-time Document's realm/settings.
    // TRust multiplexes same-agent nested Window realms through one Lumen
    // global, so enter the script element's owning frame for evaluation and
    // the immediately-following microtask checkpoint. This is the module
    // counterpart of `run_injected_classic_task` above.
    let _ = host_call_trust(
        engine.ctx(),
        "bindFrameForNode",
        &[Value::Num(node_id as f64)],
    );
    let result = (|| {
        let evaluated = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            if let Some((page, handle, cache, fetched)) = snapshot {
                let loader_page = page.clone();
                engine.eval_module_attrs_interruptible(
                    source,
                    name,
                    move |specifier, referrer, _attributes| {
                        module_dependency_loader(
                            &loader_page,
                            &cookie_context,
                            &handle,
                            &cache,
                            &fetched,
                            Some(&import_map),
                            &environment,
                            specifier,
                            referrer,
                        )
                    },
                )
            } else {
                engine.eval_module_attrs_interruptible(
                    source,
                    name,
                    |_specifier, _referrer, _attributes| None,
                )
            }
        }));
        match evaluated {
            Ok(Ok(lumen::ExecutionOutcome::Value(_))) => {
                if !track_module_evaluation(engine, node_id, name) {
                    fire_engine_script_event(engine, node_id, "load");
                }
                engine.run_microtasks_interruptible().map_err(|reason| {
                    format!("module {name} microtasks interrupted: {}", reason.message())
                })?;
            }
            Ok(Ok(lumen::ExecutionOutcome::Throw { name: ty, message })) => {
                push_engine_error(engine, format!("module {name}: {ty}: {message}"));
                fire_engine_script_event(engine, node_id, "error");
            }
            Ok(Ok(lumen::ExecutionOutcome::Interrupted { reason })) => {
                return Err(format!("module {name} interrupted: {}", reason.message()));
            }
            Ok(Err(error)) => {
                push_engine_error(
                    engine,
                    format!(
                        "module {name} parse error at line {}: {}",
                        error.line, error.message
                    ),
                );
                fire_engine_script_event(engine, node_id, "error");
            }
            Err(_) => {
                push_engine_error(engine, format!("module {name}: Lumen engine panic"));
                fire_engine_script_event(engine, node_id, "error");
            }
        }
        Ok(())
    })();
    let _ = host_call_trust(engine.ctx(), "restoreFrame", &[]);
    result
}

/// The fallback encoding of a script or style sheet fetched for `node`: its
/// `charset` attribute's encoding (HTML #prepare-the-script-element; the CSS
/// environment encoding of HTML #link-type-stylesheet), or else its node
/// document's encoding.
fn element_fallback_encoding(
    engine: &mut lumen::Engine,
    node: usize,
) -> &'static encoding_rs::Encoding {
    let dom = engine
        .ctx()
        .host_mut::<HostState>()
        .expect("HostState installed before resource dispatch")
        .dom
        .clone();
    let dom = dom.borrow();
    dom_fallback_encoding(&dom, node)
}

fn dom_fallback_encoding(dom: &Dom, node: usize) -> &'static encoding_rs::Encoding {
    dom.attr(node, "charset")
        .and_then(|label| encoding_rs::Encoding::for_label(label.as_bytes()))
        .unwrap_or_else(|| {
            dom.owner_document(node)
                .map_or(encoding_rs::UTF_8, |document| {
                    dom.document_encoding(document)
                })
        })
}

// The completed fetch's parts, as the resource task receives them.
#[allow(clippy::too_many_arguments)]
fn run_resource_task(
    engine: &mut lumen::Engine,
    node_id: usize,
    name: String,
    kind: LumenResourceKind,
    result: LumenResourceResult,
    text: Option<String>,
    sheet: Option<Box<crate::http::FetchedStyleSheet>>,
    external: bool,
) -> Result<(), String> {
    match kind {
        LumenResourceKind::ClassicScript => match result {
            Some((status, content_type, body, headers))
                if crate::http::classic_script_response_allowed(
                    status,
                    &content_type,
                    &headers,
                ) =>
            {
                let source = text.unwrap_or_else(|| {
                    let fallback = element_fallback_encoding(engine, node_id);
                    crate::document_encoding::decode_classic_script(&content_type, &body, fallback)
                });
                run_injected_classic_task(engine, node_id, &name, &name, &source)?;
                if external {
                    fire_engine_script_event(engine, node_id, "load");
                }
            }
            _ => fire_engine_script_event(engine, node_id, "error"),
        },
        LumenResourceKind::ModuleScript => match result {
            Some((status, content_type, body, _headers))
                if crate::http::module_script_response_allowed(status, &content_type) =>
            {
                let import_base = url::Url::parse(&name)
                    .unwrap_or_else(|_| url::Url::parse(&state_base(engine.ctx())).unwrap());
                let context = engine.ctx().host_job_context();
                let map = context_import_map(engine.ctx(), context);
                let metadata = host_dom(engine.ctx())
                    .borrow()
                    .attr(node_id, "integrity")
                    .filter(|s| !s.is_empty())
                    .map(str::to_owned)
                    .unwrap_or_else(|| {
                        map.lock()
                            .unwrap_or_else(|e| e.into_inner())
                            .integrity(&import_base)
                            .to_owned()
                    });
                if !crate::import_maps::integrity_matches(&metadata, &body) {
                    fire_engine_script_event(engine, node_id, "error");
                    return Ok(());
                }
                speculate_engine_imports(engine, &import_base, &body);
                let source = crate::document_encoding::decode_utf8(&body);
                run_injected_module_task(engine, node_id, &name, &source)?;
            }
            _ => {
                if let Some(state) = engine.ctx().host_mut::<HostState>() {
                    state.modules_skipped += 1;
                }
                fire_engine_script_event(engine, node_id, "error");
            }
        },
        LumenResourceKind::Stylesheet => match result {
            Some((status, content_type, body, headers))
                if crate::http::stylesheet_response_allowed(status, &content_type, &headers) =>
            {
                // CSS Values 4 #relative-urls: a fetched sheet arrives with
                // its URLs resolved against its own response URL. Only an
                // undelivered (`data:`) sheet is decoded here; Fetch's scheme
                // fetch makes a data: response basic, so CORS-same-origin.
                let sheet = sheet.map_or_else(
                    || {
                        let environment = element_fallback_encoding(engine, node_id);
                        crate::http::FetchedStyleSheet {
                            text: crate::document_encoding::decode_stylesheet(
                                &content_type,
                                &body,
                                Some(environment),
                            )
                            .0,
                            base: name.clone(),
                            cors_same_origin: true,
                            referrer_policy: None,
                            imports: Vec::new(),
                        }
                    },
                    |sheet| *sheet,
                );
                let dom = engine
                    .ctx()
                    .host_mut::<HostState>()
                    .expect("HostState installed before resource dispatch")
                    .dom
                    .clone();
                // Decoded CSS is Rust text; CSSOM strings are DOM engine text.
                let to_engine = |sheet: crate::http::PageSheet| crate::http::PageSheet {
                    text: dom_text_in(&sheet.text).into_owned(),
                    ..sheet
                };
                let link = to_engine(crate::http::PageSheet {
                    link_href: None,
                    url: name.clone(),
                    base: sheet.base,
                    text: sheet.text,
                    cors_same_origin: sheet.cors_same_origin,
                    referrer_policy: sheet.referrer_policy,
                });
                let imports = sheet.imports.into_iter().map(to_engine).collect();
                dom.borrow_mut()
                    .attach_sheet_to_link(node_id, link, imports);
                fire_engine_script_event(engine, node_id, "load");
            }
            _ => fire_engine_script_event(engine, node_id, "error"),
        },
        // HTML #link-type-stylesheet "process the linked resource": the sheet
        // is already attached; only the element's event remains.
        LumenResourceKind::ParsedStylesheet { obtained } => {
            fire_engine_script_event(engine, node_id, if obtained { "load" } else { "error" });
        }
        // HTML #link-type-preload: `error` only for a network error.
        LumenResourceKind::Preload => {
            fire_engine_script_event(
                engine,
                node_id,
                if result.is_some() { "load" } else { "error" },
            );
        }
    }
    Ok(())
}

fn dispatch_websocket_task(
    engine: &mut lumen::Engine,
    id: usize,
    event: crate::ws::WsIn,
) -> Result<(), String> {
    let mut args = vec![
        Value::Num(id as f64),
        Value::Undefined,
        Value::from_string(String::new()),
        Value::Bool(false),
        Value::Num(0.0),
        Value::from_string(String::new()),
        Value::Bool(false),
        Value::Bool(false),
        Value::from_string(String::new()),
        Value::from_string(String::new()),
    ];
    match event {
        crate::ws::WsIn::Open {
            protocol,
            extensions,
        } => {
            args[1] = Value::from_string(String::from("open"));
            args[8] = Value::from_string(protocol);
            args[9] = Value::from_string(extensions);
        }
        crate::ws::WsIn::Text(message) => {
            args[1] = Value::from_string(String::from("message"));
            args[2] = Value::from_string(message);
        }
        crate::ws::WsIn::Binary(bytes) => {
            args[1] = Value::from_string(String::from("message"));
            args[2] = engine
                .ctx()
                .make_array_buffer(&bytes)
                .map_err(|_| String::from("WebSocket task: message too large"))?;
            args[3] = Value::Bool(true);
        }
        crate::ws::WsIn::Sent(bytes) => {
            args[1] = Value::from_string(String::from("drain"));
            args[4] = Value::Num(bytes as f64);
        }
        crate::ws::WsIn::Closed {
            code,
            reason,
            was_clean,
            failed,
        } => {
            if let Some(sockets) = engine
                .ctx()
                .host_mut::<HostState>()
                .and_then(|state| state.websockets.as_mut())
            {
                sockets.sockets.remove(&id);
            }
            args[1] = Value::from_string(String::from("close"));
            args[4] = Value::Num(f64::from(code));
            args[5] = Value::from_string(reason);
            args[6] = Value::Bool(was_clean);
            args[7] = Value::Bool(failed);
        }
    }
    match host_call_trust_interruptible(engine.ctx(), "wsEvent", &args) {
        Ok(_) => Ok(()),
        Err(error) => host_task_failure(engine.ctx(), error, "WebSocket task"),
    }
}

/// Run the engine-owned portion of one selected host task. The caller performs the HTML event
/// loop's microtask checkpoint after this returns, before selecting another task.
#[allow(dead_code)] // The networked test realm uses this before the resident actor is switched.
fn settle_network_task(
    engine: &mut lumen::Engine,
    id: usize,
    value: impl FnOnce(&mut Ctx) -> Value,
) -> Result<(), String> {
    let pending = engine
        .ctx()
        .host_mut::<HostState>()
        .and_then(|state| state.network.as_mut())
        .and_then(|network| network.pending_fetches.remove(&id));
    let Some(pending) = pending else {
        return Ok(());
    };
    let context = pending.context;
    let native_lease = pending.native_lease;
    let run = move |engine: &mut lumen::Engine| {
        let _native_lease = native_lease;
        let value = value(engine.ctx());
        engine
            .call_function_interruptible(&pending.resolve, Value::Undefined, &[value])
            .map(|_| ())
            .map_err(|error| describe_eval_error(engine, error, "image networking task"))
    };
    if context == engine.ctx().host_job_context() {
        return run(engine);
    }
    let realm = engine
        .ctx()
        .host_mut::<HostState>()
        .and_then(|state| state.window_realms.get(&context).cloned());
    let Some(realm) = realm else { return Ok(()) }; // Replaced/inactive Document.
    match engine.with_embed_realm(&realm, run) {
        Ok(result) => result,
        Err(_) => Err(String::from("image networking task Realm is unavailable")),
    }
}

fn dispatch_host_task(engine: &mut lumen::Engine, task: LumenHostTask) -> Result<(), String> {
    match task {
        LumenHostTask::PortReady => {}
        LumenHostTask::Media { id, task } => media_host::dispatch(engine, id, task)?,
        LumenHostTask::WebAudio(task) => webaudio_host::dispatch(engine, task)?,
        LumenHostTask::CanvasFrame { node } => {
            let dom = engine
                .ctx()
                .host_mut::<HostState>()
                .expect("HostState installed before host tasks")
                .dom
                .clone();
            canvas_host::present_frames(&mut dom.borrow_mut(), Some(node));
        }
        LumenHostTask::SvgResourceDone => {
            // The next rendering opportunity resolves the references again.
            if let Some(state) = engine.ctx().host_mut::<HostState>() {
                state.dom.borrow_mut().resource_changed();
            }
        }
        LumenHostTask::FontDone { url, bytes } => {
            let dom = engine
                .ctx()
                .host_mut::<HostState>()
                .expect("HostState installed before host tasks")
                .dom
                .clone();
            dom.borrow_mut().install_downloaded_font(&url, bytes);
        }
        LumenHostTask::StyleImportsDone { url, sheets } => {
            let dom = {
                let state = engine
                    .ctx()
                    .host_mut::<HostState>()
                    .expect("HostState installed before host tasks");
                state.in_flight_imports.remove(&url);
                state.dom.clone()
            };
            // Decoded CSS is Rust text; CSSOM strings are DOM engine text.
            let sheets = sheets
                .into_iter()
                .map(|sheet| crate::http::PageSheet {
                    text: dom_text_in(&sheet.text).into_owned(),
                    ..sheet
                })
                .collect();
            dom.borrow_mut().attach_imported_sheets(sheets);
            // CSSImportRule.styleSheet: the rules waiting for these sheets
            // associate them and hand the cascade their rules.
            let _ = host_call_trust(engine.ctx(), "styleImportsArrived", &[]);
        }
        LumenHostTask::ParserResourceTiming(timing) => {
            record_resource_timing_ref(engine.ctx(), &timing);
        }
        LumenHostTask::ImageDone {
            id,
            result,
            timing,
            timing_context,
        } => {
            record_resource_timing_in(engine, timing_context, timing)?;
            settle_network_task(engine, id, move |ctx| image_host::result_value(ctx, result))?;
        }
        LumenHostTask::DocumentImageDone {
            context,
            url,
            timing,
            size,
            document_svg,
        } => {
            if let Some(state) = engine.ctx().host_mut::<HostState>() {
                state.pending_document_images = state.pending_document_images.saturating_sub(1);
                // The document learns a stylesheet image's natural dimensions
                // from its own request (CSS Images 3 #default-sizing); the next
                // rendering opportunity relays out and repaints with them.
                let changed = match size {
                    Some(size) => state.images.borrow_mut().insert(url, size) != Some(size),
                    None => false,
                };
                if changed {
                    state.geom_cache.borrow_mut().epoch = u64::MAX;
                }
                // Inline SVG document images re-serialize at the next layout.
                if changed || document_svg {
                    state.dom.borrow_mut().resource_changed();
                }
            }
            record_resource_timing_in(engine, context, timing)?;
        }
        LumenHostTask::NavigateDone {
            id,
            details,
            node,
            target,
            destination,
        } => {
            settle_network_task(engine, id, move |ctx| match details {
                Some(details) => navigation_result_value(ctx, *details, node, &target, destination)
                    .unwrap_or(Value::Null),
                None => Value::Null,
            })?;
        }
        LumenHostTask::FetchHead { id, result, flow } => {
            let pending = engine
                .ctx()
                .host_mut::<HostState>()
                .and_then(|state| state.network.as_mut())
                .and_then(|network| network.pending_fetches.remove(&id));
            let Some(pending) = pending else {
                flow.cancel();
                return Ok(());
            };
            let context = pending.context;
            let realm_active = context == engine.ctx().host_job_context()
                || engine
                    .ctx()
                    .host_mut::<HostState>()
                    .is_some_and(|state| state.window_realms.contains_key(&context));
            if !realm_active {
                flow.cancel();
                return Ok(());
            }
            if let Some(network) = engine
                .ctx()
                .host_mut::<HostState>()
                .and_then(|state| state.network.as_mut())
            {
                network.body_streams.insert(
                    id,
                    LumenBodyStream {
                        context,
                        flow,
                        buffer: Vec::new(),
                        end: None,
                        pull: None,
                    },
                );
            }
            let resolve = pending.resolve;
            run_in_context_realm(engine, context, "fetch task", move |engine| {
                let value = host_fetch_result_value(engine.ctx(), result);
                if matches!(value, Value::Obj(_)) {
                    // The body is read from the network buffer: element 8 is
                    // the fetch id the body's stream pulls with.
                    engine
                        .ctx()
                        .member_set(&value, "8", Value::Num(id as f64))
                        .map_err(|_| String::from("fetch task: response record"))?;
                }
                engine
                    .call_function_interruptible(&resolve, Value::Undefined, &[value])
                    .map(|_| ())
                    .map_err(|error| describe_eval_error(engine, error, "fetch networking task"))
            })?;
        }
        LumenHostTask::FetchBodyChunk { id, bytes } => {
            let Some(network) = engine
                .ctx()
                .host_mut::<HostState>()
                .and_then(|state| state.network.as_mut())
            else {
                return Ok(());
            };
            let Some(stream) = network.body_streams.get_mut(&id) else {
                return Ok(());
            };
            if stream.buffer.is_empty() {
                stream.buffer = bytes;
            } else {
                stream.buffer.extend_from_slice(&bytes);
            }
            settle_body_pull(engine, id)?;
        }
        LumenHostTask::FetchBodyEnd { id, ok, timing } => {
            let context = {
                let Some(network) = engine
                    .ctx()
                    .host_mut::<HostState>()
                    .and_then(|state| state.network.as_mut())
                else {
                    return Ok(());
                };
                let Some(stream) = network.body_streams.get_mut(&id) else {
                    return Ok(());
                };
                stream.end = Some(ok);
                stream.context
            };
            run_in_context_realm(engine, context, "fetch task", move |engine| {
                record_resource_timing(engine.ctx(), timing);
                Ok(())
            })?;
            settle_body_pull(engine, id)?;
        }
        LumenHostTask::FetchDone { id, result, timing } => {
            let pending = engine
                .ctx()
                .host_mut::<HostState>()
                .and_then(|state| state.network.as_mut())
                .and_then(|network| network.pending_fetches.remove(&id));
            let Some(pending) = pending else {
                return Ok(());
            };
            // Fetch §2 records a global object as the fetch params' task
            // destination and queues response processing on that global's
            // networking task source. Construct the Response payload in that
            // Realm as well: Fetch §5.3 consumes the Body using the response
            // object's relevant global, including its ArrayBuffer intrinsics.
            let context = pending.context;
            let resolve = pending.resolve;
            let run = move |engine: &mut lumen::Engine| {
                record_resource_timing(engine.ctx(), timing);
                let value = host_fetch_result_value(engine.ctx(), result);
                engine
                    .call_function_interruptible(&resolve, Value::Undefined, &[value])
                    .map_err(|error| describe_eval_error(engine, error, "fetch networking task"))
            };
            if context == engine.ctx().host_job_context() {
                run(engine)?;
            } else {
                let realm = engine
                    .ctx()
                    .host_mut::<HostState>()
                    .and_then(|state| state.window_realms.get(&context).cloned());
                let Some(realm) = realm else {
                    // A task associated with a no-longer-active Document is
                    // not runnable on the Window event loop.
                    return Ok(());
                };
                match engine.with_embed_realm(&realm, run) {
                    Ok(result) => {
                        result?;
                    }
                    Err(error) => {
                        let message = engine
                            .ctx()
                            .coerce_string(&error)
                            .map(|message| message.to_string())
                            .unwrap_or_else(|_| String::from("unknown Window Realm"));
                        return Err(format!("fetch task Realm: {message}"));
                    }
                }
            }
        }
        LumenHostTask::ResourceDone {
            context,
            node_id,
            name,
            kind,
            result,
            text,
            sheet,
            timing,
            external,
        } => {
            let _lease = engine
                .ctx()
                .host_mut::<HostState>()
                .map(|state| state.dom_gc.resource_lease(node_id));
            if let Some(state) = engine.ctx().host_mut::<HostState>() {
                if kind.delays_load() {
                    state.pending_resources = state.pending_resources.saturating_sub(1);
                } else {
                    state.pending_preloads = state.pending_preloads.saturating_sub(1);
                }
                // A script of an aborted parser: its task is discarded.
                if state.parser.abandoned.remove(&node_id) {
                    return Ok(());
                }
            }
            // HTML §8.1.7.2 queues element work against the element's relevant
            // global/Document. A parallel resource fetch therefore retains
            // the environment-settings token captured at preparation time;
            // dispatching through the actor's root Realm would fire load/error
            // against the wrong Realm-local listener registry.
            if context == engine.ctx().host_job_context() {
                record_resource_timing(engine.ctx(), timing);
                run_resource_task(engine, node_id, name, kind, result, text, sheet, external)?;
            } else {
                let realm = engine
                    .ctx()
                    .host_mut::<HostState>()
                    .and_then(|state| state.window_realms.get(&context).cloned());
                let Some(realm) = realm else {
                    // Its Document was replaced while the fetch was in
                    // flight. Tasks whose document is no longer active are
                    // not runnable in the Window event loop.
                    return Ok(());
                };
                match engine.with_embed_realm(&realm, move |engine| {
                    record_resource_timing(engine.ctx(), timing);
                    run_resource_task(engine, node_id, name, kind, result, text, sheet, external)
                }) {
                    Ok(result) => result?,
                    Err(error) => {
                        let message = engine
                            .ctx()
                            .coerce_string(&error)
                            .map(|message| message.to_string())
                            .unwrap_or_else(|_| String::from("unknown Window Realm"));
                        return Err(format!("resource task Realm: {message}"));
                    }
                }
            }
        }
        LumenHostTask::DynamicModuleStart {
            request_id,
            context,
            specifier,
            referrer,
        } => {
            if std::env::var_os("TRUST_NET_TRACE").is_some() {
                eprintln!(
                    "lumen: @{:>6}ms dynamic import task {specifier}",
                    crate::http::trace_ms()
                );
            }
            let cookie_context = cookie_context_for_id(engine.ctx(), context);
            let page = request_context_url(engine.ctx(), context);
            let environment = ModuleFetchEnvironment::of(engine.ctx(), context);
            let state = engine
                .ctx()
                .host_mut::<HostState>()
                .expect("module host state");
            if let Some(events) = state.task_events.clone() {
                let loader = LumenDynamicModuleLoader {
                    context,
                    page,
                    cookie_context,
                    environment,
                    events,
                    import_map: state.import_maps.entry(context).or_default().clone(),
                    network: state
                        .network
                        .as_ref()
                        .map(|network| LumenDynamicModuleNetwork {
                            handle: network.handle.clone(),
                            cache: network.cache.clone(),
                            fetched: network.fetched.clone(),
                        }),
                };
                queue_dynamic_module_load(&loader, request_id, &specifier, &referrer);
            }
        }
        LumenHostTask::DynamicModule {
            context,
            request_id,
            result,
        } => {
            if let Some(state) = engine.ctx().host_mut::<HostState>() {
                state.pending_dynamic_modules.update(
                    std::sync::atomic::Ordering::Relaxed,
                    std::sync::atomic::Ordering::Relaxed,
                    |count| count.saturating_sub(1),
                );
            }
            install_context_module_loader(engine, context);
            let _ = engine.finish_dynamic_module_load(request_id, result);
            install_context_module_loader(engine, 0);
        }
        LumenHostTask::WebSocket { id, event } => {
            dispatch_websocket_task(engine, id, event)?;
        }
        LumenHostTask::Worker { id, event } => {
            let (name, payload) = match event {
                crate::js::WorkerOut::Message(message) => ("workerMessage", message),
                crate::js::WorkerOut::Error(message) => ("workerError", message),
                crate::js::WorkerOut::Console(lines) => ("workerConsole", lines),
            };
            dispatch_lumen_worker_task(engine, id, name, Value::from_engine_text(payload))?;
        }
        LumenHostTask::WorkerExited { id } => {
            let result = dispatch_lumen_worker_task(engine, id, "workerExited", Value::Undefined);
            if let Some(workers) = engine
                .ctx()
                .host_mut::<HostState>()
                .and_then(|state| state.workers.as_mut())
            {
                workers.workers.remove(&id);
                workers.shared.retain(|_, (shared, ..)| *shared != id);
            }
            result?;
        }
        LumenHostTask::AbortDocument { context } => {
            // A navigable whose Document is no longer active has none to abort.
            run_in_context_realm(engine, context, "abort document", move |engine| {
                abort_document(engine.ctx(), context);
                Ok(())
            })?;
        }
    }
    Ok(())
}

fn dispatch_lumen_worker_task(
    engine: &mut lumen::Engine,
    id: usize,
    name: &str,
    payload: Value,
) -> Result<(), String> {
    let context = engine
        .ctx()
        .host_mut::<HostState>()
        .and_then(|state| state.workers.as_ref())
        .and_then(|workers| workers.workers.get(&id))
        .map(|worker| worker.context);
    let Some(context) = context else {
        return Ok(());
    };
    let run = move |engine: &mut lumen::Engine| match host_call_trust_interruptible(
        engine.ctx(),
        name,
        &[Value::Num(id as f64), payload],
    ) {
        Ok(_) => Ok(()),
        Err(error) => host_task_failure(engine.ctx(), error, "Worker task"),
    };
    if context == engine.ctx().host_job_context() {
        run(engine)
    } else {
        let realm = engine
            .ctx()
            .host_mut::<HostState>()
            .and_then(|state| state.window_realms.get(&context).cloned());
        let Some(realm) = realm else { return Ok(()) };
        engine
            .with_embed_realm(&realm, run)
            .map_err(|_| String::from("Worker task Realm is unavailable"))?
    }
}

fn host_create_element(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let tag = host_arg_string(ctx, args, 0);
    let dom = host_dom(ctx);
    let mut dom = dom.borrow_mut();
    let document = host_creation_document(&dom, args, 1);
    let id = dom.create_element(&tag);
    dom.initialize_node_document(id, document);
    Ok(host_id_value(Some(id)))
}

fn host_create_element_ns(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let namespace = host_arg_string(ctx, args, 0);
    let prefix = host_arg_string(ctx, args, 1);
    let local_name = host_arg_string(ctx, args, 2);
    let dom = host_dom(ctx);
    let mut dom = dom.borrow_mut();
    let document = host_creation_document(&dom, args, 3);
    let id = dom.create_element_ns(
        &namespace,
        (!prefix.is_empty()).then_some(prefix.as_str()),
        &local_name,
    );
    dom.initialize_node_document(id, document);
    Ok(host_id_value(Some(id)))
}

fn host_create_text(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let text = host_arg_string(ctx, args, 0);
    let dom = host_dom(ctx);
    let mut dom = dom.borrow_mut();
    let document = host_creation_document(&dom, args, 1);
    let id = dom.create_text(&text);
    dom.initialize_node_document(id, document);
    Ok(host_id_value(Some(id)))
}

fn host_create_fragment(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let dom = host_dom(ctx);
    let mut dom = dom.borrow_mut();
    let document = host_creation_document(&dom, args, 0);
    let id = dom.create_fragment();
    dom.initialize_node_document(id, document);
    Ok(host_id_value(Some(id)))
}

/// HTML fragment parsing and `DOMParser` use distinct algorithms. This operation deliberately uses
/// HTML's full document parsing algorithm and transplants its `html`/`head`/`body` tree into the
/// page arena; fragment parsing is exposed by the later inner-HTML boundary slice.
fn host_parse_document(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let html = host_arg_string(ctx, args, 0);
    let content_type = args
        .get(1)
        .filter(|value| !matches!(value, Value::Undefined))
        .map(|_| host_arg_string(ctx, args, 1))
        .unwrap_or_else(|| "text/html".into());
    // XHR #document-response step 8 sets the decoded document's encoding;
    // DOMParser and createHTMLDocument keep DOM's UTF-8 default.
    let encoding = host_arg_encoding(ctx, args, 2);
    let dom = host_dom(ctx);
    // A fourth argument true: Document.parseHTMLUnsafe()'s document, which
    // allows declarative shadow roots.
    let declarative = matches!(args.get(3), Some(Value::Bool(true)));
    let id = if content_type == "text/html" {
        dom.borrow_mut()
            .parse_document_into_with(&html, declarative)
    } else {
        // The XML parser reads the DOMString's scalar values: a lone
        // surrogate becomes U+FFFD (HTML #dom-domparser-parsefromstring).
        dom.borrow_mut()
            .parse_xml_document_into(&crate::dom::replace_lone_surrogates(&html), &content_type)
    };
    dom.borrow_mut().set_document_encoding(id, encoding);
    Ok(host_id_value(Some(id)))
}

/// An encoding name (or label) argument; absent or unknown means UTF-8.
fn host_arg_encoding(
    ctx: &mut Ctx,
    args: &[Value],
    index: usize,
) -> &'static encoding_rs::Encoding {
    match args.get(index) {
        Some(Value::Str(_)) => {
            encoding_rs::Encoding::for_label(host_arg_string(ctx, args, index).as_bytes())
                .unwrap_or(encoding_rs::UTF_8)
        }
        _ => encoding_rs::UTF_8,
    }
}

/// DOM #dom-document-characterset: the name of a document's encoding.
fn host_document_encoding(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let dom = host_dom(ctx);
    let dom = dom.borrow();
    let encoding =
        host_arg_node(&dom, args, 0).map_or(encoding_rs::UTF_8, |id| dom.document_encoding(id));
    Ok(Value::from_engine_text(encoding.name()))
}

/// Decoded document text and its encoding's name, as a two-element array.
fn host_decoded_document(
    ctx: &mut Ctx,
    decoded: crate::document_encoding::DecodedDocument,
) -> Value {
    ctx.make_array(vec![
        Value::from_string(decoded.text),
        Value::from_engine_text(decoded.encoding.name()),
    ])
}

/// HTML #read-html, #read-xml and #read-text for a nested navigable's
/// response: (bytes, Content-Type, response URL, container Document's
/// encoding name when same origin, or null) → [text, encoding name].
fn host_document_decode(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let bytes = args
        .first()
        .and_then(|value| ctx.buffer_source_bytes(value, true))
        .ok_or_else(|| ctx.make_error("TypeError", "Document body is not a BufferSource"))?;
    let content_type = host_arg_string(ctx, args, 1);
    let url = host_arg_usv(ctx, args, 2);
    let container = match args.get(3) {
        Some(Value::Str(_)) => {
            encoding_rs::Encoding::for_label(host_arg_string(ctx, args, 3).as_bytes())
        }
        _ => None,
    };
    let essence = content_type.split(';').next().unwrap_or("").trim();
    let decoded = crate::document_encoding::decode_document(
        crate::document_encoding::DocumentKind::for_essence(essence),
        &bytes,
        crate::document_encoding::SniffContext {
            content_type: &content_type,
            container,
            local_file: url::Url::parse(&url).is_ok_and(|url| url.scheme() == "file"),
        },
    );
    Ok(host_decoded_document(ctx, decoded))
}

/// XHR response decoding: (bytes, a label or null, html) → [text, encoding
/// name]. With `html`, #document-response step 5 for an HTML document (the
/// final encoding's label, else the prescan, else UTF-8); otherwise
/// #text-response's Encoding #decode with the label's fallback encoding.
fn host_xhr_decode(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let bytes = args
        .first()
        .and_then(|value| ctx.buffer_source_bytes(value, true))
        .ok_or_else(|| ctx.make_error("TypeError", "Response body is not a BufferSource"))?;
    let label = match args.get(1) {
        Some(Value::Str(_)) => Some(host_arg_string(ctx, args, 1)),
        _ => None,
    };
    let decoded = if matches!(args.get(2), Some(Value::Bool(true))) {
        crate::document_encoding::decode_xhr_html(&bytes, label.as_deref())
    } else {
        crate::document_encoding::decode_with_label(&bytes, label.as_deref())
    };
    Ok(host_decoded_document(ctx, decoded))
}

/// HTML's "consume a character reference" outside an attribute, as WebVTT's
/// cue text tokenizer uses it (WebVTT #webvtt-cue-text-tokenizer, "HTML
/// character reference in data/annotation state"): (text after the U+0026,
/// additional allowed character or null) → [code units consumed, characters],
/// or null when nothing is consumed and the ampersand stays literal.
fn host_html_char_ref(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let input = host_arg_string(ctx, args, 0);
    let additional = match args.get(1) {
        Some(Value::Str(_)) => host_arg_string(ctx, args, 1).chars().next(),
        _ => None,
    };
    Ok(match consume_character_reference(&input, additional) {
        Some((consumed, text)) => {
            ctx.make_array(vec![Value::Num(consumed as f64), Value::from_string(text)])
        }
        None => Value::Null,
    })
}

/// HTML #character-reference-state, #numeric-character-reference-end-state
/// and #named-character-reference-state, not as part of an attribute: the
/// number of (ASCII, so UTF-16 and UTF-8 alike) units consumed after the
/// U+0026 and the characters they stand for.
fn consume_character_reference(input: &str, additional: Option<char>) -> Option<(usize, String)> {
    let bytes = input.as_bytes();
    let first = input.chars().next()?;
    if matches!(first, '\t' | '\n' | '\x0C' | ' ' | '<' | '&') || Some(first) == additional {
        return None;
    }
    if first == '#' {
        let hex = matches!(bytes.get(1), Some(b'x' | b'X'));
        let digits_start = if hex { 2 } else { 1 };
        let radix = if hex { 16 } else { 10 };
        let mut end = digits_start;
        let mut value: u32 = 0;
        while let Some(digit) = bytes
            .get(end)
            .and_then(|&byte| char::from(byte).to_digit(radix))
        {
            // Any value past U+10FFFF is replaced; saturate rather than wrap.
            value = value
                .saturating_mul(radix)
                .saturating_add(digit)
                .min(0x11_0000);
            end += 1;
        }
        if end == digits_start {
            return None;
        }
        if bytes.get(end) == Some(&b';') {
            end += 1;
        }
        let character = match value {
            0 | 0xD800..=0xDFFF => '\u{FFFD}',
            0x80..=0x9F => html5ever::data::C1_REPLACEMENTS[(value - 0x80) as usize]
                .unwrap_or_else(|| char::from_u32(value).unwrap_or('\u{FFFD}')),
            value => char::from_u32(value).unwrap_or('\u{FFFD}'),
        };
        return Some((end, character.to_string()));
    }
    // The longest name in the named character reference table that the
    // input starts with; a missing semicolon is only a parse error here.
    let mut matched = None;
    for (index, character) in input.char_indices() {
        if !character.is_ascii() {
            break;
        }
        match html5ever::data::NAMED_ENTITIES.get(&input[..=index]) {
            Some(&(first, second)) => {
                if first != 0 {
                    matched = Some((index + 1, first, second));
                }
            }
            None => break,
        }
    }
    let (consumed, first, second) = matched?;
    let mut text = String::new();
    text.extend(char::from_u32(first));
    if second != 0 {
        text.extend(char::from_u32(second));
    }
    Some((consumed, text))
}

fn host_create_document(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let content_type = host_arg_string(ctx, args, 0);
    let id = host_dom(ctx).borrow_mut().create_document(&content_type);
    Ok(host_id_value(Some(id)))
}

fn host_document_content_type(ctx: &mut Ctx, _this: Value, args: &[Value]) -> Result<Value, Value> {
    let dom = host_dom(ctx);
    let dom = dom.borrow();
    let content_type = host_arg_node(&dom, args, 0)
        .map(|id| dom.document_content_type(id))
        .unwrap_or("text/html");
    Ok(Value::from_engine_text(content_type))
}

/// Whether the Document is an inert template contents owner document (HTML
/// #appropriate-template-contents-owner-document): its URL is about:blank.
