    #[test]
    fn client_rects_keep_viewport_fixed_descendants_stationary_while_scrolling() {
        let dom = Rc::new(RefCell::new(Dom::parse_document(
            r#"<!doctype html><style>body{margin:0;width:2000px;height:2000px}
            #fixed{position:fixed;left:20px;top:30px;width:80px;height:50px}
            #child{width:20px;height:10px} #flow{width:20px;height:10px}
            #transformed{transform:translateX(0);height:80px}
            #local{position:fixed;top:5px;left:7px;width:10px;height:10px}
            </style><div id=fixed><div id=child></div></div><div id=flow></div>
            <div id=transformed><div id=local></div></div>"#,
        )));
        let mut engine =
            configured_engine(HostState::new(dom, Rc::new(RealmClock::new())), DEFAULT_URL);
        assert_eq!(
            string_value(
                &mut engine,
                r#"(() => {
            const fixed=document.getElementById('fixed'), child=document.getElementById('child');
            const flow=document.getElementById('flow'), local=document.getElementById('local');
            const before=[fixed,child,flow,local].map(e=>e.getBoundingClientRect());
            __trust.setScroll(100,200);
            const after=[fixed,child,flow,local].map(e=>e.getBoundingClientRect());
            for(let i=0;i<4;i++) {
                const dx=before[i].x-after[i].x, dy=before[i].y-after[i].y;
                if(dx!==(i<2?0:100)||dy!==(i<2?0:200)) return 'scroll '+i+': '+dx+','+dy;
            }
            if(fixed.getClientRects()[0].top!==30 || fixed.offsetTop!==30) return 'rect interfaces';
            if(before[0].top!==30) return 'snapshot';
            return 'ok';
        })()"#
            ),
            "ok"
        );
    }

    #[test]
    fn lazy_border_box_projection_keeps_scroll_inline_and_frame_geometry_current() {
        // CSSOM View #dom-element-getboundingclientrect / #dom-element-scrollwidth:
        // a border rectangle and a scrolling area are distinct projections of
        // the same current layout. Returned rectangles remain snapshots.
        let dom = Rc::new(RefCell::new(Dom::parse_document(
            r#"<style>
            body { margin:0 }
            #box { width:80px; height:20px; padding:2px; border:3px solid }
            #scroll { width:120px; height:60px; overflow:auto }
            #wide { width:250px; height:80px }
            #fixed { position:fixed; left:200px; top:100px; width:30px; height:40px }
            #zero { position:absolute; left:3px; top:4px; width:0; height:0 }
            #wrap { width:80px }
            iframe { width:180px; height:80px; border:3px solid }
            </style><div id=box></div><div id=scroll><div id=wide></div></div>
            <div id=fixed></div><div id=zero></div>
            <div id=wrap><span id=inline>several words wrapping onto more lines</span></div>
            <iframe id=frame></iframe>"#,
        )));
        let mut engine =
            configured_engine(HostState::new(dom, Rc::new(RealmClock::new())), DEFAULT_URL);
        let start = crate::layout2::layout_pass_count();
        assert_eq!(
            string_value(
                &mut engine,
                r#"
                var box=document.getElementById('box');
                var before=box.getBoundingClientRect();
                var fixed=document.getElementById('fixed').getBoundingClientRect();
                var zero=document.getElementById('zero').getBoundingClientRect();
                JSON.stringify([before.width,before.height,fixed.x,fixed.y,
                    fixed.width,fixed.height,zero.x,zero.y,zero.width,zero.height])
            "#
            ),
            "[90,30,200,100,30,40,3,4,0,0]"
        );
        assert_eq!(crate::layout2::layout_pass_count(), start + 1);
        let cache = engine
            .ctx()
            .host_mut::<HostState>()
            .unwrap()
            .geom_cache
            .clone();
        assert!(!cache.borrow().complete_geometry);
        assert_eq!(cache.borrow().boxes.len(), 3);
        assert_eq!(
            string_value(
                &mut engine,
                "String(document.getElementById('scroll').scrollWidth)"
            ),
            "250"
        );
        assert!(cache.borrow().complete_geometry);
        assert_eq!(crate::layout2::layout_pass_count(), start + 1);
        assert_eq!(
            string_value(
                &mut engine,
                r#"
                box.style.width='110px';
                JSON.stringify([before.width,box.getBoundingClientRect().width])
            "#
            ),
            "[90,120]"
        );
        assert!(!cache.borrow().complete_geometry);
        assert_eq!(crate::layout2::layout_pass_count(), start + 2);
        assert_eq!(
            string_value(
                &mut engine,
                r#"
                var inline=document.getElementById('inline').getBoundingClientRect();
                String(inline.width>0 && inline.height>20)
            "#
            ),
            "true"
        );
        assert!(cache.borrow().complete_geometry);
        assert_eq!(crate::layout2::layout_pass_count(), start + 2);
        assert_eq!(
            string_value(
                &mut engine,
                r#"
                box.style.display='none';
                var hidden=box.getBoundingClientRect();
                JSON.stringify([hidden.x,hidden.y,hidden.width,hidden.height])
            "#
            ),
            "[0,0,0,0]"
        );
        assert!(cache.borrow().complete_geometry);
        assert_eq!(
            string_value(
                &mut engine,
                r#"
                var frame=document.getElementById('frame');
                var child=frame.contentDocument;
                child.body.innerHTML='<div id=inside style="width:37px;height:19px"></div>';
                var inside=child.getElementById('inside');
                var childBefore=inside.getBoundingClientRect();
                var frameBefore=frame.getBoundingClientRect();
                inside.style.width='57px';
                JSON.stringify([childBefore.x,childBefore.width,frameBefore.width,
                    frame.getBoundingClientRect().width,inside.getBoundingClientRect().width])
            "#
            ),
            "[8,37,186,186,57]"
        );
        // A nested Document's node takes the rectangle-only projection too,
        // placed in its own viewport by the container's content-box origin.
        // It agrees with the complete projection of the same layout.
        let start = crate::layout2::layout_pass_count();
        let lazy = string_value(
            &mut engine,
            r#"
            frame.style.marginLeft='13px';
            var lazy=inside.getBoundingClientRect();
            JSON.stringify([lazy.x,lazy.y,lazy.width,lazy.height])
        "#,
        );
        assert_eq!(lazy, "[8,8,57,19]");
        assert!(!cache.borrow().complete_geometry);
        assert_eq!(cache.borrow().boxes.len(), 1);
        assert_eq!(cache.borrow().frame_viewports.len(), 1);
        let complete = string_value(
            &mut engine,
            r#"
            document.getElementById('scroll').scrollWidth;
            var complete=inside.getBoundingClientRect();
            JSON.stringify([complete.x,complete.y,complete.width,complete.height])
        "#,
        );
        assert!(cache.borrow().complete_geometry);
        assert_eq!(lazy, complete);
        assert_eq!(crate::layout2::layout_pass_count(), start + 1);
    }

    #[test]
    fn canvas_pixels_repaint_without_relayout_but_resize_updates_geometry() {
        let dom = Rc::new(RefCell::new(Dom::parse_document(
            "<style>body{margin:0}canvas{display:block}</style>\
             <canvas id=c width=12 height=10></canvas><div id=after>after</div>",
        )));
        let mut engine = configured_engine(
            HostState::new(dom.clone(), Rc::new(RealmClock::new())),
            DEFAULT_URL,
        );
        let canvas = dom.borrow().get_by_id("c").unwrap();
        let cache = ensure_host_geom_cache(engine.ctx(), "before drawing");
        let fragments = cache.borrow().fragments.clone().unwrap();
        let _ = dom.borrow_mut().take_dirty();
        let _ = dom.borrow_mut().take_dirty_targets();
        eval(
            &mut engine,
            r#"
            const c=document.getElementById('c'),two=c.getContext('2d');
            two.fillStyle='red';
            for(let i=0;i<100;i++)two.fillRect(0,0,12,10);
        "#,
            "draw canvas pixels",
        )
        .unwrap();
        assert!(
            dom.borrow_mut().take_dirty(),
            "drawing requests presentation"
        );
        assert_eq!(
            dom.borrow_mut().take_dirty_targets(),
            Some(vec![(canvas, crate::dom::DirtyKind::Paint)])
        );
        ensure_host_geom_cache(engine.ctx(), "after drawing");
        assert!(
            Arc::ptr_eq(&fragments, cache.borrow().fragments.as_ref().unwrap()),
            "bitmap updates must reuse the established fragment geometry"
        );
        assert_eq!(
            &dom.borrow().canvas_image(canvas).unwrap().image.rgba[..4],
            &[255, 0, 0, 255]
        );
        assert_eq!(
            string_value(
                &mut engine,
                "String(document.getElementById('after').getBoundingClientRect().top)"
            ),
            "10"
        );
        eval(&mut engine, "c.height=25", "resize canvas").unwrap();
        assert_eq!(
            string_value(
                &mut engine,
                "String(document.getElementById('after').getBoundingClientRect().top)"
            ),
            "25"
        );
        assert!(!Arc::ptr_eq(
            &fragments,
            cache.borrow().fragments.as_ref().unwrap()
        ));
        assert_eq!(
            &dom.borrow().canvas_image(canvas).unwrap().image.rgba[..4],
            &[0, 0, 0, 0]
        );
    }

    #[test]
    fn retained_layout_invalidates_activation_and_resource_inputs_without_dom_writes() {
        let dom = Rc::new(RefCell::new(Dom::parse_document(
            r#"<body><a id="link" href="/next">next</a><img id="image" src="/image.png"></body>"#,
        )));
        let mut engine = configured_engine(
            HostState::new(dom.clone(), Rc::new(RealmClock::new())),
            DEFAULT_URL,
        );
        let cache = ensure_host_geom_cache(engine.ctx(), "initial");
        let initial = cache.borrow().fragments.clone().unwrap();
        let epoch = dom.borrow().epoch();
        let link = dom.borrow().get_by_id("link").unwrap();
        dom.borrow_mut()
            .set_render_clickables([link].into_iter().collect(), true);
        assert_eq!(
            dom.borrow().epoch(),
            epoch,
            "presentation metadata is not a DOM mutation"
        );
        ensure_host_geom_cache(engine.ctx(), "activation");
        assert!(!Arc::ptr_eq(
            &initial,
            cache.borrow().fragments.as_ref().unwrap()
        ));
        let activated = cache.borrow().fragments.clone().unwrap();
        dom.borrow_mut()
            .set_render_clickables([link].into_iter().collect(), true);
        ensure_host_geom_cache(engine.ctx(), "same-activation");
        assert!(Arc::ptr_eq(
            &activated,
            cache.borrow().fragments.as_ref().unwrap()
        ));
        {
            let state = engine.ctx().host_mut::<HostState>().unwrap();
            state
                .images
                .borrow_mut()
                .insert("https://example.com/image.png".into(), (320, 180));
            state.geom_cache.borrow_mut().epoch = u64::MAX;
        }
        ensure_host_geom_cache(engine.ctx(), "image-size");
        assert!(!Arc::ptr_eq(
            &activated,
            cache.borrow().fragments.as_ref().unwrap()
        ));
        let image = dom.borrow().get_by_id("image").unwrap();
        assert_eq!(cache.borrow().boxes[&image].width, 320.);
        assert_eq!(cache.borrow().boxes[&image].height, 180.);
        assert_eq!(dom.borrow().epoch(), epoch);
    }

    #[test]
    fn retained_layout_scroll_updates_hit_testing_without_reflow() {
        // CSSOM View §5: hit testing applies the current scroll transforms;
        // scrolling itself does not change the underlying flow geometry.
        let dom = Rc::new(RefCell::new(Dom::parse_document(
            r#"<style>
            body { margin:0 } #scroller { width:100px; height:40px; overflow:auto }
            #first, #second { height:40px }
        </style><div id="scroller"><div id="first">first</div><div id="second">second</div></div>"#,
        )));
        let mut engine = configured_engine(
            HostState::new(dom.clone(), Rc::new(RealmClock::new())),
            DEFAULT_URL,
        );
        assert_eq!(
            string_value(&mut engine, "document.elementFromPoint(10,10).id"),
            "first"
        );
        let passes = crate::layout2::layout_pass_count();
        let hit_storage = ensure_host_hit_test_cache(engine.ctx())
            .borrow()
            .hit_index
            .as_ref()
            .unwrap()
            .storage_identity();
        let epoch = dom.borrow().epoch();
        let scroller = dom.borrow().get_by_id("scroller").unwrap();
        dom.borrow_mut().set_scroll_pos(scroller, 40., 0., true);
        assert_eq!(dom.borrow().epoch(), epoch);
        assert_eq!(
            string_value(&mut engine, "document.elementFromPoint(10,10).id"),
            "second"
        );
        assert_eq!(
            crate::layout2::layout_pass_count(),
            passes,
            "scroll must refresh hit-test paint, not relayout"
        );
        assert_eq!(
            ensure_host_hit_test_cache(engine.ctx())
                .borrow()
                .hit_index
                .as_ref()
                .unwrap()
                .storage_identity(),
            hit_storage
        );
    }

    #[test]
    fn top_level_hit_testing_reuses_paint_across_nested_document_changes() {
        // HTML §7.3.1.3: a child navigable's Document changes neither the
        // container's boxes nor its paint order, so top-level hit testing
        // after a nested-only change needs no new layout or paint.
        let dom = Rc::new(RefCell::new(Dom::parse_document(
            r#"<!doctype html><style>body{margin:0} iframe{display:block;border:0;width:200px;height:100px}
            #below{height:50px}</style><iframe id=frame
            srcdoc='<!doctype html><style>body{margin:0}</style><p id=inner style="margin:0;height:20px">x</p>'></iframe>
            <div id=below></div>"#,
        )));
        let mut engine = configured_engine(
            HostState::new(dom.clone(), Rc::new(RealmClock::new())),
            DEFAULT_URL,
        );
        assert_eq!(
            string_value(
                &mut engine,
                "__trust.hydrateFrames(); document.elementFromPoint(10,10).id"
            ),
            "frame"
        );
        let passes = crate::layout2::layout_pass_count();
        let revision = dom.borrow().top_document_revision();
        assert_eq!(
            string_value(
                &mut engine,
                r#"const inner = document.getElementById('frame').contentDocument.getElementById('inner');
                inner.style.height = '60px'; inner.remove();
                [document.elementFromPoint(10,10).id, document.elementFromPoint(10,120).id].join()"#
            ),
            "frame,below"
        );
        assert_eq!(dom.borrow().top_document_revision(), revision);
        assert_eq!(
            crate::layout2::layout_pass_count(),
            passes,
            "nested-only changes reuse top-level hit testing"
        );
        // Nested hit testing still reflects the nested Document's changes:
        // the removed paragraph left an empty body below the root element.
        assert_eq!(
            string_value(
                &mut engine,
                "document.getElementById('frame').contentDocument.elementFromPoint(10,10).localName"
            ),
            "html"
        );
        assert_eq!(
            string_value(
                &mut engine,
                "document.getElementById('below').style.height = '0px'; document.getElementById('frame').style.height = '130px'; document.elementFromPoint(10,120).id"
            ),
            "frame"
        );
        assert_ne!(dom.borrow().top_document_revision(), revision);
    }

