    #[derive(Default)]
    struct HostRetainedProbe {
        allocations: usize,
        values: Vec<Value>,
        opaque: usize,
        unavailable: usize,
    }

    impl HostRetainedMemoryVisitor for HostRetainedProbe {
        fn allocation(&mut self, _allocation: RetainedManagedAllocation) {
            self.allocations += 1;
        }

        fn value(&mut self, value: &Value) {
            self.values.push(value.clone());
        }

        fn opaque_storage(&mut self) {
            self.opaque += 1;
        }

        fn unavailable(&mut self) {
            self.unavailable += 1;
        }
    }

    #[test]
    fn host_state_retained_inventory_is_exhaustive_and_keeps_value_roots() {
        let mut state = HostState::new(
            Rc::new(RefCell::new(Dom::new())),
            Rc::new(RealmClock::new()),
        );
        state.window_realms.insert(7, Value::Num(19.0));
        let mut probe = HostRetainedProbe::default();
        state.scan_retained_memory(&mut probe);

        assert!(probe.allocations >= 8);
        assert_eq!(probe.values.len(), 1);
        assert_eq!(probe.values[0].as_num_opt(), Some(19.0));
        assert!(probe.opaque >= 1);
        assert_eq!(probe.unavailable, 0);
    }

    #[test]
    fn non_isolated_globals_hide_shared_array_buffer() {
        // HTML #dom-crossoriginisolated and the realm creation steps: a
        // Window or worker outside a cross-origin isolated agent cluster
        // reports false and has no global SharedArrayBuffer (Chromium and
        // Firefox agree).
        for mut engine in [platform_engine(), worker_platform_engine()] {
            assert_eq!(
                string_value(
                    &mut engine,
                    "[typeof SharedArrayBuffer, crossOriginIsolated, \
                      typeof Object.getOwnPropertyDescriptor(globalThis, 'crossOriginIsolated').get, \
                      'SharedArrayBuffer' in globalThis].join()"
                ),
                "undefined,false,function,false"
            );
        }
    }

    #[test]
    fn legacy_factories_and_visual_viewport_follow_their_idl() {
        // HTML #dom-option, #dom-image and #dom-audio are legacy factory
        // functions (Web IDL #legacy-factory-functions: length 0, a fixed
        // prototype property, `new` required); option text is HTML's
        // collect option text. CSSOM View #the-visualviewport-interface
        // without pinch zoom reports the layout viewport. Values match
        // Chromium's.
        let mut engine = platform_engine();
        assert_eq!(
            string_value(
                &mut engine,
                "const s = document.createElement('select');\n\
                 s.innerHTML = '<optgroup><option label=L> x <script>y</script> z </option>' +\n\
                   '</optgroup><option>b</option>';\n\
                 const [a, b] = s.querySelectorAll('option');\n\
                 const o = new Option(' t ', 'v', false, true);\n\
                 const i = new Image(3, 4), au = new Audio('x.mp3');\n\
                 let thrown = false; try { Option(); } catch (e) { thrown = e instanceof TypeError; }\n\
                 const p = Object.getOwnPropertyDescriptor(Option, 'prototype');\n\
                 [a.text, a.value, a.label, b.label, a.index, b.index, a.form,\n\
                  o.text, o.value, o.selected, Option.length, p.writable, p.configurable,\n\
                  Option.prototype === HTMLOptionElement.prototype, thrown,\n\
                  i.getAttribute('width'), i.height, Image.length,\n\
                  au.getAttribute('preload'), au.getAttribute('src'), au instanceof HTMLAudioElement,\n\
                  visualViewport instanceof EventTarget, visualViewport.width === innerWidth,\n\
                  visualViewport.height === innerHeight, visualViewport.scale,\n\
                  visualViewport.offsetLeft, visualViewport.pageTop, visualViewport.onresize,\n\
                  String(visualViewport)].join('|')"
            ),
            "x z|x z|L|b|0|1||t|v|true|0|false|false|true|true|3|4|0|auto|x.mp3|true|true|true|true|1|0|0||[object VisualViewport]"
        );
    }

    fn platform_engine() -> lumen::Engine {
        let clock = Rc::new(RealmClock::new());
        configured_engine(
            HostState::new(Rc::new(RefCell::new(Dom::new())), clock),
            DEFAULT_URL,
        )
    }

    /// A Window realm whose agent cluster is cross-origin isolated, so it
    /// keeps SharedArrayBuffer (HTML's realm creation steps).
    fn isolated_platform_engine() -> lumen::Engine {
        let clock = Rc::new(RealmClock::new());
        let mut engine = configured_engine_before_prelude(
            HostState::new(Rc::new(RefCell::new(Dom::new())), clock),
            DEFAULT_URL,
        );
        eval(
            &mut engine,
            "globalThis.__trust_cfg.crossOriginIsolated = true;",
            "isolation",
        )
        .unwrap();
        eval_platform_prelude(&mut engine).unwrap();
        engine
    }

    #[test]
    fn platform_objects_report_their_interface_class_strings() {
        // Web IDL #interface-prototype-object / #namespace-object: a
        // @@toStringTag data property names each interface prototype and
        // namespace; ECMAScript objects keep the engine's tags. Values match
        // Chromium's.
        let mut engine = platform_engine();
        assert_eq!(
            string_value(
                &mut engine,
                "const tag = o => Object.prototype.toString.call(o).slice(8, -1);\n\
                 const d = Object.getOwnPropertyDescriptor(HTMLDivElement.prototype, Symbol.toStringTag);\n\
                 [tag(HTMLDivElement.prototype), tag(document.createElement('div')),\n\
                  tag(document.createElementNS('http://www.w3.org/2000/svg', 'svg')),\n\
                  tag(document.createElementNS('urn:x', 'x')), tag(Element.prototype),\n\
                  tag(new Blob([])), tag(new Event('x')), tag(new AbortController().signal),\n\
                  tag(new URLSearchParams()), tag(new TextEncoder()), tag(console), tag(CSS),\n\
                  tag(Image.prototype), tag(Array.prototype), tag(Error.prototype), tag(Promise.prototype),\n\
                  d.writable, d.enumerable, d.configurable, typeof d.get].join()"
            ),
            "HTMLDivElement,HTMLDivElement,SVGSVGElement,Element,Element,Blob,Event,AbortSignal,\
             URLSearchParams,TextEncoder,console,CSS,HTMLImageElement,Array,Object,Promise,\
             false,false,true,undefined"
        );
        assert_eq!(
            string_value(&mut engine, "typeof __engine_global_names"),
            "undefined"
        );
        let mut worker = worker_platform_engine();
        assert_eq!(
            string_value(
                &mut worker,
                "const tag = o => Object.prototype.toString.call(o).slice(8, -1);\n\
                 [tag(new Blob([])), tag(new TextDecoder()), tag(navigator), tag(new Event('x')),\n\
                  typeof __engine_global_names].join()"
            ),
            "Blob,TextDecoder,WorkerNavigator,Event,undefined"
        );
    }

    #[test]
    fn geometry_points_quads_and_matrices_follow_their_idl() {
        // Geometry Interfaces 1 §2, §5, §6: internal-slot state, the 2D/3D
        // matrix model, the transform methods, CSS transform-list parsing in
        // a Window only, the stringifier and structured serialization.
        // Values match Chromium's, except that the spec (unlike Chromium)
        // makes rotateZ() three-dimensional and treats an undefined scaleY
        // as missing.
        let mut engine = platform_engine();
        assert_eq!(
            string_value(
                &mut engine,
                "const tag = o => Object.prototype.toString.call(o).slice(8, -1);\n\
                 const m = new DOMMatrix('scale(2) translateX(5px) translateY(calc(2 * 2.5px))');\n\
                 const q = new DOMQuad({x: 40, y: 25}, {x: 180, y: 8}, {x: 210, y: 150}, {x: 10, y: 180});\n\
                 const b = q.getBounds();\n\
                 const errors = [() => new DOMMatrix('translateX(5em)'), () => new DOMMatrix([1, 2, 3]),\n\
                   () => String(new DOMMatrix([NaN, 0, 0, 1, 0, 0])), () => new DOMMatrix().multiply({a: 1, m11: 2}),\n\
                   () => DOMMatrix.prototype.translateSelf.call(new DOMMatrixReadOnly())]\n\
                   .map(f => { try { f(); return 'none'; } catch (e) { return e.name; } });\n\
                 const c = structuredClone([new DOMMatrixReadOnly([1, 2, 3, 4, 5, 6]), q, new DOMPoint(1, 2, 3, 4)]);\n\
                 [String(m), m.is2D, m.isIdentity, new DOMMatrix('rotateZ(90deg)').is2D,\n\
                  String(new DOMMatrix().rotate(90)), String(new DOMMatrix([1, 2, 3, 4, 5, 6]).inverse()),\n\
                  String(new DOMMatrix().scale(2, undefined, 3, 1, 2, 3)),\n\
                  new DOMMatrix().translate(1, 2, 3).is2D, String(new DOMMatrix().scale3d(2)),\n\
                  String(DOMMatrix.fromFloat32Array(new Float32Array([1, 0, 0, 1, 7, 8]))),\n\
                  new DOMMatrix().invertSelf().isIdentity, new DOMMatrix([0, 0, 0, 0, 0, 0]).inverse().is2D,\n\
                  new DOMPoint(1, 2).matrixTransform({e: 3, f: 4}).x, m.transformPoint({x: 1, y: 1}).y,\n\
                  b.x, b.y, b.width, b.height, tag(b), q.p1 === q.p1, JSON.stringify(DOMQuad.fromRect({width: 2}).p2),\n\
                  Object.keys(new DOMMatrix().toJSON()).length, errors.join(' '),\n\
                  tag(new DOMPointReadOnly()), tag(new DOMMatrix()), WebKitCSSMatrix === DOMMatrix,\n\
                  SVGMatrix === DOMMatrix, SVGPoint === DOMPoint, tag(DOMMatrixReadOnly.fromMatrix()),\n\
                  c.map(tag).join(' '), c[0].f, c[1].p3.x, c[2].w,\n\
                  new DOMMatrix().setMatrixValue('perspective(none)').is2D, DOMMatrix.length,\n\
                  Object.getOwnPropertyDescriptor(DOMMatrix.prototype, 'a').enumerable].join('|')"
            ),
            "matrix(2, 0, 0, 2, 10, 10)|true|false|false|matrix(0, 1, -1, 0, 0, 0)|\
             matrix(-2, 1, 1.5, -0.5, 1, -2)|\
             matrix3d(2, 0, 0, 0, 0, 2, 0, 0, 0, 0, 3, 0, -1, -2, -6, 1)|false|\
             matrix3d(2, 0, 0, 0, 0, 2, 0, 0, 0, 0, 2, 0, 0, 0, 0, 1)|matrix(1, 0, 0, 1, 7, 8)|true|false|\
             4|12|10|8|200|172|DOMRect|true|{\"x\":2,\"y\":0,\"z\":0,\"w\":1}|24|\
             SyntaxError TypeError InvalidStateError TypeError TypeError|\
             DOMPointReadOnly|DOMMatrix|true|true|true|DOMMatrixReadOnly|\
             DOMMatrixReadOnly DOMQuad DOMPoint|6|210|4|false|0|true"
        );
        // [Exposed=Window] stringifier and setMatrixValue(); only a Window
        // parses CSS transform lists.
        let mut worker = worker_platform_engine();
        assert_eq!(
            string_value(
                &mut worker,
                "const tag = o => Object.prototype.toString.call(o).slice(8, -1);\n\
                 let thrown; try { new DOMMatrix('matrix(1, 0, 0, 1, 0, 0)'); } catch (e) { thrown = e.name; }\n\
                 [thrown, String(new DOMMatrix()), 'setMatrixValue' in DOMMatrix.prototype,\n\
                  typeof WebKitCSSMatrix, typeof SVGPoint, tag(new DOMQuad()),\n\
                  new DOMMatrix([1, 2, 3, 4, 5, 6]).translate(1, 2).e].join('|')"
            ),
            "TypeError|[object DOMMatrix]|false|undefined|undefined|DOMQuad|12"
        );
    }

    #[test]
    fn dom_rect_lists_are_static_indexed_lists_of_rects() {
        // Geometry 1 #DOMRectList and CSSOM View #dom-element-getclientrects:
        // not an Array, with item(), length, a readonly indexed getter and
        // %Array.prototype.values% as @@iterator; not serializable. Values
        // match Chromium's.
        let mut engine = platform_engine();
        assert_eq!(
            string_value(
                &mut engine,
                "const tag = o => Object.prototype.toString.call(o).slice(8, -1);\n\
                 const list = document.createElement('div').getClientRects();\n\
                 const shown = document.createElement('div'); shown.style.height = '10px';\n\
                 (document.documentElement || document.appendChild(document.createElement('html'))).append(shown);\n\
                 const selected = document.createRange(); selected.selectNode(shown);\n\
                 const range = selected.getClientRects();\n\
                 let cloned; try { structuredClone(list); cloned = 'cloned'; } catch (e) { cloned = e.name; }\n\
                 let constructed; try { new DOMRectList(); } catch (e) { constructed = e.name; }\n\
                 [tag(list), Array.isArray(list), list.length, list.item(0), tag(range), range.length,\n\
                  tag(range[0]), range.item(0) === range[0], range[1], Object.keys(range).join(),\n\
                  DOMRectList.prototype[Symbol.iterator] === Array.prototype.values, [...range].length,\n\
                  cloned, constructed].join('|')"
            ),
            "DOMRectList|false|0||DOMRectList|1|DOMRect|true||0|true|1|DataCloneError|TypeError"
        );
    }

    /// A Window realm whose Document has `<html><head></head><body></body>`,
    /// for tests that need connected elements.
    fn platform_engine_with_body() -> lumen::Engine {
        let mut engine = platform_engine();
        eval(
            &mut engine,
            "const html = document.createElement('html'); document.append(html);\n\
             html.append(document.createElement('head'), document.createElement('body'));",
            "test body",
        )
        .unwrap();
        engine
    }

    #[test]
    fn dom_collections_iterate_with_array_intrinsics() {
        // Web IDL #define-the-iteration-methods: an indexed getter with an
        // integer length gives %Array.prototype.values% as @@iterator; value
        // iterables (NodeList, DOMTokenList) also take entries, keys and
        // forEach from %Array.prototype%. DOM #interface-domtokenlist has an
        // indexed getter.
        let mut engine = platform_engine_with_body();
        assert_eq!(
            string_value(
                &mut engine,
                r#"(() => {
                    const values = Array.prototype.values;
                    const d = document.createElement('div'); d.className = 'a b a';
                    const sheet = new CSSStyleSheet();
                    sheet.replaceSync('@keyframes k { from { color: red } to { color: blue } } p { color: red }');
                    return [
                        NodeList.prototype[Symbol.iterator] === values,
                        NodeList.prototype.entries === Array.prototype.entries,
                        NodeList.prototype.keys === Array.prototype.keys,
                        NodeList.prototype.forEach === Array.prototype.forEach,
                        HTMLCollection.prototype[Symbol.iterator] === values,
                        'entries' in HTMLCollection.prototype,
                        DOMTokenList.prototype[Symbol.iterator] === values,
                        DOMTokenList.prototype.forEach === Array.prototype.forEach,
                        d.classList.length, d.classList[1], Object.keys(d.classList).join(), [...d.classList].join(),
                        CSSRuleList.prototype[Symbol.iterator] === values,
                        StyleSheetList.prototype[Symbol.iterator] === values,
                        CSSKeyframesRule.prototype[Symbol.iterator] === values,
                        sheet.cssRules[0].length, sheet.cssRules[0][1].keyText, [...sheet.cssRules[0]].length,
                        SVGTransformList.prototype[Symbol.iterator] === values,
                    ].join('|');
                })()"#
            ),
            "true|true|true|true|true|false|true|true|2|b|0,1|a,b|true|true|true|2|100%|2|true"
        );
    }

    #[test]
    fn live_ranges_follow_dom_boundary_point_algorithms() {
        // DOM #interface-range: boundary comparison, cloning, extraction and
        // insertion, the removing steps' live updates, surroundContents()'s
        // partially-contained check, and StaticRange's validation.
        let mut engine = platform_engine_with_body();
        assert_eq!(
            string_value(
                &mut engine,
                r#"(() => {
                    const p = document.createElement('p'); p.innerHTML = 'one<b>two</b>three'; document.body.append(p);
                    const r = document.createRange(); r.setStart(p.firstChild, 1); r.setEnd(p.lastChild, 2);
                    const out = [r.toString(), r.commonAncestorContainer === p, r.collapsed];
                    const clone = r.cloneContents(); out.push(clone.childNodes.length, clone.textContent);
                    const r2 = document.createRange(); r2.selectNodeContents(p);
                    out.push(r.compareBoundaryPoints(Range.START_TO_START, r2), r.compareBoundaryPoints(Range.END_TO_END, r2));
                    out.push(r.comparePoint(p, 0), r.isPointInRange(p.childNodes[1], 0), r.intersectsNode(p.childNodes[1]));
                    const extracted = r.extractContents();
                    out.push(extracted.textContent, p.innerHTML, r.collapsed, r.startContainer === p, r.startOffset);
                    r.insertNode(document.createTextNode('X')); out.push(p.innerHTML, r.toString());
                    try { r.setStart(document.implementation.createDocumentType('html', '', ''), 0); } catch (e) { out.push(e.name); }
                    const r3 = document.createRange(); r3.selectNodeContents(p.firstChild); p.firstChild.remove();
                    out.push(r3.startContainer === p, r3.startOffset, r3.collapsed);
                    const d = document.createElement('div'); d.innerHTML = 'ab<i>cd</i>ef'; document.body.append(d);
                    const r4 = document.createRange(); r4.setStart(d.childNodes[1].firstChild, 1); r4.setEnd(d.lastChild, 1);
                    try { r4.surroundContents(document.createElement('span')); } catch (e) { out.push(e.name); }
                    const r5 = document.createRange(); r5.setStart(d.firstChild, 1); r5.setEnd(d.lastChild, 1);
                    r5.surroundContents(document.createElement('span')); out.push(d.innerHTML);
                    const s = new StaticRange({startContainer: d, startOffset: 0, endContainer: d, endOffset: 1});
                    out.push(s.collapsed, s.endOffset, s instanceof AbstractRange, Object.prototype.toString.call(s));
                    try { new StaticRange({startContainer: document.implementation.createDocumentType('x', '', ''), startOffset: 0, endContainer: d, endOffset: 0}); }
                    catch (e) { out.push(e.name); }
                    return out.join('|');
                })()"#
            ),
            "netwoth|true|false|3|netwoth|1|-1|-1|true|true|netwoth|oree|true|true|1|oXree|X|\
             InvalidNodeTypeError|true|0|true|InvalidStateError|a<span>b<i>cd</i>e</span>f|false|1|true|\
             [object StaticRange]|InvalidNodeTypeError"
        );
    }

    #[test]
    fn selection_api_tracks_its_range_and_direction() {
        // Selection API #selection-interface: collapse/extend/setBaseAndExtent
        // set the direction, toString() is the range's text, and
        // getComposedRanges() returns StaticRanges.
        let mut engine = platform_engine_with_body();
        assert_eq!(
            string_value(
                &mut engine,
                r#"(() => {
                    const d = document.createElement('div'); d.innerHTML = '<span>hello</span> <em>world</em>'; document.body.append(d);
                    const sel = getSelection(); sel.removeAllRanges();
                    const out = [sel.rangeCount, sel.type, sel.anchorNode];
                    sel.collapse(d.firstChild.firstChild, 1); out.push(sel.type, sel.anchorOffset, sel.isCollapsed, sel.direction);
                    sel.extend(d.lastChild.firstChild, 3); out.push(sel.type, sel.toString(), sel.direction, sel.focusOffset);
                    sel.extend(d.firstChild.firstChild, 0); out.push(sel.direction, sel.toString());
                    sel.setBaseAndExtent(d.lastChild.firstChild, 2, d.firstChild.firstChild, 2);
                    out.push(sel.direction, sel.toString(), sel.containsNode(d.childNodes[1]), sel.containsNode(d.firstChild, true));
                    const composed = sel.getComposedRanges();
                    out.push(composed.length, composed[0] instanceof StaticRange, composed[0].startOffset);
                    sel.selectAllChildren(d); out.push(sel.toString(), sel.anchorNode === d, sel.focusOffset);
                    sel.deleteFromDocument(); out.push(d.childNodes.length, document.getSelection() === sel);
                    return out.join('|');
                })()"#
            ),
            "0|None||Caret|1|true|none|Range|ello wor|forward|3|backward|h|backward|llo wo|true|true|1|true|2|hello world|true|3|0|true"
        );
    }

    #[test]
    fn user_selection_gestures_follow_the_selection_api_and_css_ui() {
        // Selection API §2 "User Interactions" (local w3c/selection-api
        // b475d4b) and CSS UI 4 #content-selection: a primary press starts a
        // gesture that drags, doubles to a word, triples to a paragraph,
        // extends with Shift, fires selectstart once from a collapsed
        // selection, keeps links to activation, and honors user-select.
        let mut engine = platform_engine_with_body();
        assert_eq!(
            string_value(
                &mut engine,
                r#"(() => {
                    document.body.innerHTML = '<p id=p>Hello brave world</p><p id=q>Second line</p>' +
                        '<p id=n style="user-select:none">no select</p><p><a id=l href="/x">link text</a></p>' +
                        '<p id=all style="user-select:all">all <b id=b>of it</b></p>';
                    const el = (id) => document.getElementById(id);
                    const t = el('p').firstChild, q = el('q').firstChild;
                    const sel = getSelection(), out = [];
                    let starts = 0;
                    document.addEventListener('selectstart', () => starts++);
                    const press = (target, node, offset, x, mods = 0) => __trust.pointerButton(
                        target.__id, true, x, 5, x, 5, 0, mods, false, node.__id, offset, true, false);
                    const release = (target, node, offset, x) => __trust.pointerButton(
                        target.__id, false, x, 5, x, 5, 0, 0, false, node.__id, offset, true, false);
                    const move = (node, offset) => __trust.hover(el('p').__id, 9, 9, 9, 9, 0, false, true, node.__id, offset);
                    press(el('p'), t, 2, 10); out.push(sel.type, sel.anchorOffset, starts);
                    move(t, 11); out.push(sel.toString(), sel.direction);
                    move(t, 0); out.push(sel.toString(), sel.direction);
                    release(el('p'), t, 0, 10); out.push(starts);
                    // A click on other text only collapses: no selectstart from
                    // a non-collapsed selection.
                    press(el('q'), q, 3, 40); release(el('q'), q, 3, 40); out.push(sel.type, starts);
                    press(el('q'), q, 1, 40); out.push(sel.toString(), starts); release(el('q'), q, 1, 40);
                    press(el('q'), q, 1, 40); out.push(sel.toString()); release(el('q'), q, 1, 40);
                    press(el('p'), t, 5, 80, 1); out.push(JSON.stringify(sel.toString()), sel.direction);
                    release(el('p'), t, 5, 80);
                    press(el('n'), el('n').firstChild, 2, 120); out.push(JSON.stringify(sel.toString()));
                    release(el('n'), el('n').firstChild, 2, 120);
                    const link = el('l').firstChild;
                    press(el('l'), link, 2, 160); move(link, 6); out.push(sel.type);
                    release(el('l'), link, 6, 160);
                    press(el('l'), link, 0, 200, 4); move(link, 4); out.push(sel.toString());
                    release(el('l'), link, 4, 200);
                    press(el('b'), el('b').firstChild, 1, 240); out.push(sel.toString());
                    release(el('b'), el('b').firstChild, 1, 240);
                    __trust.key(null, 'a', 'KeyA', false, false, false, true, false, false);
                    out.push(sel.anchorNode === document.body, sel.focusOffset === document.body.childNodes.length);
                    sel.removeAllRanges();
                    document.addEventListener('selectstart', (e) => e.preventDefault());
                    press(el('p'), t, 2, 280); move(t, 8); out.push(sel.type);
                    return out.join('|');
                })()"#
            ),
            "Caret|2|1|llo brave|forward|He|backward|1|Caret|1|Second|2|Second line|\" brave world\"|backward|\" brave world\"|Caret|link|all of it|true|true|None"
        );
    }

    #[test]
    fn triple_click_selects_the_rendered_paragraph() {
        // A triple click's granule is the paragraph (Selection API
        // #dom-selection-modify boundaries): a segment break that the text's
        // white-space collapses is a space, not a break, while a <br> and a
        // preserved newline (CSS Text 3 #white-space-processing) are.
        let mut engine = platform_engine_with_body();
        assert_eq!(
            string_value(
                &mut engine,
                r#"(() => {
                    document.body.innerHTML = '<p id=p>First line of\n  the paragraph<br>after break</p>' +
                        '<pre id=pre>one\ntwo</pre>';
                    const el = (id) => document.getElementById(id);
                    const text = el('p').firstChild, after = el('p').lastChild, pre = el('pre').firstChild;
                    const sel = getSelection(), out = [];
                    const triple = (target, node, offset, x) => {
                        for (let i = 0; i < 3; i++) {
                            __trust.pointerButton(target.__id, true, x, 5, x, 5, 0, 0, false, node.__id, offset, true, false);
                            __trust.pointerButton(target.__id, false, x, 5, x, 5, 0, 0, false, node.__id, offset, true, false);
                        }
                        out.push(JSON.stringify(sel.toString()));
                    };
                    triple(el('p'), text, 18, 10);
                    triple(el('p'), after, 2, 60);
                    triple(el('pre'), pre, 5, 110);
                    sel.collapse(text, 18);
                    sel.modify('extend', 'forward', 'paragraphboundary');
                    out.push(JSON.stringify(sel.toString()));
                    return out.join('|');
                })()"#
            ),
            "\"First line of\\n  the paragraph\"|\"after break\"|\"two\"|\"e paragraph\""
        );
    }

    #[test]
    fn the_users_copy_action_fires_copy_and_writes_rendered_text() {
        // Clipboard API #copy-action and #fire-a-clipboard-event: an
        // uncanceled copy writes the selection as HTML's rendered text
        // collection steps produce it (CSS UI 4: user-select:none content
        // left out); a canceled one writes the data its listener set.
        let mut engine = platform_engine_with_body();
        let written = |engine: &mut lumen::Engine| {
            engine
                .ctx()
                .host_mut::<HostState>()
                .map(|state| std::mem::take(&mut state.clipboard_requests))
                .unwrap()
                .into_iter()
                .map(|(_, text)| text)
                .collect::<Vec<_>>()
        };
        assert_eq!(
            string_value(
                &mut engine,
                r#"(() => {
                    document.body.innerHTML = '<p id=a>One <b>two</b>  words</p>' +
                        '<p>Three<span style="user-select:none"> hidden</span><br>four</p>';
                    const sel = getSelection();
                    sel.setBaseAndExtent(document.getElementById('a').firstChild, 1, document.body.lastChild.lastChild, 2);
                    window.copies = 0;
                    document.addEventListener('copy', (e) => { copies++; });
                    __trust.userCopy();
                    return String(copies);
                })()"#
            ),
            "1"
        );
        assert_eq!(
            written(&mut engine),
            vec!["ne two words\n\nThree\nfo".to_string()]
        );
        string_value(
            &mut engine,
            r#"(() => {
                document.addEventListener('copy', (e) => { e.clipboardData.setData('text/plain', 'mine'); e.preventDefault(); });
                __trust.userCopy();
                return '';
            })()"#,
        );
        assert_eq!(written(&mut engine), vec!["mine".to_string()]);
    }

    #[test]
    fn context_menus_follow_maybe_show_context_menu() {
        // Pointer Events #maybe-show-context-menu: the UA menu shows when
        // contextmenu is not canceled; the user's bypass fires none; the menu
        // key fires it at the focused element from no pointing device.
        let mut engine = platform_engine_with_body();
        let results = |engine: &mut lumen::Engine| {
            engine
                .ctx()
                .host_mut::<HostState>()
                .map(|state| std::mem::take(&mut state.context_menus))
                .unwrap()
        };
        let seen = string_value(
            &mut engine,
            r#"(() => {
                document.body.innerHTML = '<p id=a>plain</p><p id=b>own menu</p>';
                const a = document.getElementById('a'), b = document.getElementById('b'), out = [];
                document.addEventListener('contextmenu', (e) => out.push(e.target.id || e.target.localName,
                    e.pointerId, JSON.stringify(e.pointerType)));
                b.addEventListener('contextmenu', (e) => e.preventDefault());
                const click = (el, bypass) => {
                    __trust.pointerButton(el.__id, true, 5, 5, 5, 5, 2, 0, false, null, 0, true, bypass);
                    __trust.pointerButton(el.__id, false, 5, 5, 5, 5, 2, 0, false, null, 0, true, bypass);
                };
                click(a, false); click(b, false); click(a, true);
                __trust.key(null, 'ContextMenu', 'ContextMenu', false, false, false, false, false, false);
                return out.join('|');
            })()"#,
        );
        assert_eq!(seen, "a|1|\"mouse\"|b|1|\"mouse\"|body|-1|\"\"");
        assert_eq!(results(&mut engine), vec![true, false, true]);
    }

    #[test]
    fn event_listeners_honor_options_and_dispatch_flags() {
        // DOM #dom-eventtarget-addeventlistener options (passive, signal,
        // once), #concept-event-dispatch's phases and dispatch flag, and Web
        // IDL dictionary conversion order (inherited members first).
        let mut engine = platform_engine_with_body();
        assert_eq!(
            string_value(
                &mut engine,
                r#"(() => {
                    const out = [];
                    const d = document.createElement('div'); document.body.append(d);
                    d.addEventListener('x', (e) => { e.preventDefault(); out.push('passive:' + e.defaultPrevented); }, {passive: true});
                    const ev = new Event('x', {cancelable: true}); d.dispatchEvent(ev); out.push(ev.defaultPrevented);
                    const ac = new AbortController(); let count = 0;
                    d.addEventListener('y', () => count++, {signal: ac.signal});
                    d.dispatchEvent(new Event('y')); ac.abort(); d.dispatchEvent(new Event('y')); out.push(count);
                    let once = 0; d.addEventListener('z', () => once++, {once: true});
                    d.dispatchEvent(new Event('z')); d.dispatchEvent(new Event('z')); out.push(once);
                    const order = [];
                    document.body.addEventListener('w', () => order.push('bubble'));
                    document.body.addEventListener('w', () => order.push('capture'), true);
                    d.addEventListener('w', (e) => { order.push('target'); e.stopImmediatePropagation(); });
                    d.addEventListener('w', () => order.push('never'));
                    d.dispatchEvent(new Event('w', {bubbles: true})); out.push(order.join('>'));
                    const inner = new Event('q'); let err;
                    d.addEventListener('q', () => { try { d.dispatchEvent(inner); } catch (e) { err = e.name; } });
                    d.dispatchEvent(inner); out.push(err);
                    const reads = [];
                    new MouseEvent('m', {get bubbles() { reads.push('bubbles'); return true; },
                        get button() { reads.push('button'); return 1; }, get altKey() { reads.push('altKey'); return false; }});
                    out.push(reads.join());
                    const e2 = new Event('r', {cancelable: true}); e2.returnValue = false; out.push(e2.defaultPrevented, e2.returnValue);
                    out.push([CommandEvent, FormDataEvent, TextEvent, TouchList, BeforeUnloadEvent].every((C) => typeof C === 'function'));
                    return out.join('|');
                })()"#
            ),
            "passive:false|false|1|1|capture>target|InvalidStateError|bubbles,altKey,button|true|false|true"
        );
    }

    #[test]
    fn event_handler_attributes_compile_with_html_scopes() {
        // HTML #getting-the-current-value-of-the-event-handler: content
        // attributes compile with the element, form and document scopes,
        // `return false` cancels, window.event is the current event, and
        // reportError() runs the error event handler with five arguments.
        let mut engine = platform_engine_with_body();
        assert_eq!(
            string_value(
                &mut engine,
                r#"(() => {
                    const out = [];
                    const d = document.createElement('div'); document.body.append(d); globalThis.target = d;
                    d.setAttribute('onclick', 'globalThis.probe = [this === target, typeof event, event.type, window.event === event]; return false;');
                    const ev = new MouseEvent('click', {cancelable: true}); d.dispatchEvent(ev);
                    out.push(globalThis.probe.join(','), ev.defaultPrevented, typeof d.onclick, d.onclick.length);
                    d.onclick = null; out.push(d.getAttribute('onclick') !== null, d.onclick);
                    const f = document.createElement('form');
                    f.innerHTML = '<input name=q value=v><button onclick="globalThis.scope = typeof q + \':\' + typeof elements">b</button>';
                    document.body.append(f);
                    f.querySelector('button').dispatchEvent(new MouseEvent('click')); out.push(globalThis.scope);
                    let args; window.onerror = function (...a) { args = a.length + ':' + a[0]; return true; };
                    reportError(new Error('boom')); out.push(args); window.onerror = null;
                    let seen; window.addEventListener('error', (e) => { seen = e.constructor.name + ':' + e.error.message; }, {once: true});
                    reportError(new TypeError('t1')); out.push(seen, window.event === undefined);
                    return out.join('|');
                })()"#
            ),
            "true,object,click,true|true|function|1|true||object:object|5:Uncaught Error: boom|ErrorEvent:t1|true"
        );
    }

    #[test]
    fn abort_signals_follow_dependent_signal_rules() {
        // DOM #interface-AbortSignal: any() links dependents to the source
        // signals, abort reasons propagate, and AbortSignal is not
        // constructible.
        let mut engine = platform_engine();
        assert_eq!(
            string_value(
                &mut engine,
                r#"(() => {
                    const out = [];
                    const a = new AbortController(), b = new AbortController();
                    const any = AbortSignal.any([a.signal, b.signal]), nested = AbortSignal.any([any]);
                    const fired = [];
                    any.onabort = () => fired.push('any'); nested.addEventListener('abort', () => fired.push('nested'));
                    b.abort('why'); out.push(any.aborted, any.reason, nested.reason, fired.join());
                    out.push(AbortSignal.abort().reason.name, AbortSignal.abort(5).reason);
                    try { AbortSignal.abort('r').throwIfAborted(); } catch (e) { out.push(e); }
                    out.push(AbortSignal.timeout(10) instanceof AbortSignal);
                    try { new AbortSignal(); } catch (e) { out.push(e.name); }
                    out.push(Object.prototype.toString.call(any));
                    return out.join('|');
                })()"#
            ),
            "true|why|why|any,nested|AbortError|5|r|true|TypeError|[object AbortSignal]"
        );
    }

