    #[test]
    fn indexed_getter_interfaces_iterate_like_arrays() {
        // Web IDL #js-iterable: an interface with an indexed property getter
        // gets %Array.prototype.values% as a writable, configurable,
        // non-enumerable @@iterator. CSSOM's CSSStyleDeclaration (`getter
        // item`), MediaList (`getter item`) and HTML's HTMLFormElement
        // (`getter Element`) all have one. Spreading a detached element's
        // style to subtract one declaration block from another is how
        // atomic-CSS runtimes (ChatGPT's composer) manage inline styles.
        let mut engine = platform_engine();
        assert_eq!(
            string_value(
                &mut engine,
                "const html = document.createElement('html'); document.append(html);\n\
                 html.append(document.createElement('head'), document.createElement('body'));\n\
                 const d = Object.getOwnPropertyDescriptor(CSSStyleDeclaration.prototype, Symbol.iterator);\n\
                 const el = document.createElement('div');\n\
                 el.style.cssText = 'color: red; margin: 1px 2px';\n\
                 const subtract = (base, managed) => { const s = document.createElement('div').style;\n\
                   s.cssText = managed; const names = [...s]; s.cssText = base;\n\
                   for (const n of names) s.removeProperty(n); return s.cssText; };\n\
                 const sheet = document.head.appendChild(document.createElement('style'));\n\
                 sheet.textContent = '@media screen, print { p { color: red; padding: 1px } }';\n\
                 const rule = sheet.sheet.cssRules[0];\n\
                 const ruleNames = []; for (const name of rule.cssRules[0].style) ruleNames.push(name);\n\
                 const form = document.body.appendChild(document.createElement('form'));\n\
                 form.append(document.createElement('input'), document.createElement('button'));\n\
                 const iterates = (i) => i.prototype[Symbol.iterator] === Array.prototype.values;\n\
                 [d.value === Array.prototype.values, d.writable, d.enumerable, d.configurable,\n\
                  [...el.style].join(), subtract('color: red; display: block', 'color: blue'),\n\
                  ruleNames.join(), iterates(MediaList), [...rule.media].join(),\n\
                  iterates(HTMLFormElement), [...form].map((e) => e.localName).join()].join('|')"
            ),
            "true|true|false|true|color,margin-top,margin-right,margin-bottom,margin-left|display: block;|color,padding-top,padding-right,padding-bottom,padding-left|true|screen,print|true|input,button"
        );
    }

    #[test]
    fn body_form_data_round_trips_and_constructors_extract_content_types() {
        // Fetch #concept-bodyinit-extract: constructing a Request or Response
        // extracts the body and appends the Content-Type it implies (a
        // FormData's carries the boundary of its multipart encoding) unless
        // the headers name one. #dom-body-formdata then decodes the read bytes
        // by that MIME type: RFC 7578 multipart parts become strings or Files
        // (text/plain by default), urlencoded bodies are parsed as by URL's
        // urlencoded parser, and anything else rejects with a TypeError.
        // Login forms in React Router apps read `request.formData()`.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r#"
            globalThis.result = undefined;
            (async () => {
                const out = [];
                const form = new FormData();
                form.append('email', 'user@example.com');
                form.append('note', 'line 1\nline 2 ✓');
                form.append('upload', new Blob(['%PDF\r\n--x'], {type: 'application/pdf'}), 'a "b".pdf');
                form.append('email', 'second');
                const request = new Request('https://example.com/login', {method: 'POST', body: form});
                const type = request.headers.get('content-type');
                out.push(/^multipart\/form-data; boundary=\S+$/.test(type));
                const parsed = await request.clone().formData();
                const file = parsed.get('upload');
                out.push(JSON.stringify(parsed.getAll('email')), parsed.get('note') === 'line 1\r\nline 2 ✓',
                    file instanceof File, file.name, file.type, await file.text());
                out.push(request.bodyUsed, (await request.text()).includes(type.slice(type.indexOf('=') + 1)), request.bodyUsed);

                const response = new Response('a=1&b=%20x+y&a=3&%3Fq=%E2%9C%93', {headers: {'Content-Type': 'application/x-www-form-urlencoded'}});
                const urlencoded = await response.formData();
                out.push(JSON.stringify([...urlencoded]));

                const boundary = 'XyZ';
                const raw = 'preamble\r\n--XyZ \r\nContent-Disposition: form-data; name="f"; filename="n.txt"\r\n\r\nfile body\r\n' +
                    '--XyZ\r\ncontent-disposition: FORM-DATA; name=plain\r\nContent-Type: text/plain; charset=latin1\r\n\r\né\r\n--XyZ--\r\nepilogue';
                const handmade = await new Response(raw, {headers: {'content-type': 'multipart/form-data; boundary="XyZ"'}}).formData();
                const named = handmade.get('f');
                out.push(named.name, named.type, await named.text(), handmade.get('plain'));

                const rejects = async (body, contentType) => {
                    try { await new Response(body, {headers: {'content-type': contentType}}).formData(); return 'resolved'; }
                    catch (e) { return e.name; }
                };
                out.push(await rejects('a=1', 'text/plain'),
                    await rejects('--b\r\nContent-Disposition: form-data; name="x"\r\n\r\nv', 'multipart/form-data; boundary=b'),
                    await rejects('--b--', 'multipart/form-data'),
                    await rejects('--b\r\nContent-Type: text/plain\r\n\r\nv\r\n--b--', 'multipart/form-data; boundary=b'));

                out.push(new Response('text').headers.get('content-type'),
                    new Response(new URLSearchParams('a=1')).headers.get('content-type'),
                    new Response(new Blob(['x'], {type: 'image/png'})).headers.get('content-type'),
                    new Response(new Uint8Array([1])).headers.get('content-type'),
                    new Response('x', {headers: {'content-type': 'text/html'}}).headers.get('content-type'),
                    Response.json({a: 1}).headers.get('content-type'),
                    new Response('x').clone().headers.get('content-type'),
                    new Request('https://example.com/', {method: 'POST', body: 'x', headers: {'Content-Type': 'text/csv'}}).headers.get('content-type'));
                globalThis.result = out.join('|');
            })().catch((e) => { globalThis.result = 'threw ' + e; });
            "#,
            "Body formData and extraction",
        )
        .unwrap();
        // File API #blob-get-stream reads a Blob's bytes from file reading tasks.
        settle_fixture(&mut engine, false);
        assert_eq!(
            string_value(&mut engine, "String(globalThis.result)"),
            "true|[\"user@example.com\",\"second\"]|true|true|a %22b%22.pdf|application/pdf|%PDF\r\n--x|false|true|true|\
             [[\"a\",\"1\"],[\"b\",\" x y\"],[\"a\",\"3\"],[\"?q\",\"✓\"]]|n.txt|text/plain|file body|é|\
             TypeError|TypeError|TypeError|TypeError|\
             text/plain;charset=UTF-8|application/x-www-form-urlencoded;charset=UTF-8|image/png||text/html|application/json|text/plain;charset=UTF-8|text/csv"
        );
    }

    #[test]
    fn location_is_a_location_with_unforgeable_members() {
        // HTML #the-location-interface: every member is [LegacyUnforgeable]
        // (own, non-configurable properties), creation adds own valueOf and
        // @@toPrimitive, Location.prototype has no members, and a top-level
        // document's ancestorOrigins is an empty DOMStringList. Values match
        // Chromium's.
        let mut engine = platform_engine();
        assert_eq!(
            string_value(
                &mut engine,
                "const tag = o => Object.prototype.toString.call(o).slice(8, -1);\n\
                 const href = Object.getOwnPropertyDescriptor(location, 'href');\n\
                 const assign = Object.getOwnPropertyDescriptor(location, 'assign');\n\
                 const primitive = Object.getOwnPropertyDescriptor(location, Symbol.toPrimitive);\n\
                 let illegal; try { href.get.call({}); } catch (e) { illegal = e.name; }\n\
                 let constructed; try { new Location(); } catch (e) { constructed = e.name; }\n\
                 const origins = location.ancestorOrigins;\n\
                 [tag(location), Object.getPrototypeOf(location) === Location.prototype,\n\
                  Object.getOwnPropertyNames(Location.prototype).join(), href.configurable, href.enumerable,\n\
                  href.get.name, assign.writable, assign.configurable, assign.value.length,\n\
                  location.valueOf === Object.prototype.valueOf, primitive.value, primitive.configurable,\n\
                  String(location) === location.href, illegal, constructed, tag(origins), origins.length,\n\
                  origins === location.ancestorOrigins, origins.item(0), origins.contains(''),\n\
                  Object.getOwnPropertyNames(DOMStringList.prototype).join()].join('|')"
            ),
            "Location|true|constructor|false|true|get href|false|false|1|true||false|true|\
             TypeError|TypeError|DOMStringList|0|true||false|constructor,length,item,contains"
        );
        // DOMStringList is [Exposed=(Window,Worker)].
        let mut worker = worker_platform_engine();
        assert_eq!(
            string_value(&mut worker, "typeof DOMStringList"),
            "function"
        );
    }

    #[test]
    fn crypto_objects_are_crypto_and_subtle_crypto_instances() {
        // WebCrypto #crypto-interface / #subtlecrypto-interface: the global's
        // [SameObject] crypto accessor returns a Crypto, whose subtle is a
        // SubtleCrypto; both interfaces are illegal constructors and brand
        // their receivers (a SubtleCrypto operation rejects). [SecureContext]
        // members and SubtleCrypto are absent outside secure contexts.
        let mut engine = platform_engine();
        assert_eq!(
            string_value(
                &mut engine,
                "const tag = o => Object.prototype.toString.call(o).slice(8, -1);\n\
                 let constructed; try { new Crypto(); } catch (e) { constructed = e.name; }\n\
                 let branded; try { Crypto.prototype.getRandomValues.call({}, new Uint8Array(1)); }\n\
                 catch (e) { branded = e.name; }\n\
                 [tag(crypto), tag(crypto.subtle), crypto === crypto, crypto.subtle === crypto.subtle,\n\
                  typeof Object.getOwnPropertyDescriptor(globalThis, 'crypto').get,\n\
                  Object.keys(Crypto.prototype).join(), Object.keys(SubtleCrypto.prototype).length,\n\
                  SubtleCrypto.prototype.verify.length, constructed, branded,\n\
                  tag(SubtleCrypto.prototype.digest.call({}, 'SHA-256', new Uint8Array(1))),\n\
                  crypto.getRandomValues(new Uint8Array(4)).length, crypto.randomUUID()[14]].join('|')"
            ),
            "Crypto|SubtleCrypto|true|true|function|subtle,getRandomValues,randomUUID|12|4|\
             TypeError|TypeError|Promise|4|4"
        );
        // The test worker's configuration is not a secure context.
        let mut worker = worker_platform_engine();
        assert_eq!(
            string_value(
                &mut worker,
                "const tag = o => Object.prototype.toString.call(o).slice(8, -1);\n\
                 [isSecureContext, tag(crypto), 'subtle' in crypto, 'randomUUID' in crypto,\n\
                  typeof SubtleCrypto, crypto.getRandomValues(new Uint8Array(2)).length,\n\
                  URL.createObjectURL(new Blob([])).length > 40].join('|')"
            ),
            "false|Crypto|false|false|undefined|2|true"
        );
    }

    #[test]
    fn match_media_lists_are_event_targets_reporting_changes() {
        // CSSOM View #the-mediaquerylist-interface: matchMedia() returns a
        // MediaQueryList (an EventTarget) whose addListener/removeListener
        // alias change listeners, with an onchange handler; "evaluate media
        // queries and report changes" fires MediaQueryListEvent at the lists
        // whose matches state changed when the viewport resizes.
        let mut engine = platform_engine();
        assert_eq!(
            string_value(
                &mut engine,
                "const tag = o => Object.prototype.toString.call(o).slice(8, -1);\n\
                 globalThis.mediaLog = [];\n\
                 globalThis.narrow = matchMedia('(max-width: 400px)');\n\
                 const listener = e => mediaLog.push('listener:' + e.matches + ':' + tag(e) + ':' + e.isTrusted);\n\
                 narrow.addListener(listener); narrow.addListener(listener);\n\
                 narrow.onchange = e => mediaLog.push('handler:' + e.media);\n\
                 let constructed; try { new MediaQueryList(); } catch (e) { constructed = e.name; }\n\
                 const event = new MediaQueryListEvent('change', {media: 'x', matches: true});\n\
                 [tag(narrow), narrow instanceof EventTarget, narrow.media, narrow.matches,\n\
                  typeof narrow.onchange, constructed, event.media, event.matches, MediaQueryListEvent.length,\n\
                  matchMedia('screen,  print').media].join('|')"
            ),
            "MediaQueryList|true|(max-width: 400px)|false|function|TypeError|x|true|1|screen, print"
        );
        assert!(
            engine_call_trust_method(
                &mut engine,
                "setViewport",
                &[Value::Num(300.0), Value::Num(200.0)]
            )
            .is_ok()
        );
        assert_eq!(
            string_value(&mut engine, "[narrow.matches, ...mediaLog].join('|')"),
            "true|listener:true:MediaQueryListEvent:true|handler:(max-width: 400px)"
        );
    }

    #[test]
    fn media_time_ranges_are_static_time_ranges() {
        // HTML #time-ranges and #dom-media-buffered: a new TimeRanges object
        // per read; start()/end() past the end throw IndexSizeError.
        let mut engine = platform_engine();
        assert_eq!(
            string_value(
                &mut engine,
                "const tag = o => Object.prototype.toString.call(o).slice(8, -1);\n\
                 const video = document.createElement('video');\n\
                 const ranges = video.buffered;\n\
                 let start; try { ranges.start(0); } catch (e) { start = e.name; }\n\
                 let constructed; try { new TimeRanges(); } catch (e) { constructed = e.name; }\n\
                 [tag(ranges), tag(video.played), tag(video.seekable), ranges.length,\n\
                  ranges === video.buffered, start, constructed].join('|')"
            ),
            "TimeRanges|TimeRanges|TimeRanges|0|false|IndexSizeError|TypeError"
        );
    }

    #[test]
    fn attributes_are_a_live_named_node_map_of_attr_nodes() {
        // DOM §4.9.1 #interface-namednodemap and §4.9.2 #interface-attr:
        // element.attributes is a live [SameObject] NamedNodeMap (not an
        // Array) with indexed and unenumerable named properties, holding
        // Attr nodes that keep their identity while the attribute exists and
        // keep their value once removed. Values match Chromium's.
        let mut engine = platform_engine();
        assert_eq!(
            string_value(
                &mut engine,
                "const tag = o => Object.prototype.toString.call(o).slice(8, -1);\n\
                 const err = f => { try { f(); return 'none'; } catch (e) { return e.name; } };\n\
                 const el = document.createElement('div');\n\
                 el.setAttribute('id', 'd'); el.setAttribute('title', 'x');\n\
                 const map = el.attributes, id = map[0];\n\
                 const before = [tag(map), Array.isArray(map), map === el.attributes, map.length, tag(id),\n\
                   id.name, id.value, id.nodeType, id.nodeName, id.nodeValue, id.ownerElement === el,\n\
                   id instanceof Node, id.parentNode, id.childNodes.length, map.id === id,\n\
                   map.getNamedItem('ID') === id, el.getAttributeNode('id') === id, map.item(5),\n\
                   Object.keys(map).join(), Object.getOwnPropertyNames(map).join(),\n\
                   Array.from(map, a => a.name).join()];\n\
                 id.value = 'e';\n\
                 const live = [el.id, map.length];\n\
                 el.removeAttribute('id');\n\
                 const removed = [map.length, id.ownerElement, id.value, 'id' in map, map[0].name];\n\
                 const created = document.createAttribute('Data-X'); created.value = 'v';\n\
                 const old = el.setAttributeNode(created);\n\
                 const set = [created.name, old, created.ownerElement === el, el.getAttribute('data-x'),\n\
                   err(() => document.createElement('p').setAttributeNode(created)),\n\
                   el.removeAttributeNode(created) === created, el.hasAttribute('data-x'),\n\
                   err(() => el.removeAttributeNode(created)), err(() => map.removeNamedItem('nope')),\n\
                   err(() => new Attr()), err(() => structuredClone(map)),\n\
                   created.cloneNode().value, created.compareDocumentPosition(el) & 1];\n\
                 [...before, ...live, ...removed, ...set].join('|')"
            ),
            "NamedNodeMap|false|true|2|Attr|id|d|2|id|d|true|true||0|true|true|true||0,1|\
             0,1,id,title|id,title|e|2|1||e|false|title|data-x||true|v|InUseAttributeError|\
             true|false|NotFoundError|NotFoundError|TypeError|DataCloneError|v|1"
        );
    }

    #[test]
    fn namespaced_attributes_follow_dom() {
        // DOM #dom-element-getattributens, -setattributens, -removeattributens
        // and -hasattributens over #concept-element-attributes-get-by-namespace,
        // -set-value and -remove-by-namespace; #validate-and-extract; Attr and
        // NamedNodeMap namespaces; #queue-a-mutation-record (attributeFilter
        // never matches a namespaced attribute); and attributeChangedCallback's
        // namespace argument (HTML #concept-element-attributes-change-ext).
        let mut engine = platform_engine();
        assert_eq!(
            string_value(
                &mut engine,
                "const XL = 'http://www.w3.org/1999/xlink';\n\
                 const err = f => { try { f(); return 'none'; } catch (e) { return e.name; } };\n\
                 const el = document.createElement('div');\n\
                 el.setAttributeNS(XL, 'xl:href', 'a');\n\
                 el.setAttributeNS(null, 'viewBox', 'v');\n\
                 const attr = el.getAttributeNodeNS(XL, 'href');\n\
                 const get = [el.getAttributeNS(XL, 'href'), el.hasAttributeNS(XL, 'href'),\n\
                   el.getAttribute('xl:href'), el.getAttributeNS('', 'viewBox'), el.getAttribute('viewbox'),\n\
                   el.hasAttributeNS(null, 'viewbox'), attr.namespaceURI === XL, attr.prefix, attr.localName,\n\
                   attr.name, el.attributes.getNamedItemNS(XL, 'href') === attr, el.getAttributeNS(XL, 'nope')];\n\
                 el.setAttributeNS(XL, 'other:href', 'b');\n\
                 const change = [el.getAttribute('xl:href'), el.getAttribute('other:href'), attr.value,\n\
                   el.attributes.length];\n\
                 const invalid = [err(() => el.setAttributeNS(null, 'p:x', '')),\n\
                   err(() => el.setAttributeNS(XL, 'xml:x', '')), err(() => el.setAttributeNS(XL, 'xmlns', '')),\n\
                   err(() => el.setAttributeNS(XL, 'a b', '')), err(() => el.getAttributeNS(XL))];\n\
                 el.removeAttributeNS(XL, 'href');\n\
                 const removed = [el.hasAttributeNS(XL, 'href'), attr.ownerElement, attr.value,\n\
                   el.attributes.length];\n\
                 const host = document.createElement('div');\n\
                 host.innerHTML = '<svg><use xlink:href=\"#a\"/></svg>';\n\
                 const use = host.querySelector('use'), useAttr = use.attributes[0];\n\
                 const parsed = [use.getAttributeNS(XL, 'href'), useAttr.prefix, useAttr.namespaceURI === XL];\n\
                 const xml = new DOMParser().parseFromString('<r xmlns:x=\"urn:x\" x:a=\"1\"/>', 'application/xml');\n\
                 const root = xml.documentElement;\n\
                 const xmlAttrs = [root.getAttributeNS('urn:x', 'a'),\n\
                   root.getAttributeNS('http://www.w3.org/2000/xmlns/', 'x'), root.attributes[1].prefix];\n\
                 const target = document.createElement('p');\n\
                 const filtered = new MutationObserver(() => {}), all = new MutationObserver(() => {});\n\
                 filtered.observe(target, {attributes: true, attributeFilter: ['href']});\n\
                 all.observe(target, {attributes: true});\n\
                 target.setAttributeNS(XL, 'xl:href', '1'); target.setAttribute('href', '2');\n\
                 const f = filtered.takeRecords(), a = all.takeRecords();\n\
                 const records = [f.length, f[0].attributeName, f[0].attributeNamespace, a.length,\n\
                   a[0].attributeName, a[0].attributeNamespace === XL];\n\
                 const calls = [];\n\
                 customElements.define('ns-attr-probe', class extends HTMLElement {\n\
                   static get observedAttributes() { return ['href']; }\n\
                   attributeChangedCallback(...args) { calls.push(args.map(String).join(',')); }\n\
                 });\n\
                 const probe = document.createElement('ns-attr-probe');\n\
                 probe.setAttributeNS(XL, 'xl:href', 'v'); probe.removeAttributeNS(XL, 'href');\n\
                 probe.setAttribute('href', 'w');\n\
                 [...get, ...change, ...invalid, ...removed, ...parsed, ...xmlAttrs, ...records,\n\
                  calls.join(';')].join('|')"
            ),
            "a|true|a|v||false|true|xl|href|xl:href|true||b||b|2|NamespaceError|NamespaceError|\
             NamespaceError|InvalidCharacterError|TypeError|false||b|1|#a|xlink|true|1|urn:x|x|\
             1|href||2|href|true|href,null,v,http://www.w3.org/1999/xlink;\
             href,v,null,http://www.w3.org/1999/xlink;href,null,w,null"
        );
    }

    #[test]
    fn xml_documents_keep_doctypes_and_serialize_namespaces() {
        // HTML #dom-domparser-parsefromstring ("a new Document") with a
        // DocumentType node for the XML DOCTYPE; DOM Parsing
        // #dfn-xml-serialization for XMLSerializer (require well-formed false)
        // and an XML document's innerHTML/outerHTML getters (HTML
        // #fragment-serializing-algorithm-steps, require well-formed true).
        let mut engine = platform_engine();
        assert_eq!(
            string_value(
                &mut engine,
                "const err = f => { try { f(); return 'none'; } catch (e) { return e.name; } };\n\
                 const ser = n => new XMLSerializer().serializeToString(n);\n\
                 const doc = new DOMParser().parseFromString('<!DOCTYPE note PUBLIC \"-//X//EN\" \"note.dtd\" \
                   [<!ENTITY e \"x\">]><note xmlns:x=\"urn:x\" x:a=\"1\" b=\"&quot;&lt;&#9;\"><x:to>T</x:to>\
                   <![CDATA[a<b]]><?pi d?><!--c--></note>', 'application/xml');\n\
                 const root = doc.documentElement;\n\
                 const created = document.implementation.createDocument('urn:a', 'a:root', null);\n\
                 const child = created.createElementNS('urn:b', 'child');\n\
                 child.setAttributeNS('urn:c', 'c:at', 'v');\n\
                 created.documentElement.appendChild(child);\n\
                 const bad = created.createElement('x');\n\
                 bad.appendChild(created.createComment('--'));\n\
                 const html = document.createElement('div');\n\
                 html.innerHTML = null;\n\
                 [doc instanceof XMLDocument, doc.doctype.name, doc.doctype.publicId, doc.doctype.systemId,\n\
                  doc.firstChild === doc.doctype, ser(doc), root.innerHTML, root.outerHTML === ser(root),\n\
                  ser(created), ser(document.createElement('br')), ser(bad), err(() => bad.outerHTML),\n\
                  err(() => ser({})), ser(root.attributes[0]), JSON.stringify(html.innerHTML)].join('|')"
            ),
            "false|note|-//X//EN|note.dtd|true|<!DOCTYPE note PUBLIC \"-//X//EN\" \"note.dtd\">\
             <note xmlns:x=\"urn:x\" x:a=\"1\" b=\"&quot;&lt;&#9;\"><x:to>T</x:to><![CDATA[a<b]]>\
             <?pi d?><!--c--></note>|<x:to xmlns:x=\"urn:x\">T</x:to><![CDATA[a<b]]><?pi d?><!--c-->|\
             true|<a:root xmlns:a=\"urn:a\"><child xmlns=\"urn:b\" xmlns:c=\"urn:c\" c:at=\"v\"/></a:root>|\
             <br xmlns=\"http://www.w3.org/1999/xhtml\" />|<x><!------></x>|InvalidStateError|TypeError||\"\""
        );
    }

