    #[test]
    fn document_last_modified_uses_the_source_time_in_local_time() {
        // HTML #dom-document-lastmodified: "MM/DD/YYYY hh:mm:ss" in the
        // user's local time zone, from the source's modification time, or
        // the current time when that is unknown. Round-trip through
        // Date.parse so the assertion holds in any system time zone.
        let clock = Rc::new(RealmClock::new());
        let mut engine = configured_engine_before_prelude(
            HostState::new(Rc::new(RefCell::new(Dom::new())), clock),
            DEFAULT_URL,
        );
        eval(
            &mut engine,
            "globalThis.__trust_cfg.lastModified = 1709622489000;",
            "last modified",
        )
        .unwrap();
        eval_platform_prelude(&mut engine).unwrap();
        assert_eq!(
            string_value(
                &mut engine,
                "const created = document.implementation.createHTMLDocument('').lastModified;\n\
                 const format = /^\\d\\d\\/\\d\\d\\/\\d{4} \\d\\d:\\d\\d:\\d\\d$/;\n\
                 [format.test(document.lastModified), Date.parse(document.lastModified),\n\
                  format.test(created), Math.abs(Date.parse(created) - Date.now()) < 5000].join()"
            ),
            "true,1709622489000,true,true"
        );
    }

    fn worker_platform_engine() -> lumen::Engine {
        worker_platform_engine_with(true)
    }

    fn worker_platform_engine_with(test_internals: bool) -> lumen::Engine {
        let clock = Rc::new(RealmClock::new());
        let mut state = HostState::new(Rc::new(RefCell::new(Dom::new())), clock.clone());
        state.test_hooks.internals = test_internals;
        let (events, _) = tokio::sync::mpsc::unbounded_channel();
        state.worker_self = Some(LumenWorkerSelf {
            id: 1,
            events: LumenTaskSender::Page(events),
            closed: false,
            origin: url::Url::parse(DEFAULT_URL).unwrap(),
            secure_context: true,
            settings_origin: url::Url::parse(DEFAULT_URL).unwrap().origin(),
            referrer_policy: Default::default(),
        });
        let origin = clock.origin_ms;
        let mut engine = lumen::Engine::new();
        engine.set_wall_clock(move || clock.now_ms());
        engine
            .ctx()
            .op_state()
            .put_retained_memory_with_external_memory(state);
        install_lumen_worker_boundary(&mut engine);
        eval(
            &mut engine,
            &format!("globalThis.__worker_cfg={{url:'https://example.org/worker.js',timeOrigin:{origin}}}"),
            "worker config",
        )
        .unwrap();
        assert!(eval_lumen_worker_platform_setup(&mut engine).unwrap());
        engine
    }

    #[test]
    fn dedicated_worker_global_is_a_dedicated_worker_global_scope() {
        // HTML #dedicated-workers-and-the-dedicatedworkerglobalscope-interface
        // (local whatwg/html@e5071a2): the global of a dedicated worker is a
        // DedicatedWorkerGlobalScope inheriting WorkerGlobalScope and
        // EventTarget. testharness.js selects its worker environment with
        // `self instanceof DedicatedWorkerGlobalScope`.
        let mut worker = worker_platform_engine();
        assert_eq!(
            string_value(
                &mut worker,
                "const results = [self instanceof DedicatedWorkerGlobalScope,\n\
                   self instanceof WorkerGlobalScope, self instanceof EventTarget,\n\
                   Object.prototype.toString.call(self), DedicatedWorkerGlobalScope.name,\n\
                   Object.getPrototypeOf(DedicatedWorkerGlobalScope) === WorkerGlobalScope,\n\
                   typeof SharedWorkerGlobalScope, typeof postMessage,\n\
                   Object.getOwnPropertyDescriptor(self, 'DedicatedWorkerGlobalScope').enumerable];\n\
                 for (const C of [WorkerGlobalScope, DedicatedWorkerGlobalScope]) {\n\
                   try { new C(); results.push('constructed'); }\n\
                   catch (error) { results.push(error instanceof TypeError); }\n\
                 }\n\
                 results.join()"
            ),
            "true,true,true,[object DedicatedWorkerGlobalScope],DedicatedWorkerGlobalScope,\
             true,undefined,function,false,true,true"
        );
    }

    #[test]
    fn declarative_shadow_wrappers_hydration_and_closed_roots() {
        let mut engine = configured_engine(
            HostState::new(
                Rc::new(RefCell::new(Dom::parse_document(
                    r#"<!doctype html>
                    <div id=host><template shadowrootmode=open shadowrootdelegatesfocus shadowrootclonable>
                        <button id=login>Log in</button></template></div>
                    <div id=closed><template shadowrootmode=closed shadowrootserializable>
                        <a>Closed navigation</a></template></div>"#,
                ))),
                Rc::new(RealmClock::new()),
            ),
            DEFAULT_URL,
        );
        assert_eq!(
            string_value(
                &mut engine,
                r#"(() => {
            const check = (v, message) => { if (!v) throw Error(message); };
            check(Object.prototype.hasOwnProperty.call(HTMLTemplateElement.prototype, 'shadowRootMode'), 'feature detection');
            const template = document.createElement('template');
            template.shadowRootMode = 'OPEN';
            template.shadowRootDelegatesFocus = true;
            check(template.shadowRootMode === 'open' && template.getAttribute('shadowrootmode') === 'OPEN', 'mode reflection');
            check(template.hasAttribute('shadowrootdelegatesfocus'), 'boolean reflection');
            template.shadowRootMode = 'invalid';
            check(template.shadowRootMode === '', 'invalid mode reflection');
            const host = document.getElementById('host');
            const root = host.shadowRoot;
            check(root instanceof ShadowRoot && root instanceof DocumentFragment, 'root interfaces');
            check(root.host === host && root.mode === 'open', 'root identity');
            check(root.delegatesFocus && root.clonable && root.slotAssignment === 'named', 'root flags');
            check(document.querySelector('#login') === null && host.children.length === 0, 'encapsulation');
            const login = root.getElementById('login');
            check(login.parentNode === root && login.getRootNode() === root, 'parent identity');
            let clicked = false;
            login.addEventListener('click', () => { clicked = true; });
            login.click();
            check(clicked, 'parsed shadow event handler');
            const copy = host.cloneNode(false);
            check(copy.shadowRoot.getElementById('login').textContent === 'Log in', 'shallow host clone');
            const observer = new MutationObserver(() => {});
            observer.observe(root, {childList:true});
            const reclaimed = host.attachShadow({mode:'open'});
            check(reclaimed === root && !root.firstChild && root.delegatesFocus, 'declarative reclaim');
            check(login.parentNode === null && !login.isConnected, 'removed child');
            check(observer.takeRecords().some(r => Array.from(r.removedNodes).includes(login)), 'removal observation');
            let duplicate = false;
            try { host.attachShadow({mode:'open'}); } catch (e) { duplicate = e.name === 'NotSupportedError'; }
            check(duplicate, 'second script attachment must throw');
            const closed = document.getElementById('closed');
            check(closed.shadowRoot === null, 'closed root privacy');
            let mismatch = false;
            try { closed.attachShadow({mode:'open'}); } catch (e) { mismatch = e.name === 'NotSupportedError'; }
            check(mismatch && closed.shadowRoot === null, 'mismatched mode');
            const hidden = closed.attachShadow({mode:'closed'});
            check(hidden.mode === 'closed' && hidden.serializable && !hidden.firstChild, 'closed reclaim');
            check(closed.shadowRoot === null, 'closed root stays closed');
            return 'declarative-shadow-ok';
        })()"#
            ),
            "declarative-shadow-ok"
        );
    }

