    /// DOM #concept-node-remove enqueues disconnectedCallback for every custom
    /// element among the removed node's shadow-including inclusive
    /// descendants, and HTML #cereactions runs it once the removal is done:
    /// for removeChild, replaceChild, and the replace-all of textContent.
    #[test]
    fn removal_disconnects_custom_elements_after_the_removal() {
        let mut engine = platform_engine();
        assert_eq!(
            string_value(
                &mut engine,
                r#"(() => {
            const html = document.createElement('html'), body = document.createElement('body');
            document.appendChild(html); html.appendChild(body);
            const log = [];
            customElements.define('x-gone', class extends HTMLElement {
                disconnectedCallback() { log.push(this.id + ':' + this.isConnected); }
            });
            const make = id => { const el = document.createElement('x-gone'); el.id = id; return el; };
            const box = document.createElement('div'); body.appendChild(box);
            box.append(make('a'), make('b'));
            const host = document.createElement('section'); box.appendChild(host);
            host.attachShadow({ mode: 'closed' }).appendChild(make('in-shadow'));
            box.textContent = 'text';
            log.push('|');
            box.appendChild(make('c'));
            box.textContent = '';
            log.push('|');
            const old = make('d'); box.appendChild(old);
            box.replaceChild(document.createElement('p'), old);
            log.push('|');
            box.appendChild(make('e')); box.innerHTML = '';
            return log.join(',');
        })()"#
            ),
            "a:false,b:false,in-shadow:false,|,c:false,|,d:false,|,e:false"
        );
    }

    /// HTML #concept-upgrade-an-element enqueues the element's
    /// attributeChangedCallback reactions (attribute-list order, values and
    /// namespaces from before construction) and its connectedCallback (when
    /// connected before construction) ahead of the constructor. While the
    /// constructor runs the element is not yet custom, so what it does to the
    /// element enqueues nothing, and a constructor that throws leaves the
    /// element failed without reactions.
    #[test]
    fn upgrade_reactions_come_from_the_element_before_construction() {
        let mut engine = platform_engine();
        assert_eq!(
            string_value(
                &mut engine,
                r#"(() => {
            const html = document.createElement('html'), body = document.createElement('body');
            document.appendChild(html); html.appendChild(body);
            const log = [];
            const a = document.createElement('x-a');
            a.setAttribute('class', 'c'); a.setAttribute('id', 'i');
            body.appendChild(a);
            customElements.define('x-a', class extends HTMLElement {
                static get observedAttributes() { return ['id', 'class', 'title']; }
                constructor() {
                    super();
                    this.title = 't'; this.setAttribute('id', 'changed');
                    log.push('ctor:' + this.getAttribute('id'));
                    this.remove();
                }
                attributeChangedCallback(n, o, v, ns) { log.push(n + '=' + v + ':' + o + ':' + ns); }
                connectedCallback() { log.push('connected:' + this.isConnected); }
                disconnectedCallback() { log.push('disconnected'); }
            });
            body.appendChild(a);
            log.push('|');
            const b = document.createElement('x-b');
            customElements.define('x-b', class extends HTMLElement {
                constructor() { super(); body.appendChild(this); log.push('ctor-b'); }
                connectedCallback() { log.push('connected-b'); }
                disconnectedCallback() { log.push('disconnected-b'); }
            });
            customElements.upgrade(b);
            log.push('|');
            b.remove();
            log.push('|');
            const c = document.createElement('x-c');
            c.id = 'x'; body.appendChild(c);
            customElements.define('x-c', class extends HTMLElement {
                static get observedAttributes() { return ['id']; }
                constructor() { super(); log.push('ctor-c'); throw new Error('failed'); }
                attributeChangedCallback() { log.push('attr-c'); }
                connectedCallback() { log.push('connected-c'); }
                disconnectedCallback() { log.push('disconnected-c'); }
            });
            c.id = 'y'; c.remove(); body.appendChild(c); customElements.upgrade(c);
            return log.join(',');
        })()"#
            ),
            "ctor:changed,class=c:null:null,id=i:null:null,connected:false,connected:true,|,\
             ctor-b,|,disconnected-b,|,ctor-c"
        );
    }

    /// HTML runs a script element's post-connection steps when an insertion
    /// connects it, whether it is the inserted node or a descendant (shadow
    /// trees included), in tree order. "Already started" scripts never run:
    /// those the fragment parser created (Inert scripting mode), those that
    /// already ran, and their clones (#already-started cloning steps).
    #[test]
    fn inserting_a_subtree_runs_its_scripts_once() {
        let mut engine = platform_engine();
        assert_eq!(
            string_value(
                &mut engine,
                r#"(() => {
            const html = document.createElement('html'), body = document.createElement('body');
            document.appendChild(html); html.appendChild(body);
            globalThis.ran = [];
            const script = text => { const s = document.createElement('script'); s.textContent = 'ran.push(' + JSON.stringify(text) + ')'; return s; };
            const box = document.createElement('div');
            const inner = document.createElement('p');
            inner.append(script('nested-1'));
            box.append(inner, script('nested-2'));
            body.appendChild(box);
            ran.push('|');
            const parsed = document.createElement('div');
            parsed.innerHTML = '<script>ran.push("innerHTML")<\/script>';
            body.appendChild(parsed);
            body.appendChild(parsed.firstChild);
            ran.push('|');
            const host = document.createElement('div');
            host.attachShadow({ mode: 'open' }).appendChild(script('shadow'));
            body.appendChild(host);
            ran.push('|');
            const holder = document.createElement('section'); body.appendChild(holder);
            holder.appendChild(box);
            ran.push('|');
            body.appendChild(box.lastChild.cloneNode(true));
            const fresh = script('clone-of-fresh');
            body.appendChild(fresh.cloneNode(true));
            return ran.join(',');
        })()"#
            ),
            "nested-1,nested-2,|,|,shadow,|,|,clone-of-fresh"
        );
    }

    /// HTML's iframe insertion and removing steps run whenever a navigable
    /// container is in the inserted or removed subtree, at any depth and on
    /// every path; the frame-free fast path never skips them.
    #[test]
    fn mutation_fast_paths_keep_frame_insertion_and_removal_steps() {
        let mut engine = platform_engine();
        assert_eq!(
            string_value(
                &mut engine,
                r#"
                const html = document.createElement('html'), body = document.createElement('body');
                document.appendChild(html); html.appendChild(body);
                const box = document.createElement('div'), frame = document.createElement('iframe');
                box.appendChild(frame);
                const states = [frame.contentWindow === null];
                body.appendChild(box); states.push(frame.contentWindow !== null);
                box.remove(); states.push(frame.contentWindow === null);
                body.appendChild(box); states.push(frame.contentWindow !== null);
                body.removeChild(box); states.push(frame.contentWindow === null);
                body.appendChild(box); box.textContent = ''; states.push(frame.contentWindow === null);
                box.appendChild(frame); body.appendChild(box); box.innerHTML = ''; states.push(frame.contentWindow === null);
                const deep = document.createElement('div');
                deep.appendChild(document.createElement('p')).appendChild(frame);
                body.insertBefore(deep, null); states.push(frame.contentWindow !== null);
                deep.firstChild.remove(); states.push(frame.contentWindow === null);
                states.join(',');
            "#
            ),
            "true,true,true,true,true,true,true,true,true"
        );
    }

    /// Wrappers of created nodes and Node's base-class constructor keep Web IDL
    /// interface identity, wrapper caching and the EventTarget superclass,
