    #[tokio::test]
    async fn a_primary_release_and_its_click_share_one_task() {
        // UI Events #handle-native-mouse-click: the platform calls it
        // "immediately after handle native mouse up" for a mouseup that
        // generates a click, so no rendering update shows the mouseup without
        // its click. The actor decides the click from its own hit tests; the
        // frontend's focus of the pressed control, sent with the release,
        // rides along (d, u, f, c below), and any other command runs after the
        // click. The slow mousedown holds the actor until the release and
        // what follows it are queued, as one native event queues them.
        let html = "<button id=b>go</button><input id=i><input id=j><output id=o></output><script>\
            const o = document.getElementById('o'), b = document.getElementById('b');\
            const log = (s) => { o.textContent += s; };\
            b.addEventListener('mousedown', () => {\
                log('d'); const t = performance.now(); while (performance.now() - t < 80) {}\
            });\
            b.addEventListener('mouseup', () => log('u'));\
            b.addEventListener('click', () => log('c'));\
            document.getElementById('i').addEventListener('focus', () => log('f'));\
            document.getElementById('j').addEventListener('input', () => log('g'), {once: true});</script>";
        let dom = Dom::parse_document(html);
        let (button, input) = (dom.get_by_id("b").unwrap(), dom.get_by_id("i").unwrap());
        let other = dom.get_by_id("j").unwrap();
        let mut env = crate::js::PageEnv::bare(DEFAULT_URL);
        env.terminal_presentation = false;
        let (handle, mut events) = spawn_page(html.into(), env);
        // Inside the button, past the body's 8px margin.
        let pointer = |pressed| crate::js::PageCmd::PointerButton {
            node: Some(button),
            pressed,
            x: 12.0,
            y: 12.0,
            button: 0,
            metadata: Default::default(),
        };
        let output = |html: &str| {
            let start = html.find("<output")?;
            let open = start + html[start..].find('>')? + 1;
            let close = open + html[open..].find("</output>")?;
            Some(html[open..close].to_owned())
        };
        tokio::time::timeout(Duration::from_secs(20), async {
            while !matches!(
                events.recv().await,
                Some(crate::js::PageEvt::Updated { .. })
            ) {}
            let mut seen = Vec::new();
            for (gesture, expected) in [
                (vec![pointer(true), pointer(false)], "duc"),
                (
                    vec![
                        pointer(true),
                        pointer(false),
                        crate::js::PageCmd::Focus(Some(input)),
                    ],
                    "ducdufc",
                ),
                (
                    vec![
                        pointer(true),
                        pointer(false),
                        crate::js::PageCmd::SetValue {
                            node: other,
                            value: String::from("x"),
                            checked: None,
                            commit: false,
                        },
                    ],
                    "ducdufcducg",
                ),
            ] {
                for command in gesture {
                    handle.try_send_user(command).unwrap();
                }
                loop {
                    match events.recv().await {
                        Some(crate::js::PageEvt::Updated { html, .. }) => {
                            let Some(text) = output(&html) else { continue };
                            if seen.last() != Some(&text) {
                                seen.push(text.clone());
                            }
                            if text == expected {
                                break;
                            }
                        }
                        Some(crate::js::PageEvt::Trouble(errors)) => panic!("{errors:?}"),
                        Some(_) => {}
                        None => panic!("actor ended before the click; saw {seen:?}"),
                    }
                }
            }
            assert!(
                seen.iter()
                    .filter(|text| text.len() <= "ducdufc".len())
                    .all(|text| !text.ends_with('u')),
                "a rendering update showed a mouseup without its click: {seen:?}"
            );
            assert_eq!(
                seen.last().map(String::as_str),
                Some("ducdufcducg"),
                "{seen:?}"
            );
        })
        .await
        .unwrap();
    }

    #[tokio::test]
    async fn a_child_navigables_fragment_navigation_sets_its_own_target() {
        // HTML #target-element, #navigate-fragid and
        // #scroll-to-the-fragment-identifier with Selectors 4
        // #the-target-pseudo: each Document has its own target element. A
        // child navigable's fragment navigation (here from its load handler,
        // as felixfever.nekoweb.org's dress-up game does with
        // `location.replace('#…')`; an about:srcdoc Document resolves that
        // against its parent's base URL, so this uses the hash setter)
        // indicates an element
        // of its Document, which :target then matches, and leaves the
        // parent's target alone even where the parent has the same id.
        let child = "<!doctype html><style>section{display:none}section:target{display:block}</style>\
            <section id=a>A</section><section id=b>B</section><script>\
            onload = () => { location.hash = 'b'; const t = document.querySelector(':target');\
            const shown = ['a','b'].map(id => getComputedStyle(document.getElementById(id)).display);\
            parent.document.getElementById('o').textContent = 'child:' + (t && t.id) + ':' + shown + \
            ' parent:' + parent.document.querySelector(':target'); };</script>";
        let html = format!(
            "<section id=b>parent b</section><output id=o></output><iframe srcdoc=\"{child}\"></iframe>\
             <script>document.addEventListener('click', () => {{}});</script>"
        );
        let mut env = crate::js::PageEnv::bare(DEFAULT_URL);
        env.terminal_presentation = false;
        let (_handle, mut events) = spawn_page(html, env);
        let expected = "child:b:none,block parent:null";
        tokio::time::timeout(Duration::from_secs(20), async {
            let mut last = String::new();
            loop {
                match events.recv().await {
                    Some(crate::js::PageEvt::Updated { html, .. }) => {
                        if let Some(start) = html.find("<output") {
                            let open = start + html[start..].find('>').unwrap() + 1;
                            let close = open + html[open..].find("</output>").unwrap();
                            last = html[open..close].to_owned();
                            if last == expected {
                                break;
                            }
                        }
                    }
                    Some(crate::js::PageEvt::Trouble(errors)) => panic!("{errors:?}"),
                    Some(_) => {}
                    None => panic!("actor ended; saw {last:?}"),
                }
            }
        })
        .await
        .unwrap_or_else(|_| panic!("the child never reported its target"));
    }

    #[tokio::test]
    async fn a_click_on_plain_content_reaches_the_element_under_the_pointer() {
        // UI Events #handle-native-mouse-down, -up and -click with CSSOM View
        // elementFromPoint as the hit test: a press and release over text with
        // no listener of its own target that text's element, and the click
        // they generate bubbles to a document listener ("click outside").
        // The frontend names no node for such content.
        let html = "<style>body{margin:0}p{margin:0;height:40px}</style><body id=body>\
            <p id=first>first</p><p id=plain>plain text</p><output id=o></output><script>\
            const o = document.getElementById('o');\
            for (const type of ['mousedown', 'mouseup', 'click'])\
                document.addEventListener(type, (e) => { o.textContent += type[5] || type[0]; \
                    o.textContent += ':' + e.target.id + ' '; });</script>";
        let mut env = crate::js::PageEnv::bare(DEFAULT_URL);
        env.terminal_presentation = false;
        let (handle, mut events) = spawn_page(html.into(), env);
        let pointer = |pressed, y| crate::js::PageCmd::PointerButton {
            node: None,
            pressed,
            x: 20.0,
            y,
            button: 0,
            metadata: Default::default(),
        };
        let output = |html: &str| {
            let start = html.find("<output")?;
            let open = start + html[start..].find('>')? + 1;
            let close = open + html[open..].find("</output>")?;
            Some(html[open..close].to_owned())
        };
        tokio::time::timeout(Duration::from_secs(20), async {
            while !matches!(
                events.recv().await,
                Some(crate::js::PageEvt::Updated { .. })
            ) {}
            // A press on one paragraph and a release on the other generate a
            // click at their nearest common ancestor, the body (Pointer Events
            // #the-click-auxclick-and-contextmenu-events).
            for command in [
                pointer(true, 60.0),
                pointer(false, 60.0),
                pointer(true, 20.0),
                pointer(false, 60.0),
            ] {
                handle.try_send_user(command).unwrap();
            }
            let expected = "d:plain u:plain c:plain d:first u:plain c:body ";
            let mut last = String::new();
            loop {
                match events.recv().await {
                    Some(crate::js::PageEvt::Updated { html, .. }) => {
                        if let Some(text) = output(&html) {
                            last = text;
                            if last == expected {
                                break;
                            }
                        }
                    }
                    Some(crate::js::PageEvt::Trouble(errors)) => panic!("{errors:?}"),
                    Some(_) => {}
                    None => panic!("actor ended; saw {last:?}"),
                }
            }
        })
        .await
        .unwrap();
    }

    #[tokio::test]
    async fn actor_reports_the_users_selection_and_context_menu() {
        // Selection API §2 "User Interactions" and Pointer Events
        // #maybe-show-context-menu, end to end: a frontend's press, drag and
        // release select the page's text, and the page answers the gesture
        // with what its selection selects (user-select:none text left out);
        // a secondary click asks whether the frontend shows its menu.
        let html = "<style>body{margin:0}p{margin:0;height:20px}</style>\
            <p id=p>Hello brave world</p><p id=n style='user-select:none'>skip</p>\
            <p id=q>more text</p><script>document.getElementById('p').addEventListener('click',()=>{});\
            document.getElementById('n').addEventListener('contextmenu',(e)=>e.preventDefault());</script>";
        let dom = Dom::parse_document(html);
        let element = |id| dom.get_by_id(id).unwrap();
        let text = |id| dom.children(element(id))[0];
        let (p, n, q) = (text("p"), text("n"), text("q"));
        let mut env = crate::js::PageEnv::bare(DEFAULT_URL);
        env.terminal_presentation = false;
        let (handle, mut events) = spawn_page(html.into(), env);
        let metadata = |node, offset, serial| crate::js::PointerMetadata {
            selection: Some(crate::js::PointerSelection::new(
                Some(crate::core::TextPoint { node, offset }),
                serial,
            )),
            ..Default::default()
        };
        // The actor hit-tests each button: the paragraphs are 20px rows.
        let row = |node| {
            [element("p"), element("n"), element("q")]
                .iter()
                .position(|&id| id == node)
                .unwrap() as f64
        };
        let button = |node, pressed, button, metadata| crate::js::PageCmd::PointerButton {
            node: Some(node),
            pressed,
            x: 10.0,
            y: 10.0 + 20.0 * row(node),
            button,
            metadata,
        };
        tokio::time::timeout(Duration::from_secs(15), async {
            while !matches!(
                events.recv().await,
                Some(crate::js::PageEvt::Updated { .. })
            ) {}
            handle
                .try_send_user(button(element("p"), true, 0, metadata(p, 2, 1)))
                .unwrap();
            handle.send_hover_with_metadata(Some(element("q")), 10.0, 50.0, metadata(q, 4, 2));
            handle
                .try_send_user(button(element("q"), false, 0, metadata(q, 4, 3)))
                .unwrap();
            let report = loop {
                match events.recv().await {
                    Some(crate::js::PageEvt::Selection(report)) if report.serial == 3 => {
                        break report;
                    }
                    Some(crate::js::PageEvt::Trouble(errors)) => panic!("{errors:?}"),
                    Some(_) => {}
                    None => panic!("actor ended before reporting the selection"),
                }
            };
            assert_eq!(report.segments.text.get(&p), Some(&vec![(2, 17)]));
            assert_eq!(report.segments.text.get(&n), None);
            assert_eq!(report.segments.text.get(&q), Some(&vec![(0, 4)]));
            assert_eq!(
                report.anchor,
                Some(crate::core::TextPoint { node: p, offset: 2 })
            );
            assert_eq!(
                report.focus,
                Some(crate::core::TextPoint { node: q, offset: 4 })
            );
            for (target, show) in [(element("p"), true), (element("n"), false)] {
                let ask = crate::js::PointerMetadata {
                    selection: Some(Default::default()),
                    ..Default::default()
                };
                handle.try_send_user(button(target, true, 2, ask)).unwrap();
                handle.try_send_user(button(target, false, 2, ask)).unwrap();
                loop {
                    match events.recv().await {
                        Some(crate::js::PageEvt::ContextMenu { show: shown }) => {
                            assert_eq!(shown, show);
                            break;
                        }
                        Some(crate::js::PageEvt::Trouble(errors)) => panic!("{errors:?}"),
                        Some(_) => {}
                        None => panic!("actor ended before answering the context menu"),
                    }
                }
            }
        })
        .await
        .unwrap();
    }

    #[tokio::test]
    async fn contenteditable_key_default_uses_live_selection_and_input_events() {
        // Selection API §3 and Input Events 2 §6: keydown/keypress precede
        // beforeinput, the native edit, and input at the focused editing host.
        let html = r#"<div id=editor contenteditable><p id=line><br></p></div>
            <output id=events></output><script>
            const editor = document.getElementById('editor');
            const seen = [];
            for (const type of ['keydown','keypress','beforeinput','input'])
                editor.addEventListener(type, event => {
                    seen.push(type + ':' + (event.inputType || event.key));
                    document.getElementById('events').textContent = seen.join(',');
                });
            </script>"#;
        let editor = Dom::parse_document(html).get_by_id("editor").unwrap();
        let mut env = crate::js::PageEnv::bare(DEFAULT_URL);
        env.terminal_presentation = false;
        let (handle, mut events) = spawn_page(html.into(), env);
        tokio::time::timeout(Duration::from_secs(20), async {
            while !matches!(
                events.recv().await,
                Some(crate::js::PageEvt::Updated { .. })
            ) {}
            handle
                .cmds
                .send(crate::js::PageCmd::Focus(Some(editor)))
                .await
                .unwrap();
            handle
                .cmds
                .send(crate::js::PageCmd::Key {
                    node: None,
                    input: crate::core::KeyInput {
                        key: crate::core::Key::Character(String::from("x")),
                        code: String::from("KeyX"),
                        location: 0,
                        state: crate::core::KeyState::Pressed,
                        modifiers: Default::default(),
                        repeat: false,
                        composing: false,
                    },
                })
                .await
                .unwrap();
            let mut rendered = false;
            let mut caret = false;
            while !rendered || !caret {
                match events.recv().await {
                    Some(crate::js::PageEvt::Updated { html, outcome }) => {
                        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
                        if html.contains(
                            "keydown:x,keypress:x,beforeinput:insertText,input:insertText",
                        ) {
                            assert!(html.contains(">x<"), "{html}");
                            rendered = true;
                        }
                    }
                    Some(crate::js::PageEvt::EditableState(Some(state))) if state.text == "x" => {
                        assert_eq!(state.node, editor);
                        assert_eq!(state.selection.start, 1);
                        assert_eq!(state.selection.end, 1);
                        caret = true;
                    }
                    Some(crate::js::PageEvt::Trouble(errors)) => panic!("{errors:?}"),
                    Some(_) => {}
                    None => panic!("editing actor closed before input"),
                }
            }
        })
        .await
        .expect("editing host did not receive input");
    }

    #[test]
    fn selection_range_keeps_boundary_points_and_deletes_contained_nodes() {
        // DOM §4.2 and Selection API §3: scripts see the selected Range by
        // identity, and deletion removes fully contained siblings as well as
        // the selected parts of endpoint Text nodes.
        let mut engine = configured_engine(
            HostState::new(
                Rc::new(RefCell::new(Dom::parse_document(
                    "<div id=host><b>ab</b><em>cd</em><i>ef</i></div>",
                ))),
                Rc::new(RealmClock::new()),
            ),
            DEFAULT_URL,
        );
        assert_eq!(
            string_value(
                &mut engine,
                r#"
                const host = document.getElementById('host');
                const selection = getSelection();
                const range = document.createRange();
                range.setStart(host.firstChild.firstChild, 1);
                range.setEnd(host.lastChild.firstChild, 1);
                selection.addRange(range);
                const same = selection === document.getSelection() && selection.getRangeAt(0) === range;
                const containsMiddle = selection.containsNode(host.children[1]);
                const containsFirst = selection.containsNode(host.children[0]);
                const partialFirst = selection.containsNode(host.children[0], true);
                range.deleteContents();
                [same, containsMiddle, containsFirst, partialFirst, host.innerHTML,
                    range.collapsed, range.startContainer === host, range.startOffset].join('|');
                "#,
            ),
            "true|true|false|true|<b>a</b><i>f</i>|true|true|1"
        );
    }

    #[test]
    fn contenteditable_default_respects_beforeinput_cancellation_and_caret() {
        // Input Events 2 §6: cancellation leaves the DOM and selection alone;
        // a later deletion uses that same caret and dispatches input once.
        let mut engine = configured_engine(
            HostState::new(
                Rc::new(RefCell::new(Dom::parse_document(
                    "<div id=editor contenteditable>abc</div>",
                ))),
                Rc::new(RealmClock::new()),
            ),
            DEFAULT_URL,
        );
        assert_eq!(
            string_value(
                &mut engine,
                r#"
                const editor = document.getElementById('editor');
                const seen = [];
                editor.addEventListener('beforeinput', e => {
                    seen.push('before:' + e.inputType);
                    if (e.inputType === 'insertText') e.preventDefault();
                });
                editor.addEventListener('input', e => seen.push('input:' + e.inputType));
                __trust.focusPage(editor.__id);
                const selection = getSelection();
                selection.collapse(editor.firstChild, 2);
                const canceled = __trust.editableKeyDefault(null, 'x', false, false, false, false);
                const unchanged = editor.textContent === 'abc' && selection.anchorOffset === 2;
                const deleted = __trust.editableKeyDefault(null, 'Backspace', false, false, false, false);
                const afterDelete = selection.anchorOffset;
                const moved = __trust.editableKeyDefault(null, 'ArrowRight', false, false, false, false);
                __trust.editableKeyDefault(null, 'ArrowLeft', true, false, false, false);
                const selected = selection.toString();
                __trust.editableKeyDefault(null, 'ArrowRight', false, false, false, false);
                [canceled, unchanged, deleted, editor.textContent, afterDelete, moved,
                    selected, selection.anchorOffset,
                    seen.join(',')].join('|');
                "#,
            ),
            "true|true|true|ac|1|true|c|2|before:insertText,before:deleteContentBackward,input:deleteContentBackward"
        );
        assert_eq!(
            string_value(
                &mut engine,
                r#"
                const island = document.createElement('span');
                island.setAttribute('contenteditable', 'FALSE');
                island.textContent = 'protected';
                document.getElementById('editor').appendChild(island);
                [__trust.editableKeyDefault(island.__id, 'x', false, false, false, false),
                    island.textContent].join('|');
                "#,
            ),
            "false|protected"
        );
    }

