    #[test]
    #[ignore = "offline diagnostic; set TRUST_CAPTURE_SCRIPT_DOCUMENT"]
    fn captured_classic_script_error_diagnostic() {
        let html = std::fs::read_to_string(std::env::var("TRUST_CAPTURE_SCRIPT_DOCUMENT").unwrap())
            .unwrap();
        let mut dom = Dom::parse_document(&html);
        dom.set_viewport_px(1100.0, 824.0);
        let scripts = dom.scripts();
        let mut engine = configured_engine(
            HostState::new(Rc::new(RefCell::new(dom)), Rc::new(RealmClock::new())),
            DEFAULT_URL,
        );
        for (index, (src, source, ty, _node)) in scripts.into_iter().enumerate() {
            if src.is_some()
                || ty.as_deref().is_some_and(|ty| {
                    !matches!(ty, "" | "text/javascript" | "application/javascript")
                })
            {
                continue;
            }
            match engine.eval_value_interruptible(&source) {
                Ok(Err(EvalError::Throw(error))) => {
                    let stack = engine
                        .ctx()
                        .get_member(&error, "stack")
                        .unwrap_or(Value::Undefined);
                    eprintln!(
                        "script {index}: {}\n{}",
                        value_string(&mut engine, &error),
                        value_string(&mut engine, &stack)
                    );
                }
                Ok(Ok(_)) => eprintln!("script {index}: completed"),
                Ok(Err(error)) => eprintln!(
                    "script {index}: {}",
                    describe_eval_error(&mut engine, error, "diagnostic")
                ),
                Err(error) => eprintln!(
                    "script {index}: parse error {}:{}",
                    error.line, error.message
                ),
            }
        }
    }

    #[test]
    fn modal_pseudo_class_follows_dialog_is_modal() {
        // HTML #selector-modal with the dialog show/showModal/close and removing
        // steps (local WHATWG HTML e5071a20c856, 2026-09-06).
        for tier in [Tier::Interp, Tier::Bytecode, Tier::Jit] {
            let mut engine = configured_engine(
                HostState::new(
                    Rc::new(RefCell::new(Dom::parse_document(
                        "<!doctype html><html><body></body></html>",
                    ))),
                    Rc::new(RealmClock::new()),
                ),
                DEFAULT_URL,
            );
            engine.set_tier(tier);
            engine.set_tier_threshold(0);
            assert_eq!(
                string_value(
                    &mut engine,
                    r#"
                const dialog = document.createElement("dialog");
                document.body.appendChild(dialog);
                const states = [dialog.matches(":modal")];
                dialog.showModal();
                states.push(dialog.matches(":modal"), document.querySelector("dialog:modal") === dialog,
                    dialog.matches("[open]:not(:modal)"));
                dialog.showModal();
                dialog.close();
                states.push(dialog.matches(":modal"));
                dialog.show();
                states.push(dialog.matches(":modal"), dialog.matches("[open]:not(:modal)"));
                try { dialog.showModal(); } catch (error) { states.push(error.name); }
                dialog.close();
                dialog.showModal();
                dialog.remove();
                states.push(dialog.matches(":modal"));
                document.body.appendChild(dialog);
                states.push(dialog.open, dialog.matches(":modal"));
                try { document.querySelector(":modal(x)"); } catch (error) { states.push(error.name); }
                dialog.close();
                const holder = document.createElement("div");
                document.body.appendChild(holder);
                holder.appendChild(dialog);
                dialog.showModal();
                holder.innerHTML = "";
                states.push(dialog.matches(":modal"));
                states.join("|");
            "#
                ),
                "false|true|true|false|false|false|true|InvalidStateError|false|true|false|SyntaxError|false"
            );
        }
    }

    /// A Window realm over `html`, for the close request, dialog, popover and
    /// fullscreen conformance tests below.
    fn top_layer_engine(html: &str) -> lumen::Engine {
        configured_engine(
            HostState::new(
                Rc::new(RefCell::new(Dom::parse_document(html))),
                Rc::new(RealmClock::new()),
            ),
            DEFAULT_URL,
        )
    }

    #[test]
    fn close_watchers_group_without_activation_and_cancel_before_close() {
        // HTML #close-watcher-infrastructure (local WHATWG HTML e5071a20c856):
        // watchers created without an intervening user activation share one
        // group, so a single close request closes them all, newest first. Each
        // cancel is non-cancelable without history-action activation.
        let mut engine = top_layer_engine("<body><p>page</p></body>");
        assert_eq!(
            string_value(
                &mut engine,
                r#"
            const log = [];
            const a = new CloseWatcher();
            a.oncancel = (e) => log.push("a-cancel:" + e.cancelable);
            a.onclose = () => log.push("a-close");
            const b = new CloseWatcher();
            b.addEventListener("cancel", (e) => log.push("b-cancel:" + e.cancelable));
            b.addEventListener("close", () => log.push("b-close"));
            log.push(__trust.closeRequest());
            log.push(__trust.closeRequest());
            const aborted = new AbortController();
            const c = new CloseWatcher({signal: aborted.signal});
            c.onclose = () => log.push("c-close");
            aborted.abort();
            log.push(__trust.closeRequest());
            const d = new CloseWatcher();
            d.onclose = () => log.push("d-close");
            d.destroy();
            d.close();
            const e = new CloseWatcher();
            e.oncancel = () => log.push("e-cancel");
            e.onclose = () => log.push("e-close");
            e.close();
            try { new CloseWatcher(1); } catch (error) { log.push(error.name); }
            log.push(Object.prototype.toString.call(e), typeof CloseWatcher.prototype.requestClose);
            log.join("|");
        "#
            ),
            "b-cancel:false|b-close|a-cancel:false|a-close|true|false|false|e-close|TypeError|[object CloseWatcher]|function"
        );
    }

    #[test]
    fn close_requests_fire_keydown_and_need_history_action_activation_to_cancel() {
        // HTML #close-requests: the Escape keydown fires first and canceling it
        // consumes the request. A cancel event can prevent closing only with
        // history-action activation, which a prevented cancel consumes, so a
        // second request always closes (#close-watcher-request-close). Each
        // user activation allows one new group.
        let mut engine = top_layer_engine("<body><p>page</p></body>");
        assert_eq!(
            string_value(
                &mut engine,
                r#"
            const log = [];
            // A non-Escape keydown is an activation-triggering input event
            // (HTML #activation-triggering-input-event) without light dismiss.
            const activate = () => __trust.key(null, "a", "KeyA", false, false,
                false, false, false, false, false, 0);
            const w = new CloseWatcher();
            w.onclose = () => log.push("w-close");
            document.addEventListener("keydown", (e) => {
                if (e.key !== "Escape") return;
                log.push("keydown:" + e.isTrusted);
                if (log.length === 1) e.preventDefault();
            });
            log.push(__trust.closeRequest());
            log.push(__trust.closeRequest());
            const v = new CloseWatcher();
            v.oncancel = (e) => { log.push("cancel:" + e.cancelable); e.preventDefault(); };
            v.onclose = () => log.push("v-close");
            activate();
            v.requestClose();
            v.requestClose();
            const first = new CloseWatcher();
            first.onclose = () => log.push("first-close");
            activate();
            const second = new CloseWatcher();
            second.onclose = () => log.push("second-close");
            log.push(__trust.closeRequest());
            log.push(__trust.closeRequest());
            log.join("|");
        "#
            ),
            "keydown:true|true|keydown:true|w-close|true|cancel:true|cancel:false|v-close|keydown:true|second-close|true|keydown:true|first-close|true"
        );
    }

    #[test]
    fn modal_dialogs_answer_close_requests_by_closedby_and_request_close() {
        // HTML #the-dialog-element: showModal() establishes the dialog's close
        // watcher (closedBy auto → closerequest), a close request fires a
        // non-cancelable cancel and queues close; closedby=none disables it,
        // requestClose() ignores closedby and sets the return value. The
        // toggle events of one task coalesce (#queue-a-dialog-toggle-event-task).
        let mut engine = top_layer_engine("<body><dialog id=d><p>hi</p></dialog></body>");
        assert_eq!(
            string_value(
                &mut engine,
                r#"
            const d = document.getElementById("d");
            const log = [];
            d.addEventListener("cancel", (e) => log.push("cancel:" + e.cancelable));
            d.addEventListener("close", () => log.push("close:" + d.returnValue));
            d.addEventListener("toggle", (e) => log.push("toggle:" + e.oldState + ">" + e.newState));
            log.push(d.closedBy);
            d.showModal();
            log.push(d.closedBy, d.matches(":modal"));
            log.push(__trust.closeRequest());
            while (__trust.hasPlatformTask()) __trust.runPlatformTask();
            log.push(d.open);
            d.setAttribute("closedby", "none");
            d.showModal();
            log.push(d.closedBy, __trust.closeRequest(), d.open);
            d.requestClose("r");
            while (__trust.hasPlatformTask()) __trust.runPlatformTask();
            log.push(d.open);
            d.closedBy = "ANY";
            log.push(d.getAttribute("closedby"), d.closedBy);
            d.show();
            log.push(d.matches(":modal"), __trust.closeRequest(), d.open);
            while (__trust.hasPlatformTask()) __trust.runPlatformTask();
            log.join("|");
        "#
            ),
            "none|closerequest|true|cancel:false|true|toggle:closed>closed|close:|false|none|false|true|cancel:false|toggle:closed>closed|close:r|false|ANY|any|cancel:false|false|true|false|toggle:closed>closed|close:r"
        );
    }

    #[test]
    fn modal_dialog_makes_the_document_inert_and_restores_focus() {
        // HTML #modal-dialogs-and-inert-subtrees: while a modal dialog blocks
        // its Document, nodes outside it are inert and unfocusable, and the
        // dialog focusing steps focus its first sequentially focusable
        // descendant; closing it refocuses the previously focused element.
        let mut engine = top_layer_engine(
            "<body><button id=outside>out</button>\
             <dialog id=d><p>text</p><button id=inside>in</button></dialog></body>",
        );
        assert_eq!(
            string_value(
                &mut engine,
                r#"
            const outside = document.getElementById("outside");
            const inside = document.getElementById("inside");
            const d = document.getElementById("d");
            const log = [];
            outside.focus();
            log.push(document.activeElement === outside);
            d.showModal();
            log.push(document.activeElement === inside);
            outside.focus();
            log.push(document.activeElement === inside);
            d.close();
            log.push(document.activeElement === outside);
            d.show();
            log.push(document.activeElement === inside);
            outside.focus();
            log.push(document.activeElement === outside);
            log.join("|");
        "#
            ),
            "true|true|true|true|true|true"
        );
    }

    #[test]
    fn autofocus_candidates_flush_at_the_rendering_update() {
        // HTML #the-autofocus-attribute and #flush-autofocus-candidates (local whatwg/html
        // e5071a20): parser- and script-inserted autofocus elements become the top-level
        // Document's candidates; the rendering update focuses the first that is a focusable
        // area and sets the autofocus processed flag, after which insertions are ignored.
        let mut engine = top_layer_engine(
            "<body><input id=hidden autofocus style='display:none'>\
             <input id=first autofocus><input id=second autofocus></body>",
        );
        assert_eq!(
            string_value(
                &mut engine,
                r#"
            const log = [];
            log.push(document.activeElement === document.body, __trust.hasRenderingUpdate());
            __trust.runRenderingFrame(performance.now());
            log.push(document.activeElement.id, __trust.hasRenderingUpdate());
            const late = document.createElement("input");
            late.autofocus = true;
            document.body.append(late);
            log.push(__trust.hasRenderingUpdate());
            __trust.runRenderingFrame(performance.now());
            log.push(document.activeElement.id);
            log.join("|");
        "#
            ),
            "true|true|first|false|false|first"
        );
    }

    #[test]
    fn autofocus_insertion_steps_follow_insertion_into_a_document() {
        // HTML #the-autofocus-attribute: only insertion into a document tree adds a candidate
        // (an attribute set on a connected element, a detached or shadow tree, a moveBefore()
        // move or a Document without a browsing context does not); the latest insertion of an
        // element moves it to the end, and innerHTML insertion counts.
        let mut engine = top_layer_engine("<body><div id=box></div><div id=host></div></body>");
        assert_eq!(
            string_value(
                &mut engine,
                r#"
            const log = [];
            const box = document.getElementById("box");
            const flush = () => {
                const pending = __trust.hasRenderingUpdate();
                __trust.runRenderingFrame(performance.now());
                return pending;
            };
            const connected = document.createElement("button");
            document.body.append(connected);
            connected.autofocus = true;
            const detached = document.createElement("div");
            detached.innerHTML = "<input autofocus>";
            const root = document.getElementById("host").attachShadow({ mode: "open" });
            root.innerHTML = "<input autofocus>";
            new DOMParser().parseFromString("<input autofocus>", "text/html");
            const other = document.implementation.createHTMLDocument("");
            other.body.innerHTML = "<input autofocus>";
            box.moveBefore(connected, null);
            log.push(flush(), document.activeElement === document.body);
            box.innerHTML = "<textarea id=a autofocus></textarea><select id=b autofocus><option>x</option></select>";
            const a = document.getElementById("a");
            document.body.append(a);
            log.push(flush(), document.activeElement.id);
            log.join("|");
        "#
            ),
            "false|true|true|b"
        );
    }

    #[test]
    fn autofocus_is_skipped_once_focus_or_a_dialog_has_moved_it() {
        // HTML #flush-autofocus-candidates step 4: a focused area other than the Document
        // empties the candidates; the dialog focusing steps set the autofocus processed flag
        // (#dialog-focusing-steps steps 7-10).
        let mut engine = top_layer_engine(
            "<body><input id=auto autofocus><button id=other>o</button>\
             <dialog id=d><input id=inner autofocus></dialog></body>",
        );
        assert_eq!(
            string_value(
                &mut engine,
                r#"
            const log = [];
            document.getElementById("other").focus();
            __trust.runRenderingFrame(performance.now());
            log.push(document.activeElement.id);
            document.getElementById("other").blur();
            const late = document.createElement("input");
            late.id = "late";
            late.autofocus = true;
            document.body.append(late);
            log.push(__trust.hasRenderingUpdate());
            log.join("|");
        "#
            ),
            "other|false"
        );
        let mut engine = top_layer_engine(
            "<body><input id=auto autofocus><dialog id=d><input id=inner autofocus></dialog></body>",
        );
        assert_eq!(
            string_value(
                &mut engine,
                r#"
            const d = document.getElementById("d");
            d.show();
            const focused = document.activeElement.id;
            __trust.runRenderingFrame(performance.now());
            [focused, document.activeElement.id, __trust.hasRenderingUpdate()].join("|");
        "#
            ),
            "inner|inner|false"
        );
    }

