    #[test]
    fn url_static_parsers_follow_url_standard_in_windows_and_workers() {
        for worker in [false, true] {
            let mut engine = configured_engine_before_prelude(
                HostState::new(
                    Rc::new(RefCell::new(Dom::new())),
                    Rc::new(RealmClock::new()),
                ),
                DEFAULT_URL,
            );
            eval_test_bootstrap(
                &mut engine,
                if worker {
                    crate::js::worker_prelude()
                } else {
                    crate::js::PRELUDE
                },
                "URL prelude",
                worker,
            )
            .unwrap();
            assert_eq!(
                string_value(
                    &mut engine,
                    r#"(() => {
                const check = (v, message) => { if (!v) throw Error(message); };
                const parse = URL.parse, canParse = URL.canParse;
                check(parse.length === 1 && canParse.length === 1, 'optional base arity');
                const url = parse.call(null, '../login?next=home', 'https://example.test/account/');
                check(url instanceof URL && url.href === 'https://example.test/login?next=home', 'relative parsing');
                url.searchParams.set('next', 'settings');
                check(url.href.endsWith('?next=settings'), 'live query');
                url.search = '?ok=yes';
                check(url.searchParams.get('ok') === 'yes', 'live parameters');
                check(parse('relative') === null && !canParse('relative'), 'invalid input');
                check(parse('https://example.test/', null) === null, 'null base is a string');
                check(!canParse('https://example.test/', 'invalid'), 'invalid base checked first');
                check(canParse('https://example.test/', undefined), 'omitted base');
                check(parse('https://example.test/\ud800').pathname === '/%EF%BF%BD', 'USVString conversion');
                for (const method of [parse, canParse]) {
                    for (const args of [[], [Symbol()], ['https://example.test/', Symbol()]]) {
                        let threw = false;
                        try { method(...args); } catch(e) { threw = e instanceof TypeError; }
                        check(threw, 'argument conversion');
                    }
                    const sentinel = {};
                    let threw = false;
                    try { method('invalid', {toString(){throw sentinel;}}); } catch(e) { threw = e === sentinel; }
                    check(threw, 'conversion errors must propagate');
                }
                class Derived extends URL {}
                check(!(Derived.parse('https://example.test/') instanceof Derived), 'new URL object');
                return 'url-static-ok';
            })()"#
                ),
                "url-static-ok",
                "worker={worker}"
            );
        }
    }

    #[test]
    fn url_search_params_and_setters_follow_url_standard_in_windows_and_workers() {
        // URL Standard §5 (urlencoded parsing/serializing) and §6 (URL and
        // URLSearchParams, local whatwg/url@55d6699), with Web IDL's union,
        // record, iterable and interface-object rules. Window and Worker
        // realms share one implementation.
        for worker in [false, true] {
            let mut engine = configured_engine_before_prelude(
                HostState::new(
                    Rc::new(RefCell::new(Dom::new())),
                    Rc::new(RealmClock::new()),
                ),
                DEFAULT_URL,
            );
            eval_test_bootstrap(
                &mut engine,
                if worker {
                    crate::js::worker_prelude()
                } else {
                    crate::js::PRELUDE
                },
                "URL prelude",
                worker,
            )
            .unwrap();
            assert_eq!(
                string_value(
                    &mut engine,
                    r#"(() => {
                const check = (v, message) => { if (!v) throw Error(message); };
                const throwsType = (f, message) => {
                    let threw = false;
                    try { f(); } catch (e) { threw = e instanceof TypeError; }
                    check(threw, message);
                };
                // Parsing: "+" before percent-decoding, bytes kept for
                // invalid escapes, U+FFFD for invalid UTF-8.
                const parsed = new URLSearchParams('?b=%2sf%2a&c=%C2x&d=a+b%2B&%FE%FF');
                check(parsed.get('b') === '%2sf*' && parsed.get('c') === '�x', 'percent-decoding');
                check(parsed.get('d') === 'a b+' && parsed.has('��'), 'plus and invalid UTF-8');
                check(parsed.toString() === 'b=%252sf*&c=%EF%BF%BDx&d=a+b%2B&%EF%BF%BD%EF%BF%BD=', 'serializer');
                check(new URLSearchParams('a=~!\'() é').toString() === 'a=%7E%21%27%28%29+%C3%A9', 'encode set');
                // set() keeps the first tuple's position; two-argument has/delete.
                const params = new URLSearchParams('a=b&c=d&a=e');
                params.set('a', 'B');
                check(params.toString() === 'a=B&c=d', 'set in place');
                params.append('c', 'x');
                check(params.has('c', 'x') && !params.has('c', 'y') && params.has('c', undefined), 'has(name, value)');
                params.delete('c', 'd');
                check(params.toString() === 'a=B&c=x', 'delete(name, value)');
                params.delete('c', undefined);
                check(params.toString() === 'a=B' && params.size === 1, 'delete(name)');
                // Union conversion: sequences, records, strings.
                throwsType(() => new URLSearchParams([['a']]), 'pair length');
                throwsType(() => new URLSearchParams([1]), 'pair must be iterable');
                check(new URLSearchParams(null).toString() === 'null=', 'null is a string');
                const record = new URLSearchParams({'\uD835x': '1', xx: '2', '\uD83Dx': '3'});
                check([...record].join(';') === '�x,3;xx,2', 'record keys');
                const custom = new URLSearchParams('z=1');
                custom[Symbol.iterator] = function* () { yield ['a', 'b']; };
                check(new URLSearchParams(custom).get('a') === 'b', 'custom iterator');
                const constants = new URLSearchParams(Object.assign(function () {}, {k: 'v'}));
                check(constants.get('k') === 'v', 'a function is a record');
                throwsType(() => params.append('a'), 'required arguments');
                throwsType(() => URLSearchParams.prototype.get.call({}, 'a'), 'brand check');
                // Live iteration over the URL's query object.
                const url = new URL('http://a.b/c?a=1&b=2&c=3');
                const seen = [];
                for (const pair of url.searchParams) { url.search = 'x=1&y=2&z=3'; seen.push(pair.join('=')); }
                check(seen.join() === 'a=1,y=2,z=3', 'live iterator: ' + seen.join());
                const iterator = url.searchParams.keys();
                check(Object.prototype.toString.call(iterator) === '[object URLSearchParams Iterator]', 'iterator tag');
                check(iterator.next().value === 'x' && [...url.searchParams.values()].join() === '1,2,3', 'keys/values');
                url.searchParams.delete('x');
                url.searchParams.delete('y');
                url.searchParams.delete('z');
                check(url.href === 'http://a.b/c', 'empty query becomes null');
                // URL setters run each component's state override.
                const u = new URL('http://example.net/path?q#h');
                u.protocol = 'https:foo : bar';
                u.port = '8080stuff';
                u.username = 'me';
                check(u.href === 'https://me@example.net:8080/path?q#h', 'setters: ' + u.href);
                u.search = '?'; u.hash = '#';
                check(u.search === '' && u.hash === '' && u.href === 'https://me@example.net:8080/path?#', 'empty query and fragment');
                const file = new URL('file:///home/you');
                file.username = 'me'; file.port = '1';
                check(file.href === 'file:///home/you', 'file URLs have no credentials or port');
                const erased = new URL('foo:///some/path');
                erased.pathname = '';
                check(erased.href === 'foo://' && erased.pathname === '', 'empty host path erased: ' + erased.href);
                check(new URL('blob:blob:https://example.org/').origin === 'null', 'blob origin');
                check(new URL('blob:https://example.org/x').origin === 'https://example.org', 'blob tuple origin');
                // Web IDL interface shape.
                const global = Object.getOwnPropertyDescriptor(globalThis, 'URLSearchParams');
                check(!global.enumerable && global.writable && global.configurable, 'interface object');
                check(URL.length === 1 && URLSearchParams.length === 0, 'constructor lengths');
                check(Object.getOwnPropertyDescriptor(URLSearchParams.prototype, 'append').enumerable &&
                    Object.getOwnPropertyDescriptor(URL.prototype, 'href').enumerable &&
                    Object.getOwnPropertyDescriptor(URL, 'canParse').enumerable, 'enumerable members');
                check(URLSearchParams.prototype[Symbol.iterator] === URLSearchParams.prototype.entries, '@@iterator');
                check((typeof webkitURL === 'undefined') === (typeof document === 'undefined'), 'webkitURL on Window only');
                return 'url-search-params-ok';
            })()"#
                ),
                "url-search-params-ok",
                "worker={worker}"
            );
        }
    }

    #[test]
    fn text_decoder_supports_every_encoding_in_windows_and_workers() {
        // Encoding Standard §4.2 labels and §7.2 TextDecoder (local
        // whatwg/encoding@a985b62): legacy single- and multi-byte decoders,
        // streaming state, fatal mode, BOM handling and Web IDL conversions,
        // in both realm kinds.
        for worker in [false, true] {
            let mut engine = configured_engine_before_prelude(
                HostState::new(
                    Rc::new(RefCell::new(Dom::new())),
                    Rc::new(RealmClock::new()),
                ),
                DEFAULT_URL,
            );
            eval_test_bootstrap(
                &mut engine,
                if worker {
                    crate::js::worker_prelude()
                } else {
                    crate::js::PRELUDE
                },
                "text codec prelude",
                worker,
            )
            .unwrap();
            assert_eq!(
                string_value(
                    &mut engine,
                    r#"(() => {
                const check = (v, message) => { if (!v) throw Error(message); };
                const throwsType = (f, message) => {
                    let threw = false;
                    try { f(); } catch (e) { threw = e instanceof TypeError; }
                    check(threw, message);
                };
                const bytes = (...values) => new Uint8Array(values);
                check(new TextDecoder(' Shift_JIS ').encoding === 'shift_jis', 'label lookup');
                check(new TextDecoder('latin1').encoding === 'windows-1252', 'latin1 is windows-1252');
                for (const label of ['iso-2022-kr', 'utf-7', 'bogus']) {
                    let threw = false;
                    try { new TextDecoder(label); } catch (e) { threw = e instanceof RangeError; }
                    check(threw, 'invalid label ' + label);
                }
                check(new TextDecoder('shift_jis').decode(bytes(0x82, 0xa0, 0x41)) === 'あA', 'shift_jis');
                check(new TextDecoder('euc-kr').decode(bytes(0xb0, 0xa1)) === '가', 'euc-kr');
                check(new TextDecoder('gbk').decode(bytes(0xc4, 0xe3)) === '你', 'gbk');
                check(new TextDecoder('big5').decode(bytes(0xa4, 0x40)) === '一', 'big5');
                check(new TextDecoder('koi8-r').decode(bytes(0xc1)) === 'а', 'koi8-r');
                check(new TextDecoder('windows-1252').decode(bytes(0x80, 0xe9)) === '€é', 'windows-1252');
                // Streaming keeps decoder state, including ISO-2022-JP's mode.
                const jis = new TextDecoder('iso-2022-jp');
                check(jis.decode(bytes(0x1b, 0x28, 0x49), {stream: true}) === '', 'escape sequence');
                check(jis.decode(bytes(0x31)) === 'ｱ', 'katakana mode persists');
                const sjis = new TextDecoder('shift_jis');
                check(sjis.decode(bytes(0x82), {stream: true}) + sjis.decode(bytes(0xa0)) === 'あ', 'split lead byte');
                check(new TextDecoder('shift_jis').decode(bytes(0x82)) === '�', 'truncated at end-of-queue');
                throwsType(() => new TextDecoder('shift_jis', {fatal: true}).decode(bytes(0x82)), 'fatal');
                // UTF-16: only a BOM of the decoder's own byte order is removed.
                check(new TextDecoder('utf-16le').decode(bytes(0xff, 0xfe, 0x41, 0)) === 'A', 'utf-16le BOM');
                check(new TextDecoder('utf-16be').decode(bytes(0xdb, 0xff, 0xdf, 0xfd, 0, 0x41)) === '\u{10fffd}A',
                    'plane-16 private use characters');
                check(new TextDecoder('utf-16le').decode(bytes(0xfe, 0xff, 0x41, 0)) === '￾A', 'no byte-order switch');
                check(new TextDecoder('utf-16be', {ignoreBOM: true}).decode(bytes(0xfe, 0xff, 0, 0x41)) === '﻿A', 'ignoreBOM');
                const utf8 = new TextDecoder();
                check(utf8.decode(bytes(0xef, 0xbb), {stream: true}) === '' && utf8.decode(bytes(0xbf, 0x41)) === 'A', 'UTF-8 BOM split');
                check(new TextDecoder().decode(new DataView(bytes(0x61, 0x62).buffer, 1)) === 'b', 'DataView input');
                throwsType(() => new TextDecoder().decode([0x61]), 'arrays are not buffer sources');
                throwsType(() => new TextDecoder('utf-8', 1), 'options must be a dictionary');
                throwsType(() => TextDecoder.prototype.decode.call({}), 'brand check');
                const encoder = new TextEncoder();
                check(encoder.encode('\ud800').join() === '239,191,189', 'USVString encode');
                const into = encoder.encodeInto('aé', new Uint8Array(2));
                check(into.read === 1 && into.written === 1, 'encodeInto stops before a partial scalar value');
                const global = Object.getOwnPropertyDescriptor(globalThis, 'TextDecoder');
                check(!global.enumerable && Object.getOwnPropertyDescriptor(TextDecoder.prototype, 'decode').enumerable,
                    'Web IDL shape');
                return 'text-codec-ok';
            })()"#
                ),
                "text-codec-ok",
                "worker={worker}"
            );
        }
    }

    #[test]
    fn document_forms_is_a_live_named_html_collection() {
        let mut engine = configured_engine(
            HostState::new(
                Rc::new(RefCell::new(Dom::parse_document(
                    r#"<!doctype html>
                <form id=challenge><input name=id><input name=getAttribute></form>
                <form name=challenge></form><div id=host><template shadowrootmode=open>
                <form id=hidden></form></template></div>"#,
                ))),
                Rc::new(RealmClock::new()),
            ),
            DEFAULT_URL,
        );
        assert_eq!(
            string_value(
                &mut engine,
                r#"(() => {
            const check = (v, message) => { if (!v) throw Error(message); };
            const forms = document.forms, first = forms[0], second = forms[1];
            check(forms === document.forms && forms instanceof HTMLCollection, 'SameObject HTMLCollection');
            check(forms.length === 2 && forms.hidden === undefined, 'document scope');
            check(forms.challenge === first && forms.namedItem('challenge') === first, 'ID before later name');
            check(Object.getOwnPropertyDescriptor(forms, 'challenge').enumerable === false, 'named property');
            first.remove();
            check(forms.length === 1 && forms.challenge === second, 'live removal');
            const extra = document.createElement('form');
            extra.name = 'newForm'; document.body.appendChild(extra);
            check(forms.newForm === extra && forms.length === 2, 'live insertion');
            extra.name = 'renamed';
            check(forms.newForm === undefined && forms.renamed === extra, 'live name change');
            check(forms.item(99) === null && forms.namedItem('missing') === null, 'absent items');
            return 'document-forms-ok';
        })()"#
            ),
            "document-forms-ok"
        );
    }

