    /// Every name the platform has ever kept on an author-visible global.
    const FORMER_GLOBAL_INTERNALS: &[&str] = &[
        "$262",
        "ShadowRealm",
        "__trust",
        "__trust_cfg",
        "__worker_cfg",
        "__wkr",
        "__trust_install_webgl",
        "__sc_serialize",
        "__sc_deserialize",
        "__viewportRect",
        "__wasm_make_func",
        "__wasm_extern_intern",
        "__wasm_extern_get",
        "__wasm_invoke_import",
        "__wasm_import_results",
        "__image_complete",
    ];

    /// The `typeof` of each host binding and former internal global, as one string.
    fn author_global_internals_probe() -> String {
        let names: Vec<_> = crate::js::host_boundary_signatures()
            .map(|(name, _)| name)
            .chain(FORMER_GLOBAL_INTERNALS.iter().copied())
            .collect();
        format!(
            r#"(names => {{
                const leaked = [];
                for (const key of Reflect.ownKeys(globalThis))
                    if (typeof key === "string" && (key.startsWith("__") || key === "$262")) leaked.push(key);
                for (const name of names)
                    if (name in globalThis || (0, eval)("typeof " + name) !== "undefined") leaked.push(name);
                return leaked.join() || "none";
            }})({})"#,
            serde_json::to_string(&names).unwrap()
        )
    }

    #[test]
    fn host_bindings_and_platform_internals_are_unreachable_from_author_globals() {
        // HTML #origin and #windowproxy: author script receives only the Web-exposed global
        // surface. The TRust host boundary, the platform's control object/configuration and
        // the engine's Test262 host object stay private to the bootstrap and the native host,
        // in the top-level Window, a child Window Realm and a dedicated worker.
        let mut engine = configured_engine_before_prelude(
            HostState::new(
                Rc::new(RefCell::new(Dom::new())),
                Rc::new(RealmClock::new()),
            ),
            DEFAULT_URL,
        );
        engine
            .ctx()
            .host_mut::<HostState>()
            .unwrap()
            .test_hooks
            .internals = false;
        eval_platform_prelude(&mut engine).unwrap();
        let probe = author_global_internals_probe();
        assert_eq!(
            string_value(&mut engine, &probe),
            "none",
            "top-level Window"
        );
        eval(
            &mut engine,
            r#"
            const html = document.createElement('html'), body = document.createElement('body');
            document.appendChild(html); html.appendChild(body);
            globalThis.frame = document.createElement('iframe');
            frame.srcdoc = '<p id=child>child</p>';
            body.appendChild(frame);
            "#,
            "child Window setup",
        )
        .unwrap();
        call_trust_method(&mut engine, "hydrateFrames", &[]);
        assert_eq!(
            string_value(
                &mut engine,
                &format!(
                    "frame.contentWindow.eval({})",
                    serde_json::to_string(&probe).unwrap()
                )
            ),
            "none",
            "child Window Realm"
        );
        assert_eq!(
            string_value(
                &mut engine,
                "frame.contentDocument.getElementById('child').textContent"
            ),
            "child",
            "the private platform still serves same-origin author code"
        );
        // The native host keeps its retained handle to each Realm's control object.
        assert!(matches!(platform_control(engine.ctx()), Ok(Value::Obj(_))));

        let mut worker = worker_platform_engine_with(false);
        assert_eq!(
            string_value(&mut worker, &probe),
            "none",
            "dedicated worker"
        );
        // WorkerGlobalScope has no print(); the engine's Test262 hook is removed too.
        assert_eq!(string_value(&mut worker, "typeof print"), "undefined");
        // Platform frames are strict: an author callback cannot reach them, or their
        // arguments, through the legacy Function.prototype.caller extension.
        let caller_probe = "(() => { let seen = 'unset'; function listener() { seen = String(listener.caller); } \
            addEventListener('probe', listener); dispatchEvent(new Event('probe')); return seen; })()";
        assert_eq!(string_value(&mut worker, caller_probe), "null", "worker");
        assert_eq!(string_value(&mut engine, caller_probe), "null", "Window");
        assert!(matches!(platform_control(worker.ctx()), Ok(Value::Obj(_))));
    }

    /// A production-configured top-level Window: no test internals are republished.
    fn sealed_platform_engine(url: &str) -> lumen::Engine {
        let mut engine = configured_engine_before_prelude(
            HostState::new(
                Rc::new(RefCell::new(Dom::new())),
                Rc::new(RealmClock::new()),
            ),
            url,
        );
        engine
            .ctx()
            .host_mut::<HostState>()
            .unwrap()
            .test_hooks
            .internals = false;
        eval_platform_prelude(&mut engine).unwrap();
        engine
    }

    #[test]
    fn cross_origin_frame_realm_is_unreachable_through_wrapper_internals() {
        // HTML #origin / #cross-origin-objects: an embedding page must not obtain a
        // cross-origin child's Window, Document or nodes. TRust shares one DOM arena and one
        // Agent between the Realms, so wrapper internals (node ids, the container's child
        // Window/Document, its URL) must be internal slots, not author-visible properties.
        let mut engine = sealed_platform_engine("https://top.example/");
        eval(
            &mut engine,
            r#"
            const html = document.createElement('html'), body = document.createElement('body');
            document.appendChild(html); html.appendChild(body);
            globalThis.frame = document.createElement('iframe');
            frame.src = 'data:text/html,<p id=secret>CROSS-ORIGIN-SECRET</p>';
            body.appendChild(frame);
            "#,
            "cross-origin frame setup",
        )
        .unwrap();
        call_trust_method(&mut engine, "hydrateFrames", &[]);
        let child = {
            let state = engine.ctx().host_mut::<HostState>().unwrap();
            let newest = *state
                .window_realms
                .keys()
                .max()
                .expect("child Window Realm");
            state.window_realms[&newest].clone()
        };
        let mut read = |object: &Value, name: &str| {
            engine
                .ctx()
                .member_get(object, name)
                .unwrap_or_else(|_| panic!("read {name}"))
        };
        let child_document = read(&child, "document");
        let child_secret = read(&child_document, "documentElement");
        let outer = read(&child_secret, "outerHTML");
        assert!(
            value_string(&mut engine, &outer).contains("CROSS-ORIGIN-SECRET"),
            "the child Realm loaded its own document"
        );
        assert_eq!(
            string_value(
                &mut engine,
                r#"(() => {
                    const leaks = [];
                    if (frame.contentDocument !== null) leaks.push('contentDocument');
                    if (frame.contentWindow.document !== null) leaks.push('contentWindow.document');
                    const internal = ['__id', '__contentRealmWindow', '__contentDoc', '__contentWin',
                        '__frameUrl', '__frame', '__trustParentWindow', '__trustTopWindow', '__sr'];
                    for (const object of [globalThis, document, document.documentElement, frame,
                        frame.contentWindow])
                        for (const key of internal)
                            if (key in object) leaks.push(key);
                    return leaks.join() || 'sealed';
                })()"#
            ),
            "sealed"
        );
        // Identity check: the child global, Document and root element are not reachable
        // through any own data property of the page-visible objects, transitively.
        eval(
            &mut engine,
            r#"globalThis.reaches = function (...secrets) {
                const seen = new Set(), queue = [[globalThis, 0], [document, 0], [frame, 0],
                    [frame.contentWindow, 0]];
                while (queue.length) {
                    const [value, depth] = queue.shift();
                    if (value === null || (typeof value !== 'object' && typeof value !== 'function')
                        || seen.has(value)) continue;
                    seen.add(value);
                    if (secrets.includes(value)) return true;
                    if (depth === 4) continue;
                    for (const key of Reflect.ownKeys(value)) {
                        const descriptor = Reflect.getOwnPropertyDescriptor(value, key);
                        if (descriptor && 'value' in descriptor) queue.push([descriptor.value, depth + 1]);
                    }
                }
                return false;
            };"#,
            "reachability probe",
        )
        .unwrap();
        let global = engine.global_this();
        let reaches = engine
            .ctx()
            .member_get(&global, "reaches")
            .unwrap_or_else(|_| panic!("read reaches"));
        let reached = engine
            .call_function(
                &reaches,
                Value::Undefined,
                &[child, child_document, child_secret],
            )
            .unwrap_or_else(|_| panic!("reachability probe threw"));
        assert!(
            matches!(reached, Value::Bool(false)),
            "child Realm reachable"
        );
    }

    #[test]
    fn dom_host_operations_refuse_nodes_of_cross_origin_documents() {
        // Defense in depth below the private prelude (HTML #same-origin-domain): a Window
        // Realm's DOM host operations act only on nodes whose Document is same origin-domain
        // with it, whatever node id reaches the boundary. Containers stay administrable.
        let mut engine = sealed_platform_engine("https://top.example/");
        eval(
            &mut engine,
            r#"
            const html = document.createElement('html'), body = document.createElement('body');
            document.appendChild(html); html.appendChild(body);
            body.appendChild(document.createElement('p')).textContent = 'TOP-SECRET';
            const cross = document.createElement('iframe');
            cross.src = 'data:text/html,<p>CROSS-SECRET</p>';
            const same = document.createElement('iframe');
            same.srcdoc = '<p>SAME-TEXT</p>';
            body.append(cross, same);
            "#,
            "frame setup",
        )
        .unwrap_or_else(|_| panic!("host operation threw"));
        call_trust_method(&mut engine, "hydrateFrames", &[]);
        let (frames, documents, realms) = {
            let state = engine.ctx().host_mut::<HostState>().unwrap();
            let dom = state.dom.clone();
            let dom = dom.borrow();
            let frames: Vec<usize> = dom
                .descendants(DOCUMENT)
                .filter(|&node| dom.tag_name(node) == Some("iframe"))
                .collect();
            let documents: Vec<usize> = frames
                .iter()
                .map(|&frame| dom.frame_document(frame).expect("child Document"))
                .collect();
            let realms: Vec<Value> = frames
                .iter()
                .map(|frame| state.window_realms[&state.frame_contexts[frame]].clone())
                .collect();
            (frames, documents, realms)
        };
        let id = |node: usize| Value::Num(node as f64);
        let serialize = |engine: &mut lumen::Engine, node: usize| {
            let value = guarded_outer_html(engine.ctx(), Value::Undefined, &[id(node)])
                .unwrap_or_else(|_| panic!("outerHTML threw"));
            value_string(engine, &value)
        };
        // The embedding Window cannot read its cross-origin child's Document...
        assert!(!serialize(&mut engine, documents[0]).contains("CROSS-SECRET"));
        // ...but reads a same-origin child's, and administers both containers.
        assert!(serialize(&mut engine, documents[1]).contains("SAME-TEXT"));
        let src = guarded_get_attr(
            engine.ctx(),
            Value::Undefined,
            &[id(frames[0]), Value::from_string("src".into())],
        )
        .unwrap_or_else(|_| panic!("host operation threw"));
        assert!(value_string(&mut engine, &src).starts_with("data:"));

        let cross_reads = engine
            .with_embed_realm(&realms[0], |engine| {
                let top = serialize(engine, DOCUMENT);
                let own = serialize(engine, documents[0]);
                let sibling = serialize(engine, documents[1]);
                let container = guarded_get_attr(
                    engine.ctx(),
                    Value::Undefined,
                    &[id(frames[0]), Value::from_string("src".into())],
                )
                .unwrap_or_else(|_| panic!("host operation threw"));
                let container = value_string(engine, &container);
                let created = guarded_create_element(
                    engine.ctx(),
                    Value::Undefined,
                    &[Value::from_string("p".into()), id(DOCUMENT)],
                )
                .is_err();
                let by_id = guarded_get_by_id(
                    engine.ctx(),
                    Value::Undefined,
                    &[Value::from_string("x".into())],
                )
                .unwrap_or_else(|_| panic!("host operation threw"));
                (
                    top,
                    own,
                    sibling,
                    container,
                    created,
                    matches!(by_id, Value::Null),
                )
            })
            .unwrap_or_else(|_| panic!("enter the cross-origin child Realm"));
        assert!(
            !cross_reads.0.contains("TOP-SECRET"),
            "child read its embedder"
        );
        assert!(
            cross_reads.1.contains("CROSS-SECRET"),
            "child reads its own Document"
        );
        assert!(
            !cross_reads.2.contains("SAME-TEXT"),
            "child read a cross-origin sibling"
        );
        assert!(
            cross_reads.3.starts_with("data:"),
            "child administers its container"
        );
        assert!(
            cross_reads.4,
            "creation in a cross-origin Document is refused"
        );
        assert!(cross_reads.5, "top-level Document lookups are refused");

        let same_reads = engine
            .with_embed_realm(&realms[1], |engine| serialize(engine, DOCUMENT))
            .unwrap_or_else(|_| panic!("enter the same-origin child Realm"));
        assert!(
            same_reads.contains("TOP-SECRET"),
            "same-origin child reads its embedder"
        );

        // The embedder may detach the cross-origin child Document (destroying the navigable),
        // but not a node inside it.
        let inner = {
            let state = engine.ctx().host_mut::<HostState>().unwrap();
            let dom = state.dom.borrow();
            dom.descendants(documents[0])
                .find(|&node| dom.tag_name(node) == Some("p"))
                .expect("child paragraph")
        };
        assert!(guarded_detach(engine.ctx(), Value::Undefined, &[id(inner)]).is_ok());
        assert!(serialize_native(&mut engine, documents[0]).contains("CROSS-SECRET"));
        assert!(guarded_detach(engine.ctx(), Value::Undefined, &[id(documents[0])]).is_ok());
        let state = engine.ctx().host_mut::<HostState>().unwrap();
        assert_eq!(state.dom.borrow().node(documents[0]).parent, None);
    }

    #[test]
    fn cross_origin_children_reach_ancestors_only_through_cross_origin_window_proxies() {
        // HTML #cross-origin-objects / #dom-frameelement / #sandboxed-origin-browsing-
        // context-flag: a child of another origin, including a sandboxed child without
        // allow-same-origin, sees its ancestors only through CrossOriginProperties.
        let mut engine = sealed_platform_engine("https://top.example/");
        eval(
            &mut engine,
            r#"
            const html = document.createElement('html'), body = document.createElement('body');
            document.appendChild(html); html.appendChild(body);
            body.appendChild(document.createElement('p')).textContent = 'TOP-SECRET';
            globalThis.received = [];
            addEventListener('message', event => received.push(event));
            for (const [name, attributes] of [
                ['cross', {src: 'data:text/html,<p>cross</p>'}],
                ['sandboxed', {sandbox: 'allow-scripts', srcdoc: '<p>sandboxed</p>'}],
                ['same', {srcdoc: '<p>same</p>'}],
            ]) {
                const frame = document.createElement('iframe');
                frame.name = name;
                for (const [key, value] of Object.entries(attributes)) frame.setAttribute(key, value);
                body.appendChild(frame);
            }
            "#,
            "frame setup",
        )
        .unwrap();
        call_trust_method(&mut engine, "hydrateFrames", &[]);
        let realms: Vec<Value> = {
            let state = engine.ctx().host_mut::<HostState>().unwrap();
            let dom = state.dom.clone();
            let dom = dom.borrow();
            dom.descendants(DOCUMENT)
                .filter(|&node| dom.tag_name(node) == Some("iframe"))
                .map(|frame| state.window_realms[&state.frame_contexts[&frame]].clone())
                .collect()
        };
        let probe = r#"(() => {
            const result = [];
            const attempt = (label, read) => {
                try { result.push(label + '=' + read()); }
                catch (error) { result.push(label + '!' + error.name); }
            };
            attempt('document', () => parent.document.body.firstChild.textContent);
            attempt('frameElement', () => frameElement);
            attempt('href', () => parent.location.href);
            attempt('keys', () => Object.keys(parent).length);
            attempt('top', () => parent === top && parent.self === parent && parent.parent === parent);
            attempt('sibling', () => typeof parent.same.postMessage);
            attempt('post', () => (parent.postMessage('hello', '*'), 'sent'));
            return result.join(' ');
        })()"#;
        let run = |engine: &mut lumen::Engine, realm: &Value| {
            engine
                .with_embed_realm(realm, |engine| string_value(engine, probe))
                .unwrap_or_else(|_| panic!("enter child Realm"))
        };
        let cross = run(&mut engine, &realms[0]);
        let sandboxed = run(&mut engine, &realms[1]);
        let same = run(&mut engine, &realms[2]);
        let restricted = "document!SecurityError frameElement=null href!SecurityError keys=0 \
                          top=true sibling=function post=sent";
        assert_eq!(cross, restricted, "cross-origin child");
        assert_eq!(sandboxed, restricted, "sandboxed child");
        assert!(
            same.starts_with("document=TOP-SECRET frameElement=[object HTMLIFrameElement]"),
            "{same}"
        );
        for _ in 0..16 {
            call_trust_method(&mut engine, "runPlatformTask", &[]);
        }
        assert_eq!(
            string_value(
                &mut engine,
                r#"(() => {
                    const frames = document.querySelectorAll('iframe');
                    const sources = received.map(event => [...frames].findIndex(frame =>
                        frame.contentWindow === event.source));
                    return [received.length, received.map(event => event.origin).join(),
                        sources.join(), frames[1].contentDocument === null].join('|');
                })()"#
            ),
            "3|null,null,https://top.example|0,1,2|true"
        );
    }

    fn serialize_native(engine: &mut lumen::Engine, node: usize) -> String {
        let state = engine.ctx().host_mut::<HostState>().unwrap();
        state.dom.borrow().serialize_js(node)
    }

    #[test]
    fn cross_origin_frame_content_is_unreachable_from_the_embedding_page() {
        // End-to-end through the production bootstrap: the page tries every former host
        // binding and wrapper-internal route to a cross-origin frame's document.
        let html = r#"<!doctype html><body><iframe id=f
            src="data:text/html,<p id=s>CROSS-ORIGIN-SECRET-42</p>"></iframe><pre id=o></pre><script>
            addEventListener('load', () => {
                const f = document.getElementById('f'), routes = [];
                function attempt(label, read) {
                    try { if (String(read()).includes('CROSS-ORIGIN-SECRET')) routes.push(label); }
                    catch (error) {}
                }
                attempt('contentDocument', () => f.contentDocument.documentElement.outerHTML);
                attempt('contentWindow', () => f.contentWindow.document.documentElement.outerHTML);
                attempt('realm window', () => f.__contentRealmWindow.document.documentElement.outerHTML);
                attempt('content doc', () => f.__contentDoc.documentElement.outerHTML);
                attempt('arena root', () => __dom_outer_html(0));
                attempt('frame document', () => __dom_outer_html(__dom_frame_document(f.__id)));
                attempt('control object', () => __trust.frameDocumentHTML);
                for (let id = 0; id < 64; id++) {
                    const forged = document.createElement('p');
                    forged.__id = id;
                    attempt('forged id ' + id, () => forged.outerHTML + forged.textContent);
                }
                document.getElementById('o').textContent = routes.join() || 'sealed';
            });
            </script>"#;
        let (output, outcome) = crate::js::transform(html, &crate::js::PageEnv::bare(DEFAULT_URL));
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        let result = output
            .split("<pre id=\"o\">")
            .nth(1)
            .and_then(|rest| rest.split("</pre>").next())
            .unwrap_or_default();
        assert_eq!(result, "sealed", "{output}");
        assert!(
            output.contains(r#"<p id="s">CROSS-ORIGIN-SECRET-42</p>"#),
            "the cross-origin frame document was realized: {output}"
        );
    }

