    #[test]
    fn linked_and_imported_sheets_are_css_style_sheets() {
        // CSSOM #css-style-sheets and #the-cssimportrule-interface, CSS
        // Cascade 4 #fetch-an-import and 5 #at-import: every fetched sheet
        // keeps its own record; the cascade splices imported rules.
        for tier in [Tier::Interp, Tier::Bytecode, Tier::Jit] {
            let mut dom = Dom::parse_document(
                "<html><head>\
                 <link rel=stylesheet title=Main href=/css/main.css>\
                 <link rel=stylesheet href=https://cdn.example/x.css>\
                 <style>@import url(inline.css) layer(base) supports(display: grid) screen;\
                 @import url(skip.css) layer supports(display: no-such-display);\
                 p { margin: 0 }</style>\
                 <link rel=stylesheet href=/css/other.css>\
                 </head><body><p id=target>x</p></body></html>",
            );
            dom.set_doc_url(url::Url::parse(DEFAULT_URL).ok());
            let sheet =
                |link: Option<&str>, url: &str, text: &str, cors: bool| crate::http::PageSheet {
                    link_href: link.map(str::to_string),
                    url: url.into(),
                    base: url.into(),
                    text: text.into(),
                    cors_same_origin: cors,
                    referrer_policy: None,
                };
            dom.attach_external_sheets(&[
                sheet(
                    Some("/css/main.css"),
                    "https://example.com/css/main.css",
                    "@import 'theme.css' print; @import url(missing.css); .a { color: blue }",
                    true,
                ),
                sheet(
                    Some("https://cdn.example/x.css"),
                    "https://cdn.example/x.css",
                    ".b {}",
                    false,
                ),
                sheet(
                    Some("/css/other.css"),
                    "https://example.com/css/other.css",
                    "@import url(https://cdn.example/y.css);",
                    true,
                ),
                sheet(
                    None,
                    "https://example.com/css/theme.css",
                    "@import url(deep.css); .t { color: green }",
                    true,
                ),
                sheet(
                    None,
                    "https://example.com/css/deep.css",
                    ".d { margin: 0 }",
                    true,
                ),
                sheet(
                    None,
                    "https://example.com/inline.css",
                    "#target { color: red }",
                    true,
                ),
                sheet(
                    None,
                    "https://example.com/skip.css",
                    "#target { color: lime }",
                    true,
                ),
                sheet(None, "https://cdn.example/y.css", ".y {}", false),
            ]);
            let dom = Rc::new(RefCell::new(dom));
            let mut engine = configured_engine(
                HostState::new(dom.clone(), Rc::new(RealmClock::new())),
                DEFAULT_URL,
            );
            engine.set_tier(tier);
            engine.set_tier_threshold(0);
            assert_eq!(
                string_value(
                    &mut engine,
                    include_str!("fixtures/cssom_imported_sheets.mjs")
                ),
                "cssom-imported-sheets-ok",
                "{tier:?}"
            );
            // A CSSOM-inserted @import requests its sheet (CSS Cascade 4
            // #fetch-an-import); its arrival associates the sheet with the
            // rule and cascades it.
            assert_eq!(
                string_value(
                    &mut engine,
                    "globalThis.late = document.styleSheets[2];\n\
                     late.insertRule('@import url(late.css);', 0);\n\
                     [late.cssRules[0].styleSheet, getComputedStyle(document.getElementById('target')).color].join()"
                ),
                ",rgb(0, 0, 0)",
                "{tier:?}"
            );
            let requests = dom.borrow().take_import_requests();
            assert!(
                requests
                    .iter()
                    .any(|(_, url)| url == "https://example.com/late.css"),
                "{requests:?}"
            );
            dom.borrow_mut()
                .attach_imported_sheets(vec![crate::http::PageSheet {
                    link_href: None,
                    url: "https://example.com/late.css".into(),
                    base: "https://example.com/late.css".into(),
                    text: "#target { color: rgb(7, 8, 9) }".into(),
                    cors_same_origin: true,
                    referrer_policy: None,
                }]);
            assert_eq!(
                string_value(
                    &mut engine,
                    "__trust.styleImportsArrived();\n\
                     [late.cssRules[0].styleSheet.href, late.cssRules[0].styleSheet.parentStyleSheet === late,\n\
                      getComputedStyle(document.getElementById('target')).color].join()"
                ),
                "https://example.com/late.css,true,rgb(7, 8, 9)",
                "{tier:?}"
            );
        }
    }

    #[test]
    fn style_sheets_load_after_their_critical_subresources() {
        // HTML #the-style-element, #update-a-style-block, #critical-subresources and
        // #delay-the-load-event (local whatwg/html e5071a20): a style element fires load (or
        // error, when an @import failed) once the sheets its @import rules import are obtained
        // and delays the document's load event meanwhile; an @import CSSOM inserts into an
        // already loaded sheet only delays the load event.
        let dom = Rc::new(RefCell::new(Dom::parse_document(
            "<!doctype html><head></head><body><p id=target>t</p></body>",
        )));
        dom.borrow_mut()
            .set_doc_url(Some(url::Url::parse(DEFAULT_URL).unwrap()));
        let mut engine = configured_engine(
            HostState::new(dom.clone(), Rc::new(RealmClock::new())),
            DEFAULT_URL,
        );
        let settle = "__trust.hasRenderingUpdate();\n\
                      while (__trust.hasPlatformTask()) __trust.runPlatformTask();";
        let sheet = |url: &str, text: &str| crate::http::PageSheet {
            link_href: None,
            url: url.into(),
            base: url.into(),
            text: text.into(),
            cors_same_origin: true,
            referrer_policy: None,
        };
        assert_eq!(
            string_value(
                &mut engine,
                &format!(
                    r#"
            globalThis.log = [];
            const add = (name, css, type) => {{
                const style = document.createElement('style');
                if (type) style.setAttribute('type', type);
                style.textContent = css;
                style.onload = () => log.push(name + ' load');
                style.onerror = () => log.push(name + ' error');
                document.head.append(style);
                return style;
            }};
            globalThis.plain = add('plain', 'p {{}}');
            add('imported', '@import url(a.css); p {{}}');
            add('missing', '@import url(missing.css);');
            add('other', '@import url(z.css);', 'text/plain');
            {settle}
            log.push('delayed ' + __trust.loadEventDelayed());
            log.join('|');
        "#
                )
            ),
            "plain load|delayed true"
        );
        // The import fetches complete: a.css arrives, missing.css fails.
        let requests = dom.borrow().take_import_requests();
        let mut urls: Vec<_> = requests.iter().map(|(_, url)| url.as_str()).collect();
        urls.sort_unstable();
        assert_eq!(
            urls,
            [
                "https://example.com/a.css",
                "https://example.com/missing.css"
            ]
        );
        dom.borrow_mut()
            .attach_imported_sheets(vec![sheet("https://example.com/a.css", "p {}")]);
        assert_eq!(
            string_value(
                &mut engine,
                &format!(
                    "log.length = 0; __trust.styleImportsArrived();\n{settle}\n\
                     log.push('delayed ' + __trust.loadEventDelayed()); log.join('|')"
                )
            ),
            "imported load|missing error|delayed false"
        );
        // A loaded sheet that gains an @import delays the load event only; a
        // children change updates the style block, which loads again.
        assert_eq!(
            string_value(
                &mut engine,
                &format!(
                    "log.length = 0; plain.sheet.insertRule('@import url(late.css);', 0);\n{settle}\n\
                     log.push('delayed ' + __trust.loadEventDelayed()); log.join('|')"
                )
            ),
            "delayed true"
        );
        dom.borrow().take_import_requests();
        dom.borrow_mut()
            .attach_imported_sheets(vec![sheet("https://example.com/late.css", "p {}")]);
        assert_eq!(
            string_value(
                &mut engine,
                &format!(
                    "log.length = 0; __trust.styleImportsArrived();\n{settle}\n\
                     log.push('delayed ' + __trust.loadEventDelayed());\n\
                     plain.textContent = 'p {{ color: red }}';\n{settle}\n\
                     plain.remove();\n{settle}\n\
                     log.join('|')"
                )
            ),
            "delayed false|plain load"
        );
    }

