    /// A Window realm whose host tasks (Web Audio rendering threads'
    /// reports) arrive on `tasks`.
    fn audio_engine() -> (
        lumen::Engine,
        tokio::sync::mpsc::UnboundedReceiver<LumenHostTask>,
    ) {
        let (sender, tasks) = tokio::sync::mpsc::unbounded_channel();
        let mut state = HostState::new(
            Rc::new(RefCell::new(Dom::new())),
            Rc::new(RealmClock::new()),
        );
        state.task_events = Some(LumenTaskSender::Page(sender));
        (configured_engine(state, DEFAULT_URL), tasks)
    }

    /// Run host and platform tasks until `condition` is true (or panic
    /// after `seconds`).
    fn pump_audio_until(
        engine: &mut lumen::Engine,
        tasks: &mut tokio::sync::mpsc::UnboundedReceiver<LumenHostTask>,
        condition: &str,
        seconds: u64,
    ) {
        let deadline = Instant::now() + Duration::from_secs(seconds);
        loop {
            run_microtask_checkpoint(engine);
            if string_value(engine, &format!("String({condition})")) == "true" {
                return;
            }
            assert!(
                Instant::now() < deadline,
                "audio never reached {condition}: {}",
                string_value(engine, "__trust.takeErrors()")
            );
            if let Ok(task) = tasks.try_recv() {
                dispatch_host_task(engine, task).unwrap();
            } else if string_value(engine, "__trust.hasPlatformTask()") == "true" {
                eval(engine, "__trust.runPlatformTask()", "audio task").unwrap();
            } else if string_value(engine, "String(__trust.hasPortMessageTask())") == "true" {
                eval(engine, "__trust.runPortMessageTask()", "port task").unwrap();
            } else if string_value(engine, "String(__trust.tick())") != "true" {
                std::thread::sleep(Duration::from_millis(1));
            }
        }
    }

    #[test]
    fn audio_context_waits_for_activation_then_renders() {
        // Web Audio 1.1 (local WebAudio/web-audio-api@2047f16)
        // #AudioContext-constructors "allowed to start", #AudioContext-methods
        // resume()/suspend()/close() and #rendering-loop: without sticky
        // activation resume() waits; after activation the context runs (here
        // on the silent real-time sink) and its clock advances.
        for tier in [Tier::Interp, Tier::Bytecode, Tier::Jit] {
            let (mut engine, mut tasks) = audio_engine();
            engine.set_tier(tier);
            engine.set_tier_threshold(0);
            assert_eq!(
                string_value(&mut engine, include_str!("fixtures/audio_context.mjs")),
                "audio-context-pending",
                "{tier:?}"
            );
            pump_audio_until(
                &mut engine,
                &mut tasks,
                "audioSuspendResult !== 'pending' && audioBrandResult !== 'pending'",
                10,
            );
            std::thread::sleep(Duration::from_millis(50));
            run_microtask_checkpoint(&mut engine);
            assert_eq!(
                string_value(
                    &mut engine,
                    "[audioResumeResult, audioSuspendResult, audioBrandResult, audioEvents.join(), audioContext.state, audioContext.currentTime].join('|')"
                ),
                "pending|suspended|TypeError||suspended|0",
                "{tier:?}"
            );
            eval(
                &mut engine,
                "const root = document.createElement('html'), body = document.createElement('body');\n\
                 document.append(root); root.append(body);\n\
                 __trust.key(body.__id,'a','KeyA',false,false,false,false,false,false);\n\
                 if (!navigator.userActivation.hasBeenActive) throw Error('no activation');\n\
                 audioContext.resume().then(() => globalThis.secondResume = 'resumed');",
                "activate and resume",
            )
            .unwrap();
            pump_audio_until(
                &mut engine,
                &mut tasks,
                "audioResumeResult === 'resumed' && globalThis.secondResume === 'resumed' && audioContext.currentTime > 0.05",
                10,
            );
            pump_audio_until(&mut engine, &mut tasks, "audioEvents.length > 0", 5);
            assert_eq!(
                string_value(
                    &mut engine,
                    "[audioEvents.join(), audioContext.state, __trust.takeErrors()].join('|')"
                ),
                "state:running|running|",
                "{tier:?}"
            );
            eval(
                &mut engine,
                r#"
                audioContext.close().then(() => audioEvents.push('closed-promise'));
                if (audioContext.state !== 'closed') throw Error('close changes control state synchronously');
                Promise.all(['resume', 'suspend', 'close'].map(method =>
                    audioContext[method]().catch(error => error.name))).then(results => {
                        globalThis.audioClosedResults = results.join(',');
                    });
            "#,
                "close audio context",
            )
            .unwrap();
            pump_audio_until(
                &mut engine,
                &mut tasks,
                "audioEvents.includes('state:closed') && globalThis.audioClosedResults !== undefined",
                10,
            );
            let stopped = string_value(&mut engine, "audioContext.currentTime");
            std::thread::sleep(Duration::from_millis(60));
            assert_eq!(
                string_value(
                    &mut engine,
                    "[audioEvents.join(), audioClosedResults, audioContext.currentTime, __trust.takeErrors()].join('|')"
                ),
                format!(
                    "state:running,closed-promise,state:closed|InvalidStateError,InvalidStateError,InvalidStateError|{stopped}|"
                ),
                "{tier:?}"
            );
        }
    }

    #[test]
    fn audio_context_script_processor_suspended_graph() {
        for tier in [Tier::Interp, Tier::Bytecode, Tier::Jit] {
            let (mut engine, mut tasks) = audio_engine();
            engine.set_tier(tier);
            engine.set_tier_threshold(0);
            assert_eq!(
                string_value(
                    &mut engine,
                    include_str!("fixtures/audio_script_processor.mjs")
                ),
                "audio-script-processor-ready",
                "{tier:?}"
            );
            run_microtask_checkpoint(&mut engine);
            std::thread::sleep(Duration::from_millis(50));
            pump_audio_until(&mut engine, &mut tasks, "true", 1);
            engine.ctx().collect_garbage_for_host();
            assert_eq!(
                string_value(
                    &mut engine,
                    "[silentResume, silentContext.state, silentContext.currentTime, processCalls].join('|')"
                ),
                "pending|suspended|0|0",
                "{tier:?}"
            );
            // Connections remain valid across collection and context closure;
            // close stops processing, not author access to retained objects.
            eval(
                &mut engine,
                r#"
                processor.disconnect(destination);
                processor.connect(destination);
                silentContext.close();
            "#,
                "close suspended graph",
            )
            .unwrap();
            pump_audio_until(
                &mut engine,
                &mut tasks,
                "silentContext.state === 'closed'",
                10,
            );
            assert_eq!(
                string_value(
                    &mut engine,
                    "[silentContext.state, silentContext.currentTime, processCalls].join('|')"
                ),
                "closed|0|0",
                "{tier:?}"
            );
            eval(
                &mut engine,
                "processor.disconnect(destination)",
                "disconnect closed graph",
            )
            .unwrap();
        }
    }

    #[test]
    fn audio_context_construction_does_not_abort_module_ui() {
        let html = r#"<!doctype html><div id="root"></div><script type="module">
            const context = new AudioContext({latencyHint: 0.03});
            const root = document.getElementById('root');
            root.innerHTML = '<button>Start audio</button><output>Ready</output>';
            context.resume().catch(error => root.querySelector('output').textContent = error.name);
        </script>"#;
        let (rendered, outcome) =
            crate::js::transform(html, &crate::js::PageEnv::bare(DEFAULT_URL));
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        assert!(!outcome.panicked);
        assert!(rendered.contains(">Start audio</button>"), "{rendered}");
        // Without user activation the context may not start: resume() waits.
        assert!(rendered.contains(">Ready</output>"), "{rendered}");
    }

    #[test]
    fn page_visible_platform_objects_expose_no_internal_properties() {
        // Web IDL #js-platform-objects keeps implementation state in internal
        // slots. Exercise wrappers, collections, events, observers, CSSOM,
        // fetch/XHR, Indexed Database and the newer device APIs, in an engine
        // without the test-only control-object exposure, and list every own
        // "__…" or "…trust…" property reachable on those objects or their
        // prototype chains. The engine's legacy RegExp statics are excluded.
        let mut state = HostState::new(
            Rc::new(RefCell::new(Dom::new())),
            Rc::new(RealmClock::new()),
        );
        state
            .window_request_urls
            .insert(0, url::Url::parse(DEFAULT_URL).unwrap());
        let mut engine = lumen::Engine::new();
        engine.set_tier(Tier::Interp);
        let clock = state.clock.clone();
        engine.set_wall_clock(move || clock.now_ms());
        state.configure_module_loading(&mut engine);
        engine
            .ctx()
            .op_state()
            .put_retained_memory_with_external_memory(state);
        install_host_boundary(&mut engine);
        eval(
            &mut engine,
            &format!(
                "globalThis.__trust_cfg = {{ url: {DEFAULT_URL:?}, width: 640, height: 384 }};"
            ),
            "configuration",
        )
        .unwrap();
        eval_platform_prelude(&mut engine).unwrap();
        assert_eq!(
            string_value(&mut engine, "typeof globalThis.__trust"),
            "undefined"
        );
        eval(
            &mut engine,
            include_str!("fixtures/internal_names.mjs"),
            "internal names",
        )
        .unwrap();
        call_trust_method(&mut engine, "hydrateFrames", &[]);
        let mut result = String::from("undefined");
        for _ in 0..2000 {
            run_microtask_checkpoint(&mut engine);
            result = string_value(&mut engine, "String(globalThis.internalNamesResult)");
            if result != "undefined" {
                break;
            }
            if matches!(
                call_trust_method(&mut engine, "hasPlatformTask", &[]),
                Value::Bool(true)
            ) {
                call_trust_method(&mut engine, "runPlatformTask", &[]);
            } else {
                call_trust_method(&mut engine, "tick", &[]);
            }
        }
        assert_eq!(result, "none");

        let mut worker = worker_platform_engine_with(false);
        let probe = r#"
            (() => {
                const bad = key => typeof key === 'string' && !['__proto__', '__defineGetter__',
                    '__defineSetter__', '__lookupGetter__', '__lookupSetter__', 'isTrusted'].includes(key)
                    && (key.startsWith('__') || /trust/i.test(key));
                const found = new Set();
                const scan = object => {
                    if (object === null || (typeof object !== 'object' && typeof object !== 'function') || object === RegExp) return;
                    for (let o = object, depth = 0; o && depth < 8; o = Object.getPrototypeOf(o), depth++)
                        for (const key of Reflect.ownKeys(o)) if (bad(key)) found.add(key);
                };
                scan(globalThis);
                for (const name of Object.getOwnPropertyNames(globalThis)) {
                    const value = globalThis[name];
                    if (typeof value === 'function' && value !== RegExp) { scan(value); scan(value.prototype); }
                }
                const url = new URL('https://example.com/?a=1');
                url.searchParams.append('b', '2');
                for (const object of [new Blob(['x']), new File(['y'], 'f'), url, url.searchParams,
                    new URLSearchParams('c=3'), new Headers({a: 'b'}),
                    new TextDecoder(), new TextEncoder(), new MessageChannel().port1, new Notification('x'),
                    navigator, navigator.permissions, performance, location])
                    scan(object);
                return [...found].sort().join() || 'none';
            })()
        "#;
        assert_eq!(string_value(&mut worker, probe), "none");
    }

