    #[test]
    fn iframe_document_referrer_is_a_snapshot_of_the_navigation_request() {
        use tokio::io::{AsyncReadExt as _, AsyncWriteExt as _};
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .enable_all()
            .build()
            .unwrap();
        let listener = runtime
            .block_on(tokio::net::TcpListener::bind("127.0.0.1:0"))
            .unwrap();
        let origin = format!(
            "http://127.0.0.1:{}/",
            listener.local_addr().unwrap().port()
        );
        let page = format!("{origin}parent?q=1#fragment");
        let server = runtime.spawn(async move {
            let mut requests=Vec::new();
            for _ in 0..3 {
                let (mut stream,_) = listener.accept().await.unwrap();
                let mut bytes=Vec::new();let mut buffer=[0;2048];
                while !bytes.windows(4).any(|w|w==b"\r\n\r\n") {let n=stream.read(&mut buffer).await.unwrap();assert_ne!(n,0);bytes.extend_from_slice(&buffer[..n]);}
                requests.push(String::from_utf8(bytes).unwrap());
                let html="<!doctype html><html><head></head><body>child</body></html>";
                stream.write_all(format!("HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{html}",html.len()).as_bytes()).await.unwrap();
            }
            requests
        });
        let cache = Arc::new(crate::http::PageCache::default());
        let (tx, _rx) = tokio::sync::mpsc::unbounded_channel();
        let mut state = HostState::new(
            Rc::new(RefCell::new(Dom::parse_document(
                "<!doctype html><html><head></head><body></body></html>",
            ))),
            Rc::new(RealmClock::new()),
        );
        state.enable_network(
            url::Url::parse(&page).unwrap(),
            runtime.handle().clone(),
            cache.clone(),
            tx,
        );
        let mut engine = configured_engine(state, &page);
        let result = string_value(
            &mut engine,
            &format!(
                r#"(()=>{{
            const results=[];
            for(const policy of ['', 'origin','no-referrer']) {{
                const f=document.createElement('iframe');document.body.appendChild(f);
                const initial=f.contentDocument;
                if(initial.referrer!==document.URL)throw Error('initial blank creator referrer');
                f.referrerPolicy=policy;f.src={origin:?}+'child?policy='+policy;
                const doc=f.contentDocument;
                if(doc===initial || initial.referrer!==document.URL)throw Error('old Document metadata changed');
                results.push(doc.referrer);
            }}
            return results.join('|');
        }})()"#
            ),
        );
        assert_eq!(result, format!("{origin}parent?q=1|{origin}|"));
        let requests = runtime.block_on(async {
            tokio::time::timeout(Duration::from_secs(5), server)
                .await
                .unwrap()
                .unwrap()
        });
        assert!(requests[0].contains(&format!("Referer: {origin}parent?q=1\r\n")));
        assert!(requests[1].contains(&format!("Referer: {origin}\r\n")));
        assert!(!requests[2].to_ascii_lowercase().contains("referer:"));
        cache.cancel();
    }

    #[test]
    fn canvas_image_origin_clean_includes_redirects_and_survives_base_changes() {
        use futures::FutureExt as _;
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .enable_all()
            .build()
            .unwrap();
        let page = url::Url::parse("https://canvas.example/document").unwrap();
        let cache = Arc::new(crate::http::PageCache::default());
        let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
        let mut state = HostState::new(
            Rc::new(RefCell::new(Dom::parse_document(
                "<!doctype html><html><head></head><body></body></html>",
            ))),
            Rc::new(RealmClock::new()),
        );
        state.enable_network(page.clone(), runtime.handle().clone(), cache.clone(), tx);
        let mut engine = configured_engine(state, page.as_str());
        let png = string_value(
            &mut engine,
            "(()=>{const c=document.createElement('canvas');c.width=2;c.height=2;const x=c.getContext('2d');x.fillStyle='red';x.fillRect(0,0,2,2);return c.toDataURL();})()",
        );
        let bytes = crate::img::decode_data_url(&png).unwrap();
        for (name, urls) in [
            ("same", vec!["https://canvas.example/same"]),
            ("cross", vec!["https://other.example/cross"]),
            (
                "redirect",
                vec![
                    "https://canvas.example/redirect",
                    "https://other.example/hop",
                    "https://canvas.example/final",
                ],
            ),
            ("unknown", vec![]),
        ] {
            let url = if name == "cross" {
                "https://other.example/cross".to_string()
            } else {
                format!("https://canvas.example/{name}")
            };
            let response = Arc::new(crate::http::CachedResp {
                status: 200,
                status_text: String::new(),
                content_type: "image/png".into(),
                headers: Vec::new(),
                body: bytes.clone(),
                timing: None,
                url_list: urls
                    .into_iter()
                    .map(|u| url::Url::parse(u).unwrap())
                    .collect(),
            });
            let fetch = futures::future::ready(Ok(response)).boxed().shared();
            assert!(fetch.clone().now_or_never().is_some());
            cache.seed_pending(url, fetch);
        }
        eval(
            &mut engine,
            r#"globalThis.canvasOriginResult = 'pending'; (async()=>{
            function check(v,m){if(!v)throw Error(m);}
            function security(f){try{f();}catch(e){check(e.name==='SecurityError','wrong error '+e);return;}throw Error('taint missing');}
            function load(src) { return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=src;}); }
            for(const name of ['same','cross','redirect','unknown']) {
                const c=document.createElement('canvas');c.width=2;c.height=2;const x=c.getContext('2d');
                const img=await load((name==='cross'?'https://other.example/':'https://canvas.example/')+name);
                x.drawImage(img,0,0);
                if(name==='same'){check(x.getImageData(0,0,1,1).data[0]===255,'same-origin pixels');continue;}
                security(()=>x.getImageData(0,0,1,1));security(()=>c.toDataURL());
                const copy=document.createElement('canvas'), y=copy.getContext('2d');y.drawImage(c,0,0);security(()=>copy.toDataURL());
                x.clearRect(0,0,2,2);security(()=>c.toDataURL());
                c.width=2;check(x.getImageData(0,0,1,1).data[3]===0,'resize restores clean bitmap');
            }
            const base=document.createElement('base');base.href='https://other.example/';document.head.appendChild(base);
            const c=document.createElement('canvas'),x=c.getContext('2d'),img=await load('https://other.example/cross');x.drawImage(img,0,0);security(()=>c.toDataURL());
            return 'canvas-origin-clean-ok';
        })().then(result=>{canvasOriginResult=result}, error=>{canvasOriginResult=String(error)})"#,
            "canvas image taint checks",
        ).unwrap();
        run_microtask_checkpoint(&mut engine);
        for _ in 0..5 {
            let task = runtime
                .block_on(async { tokio::time::timeout(Duration::from_secs(5), rx.recv()).await })
                .unwrap()
                .unwrap();
            dispatch_host_task(&mut engine, task).unwrap();
            run_microtask_checkpoint(&mut engine);
            for _ in 0..4 {
                eval(
                    &mut engine,
                    "__trust.tickTo(__trust.now()+50)",
                    "image taint tasks",
                )
                .unwrap();
                run_microtask_checkpoint(&mut engine);
            }
        }
        assert_eq!(
            string_value(&mut engine, "canvasOriginResult"),
            "canvas-origin-clean-ok"
        );
        cache.cancel();
    }

    #[test]
    fn canvas_bitmap_reaches_canonical_layout_and_pixel_renderer() {
        let mut engine = configured_engine(
            HostState::new(
                Rc::new(RefCell::new(Dom::parse_document(
                    "<!doctype html><html><head></head><body></body></html>",
                ))),
                Rc::new(RealmClock::new()),
            ),
            DEFAULT_URL,
        );
        eval(&mut engine,r#"
            document.body.innerHTML = '<canvas id="raster" width="64" height="48" style="position:absolute;left:0;top:0;width:64px;height:48px"></canvas>';
            const c = document.getElementById('raster'), context = c.getContext('2d');
            context.fillStyle='#ff0000'; context.fillRect(0,0,32,48);
            context.fillStyle='#00ff00'; context.fillRect(32,0,32,48);
        "#,"canvas presentation setup").unwrap();
        let dom = engine.ctx().host_mut::<HostState>().unwrap().dom.clone();
        let base = url::Url::parse(DEFAULT_URL).unwrap();
        let make_page = || {
            crate::http::render_arena(
                &dom.borrow(),
                &base,
                crate::layout2::Viewport::new(128., 96.),
                1.,
                None,
                &Default::default(),
            )
        };
        let page = make_page();
        assert!(page.image_urls.is_empty(), "canvas is not an image fetch");
        assert!(page.layout.paint.image_requests.is_empty());
        assert_eq!(page.layout.paint.canvas_images.len(), 1);
        let frame = crate::render::headless::render_paint(
            &page.layout.paint,
            crate::core::CssSize::new(128., 96.),
        )
        .unwrap();
        let pixel = |x: usize, y: usize| &frame.pixels[(y * 128 + x) * 4..(y * 128 + x) * 4 + 4];
        assert_eq!(pixel(10, 20), &[255, 0, 0, 255]);
        assert_eq!(pixel(50, 20), &[0, 255, 0, 255]);

        let make_scene = |paint: &crate::render::PagePaint| {
            use crate::core::{CssPoint, CssSize, PhysicalSize, ViewportMetrics};
            use crate::render::CssRect;
            let mut scene = crate::render::Scene {
                viewport: ViewportMetrics::from_physical(
                    PhysicalSize::new(128, 96),
                    Default::default(),
                ),
                primitives: Vec::new(),
                controls: Vec::new(),
                content_viewport: CssRect::new(0., 0., 128., 96.),
                image_store: Default::default(),
                canvas_images: Default::default(),
                page_scroll_containers: Vec::new(),
                page_size: CssSize::default(),
            };
            scene.append_page(paint, CssPoint::default());
            scene
        };
        let first = make_scene(&page.layout.paint);
        let mut renderer = crate::render::vello_cpu::VelloCpuRenderer::new();
        let initial = renderer.render_rgba(&first).unwrap();
        eval(
            &mut engine,
            "context.fillStyle='#0000ff';context.fillRect(0,0,64,48)",
            "canvas update",
        )
        .unwrap();
        let mut repainted = (*page.layout).clone();
        assert!(crate::layout2::repaint_graphical(
            &mut repainted,
            &dom.borrow(),
            &base,
            &Default::default(),
            &Default::default()
        ));
        let updated = make_page();
        assert_eq!(
            repainted.paint.canvas_images, updated.layout.paint.canvas_images,
            "paint-only invalidation refreshes pixels without rebuilding geometry"
        );
        let second = make_scene(&updated.layout.paint);
        let old_image = &page.layout.paint.canvas_images[0].1;
        let new_image = &updated.layout.paint.canvas_images[0].1;
        assert_eq!(old_image.handle, new_image.handle, "stable canvas identity");
        assert_ne!(old_image.generation, new_image.generation);
        assert_eq!(
            crate::render::scene_damage(&first, &second),
            crate::render::SceneDamage::Full
        );
        let changed = renderer.render_rgba(&second).unwrap();
        assert_eq!(
            &changed.pixels[(20 * 128 + 10) * 4..(20 * 128 + 10) * 4 + 4],
            &[0, 0, 255, 255]
        );
        assert_eq!(
            renderer.render_rgba(&first).unwrap().pixels,
            initial.pixels,
            "old frames retain their pixels, even with a shared renderer cache"
        );
        if let Ok(mut hybrid) = futures::executor::block_on(
            crate::render::vello_hybrid::VelloHybridRenderer::new_headless(),
        ) {
            let gpu_initial = hybrid.render_rgba(&first).unwrap();
            let gpu_changed = hybrid.render_rgba(&second).unwrap();
            assert_eq!(
                &gpu_changed.pixels[(20 * 128 + 10) * 4..][..4],
                &[0, 0, 255, 255]
            );
            assert_eq!(
                hybrid.render_rgba(&first).unwrap().pixels,
                gpu_initial.pixels
            );
            eprintln!("canvas snapshot handoff exercised on hybrid renderer");
        }

        // The terminal adapter names this page's snapshot, not the newly
        // painted DOM, and its key resolves to that snapshot's pixels.
        let old_url = old_image.terminal_url();
        let old_rgba = old_image.image.rgba.clone();
        let terminal = crate::http::adapt_rendered_terminal(
            &base,
            "text/html",
            Vec::new(),
            page,
            crate::layout2::TerminalViewport::new(16, 6, 8., 16.),
            &Default::default(),
        );
        assert!(terminal.image_urls.contains(&old_url));
        assert!(terminal.eager_image_urls.contains(&old_url));
        assert!(
            terminal
                .rows
                .iter()
                .flat_map(|row| &row.items)
                .any(|item| item.image.as_ref() == Some(&old_url)),
            "terminal rows retain their canvas image"
        );
        let frame = crate::img::registered_canvas_frame(&old_url).unwrap();
        assert!(frame.ends_with(&old_rgba));
        assert_ne!(old_url, new_image.terminal_url());

        // Resizing replaces the bitmap with transparent black, even when the
        // dimensions are unchanged; retaining the handle must not retain pixels.
        eval(&mut engine, "c.width=64", "canvas resize").unwrap();
        let resized = make_page();
        let resized_scene = make_scene(&resized.layout.paint);
        assert_eq!(
            crate::render::scene_damage(&second, &resized_scene),
            crate::render::SceneDamage::Full
        );
        let resized_frame = renderer.render_rgba(&resized_scene).unwrap();
        assert_eq!(
            &resized_frame.pixels[(20 * 128 + 10) * 4..(20 * 128 + 10) * 4 + 4],
            &[255, 255, 255, 255]
        );
        eval(&mut engine, r#"
            document.body.innerHTML='<canvas width="64" height="48" style="position:absolute;left:0;top:0"></canvas>';
        "#, "canvas without context").unwrap();
        let blank = make_page();
        assert!(blank.layout.paint.canvas_images.is_empty());
        assert!(blank.layout.paint.image_requests.is_empty());
        assert!(
            blank
                .layout
                .paint
                .primitives
                .iter()
                .any(|command| matches!(command, crate::render::DisplayCommand::HitRegion { .. })),
            "transparent canvas still participates in hit testing"
        );
        assert_eq!(
            renderer
                .render_rgba(&make_scene(&blank.layout.paint))
                .unwrap()
                .pixels,
            resized_frame.pixels
        );
    }

    #[test]
    fn create_element_ns_preserves_expanded_names_and_element_interfaces() {
        // WHATWG DOM §1.4 "validate and extract" and §4.5 createElementNS:
        // namespace, prefix, and local name select the element interface and
        // remain observable. This is the construction path React uses for SVG;
        // losing the namespace made Stockcharts omit its interactive SVG layer.
        let mut engine = platform_engine();
        let actual = string_value(
            &mut engine,
            r#"(() => {
                const SVG = 'http://www.w3.org/2000/svg';
                const MATH = 'http://www.w3.org/1998/Math/MathML';
                const XML = 'http://www.w3.org/XML/1998/namespace';
                const XMLNS = 'http://www.w3.org/2000/xmlns/';
                const svg = document.createElementNS(SVG, 'svg');
                const rect = document.createElementNS(SVG, 'rect');
                rect.setAttribute('class', 'react-stockcharts-crosshair-cursor');
                svg.appendChild(rect);
                const host = document.createElement('div');
                host.appendChild(svg);
                const math = document.createElementNS(MATH, 'math');
                const plain = document.createElementNS(null, 'widget');
                const prefixed = document.createElementNS(XML, 'xml:item');
                host.insertAdjacentHTML('beforeend', '<svg><path id="parsed-svg"/></svg>');
                const parsed = host.querySelector('#parsed-svg');
                function errorName(run) {
                    try { run(); return 'none'; } catch (error) { return error.name; }
                }
                return [
                    svg.namespaceURI === SVG,
                    svg.localName === 'svg', svg.tagName === 'svg', svg.prefix === null,
                    svg instanceof SVGElement, svg instanceof SVGSVGElement,
                    !(svg instanceof HTMLElement),
                    rect instanceof SVGRectElement,
                    Object.prototype.toString.call(rect) === '[object SVGRectElement]',
                    host.querySelector('.react-stockcharts-crosshair-cursor') === rect,
                    math.namespaceURI === MATH, math instanceof MathMLElement,
                    plain.namespaceURI === null, plain.constructor === Element,
                    prefixed.prefix === 'xml', prefixed.localName === 'item',
                    prefixed.tagName === 'xml:item', prefixed.nodeName === 'xml:item',
                    parsed instanceof SVGPathElement,
                    errorName(() => document.createElementNS()),
                    errorName(() => document.createElementNS(null, '')),
                    errorName(() => document.createElementNS(null, 'p:item')),
                    errorName(() => document.createElementNS(SVG, 'xml:item')),
                    errorName(() => document.createElementNS(SVG, 'xmlns')),
                    errorName(() => document.createElementNS(XMLNS, 'item'))
                ].join(',');
            })()"#,
        );
        assert_eq!(
            actual,
            "true,true,true,true,true,true,true,true,true,true,true,true,true,true,true,true,true,true,true,TypeError,InvalidCharacterError,NamespaceError,NamespaceError,NamespaceError,NamespaceError"
        );
    }

    #[test]
    fn webassembly_boundary_preserves_store_identity_memory_and_reentry() {
        // WebAssembly JS Interface §§4.1–4.2 and 5.1–5.6: one store per agent, one wrapper per
        // address, imported host calls see the current memory Data Block, memory growth detaches
        // the previous fixed buffer, and i64 crosses the JS boundary as BigInt.
        let mut engine = platform_engine();
        let mut module = wat::parse_str(
            r##"
            (module
              (import "env" "observe" (func $observe (result i32)))
              (import "env" "boom" (func $boom))
              (import "env" "g" (global $g (mut i32)))
              (import "env" "memory" (memory $memory 1 3))
              (import "env" "table" (table $table 1 3 externref))
              (export "memory" (memory $memory))
              (export "table" (table $table))
              (export "g" (global $g))
              (func (export "addGlobal") (param i32) (result i32)
                local.get 0 global.get $g i32.add)
              (func (export "read2") (result i32)
                i32.const 2 i32.load8_u)
              (func (export "write0") (param i32)
                i32.const 0 local.get 0 i32.store8)
              (func (export "bridge") (result i32)
                i32.const 0 i32.const 37 i32.store8
                call $observe
                i32.const 1 i32.load8_u
                i32.add)
              (func (export "growInside") (result i32)
                i32.const 1 memory.grow)
              (func (export "callBoom") call $boom)
              (global (export "big") (mut i64) (i64.const -2)))
            "##,
        )
        .unwrap();
        // A custom section named "note" with payload [1, 2, 3].
        module.extend_from_slice(&[0, 8, 4, b'n', b'o', b't', b'e', 1, 2, 3]);
        let forwarding = wat::parse_str(
            r#"
            (module
              (import "x" "f" (func $f (param i32) (result i32)))
              (export "f" (func $f)))
            "#,
        )
        .unwrap();
        let reentrant = wat::parse_str(
            r#"
            (module
              (import "env" "instantiate" (func $instantiate (result i32)))
              (func (export "run") (result i32) call $instantiate))
            "#,
        )
        .unwrap();
        let nested = wat::parse_str(
            r#"
            (module
              (import "env" "started" (func $started))
              (func $start call $started)
              (start $start)
              (func (export "answer") (result i32) i32.const 23))
            "#,
        )
        .unwrap();
        let module_value = engine
            .ctx()
            .make_uint8array(&module)
            .unwrap_or_else(|_| panic!("make wasm fixture"));
        let forwarding_value = engine
            .ctx()
            .make_uint8array(&forwarding)
            .unwrap_or_else(|_| panic!("make forwarding fixture"));
        let reentrant_value = engine
            .ctx()
            .make_uint8array(&reentrant)
            .unwrap_or_else(|_| panic!("make reentrant fixture"));
        let nested_value = engine
            .ctx()
            .make_uint8array(&nested)
            .unwrap_or_else(|_| panic!("make nested fixture"));
        let global = engine.global_this();
        engine
            .ctx()
            .member_set(&global, "wasmFixture", module_value)
            .unwrap_or_else(|_| panic!("install wasm fixture"));
        engine
            .ctx()
            .member_set(&global, "wasmForwardingFixture", forwarding_value)
            .unwrap_or_else(|_| panic!("install forwarding fixture"));
        engine
            .ctx()
            .member_set(&global, "wasmReentrantFixture", reentrant_value)
            .unwrap_or_else(|_| panic!("install reentrant fixture"));
        engine
            .ctx()
            .member_set(&global, "wasmNestedFixture", nested_value)
            .unwrap_or_else(|_| panic!("install nested fixture"));

        eval(
            &mut engine,
            r#"
            const wasmModule = new WebAssembly.Module(wasmFixture);
            const importGlobal = new WebAssembly.Global({ value: "i32", mutable: true }, 4);
            const importMemory = new WebAssembly.Memory({ initial: 1, maximum: 3 });
            const importTable = new WebAssembly.Table({ element: "externref", initial: 1, maximum: 3 });
            let observed = -1;
            let wasmInstance;
            const sentinel = { sentinel: true };
            const imports = { env: {
                g: importGlobal,
                memory: importMemory,
                table: importTable,
                observe() {
                    const bytes = new Uint8Array(importMemory.buffer);
                    observed = bytes[0];
                    bytes[1] = 5;
                    return wasmInstance.exports.addGlobal(observed);
                },
                boom() { throw sentinel; }
            }};
            wasmInstance = new WebAssembly.Instance(wasmModule, imports);
            const firstBuffer = importMemory.buffer;
            const sameBuffer = firstBuffer === importMemory.buffer;
            new Uint8Array(firstBuffer)[2] = 8;
            const readFromJs = wasmInstance.exports.read2();
            wasmInstance.exports.write0(11);
            const writtenFromWasm = new Uint8Array(firstBuffer)[0];
            const bridge = wasmInstance.exports.bridge();
            const internalOldPages = wasmInstance.exports.growInside();
            const detachedAfterInternalGrow = firstBuffer.byteLength;
            const secondBuffer = importMemory.buffer;
            const explicitOldPages = importMemory.grow(1);
            const detachedAfterExplicitGrow = secondBuffer.byteLength;

            const marker = { marker: 1 };
            importTable.set(0, marker);
            const tableIdentity = importTable.get(0) === marker;
            const oldTableLength = importTable.grow(1);
            const tableDefault = importTable.get(1) === undefined;
            const anyfunc = new WebAssembly.Table({ element: "anyfunc", initial: 1 });
            const anyfuncDefault = anyfunc.get(0) === null;
            let explicitUndefinedRejected = false;
            try { anyfunc.set(0, undefined); } catch (error) {
                explicitUndefinedRejected = error instanceof TypeError;
            }

            const forwardingModule = new WebAssembly.Module(wasmForwardingFixture);
            const forwardingInstance = new WebAssembly.Instance(forwardingModule, {
                x: { f: wasmInstance.exports.addGlobal }
            });
            const functionIdentity = forwardingInstance.exports.f === wasmInstance.exports.addGlobal;
            let nestedStarts = 0;
            let nestedBoundary = false;
            const reentrantInstance = new WebAssembly.Instance(
                new WebAssembly.Module(wasmReentrantFixture),
                { env: { instantiate() {
                    const nestedModule = new WebAssembly.Module(wasmNestedFixture);
                    const nestedGlobal = new WebAssembly.Global({ value: "i32" }, 7);
                    const nestedMemory = new WebAssembly.Memory({ initial: 1 });
                    const nestedTable = new WebAssembly.Table({ element: "externref", initial: 1 });
                    nestedBoundary = WebAssembly.validate(wasmNestedFixture) &&
                        WebAssembly.Module.imports(nestedModule)[0].name === "started" &&
                        WebAssembly.Module.exports(nestedModule)[0].name === "answer" &&
                        WebAssembly.Module.customSections(nestedModule, "missing").length === 0 &&
                        nestedGlobal.value === 7 && nestedMemory.buffer.byteLength === 65536 &&
                        nestedTable.get(0) === undefined;
                    const inner = new WebAssembly.Instance(nestedModule, {
                        env: { started() { nestedStarts++; } }
                    });
                    return inner.exports.answer();
                } } }
            );
            const nestedInstantiation = reentrantInstance.exports.run() === 23 &&
                nestedStarts === 1 && nestedBoundary;
            let throwIdentity = false;
            try { wasmInstance.exports.callBoom(); }
            catch (error) { throwIdentity = error === sentinel; }
            const custom = WebAssembly.Module.customSections(wasmModule, "note")[0];
            const descriptors = [
                WebAssembly.Module.imports(wasmModule).map(v => v.kind).join(','),
                WebAssembly.Module.exports(wasmModule).map(v => v.kind).join(','),
                Array.from(new Uint8Array(custom)).join(',')
            ].join(';');
            const identity = wasmInstance.exports.memory === importMemory &&
                wasmInstance.exports.table === importTable && wasmInstance.exports.g === importGlobal;
            const big = wasmInstance.exports.big.value;
            wasmInstance.exports.big.value = 9n;
            const globalDefaults = new WebAssembly.Global({ value: "f64" }).value === 0 &&
                new WebAssembly.Global({ value: "externref" }).value === undefined;
            let badMemory = false, badTable = false, keyedTransfer = false;
            try { new WebAssembly.Memory({ initial: 4294967296 }); }
            catch (error) { badMemory = error instanceof TypeError; }
            try { new WebAssembly.Table({ element: "externref" }); }
            catch (error) { badTable = error instanceof TypeError; }
            try { importMemory.buffer.transfer(); }
            catch (error) { keyedTransfer = error instanceof TypeError; }

            globalThis.wasmResult = [
                WebAssembly.validate(wasmFixture), sameBuffer, readFromJs, writtenFromWasm,
                observed, bridge, internalOldPages, detachedAfterInternalGrow,
                explicitOldPages, detachedAfterExplicitGrow, tableIdentity, oldTableLength,
                tableDefault, anyfuncDefault, explicitUndefinedRejected, functionIdentity,
                nestedInstantiation, throwIdentity, identity, String(big),
                String(wasmInstance.exports.big.value), globalDefaults,
                badMemory, badTable, keyedTransfer, descriptors
            ].join('|');
            "#,
            "WebAssembly Lumen boundary",
        )
        .unwrap();

        assert_eq!(
            string_value(&mut engine, "wasmResult"),
            "true|true|8|11|37|46|1|0|2|0|true|1|true|true|true|true|true|true|true|-2|9|true|true|true|true|function,function,global,memory,table;memory,table,global,function,function,function,function,function,function,global;1,2,3"
        );
        let (reported_memories, retained_unavailable, retained_opaque) = engine
            .ctx()
            .host_mut::<HostState>()
            .map(|state| {
                let mut allocations = Vec::new();
                lumen::embed::RetainedExternalMemory::retained_external_memory(
                    state,
                    &mut |allocation| allocations.push(allocation),
                );
                let mut retained = HostRetainedProbe::default();
                state.scan_retained_memory(&mut retained);
                (allocations.len(), retained.unavailable, retained.opaque)
            })
            .unwrap_or((0, usize::MAX, 0));
        assert!(reported_memories >= 2);
        assert_eq!(retained_unavailable, 0);
        assert!(retained_opaque >= 1);
    }

    #[test]
    fn webassembly_memory_descriptor_follows_webidl_dictionary_conversion() {
        // WebAssembly JS API #memories: MemoryDescriptor is { initial, maximum, address }.
        // WebIDL #js-dictionary reads those members once, in lexicographic order, and never
        // reads an unknown member such as the threads proposal's `shared`, so Pyodide's
        // `new WebAssembly.Memory({shared: true, initial: 1, maximum: 1})` probe gets an
        // ordinary memory and its Atomics.wait fallback instead of a TypeError.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r#"
            const reads = [];
            const descriptor = {};
            for (const [name, value] of [["shared", true], ["maximum", 2], ["initial", 1], ["address", "i32"]]) {
                Object.defineProperty(descriptor, name, { get() { reads.push(name); return value; } });
            }
            const memory = new WebAssembly.Memory(descriptor);
            const view = new Int32Array(new WebAssembly.Memory({ shared: true, initial: 1, maximum: 1 }).buffer);
            let wait = "none";
            try { Atomics.wait(view, 0, 0, 0); } catch (error) { wait = error.constructor.name; }
            let required = "none";
            try { new WebAssembly.Memory(null); } catch (error) { required = error.constructor.name; }
            globalThis.memoryDescriptorResult = [
                reads.join(","), memory.buffer.byteLength, memory.grow(1), memory.buffer.byteLength,
                view.buffer instanceof ArrayBuffer, view.length, wait, required
            ].join("|");
            "#,
            "WebAssembly.Memory descriptor",
        )
        .unwrap();
        assert_eq!(
            string_value(&mut engine, "memoryDescriptorResult"),
            "address,initial,maximum|65536|1|131072|true|16384|TypeError|TypeError"
        );
    }

    #[test]
    fn webassembly_large_import_array_keeps_late_bindings() {
        // hCaptcha currently instantiates a module with 168 consecutive function imports. Keep
        // this boundary-sized fixture here so Array construction/push fast paths cannot silently
        // drop a late binding and turn a later callback into a null-property TypeError.
        let import_count = 168;
        let imports = (0..import_count)
            .map(|index| format!("(import \"env\" \"f{index}\" (func $f{index}))"))
            .collect::<Vec<_>>()
            .join("\n");
        let module_wat = format!("(module {imports} (func (export \"call\") call $f162))");
        let module = wat::parse_str(module_wat).unwrap();
        let mut engine = platform_engine();
        engine.set_tier(Tier::Bytecode);
        let fixture = engine
            .ctx()
            .make_uint8array(&module)
            .unwrap_or_else(|_| panic!("make large import wasm fixture"));
        let global = engine.global_this();
        engine
            .ctx()
            .member_set(&global, "largeImportFixture", fixture)
            .unwrap_or_else(|_| panic!("install large import wasm fixture"));
        eval(
            &mut engine,
            r#"
                const largeImportModule = new WebAssembly.Module(largeImportFixture);
                const largeImportNamespace = {};
                for (let i = 0; i < 168; ++i)
                    largeImportNamespace['f' + i] = function () { return undefined; };
                const largeImportInstance = new WebAssembly.Instance(
                    largeImportModule, { env: largeImportNamespace });
                largeImportInstance.exports.call();
                globalThis.largeImportResult = 'ok';
            "#,
            "large WebAssembly import fixture",
        )
        .unwrap();
        assert_eq!(string_value(&mut engine, "largeImportResult"), "ok");
    }

    #[test]
    fn webassembly_legacy_tagged_exceptions_unwind_to_the_matching_catch() {
        // Legacy WebAssembly exception handling: a throw transfers control to the nearest
        // enclosing matching catch and preserves the tag payload on the Wasm operand stack.
        let mut engine = platform_engine();
        let module = wat::parse_str(
            r#"
            (module
              (tag $tag (param i32))
              (func (export "caught") (result i32)
                try (result i32)
                  i32.const 7
                  throw $tag
                catch $tag
                  drop
                  i32.const 42
                end)
              (func (export "uncaught")
                i32.const 9
                throw $tag))
            "#,
        )
        .unwrap();
        let bytes = engine
            .ctx()
            .make_uint8array(&module)
            .unwrap_or_else(|_| panic!("make exception fixture"));
        let global = engine.global_this();
        engine
            .ctx()
            .member_set(&global, "exceptionFixture", bytes)
            .unwrap_or_else(|_| panic!("install exception fixture"));
        eval(
            &mut engine,
            r#"
            const exceptionInstance = new WebAssembly.Instance(
                new WebAssembly.Module(exceptionFixture));
            let uncaught = false;
            try { exceptionInstance.exports.uncaught(); }
            catch (error) { uncaught = !!error; }
            globalThis.exceptionResult = [
                exceptionInstance.exports.caught(), uncaught
            ].join('|');
            "#,
            "WebAssembly legacy exceptions",
        )
        .unwrap();
        assert_eq!(string_value(&mut engine, "exceptionResult"), "42|true");
    }

    #[test]
    fn webassembly_standard_exceptions_keep_exnref_out_of_javascript() {
        // WebAssembly Core 3.0 `try_table`/`throw_ref` run inside Wasm, while the JS API keeps
        // exnref values out of JavaScript: exported functions, host functions, globals and
        // tables of that type throw a TypeError ("call an Exported Function" step 4, "run a
        // host function" step 2, GetGlobalValue, Table.get/set), and Table.grow defaults to
        // null.
        let mut engine = platform_engine();
        install_wasm_test_fixture(
            &mut engine,
            r#"
            (module
              (import "env" "takes" (func $takes (param exnref)))
              (tag $tag (param i32))
              (global (export "g") (mut exnref) (ref.null exn))
              (table (export "t") 1 exnref)
              (func (export "caught") (param i32) (result i32)
                (block $h (result i32)
                  (try_table (catch $tag $h)
                    (throw_ref (block $r (result exnref)
                      (try_table (catch_all_ref $r) (throw $tag (local.get 0)))
                      (unreachable))))
                  (unreachable)))
              (func (export "returns") (result exnref) (ref.null exn))
              (func (export "calls_import") (call $takes (ref.null exn))))
            "#,
        );
        eval(
            &mut engine,
            r#"
            let called = false;
            const instance = new WebAssembly.Instance(new WebAssembly.Module(wasmFixture),
                { env: { takes() { called = true; } } });
            const typeError = (f) => {
                try { f(); return false; } catch (error) { return error instanceof TypeError; }
            };
            const exports = instance.exports;
            globalThis.exnrefResult = [
                exports.caught(5),
                typeError(() => exports.returns()),
                typeError(() => exports.g.value),
                typeError(() => { exports.g.value = null; }),
                typeError(() => exports.t.get(0)),
                typeError(() => exports.t.set(0, null)),
                exports.t.grow(1),
                exports.t.length,
                typeError(() => exports.calls_import()),
                called
            ].join('|');
            "#,
            "WebAssembly exnref boundary",
        )
        .unwrap();
        assert_eq!(
            string_value(&mut engine, "exnrefResult"),
            "5|true|true|true|true|true|1|2|true|false"
        );
    }

    #[test]
    fn webassembly_tag_and_exception_interfaces_follow_web_idl() {
        // WebAssembly JS API #tags, #exceptions and the JSTag attribute (local snapshot of the
        // spec repository 37d6b059) with Web IDL's interface objects, dictionary, sequence,
        // enum and [EnforceRange] conversions, brand checks and [LegacyNamespace] properties.
        for tier in [Tier::Interp, Tier::Bytecode, Tier::Jit] {
            let mut engine = platform_engine();
            engine.set_tier(tier);
            eval(
                &mut engine,
                r#"
                const failures = [];
                const check = (name, condition) => { if (!condition) failures.push(name); };
                const throws = (Ctor, f) => {
                    try { f(); return false; }
                    catch (e) { return e instanceof Ctor && e.constructor === Ctor; }
                };
                const W = WebAssembly, desc = Object.getOwnPropertyDescriptor;
                for (const name of ['Tag', 'Exception']) {
                    const d = desc(W, name);
                    check(name + ' property', d.writable && !d.enumerable && d.configurable);
                    const p = desc(W[name], 'prototype');
                    check(name + ' prototype', !p.writable && !p.enumerable && !p.configurable);
                    check(name + ' constructor', W[name].prototype.constructor === W[name]);
                }
                const jsTag = desc(W, 'JSTag');
                check('JSTag accessor', typeof jsTag.get === 'function' && jsTag.set === undefined &&
                    jsTag.enumerable && jsTag.configurable && jsTag.get.name === 'get JSTag' &&
                    jsTag.get.length === 0);
                check('JSTag identity', W.JSTag === W.JSTag && W.JSTag instanceof W.Tag);
                check('lengths', W.Tag.length === 1 && W.Exception.length === 2 &&
                    W.Tag.name === 'Tag' && W.Exception.name === 'Exception');
                check('Tag class string', Object.prototype.toString.call(new W.Tag({ parameters: [] }))
                    === '[object WebAssembly.Tag]' &&
                    desc(W.Tag.prototype, Symbol.toStringTag).value === 'WebAssembly.Tag');
                // new Tag(type): TagType { required sequence<ValueType> parameters }.
                check('Tag without arguments', throws(TypeError, () => new W.Tag()));
                check('Tag called', throws(TypeError, () => W.Tag({ parameters: [] })));
                for (const bad of [undefined, null, false, 1, 'x', Symbol(), {}, { parameters: 1 }])
                    check('Tag type ' + String(bad), throws(TypeError, () => new W.Tag(bad)));
                for (const bad of ['i16', 'i32\0', 'funcref', 'exnref', 'anyref', Symbol()])
                    check('ValueType ' + String(bad), throws(TypeError, () => new W.Tag({ parameters: [bad] })));
                const every = new W.Tag({
                    parameters: ['i32', 'i64', 'f32', 'f64', 'v128', 'externref', 'anyfunc']
                });
                check('iterable parameters', new W.Tag({ parameters: new Set(['i32']) }) instanceof W.Tag);
                const i32 = new W.Tag({ parameters: ['i32'] });
                check('distinct tags', i32 !== new W.Tag({ parameters: ['i32'] }));
                // new Exception(exceptionTag, payload, options).
                check('Exception arguments', throws(TypeError, () => new W.Exception()) &&
                    throws(TypeError, () => new W.Exception(i32)));
                check('Exception called', throws(TypeError, () => W.Exception(i32, [1])));
                check('Exception tag brand', throws(TypeError, () => new W.Exception({}, [1])) &&
                    throws(TypeError, () => new W.Exception(Object.create(W.Tag.prototype), [1])));
                check('Exception payload', throws(TypeError, () => new W.Exception(i32, 1)));
                check('Exception arity', throws(TypeError, () => new W.Exception(i32, [])) &&
                    throws(TypeError, () => new W.Exception(i32, [1, 2])));
                check('Exception JSTag', throws(TypeError, () => new W.Exception(W.JSTag, [{}])));
                check('Exception v128', throws(TypeError,
                    () => new W.Exception(every, [0, 0n, 0, 0, 0, null, null])));
                check('Exception i64', throws(TypeError,
                    () => new W.Exception(new W.Tag({ parameters: ['i64'] }), [1])));
                check('Exception anyfunc', throws(TypeError,
                    () => new W.Exception(new W.Tag({ parameters: ['anyfunc'] }), [() => {}])));
                check('Exception options', throws(TypeError, () => new W.Exception(i32, [1], 5)));
                const object = {};
                const many = new W.Tag({ parameters: ['i32', 'i64', 'f32', 'f64', 'externref', 'anyfunc'] });
                const e = new W.Exception(many, [{ valueOf() { return 7; } }, 5n, 1.5, -0, object, null]);
                check('getArg values', e.getArg(many, 0) === 7 && e.getArg(many, 1) === 5n &&
                    e.getArg(many, 2) === 1.5 && Object.is(e.getArg(many, 3), -0) &&
                    e.getArg(many, 4) === object && e.getArg(many, 5) === null);
                check('getArg out of bounds', throws(RangeError, () => e.getArg(many, 6)));
                for (const bad of [undefined, NaN, Infinity, -Infinity, -1, 2 ** 32, '0x100000000',
                    { valueOf() { return 2 ** 32; } }, 1n])
                    check('getArg index ' + String(bad), throws(TypeError, () => e.getArg(many, bad)));
                check('getArg conversions', e.getArg(many, 0.9) === 7 && e.getArg(many, '1') === 5n);
                check('getArg arguments', throws(TypeError, () => e.getArg()) &&
                    throws(TypeError, () => e.getArg(many)));
                check('getArg tag', throws(TypeError, () => e.getArg(i32, 0)) &&
                    throws(TypeError, () => e.getArg({}, 0)));
                check('getArg brand', throws(TypeError, () => W.Exception.prototype.getArg.call({}, many, 0)));
                check('is', e.is(many) && !e.is(i32) && throws(TypeError, () => e.is()) &&
                    throws(TypeError, () => e.is({})) &&
                    throws(TypeError, () => W.Exception.prototype.is.call(i32, i32)));
                check('stack', e.stack === undefined &&
                    new W.Exception(i32, [1], { traceStack: false }).stack === undefined &&
                    typeof new W.Exception(i32, [1], { traceStack: true }).stack === 'string');
                check('stack brand', throws(TypeError, () => W.Exception.prototype.stack));
                const proto = W.Exception.prototype;
                check('operations', desc(proto, 'getArg').enumerable && desc(proto, 'getArg').writable &&
                    desc(proto, 'is').enumerable && desc(proto, 'stack').enumerable &&
                    desc(proto, 'stack').set === undefined && proto.getArg.length === 2 &&
                    proto.is.length === 1);
                check('Exception class string', Object.prototype.toString.call(e) ===
                    '[object WebAssembly.Exception]');
                check('not an Error', !(e instanceof Error));
                // HTML #structuredserializeinternal: neither interface is [Serializable].
                for (const value of [i32, e, W.JSTag])
                    check('not serializable', (() => {
                        try { structuredClone(value); return false; }
                        catch (error) { return error.name === 'DataCloneError'; }
                    })());
                globalThis.tagInterfaceResult = failures.join(',') || 'ok';
                "#,
                "WebAssembly exception interfaces",
            )
            .unwrap();
            assert_eq!(
                string_value(&mut engine, "tagInterfaceResult"),
                "ok",
                "{tier:?}"
            );
        }
    }

    #[test]
    fn webassembly_interfaces_and_namespace_follow_web_idl() {
        // WebAssembly JS API #webassembly-namespace, #modules, #instances, #memories, #tables,
        // #globals and #error-objects, and Web API #serialization (local spec repository
        // 37d6b059), with Web IDL #namespace-object, #legacy-namespace, #interface-object,
        // #js-operations, #js-attributes, #dfn-qualified-name and #js-dictionary, and HTML
        // #structuredserializeinternal for the non-[Serializable] interfaces.
        let mut engine = platform_engine();
        install_wasm_test_fixture(
            &mut engine,
            r#"
            (module
              (memory (export "m") 1)
              (table (export "t") 1 funcref)
              (global (export "g") (mut i32) (i32.const 7))
              (func (export "f") (result i32) (i32.const 1)))
            "#,
        );
        eval(
            &mut engine,
            r#"
            const failures = [];
            const check = (name, condition) => { if (!condition) failures.push(name); };
            const throws = (Ctor, f) => {
                try { f(); return false; }
                catch (e) { return e instanceof Ctor; }
            };
            const W = WebAssembly, desc = Object.getOwnPropertyDescriptor;
            const global = desc(globalThis, 'WebAssembly');
            check('global property', global.writable && !global.enumerable && global.configurable);
            check('namespace tag', Object.prototype.toString.call(W) === '[object WebAssembly]');
            for (const [name, length] of [['validate', 1], ['compile', 1], ['instantiate', 1],
                    ['compileStreaming', 1], ['instantiateStreaming', 1]]) {
                const d = desc(W, name);
                check(name + ' operation', d.writable && d.enumerable && d.configurable &&
                    d.value.name === name && d.value.length === length &&
                    !('prototype' in d.value));
                check(name + ' not a constructor', throws(TypeError, () => new d.value(wasmFixture)));
                check(name + ' arguments', throws(TypeError, () => d.value()));
            }
            for (const name of ['Module', 'Instance', 'Memory', 'Table', 'Global', 'Tag', 'Exception',
                    'CompileError', 'LinkError', 'RuntimeError']) {
                const d = desc(W, name);
                check(name + ' property', d.writable && !d.enumerable && d.configurable);
            }
            check('enumerable keys', Object.keys(W).join() ===
                'validate,compile,instantiate,compileStreaming,instantiateStreaming,JSTag');
            const module = new W.Module(wasmFixture);
            const instance = new W.Instance(module, {});
            const memory = new W.Memory({ initial: 1 });
            const table = new W.Table({ element: 'anyfunc', initial: 1 });
            const value = new W.Global({ value: 'i32', mutable: true }, 3);
            const objects = { Module: module, Instance: instance, Memory: memory, Table: table, Global: value };
            const lengths = { Module: 1, Instance: 1, Memory: 1, Table: 1, Global: 1 };
            const members = {
                Module: [], Instance: ['exports'],
                Memory: ['grow', 'toFixedLengthBuffer', 'toResizableBuffer', 'buffer'],
                Table: ['grow', 'get', 'set', 'length'], Global: ['valueOf', 'value'],
            };
            for (const name of Object.keys(objects)) {
                const I = W[name];
                check(name + ' class string', Object.prototype.toString.call(objects[name]) ===
                    '[object WebAssembly.' + name + ']' &&
                    desc(I.prototype, Symbol.toStringTag).value === 'WebAssembly.' + name &&
                    !desc(I.prototype, Symbol.toStringTag).enumerable);
                check(name + ' interface object', I.name === name && I.length === lengths[name] &&
                    Object.getPrototypeOf(I) === Function.prototype &&
                    Object.getPrototypeOf(I.prototype) === Object.prototype &&
                    I.prototype.constructor === I);
                check(name + ' called', throws(TypeError, () => I()));
                for (const member of members[name]) {
                    const d = desc(I.prototype, member);
                    check(name + '.' + member + ' enumerable', d && d.enumerable && d.configurable);
                    const steps = d.get || d.value;
                    check(name + '.' + member + ' brand', throws(TypeError, () => steps.call({})));
                }
                check(name + ' no own properties', Reflect.ownKeys(objects[name]).length === 0);
            }
            for (const name of ['exports', 'imports', 'customSections']) {
                const d = desc(W.Module, name);
                check('Module.' + name, d.enumerable && d.writable && d.configurable);
            }
            check('Module.customSections arguments',
                throws(TypeError, () => W.Module.customSections(module)));
            check('Table lengths', W.Table.prototype.grow.length === 1 &&
                W.Table.prototype.set.length === 1 && W.Table.prototype.get.length === 1);
            check('Instance exports', instance.exports === instance.exports &&
                Object.isFrozen(instance.exports) && instance.exports.f() === 1 &&
                instance.exports.g.value === 7);
            check('Table.set result', table.set(0, null) === undefined);
            // Dictionary members convert once each, in lexicographic order.
            const order = [];
            const recorder = (values) => new Proxy(values, {
                get(target, key) { if (typeof key === 'string') order.push(key); return target[key]; }
            });
            new W.Table(recorder({ element: 'externref', initial: 1, maximum: 2 }));
            new W.Global(recorder({ value: 'i32', mutable: false }));
            new W.Memory(recorder({ initial: 1, maximum: 2 }));
            check('dictionary order ' + order.join(), order.join() ===
                'address,element,initial,maximum,mutable,value,address,initial,maximum');
            check('TableKind', throws(TypeError, () => new W.Table({ element: 'i32', initial: 1 })));
            check('ValueType', throws(TypeError, () => new W.Global({ value: 'i16' })));
            // Only WebAssembly.Module is serializable.
            check('Module clone', structuredClone(module) instanceof W.Module);
            for (const name of ['Instance', 'Memory', 'Table', 'Global']) {
                let error = null;
                try { structuredClone(objects[name]); } catch (e) { error = e; }
                check(name + ' clone', error instanceof DOMException && error.name === 'DataCloneError');
            }
            globalThis.wasmInterfaceResult = failures.join(',') || 'ok';
            "#,
            "WebAssembly interfaces",
        )
        .unwrap();
        assert_eq!(string_value(&mut engine, "wasmInterfaceResult"), "ok");
    }

    const WASM_EXCEPTION_BOUNDARY_FIXTURE: &str = r#"
        (module
          (import "env" "tag" (tag $imported (param i32)))
          (import "env" "js" (func $js (param i32)))
          (import "env" "jsTag" (tag $jsTag (param externref)))
          (tag $own (export "own") (param i32 i64 f64 externref funcref))
          (tag $opaque (export "opaque") (param v128 exnref i32))
          (export "imported" (tag $imported))
          (global $kept (mut exnref) (ref.null exn))
          (func $f (export "f") (result i32) (i32.const 1))
          (elem declare func $f)
          (func (export "throwOwn") (param i32 externref)
            (throw $own (local.get 0) (i64.const -5) (f64.const 2.5) (local.get 1) (ref.func $f)))
          (func (export "throwImported") (param i32) (throw $imported (local.get 0)))
          (func (export "throwOpaque")
            (throw $opaque (v128.const i32x4 1 2 3 4) (ref.null exn) (i32.const 3)))
          (func (export "throwJsTag") (param externref) (throw $jsTag (local.get 0)))
          (func (export "callJs") (param i32) (call $js (local.get 0)))
          (func (export "catchImported") (param i32) (result i32)
            (block $h (result i32)
              (try_table (catch $imported $h) (call $js (local.get 0)))
              (i32.const -1)))
          (func (export "catchJs") (param i32) (result externref)
            (block $h (result externref)
              (try_table (catch $jsTag $h) (call $js (local.get 0)))
              (ref.null extern)))
          (func (export "catchAll") (param i32) (result i32)
            (block $h
              (try_table (catch_all $h) (call $js (local.get 0)))
              (return (i32.const 0)))
            (i32.const 1))
          (func (export "keep") (param i32)
            (global.set $kept
              (block $h (result exnref)
                (try_table (catch_all_ref $h) (call $js (local.get 0)))
                (unreachable))))
          (func (export "rethrow") (throw_ref (global.get $kept)))
          (func (export "clear") (global.set $kept (ref.null exn)))
          (func (export "legacyCatch") (param i32) (result i32)
            try (result i32)
              (call $js (local.get 0))
              i32.const -1
            catch $imported
            end)
          (func (export "trap") (unreachable)))
    "#;

    #[test]
    fn webassembly_exceptions_cross_the_javascript_boundary() {
        // JS API "call an Exported Function" step 11 and "create a host function" step 3.10:
        // Wasm exceptions reach JavaScript as their cached Exception objects (or, for JSTag, the
        // original value), and JavaScript exceptions of imports are catchable in Wasm, keeping
        // their identity when they are thrown back out.
        for tier in [Tier::Interp, Tier::Bytecode, Tier::Jit] {
            let mut engine = platform_engine();
            engine.set_tier(tier);
            install_wasm_test_fixture(&mut engine, WASM_EXCEPTION_BOUNDARY_FIXTURE);
            eval(
                &mut engine,
                r#"
                const failures = [];
                const check = (name, condition) => { if (!condition) failures.push(name); };
                const caught = f => { try { f(); return undefined; } catch (e) { return e; } };
                const tag = new WebAssembly.Tag({ parameters: ['i32'] });
                let mode = 'ok', thrown, last;
                const js = n => {
                    if (mode === 'exception') throw (last = new WebAssembly.Exception(tag, [n]));
                    if (mode === 'value') throw thrown;
                    if (mode === 'trap') x.trap();
                    if (mode === 'nested') x.throwOwn(n, null);
                };
                const module = new WebAssembly.Module(wasmFixture);
                const x = new WebAssembly.Instance(module, {
                    env: { tag, js, jsTag: WebAssembly.JSTag }
                }).exports;
                check('kinds', WebAssembly.Module.imports(module).map(i => i.kind).join() ===
                    'tag,function,tag' && WebAssembly.Module.exports(module)
                        .filter(e => e.kind === 'tag').map(e => e.name).join() === 'own,opaque,imported');
                check('re-exported tag', x.imported === tag);
                check('exported tag', x.own instanceof WebAssembly.Tag && x.own !== tag);
                // Wasm exceptions in JavaScript.
                const object = {};
                const own = caught(() => x.throwOwn(7, object));
                check('Exception object', own instanceof WebAssembly.Exception && !(own instanceof Error));
                check('Exception tag', own.is(x.own) && !own.is(tag) && own.stack === undefined);
                check('Exception payload', own.getArg(x.own, 0) === 7 && own.getArg(x.own, 1) === -5n &&
                    own.getArg(x.own, 2) === 2.5 && own.getArg(x.own, 3) === object &&
                    own.getArg(x.own, 4) === x.f);
                // getArg steps 7 and 9: v128 and exnref fields stay in Wasm.
                const opaque = caught(() => x.throwOpaque());
                check('opaque fields', opaque.getArg(x.opaque, 2) === 3 &&
                    caught(() => opaque.getArg(x.opaque, 0)) instanceof TypeError &&
                    caught(() => opaque.getArg(x.opaque, 1)) instanceof TypeError &&
                    caught(() => opaque.getArg(x.opaque, 3)) instanceof RangeError &&
                    caught(() => new WebAssembly.Exception(x.opaque, [0, null, 0])) instanceof TypeError);
                const imported = caught(() => x.throwImported(3));
                check('imported tag', imported.is(tag) && imported.getArg(tag, 0) === 3);
                check('new exceptions', caught(() => x.throwImported(3)) !== imported);
                check('JSTag payload', caught(() => x.throwJsTag(object)) === object &&
                    caught(() => x.throwJsTag(null)) === null &&
                    caught(() => x.throwJsTag(undefined)) === undefined);
                // JavaScript exceptions in Wasm.
                mode = 'exception';
                check('catch imported', x.catchImported(5) === 5 && x.legacyCatch(6) === 6);
                check('uncaught Exception identity', caught(() => x.catchJs(4)) === last);
                check('direct Exception identity', caught(() => x.callJs(4)) === last);
                check('catch_all', x.catchAll(1) === 1);
                x.keep(9);
                const kept = last;
                kept.marker = 'kept';
                check('rethrown Exception', caught(() => x.rethrow()) === kept);
                mode = 'value';
                thrown = { message: 'value' };
                check('JSTag catch', x.catchJs(0) === thrown);
                check('JSTag identity', caught(() => x.callJs(0)) === thrown &&
                    caught(() => x.catchImported(0)) === thrown);
                x.keep(0);
                check('JSTag rethrow', caught(() => x.rethrow()) === thrown);
                for (const value of [undefined, null, 0, -0, 'text', Symbol.iterator, 1n]) {
                    thrown = value;
                    check('thrown ' + String(value), Object.is(caught(() => x.callJs(0)), value) &&
                        Object.is(x.catchJs(0), value));
                }
                thrown = new TypeError('from JavaScript');
                check('catch_all JavaScript', x.catchAll(0) === 1);
                mode = 'trap';
                const trap = caught(() => x.callJs(0));
                check('trap through JavaScript', trap instanceof WebAssembly.RuntimeError &&
                    x.catchAll(0) === 1);
                mode = 'nested';
                const nested = caught(() => x.callJs(8));
                check('nested exception', nested instanceof WebAssembly.Exception &&
                    nested.is(x.own) && nested.getArg(x.own, 0) === 8);
                x.keep(8);
                check('nested rethrow', caught(() => x.rethrow()) !== nested &&
                    caught(() => x.rethrow()) === caught(() => x.rethrow()));
                mode = 'ok';
                check('no exception', x.catchAll(0) === 0 && x.catchImported(0) === -1);
                // Tag imports require Tag objects.
                const link = imports => caught(() => new WebAssembly.Instance(module, {
                    env: Object.assign({ tag, js, jsTag: WebAssembly.JSTag }, imports)
                }));
                check('tag import kind', link({ tag: {} }) instanceof WebAssembly.LinkError &&
                    link({ tag: 1 }) instanceof WebAssembly.LinkError &&
                    link({ tag: x.f }) instanceof WebAssembly.LinkError);
                check('tag import type', link({ tag: new WebAssembly.Tag({ parameters: ['i64'] }) })
                    instanceof WebAssembly.LinkError && link({ jsTag: tag }) instanceof WebAssembly.LinkError);
                globalThis.boundaryResult = failures.join(',') || 'ok';
                "#,
                "WebAssembly exception boundary",
            )
            .unwrap();
            assert_eq!(
                string_value(&mut engine, "boundaryResult"),
                "ok",
                "{tier:?}"
            );
        }
    }

    #[test]
    fn webassembly_start_function_exceptions_propagate() {
        // JS API "instantiate the core of a WebAssembly module" step 3: the start function's
        // exception propagates as the object it is in JavaScript.
        let mut engine = platform_engine();
        install_wasm_test_fixture(
            &mut engine,
            r#"
            (module
              (import "env" "tag" (tag $t (param i32)))
              (import "env" "start" (func $start (param i32)))
              (func $run (call $start (i32.const 1)) (throw $t (i32.const 2)))
              (start $run))
            "#,
        );
        eval(
            &mut engine,
            r#"
            const tag = new WebAssembly.Tag({ parameters: ['i32'] });
            const value = { start: true };
            let throwing = true;
            const instantiate = () => {
                try {
                    new WebAssembly.Instance(new WebAssembly.Module(wasmFixture), {
                        env: { tag, start() { if (throwing) throw value; } }
                    });
                    return undefined;
                } catch (e) { return e; }
            };
            const first = instantiate();
            throwing = false;
            const second = instantiate();
            globalThis.startResult = [first === value, second instanceof WebAssembly.Exception,
                second.is(tag), second.getArg(tag, 0)].join();
            "#,
            "WebAssembly start function exceptions",
        )
        .unwrap();
        assert_eq!(string_value(&mut engine, "startResult"), "true,true,true,2");
    }

    #[test]
    fn webassembly_exception_objects_keep_identity_then_collect() {
        // JS API #object-caches: while Wasm keeps an exception, its Exception object (and its
        // expandos) survives the loss of every JavaScript reference; once neither side keeps
        // it, the object and the exception are collected.
        for tier in [Tier::Interp, Tier::Bytecode, Tier::Jit] {
            let mut engine = platform_engine();
            engine.set_tier(tier);
            install_wasm_test_fixture(&mut engine, WASM_EXCEPTION_BOUNDARY_FIXTURE);
            eval(
                &mut engine,
                r#"
                const tag = new WebAssembly.Tag({ parameters: ['i32'] });
                let next;
                globalThis.x = new WebAssembly.Instance(new WebAssembly.Module(wasmFixture), {
                    env: { tag, js() { throw next; }, jsTag: WebAssembly.JSTag }
                }).exports;
                (() => {
                    next = new WebAssembly.Exception(tag, [41]);
                    next.marker = 'kept';
                    x.keep(0);
                    next = null;
                    for (let i = 0; i < 100; i++) new WebAssembly.Exception(tag, [i]);
                })();
                "#,
                "WebAssembly Exception object identity",
            )
            .unwrap();
            collect_wasm_test_garbage(&mut engine);
            let (_, exceptions) = engine
                .ctx()
                .host_mut::<HostState>()
                .unwrap()
                .wasm
                .cached_exception_objects();
            assert_eq!(exceptions, 1, "{tier:?}: only the kept Exception object");
            assert_eq!(
                string_value(
                    &mut engine,
                    r#"
                    (() => {
                        let e;
                        try { x.rethrow(); } catch (error) { e = error; }
                        return [e.marker, e.getArg(x.imported, 0)].join();
                    })()
                    "#
                ),
                "kept,41",
                "{tier:?}"
            );
            eval(&mut engine, "x.clear()", "release the exception").unwrap();
            collect_wasm_test_garbage(&mut engine);
            let (_, exceptions) = engine
                .ctx()
                .host_mut::<HostState>()
                .unwrap()
                .wasm
                .cached_exception_objects();
            assert_eq!(exceptions, 0, "{tier:?}: unreachable Exception objects");
        }
    }

    #[test]
    fn webassembly_tags_and_exceptions_keep_agent_identity_across_realms() {
        // JS API #object-caches are per agent: a Tag object imported by an instance of another
        // Realm of the agent is re-exported as itself, and an Exception object keeps its
        // identity through Wasm of another Realm, while instanceof follows each object's Realm.
        let mut engine = platform_engine();
        install_wasm_test_fixture(&mut engine, WASM_EXCEPTION_BOUNDARY_FIXTURE);
        eval(
            &mut engine,
            r##"
            const html = document.createElement("html"), body = document.createElement("body");
            document.appendChild(html); html.appendChild(body);
            const frame = document.createElement("iframe");
            frame.srcdoc = '<body></body>';
            body.appendChild(frame);
            __trust.hydrateFrames();
            const FW = frame.contentWindow.WebAssembly;
            const tag = new WebAssembly.Tag({ parameters: ['i32'] });
            let next;
            const x = new FW.Instance(new FW.Module(wasmFixture), {
                env: { tag, js() { throw next; }, jsTag: FW.JSTag }
            }).exports;
            next = new WebAssembly.Exception(tag, [3]);
            let rethrown;
            x.keep(0);
            try { x.rethrow(); } catch (e) { rethrown = e; }
            let foreign;
            try { x.throwImported(4); } catch (e) { foreign = e; }
            globalThis.realmResult = [
                FW !== WebAssembly, x.imported === tag, tag instanceof WebAssembly.Tag,
                !(tag instanceof FW.Tag), x.own instanceof FW.Tag, FW.JSTag === WebAssembly.JSTag,
                rethrown === next, foreign instanceof FW.Exception,
                !(foreign instanceof WebAssembly.Exception),
                WebAssembly.Exception.prototype.getArg.call(foreign, tag, 0) === 4,
                FW.Exception.prototype.is.call(next, tag)
            ].join();
            "##,
            "WebAssembly exception realms",
        )
        .unwrap();
        assert_eq!(
            string_value(&mut engine, "realmResult"),
            "true,true,true,true,true,true,true,true,true,true,true"
        );
    }

    #[test]
    fn webassembly_exceptions_work_in_workers() {
        // The worker scope reuses the WebAssembly block with its own agent store and JSTag.
        let mut engine = worker_platform_engine();
        install_wasm_test_fixture(&mut engine, WASM_EXCEPTION_BOUNDARY_FIXTURE);
        assert_eq!(
            string_value(
                &mut engine,
                r#"
                (() => {
                    const tag = new WebAssembly.Tag({ parameters: ['i32'] });
                    let thrown;
                    const x = new WebAssembly.Instance(new WebAssembly.Module(wasmFixture), {
                        env: { tag, js() { throw thrown; }, jsTag: WebAssembly.JSTag }
                    }).exports;
                    thrown = new WebAssembly.Exception(tag, [12]);
                    const caught = x.catchImported(0);
                    thrown = 'value';
                    let escaped;
                    try { x.catchImported(0); } catch (e) { escaped = e; }
                    return [caught, escaped, x.imported === tag,
                        typeof __wasm_exception_binding].join();
                })()
                "#
            ),
            "12,value,true,undefined"
        );
    }

    /// A minimal testharness.js for the official WebAssembly JS API tests: `test`,
    /// `promise_test` and the assertions they use, recording one line per subtest. Promises
    /// that `WebAssembly.instantiate` returns are tracked, so that assertions in their
    /// callbacks (as in `exception/identity.tentative.any.js`) fail the run as well.
    const WASM_JS_API_HARNESS: &str = r#"
        globalThis.__results = [];
        globalThis.__pending = [];
        function __record(name, error) {
            __results.push(error === undefined ? 'PASS ' + name
                : 'FAIL ' + name + ': ' + (error && error.message || format_value(error)));
        }
        function test(fn, name) {
            try { fn(); __record(name); } catch (e) { __record(name, e); }
        }
        function promise_test(fn, name) {
            __pending.push(Promise.resolve().then(() => fn())
                .then(() => __record(name), e => __record(name, e)));
        }
        function format_value(v) {
            try { return typeof v === 'symbol' ? v.toString() : String(v); }
            catch (e) { return typeof v; }
        }
        function __fail(message) { throw new Error(message); }
        function assert_true(v, m) { if (v !== true) __fail('assert_true: ' + m); }
        function assert_false(v, m) { if (v !== false) __fail('assert_false: ' + m); }
        function assert_equals(a, b, m) {
            if (!Object.is(a, b)) __fail('assert_equals: ' + format_value(a) + ' vs ' + format_value(b) + ' ' + m);
        }
        function assert_not_equals(a, b, m) { if (Object.is(a, b)) __fail('assert_not_equals: ' + m); }
        function assert_array_equals(a, b, m) {
            if (a.length !== b.length) __fail('assert_array_equals length: ' + m);
            for (let i = 0; i < a.length; i++) assert_equals(a[i], b[i], m);
        }
        function assert_not_reached(m) { __fail('assert_not_reached: ' + m); }
        function assert_own_property(o, p, m) {
            if (!Object.prototype.hasOwnProperty.call(o, p)) __fail('assert_own_property: ' + String(p));
        }
        function assert_class_string(o, c, m) {
            const s = Object.prototype.toString.call(o);
            if (s !== '[object ' + c + ']') __fail('assert_class_string: ' + s);
        }
        function assert_throws_js(C, f, m) {
            try { f(); } catch (e) {
                if (e !== null && typeof e === 'object' && e.constructor === C && e instanceof C) return;
                __fail('assert_throws_js: ' + format_value(e) + ' ' + m);
            }
            __fail('assert_throws_js: nothing thrown ' + m);
        }
        function assert_throws_exactly(v, f, m) {
            try { f(); } catch (e) {
                if (Object.is(e, v)) return;
                __fail('assert_throws_exactly: ' + format_value(e) + ' ' + m);
            }
            __fail('assert_throws_exactly: nothing thrown ' + m);
        }
        const __instantiate = WebAssembly.instantiate;
        WebAssembly.instantiate = function () {
            const promise = Reflect.apply(__instantiate, this, arguments);
            const then = promise.then;
            promise.then = function (onFulfilled, onRejected) {
                const derived = Reflect.apply(then, promise, [onFulfilled, onRejected]);
                __pending.push(derived.then(undefined, e => __record('instantiate callback', e)));
                return derived;
            };
            return promise;
        };
    "#;

    #[test]
    #[ignore]
    fn webassembly_official_exception_js_api_tests() {
        // `WASM_JS_API_DIR=/big/web-standards/repositories/WebAssembly/spec/test/js-api`:
        // the official tag and exception tests of the WebAssembly JS API in every tier.
        let dir = std::env::var_os("WASM_JS_API_DIR").expect("set WASM_JS_API_DIR");
        let dir = std::path::Path::new(&dir);
        let read = |name: &str| std::fs::read_to_string(dir.join(name)).unwrap();
        let builder = read("wasm-module-builder.js");
        let assertions = read("assertions.js");
        let files = [
            "tag/constructor.tentative.any.js",
            "tag/toString.tentative.any.js",
            "exception/basic.tentative.any.js",
            "exception/constructor.tentative.any.js",
            "exception/getArg.tentative.any.js",
            "exception/identity.tentative.any.js",
            "exception/is.tentative.any.js",
            "exception/jsTag.tentative.any.js",
            "exception/toString.tentative.any.js",
        ];
        let mut failures = Vec::new();
        for tier in [Tier::Interp, Tier::Bytecode, Tier::Jit] {
            let (mut passed, mut total) = (0, 0);
            for file in files {
                let mut engine = platform_engine();
                engine.set_tier(tier);
                for (source, label) in [
                    (WASM_JS_API_HARNESS, "harness"),
                    (builder.as_str(), "wasm-module-builder.js"),
                    (assertions.as_str(), "assertions.js"),
                ] {
                    eval(&mut engine, source, label).unwrap();
                }
                if let Err(error) = eval(&mut engine, &read(file), file) {
                    failures.push(format!("{tier:?} {file}: {error}"));
                    continue;
                }
                // Settle the promise tests and their tracked callbacks.
                for _ in 0..8 {
                    run_microtask_checkpoint(&mut engine);
                }
                let results = string_value(&mut engine, "__results.join('\\n')");
                for line in results.lines() {
                    total += 1;
                    if line.starts_with("PASS ") {
                        passed += 1;
                    } else {
                        failures.push(format!("{tier:?} {file}: {line}"));
                    }
                }
            }
            std::println!("{tier:?}: {passed}/{total} subtests passed");
        }
        assert!(failures.is_empty(), "{}", failures.join("\n"));
    }

    fn install_wasm_test_fixture(engine: &mut lumen::Engine, source: &str) {
        let bytes = wat::parse_str(source).unwrap();
        let fixture = engine
            .ctx()
            .make_uint8array(&bytes)
            .unwrap_or_else(|_| panic!("make WASM test fixture"));
        let global = engine.global_this();
        engine
            .ctx()
            .member_set(&global, "wasmFixture", fixture)
            .unwrap_or_else(|_| panic!("install WASM test fixture"));
    }

    fn collect_wasm_test_garbage(engine: &mut lumen::Engine) {
        // Clear kept objects, collect, deliver finalizers, then collect their held values.
        // Compare heap counts at the same completed host boundary in every test batch.
        for _ in 0..3 {
            run_microtask_checkpoint(engine);
            engine.ctx().collect_garbage_for_host();
        }
    }

    fn cached_wasm_functions(engine: &mut lumen::Engine) -> usize {
        engine
            .ctx()
            .host_mut::<HostState>()
            .unwrap()
            .wasm
            .cached_functions()
    }

    #[test]
    fn webassembly_sibling_exports_keep_identity_then_collect_together() {
        for tier in [Tier::Interp, Tier::Bytecode, Tier::Jit] {
            let mut engine = platform_engine();
            engine.set_tier(tier);
            install_wasm_test_fixture(
                &mut engine,
                r#"
                (module
                    (func $f (export "f") (param i32) (result i32) local.get 0)
                    (elem declare func $f)
                    (func (export "again") (result funcref) ref.func $f))
            "#,
            );
            eval(
                &mut engine,
                r#"
                let again;
                (() => {
                    const e = new WebAssembly.Instance(new WebAssembly.Module(wasmFixture)).exports;
                    e.f.marker = 'original';
                    e.f.cycle = e;
                    again = e.again;
                })();
            "#,
                "sibling-only WASM reachability",
            )
            .unwrap();
            collect_wasm_test_garbage(&mut engine);
            assert_eq!(
                string_value(
                    &mut engine,
                    "again().marker + ':' + again().length + ':' + again()(42)"
                ),
                "original:1:42",
                "{tier:?}"
            );
            assert_eq!(cached_wasm_functions(&mut engine), 2);
            eval(&mut engine, "again = null", "release WASM function group").unwrap();
            collect_wasm_test_garbage(&mut engine);
            assert_eq!(
                cached_wasm_functions(&mut engine),
                0,
                "{tier:?}: unreachable group"
            );
        }
    }

    #[test]
    fn webassembly_native_reference_containers_keep_wrapper_identity() {
        // Exercise core-written, UNEXPORTED state, not just JS Table.set / Global.value.
        for tier in [Tier::Interp, Tier::Bytecode, Tier::Jit] {
            let mut engine = platform_engine();
            engine.set_tier(tier);
            install_wasm_test_fixture(
                &mut engine,
                r#"
                (module
                    (table 1 funcref)
                    (global $held (mut funcref) (ref.null func))
                    (func (export "save") (param funcref)
                        i32.const 0 local.get 0 table.set
                        local.get 0 global.set $held)
                    (func (export "fromTable") (result funcref) i32.const 0 table.get)
                    (func (export "fromGlobal") (result funcref) global.get $held)
                    (func (export "clearTable") i32.const 0 ref.null func table.set)
                    (func (export "clearGlobal") ref.null func global.set $held))
            "#,
            );
            eval(&mut engine,
                "const keeper = new WebAssembly.Instance(new WebAssembly.Module(wasmFixture)).exports;",
                "private WASM reference containers").unwrap();
            install_wasm_test_fixture(
                &mut engine,
                r#"
                (module (func (export "f") (param i32) (result i32) local.get 0))
            "#,
            );
            eval(&mut engine, r#"
                (() => {
                    const f = new WebAssembly.Instance(new WebAssembly.Module(wasmFixture)).exports.f;
                    f.marker = 'native-held';
                    keeper.save(f);
                })();
            "#, "core table/global writes").unwrap();
            collect_wasm_test_garbage(&mut engine);
            assert_eq!(
                string_value(
                    &mut engine,
                    r#"
                [keeper.fromTable() === keeper.fromGlobal(), keeper.fromTable().marker,
                    keeper.fromGlobal().length, keeper.fromTable()(42)].join(':')
            "#
                ),
                "true:native-held:1:42",
                "{tier:?}"
            );
            assert_eq!(cached_wasm_functions(&mut engine), 6);
            eval(
                &mut engine,
                "keeper.clearGlobal()",
                "leave only native table reference",
            )
            .unwrap();
            collect_wasm_test_garbage(&mut engine);
            assert_eq!(
                string_value(&mut engine, "keeper.fromTable().marker"),
                "native-held"
            );
            eval(
                &mut engine,
                "keeper.save(keeper.fromTable()); keeper.clearTable()",
                "leave only native global reference",
            )
            .unwrap();
            collect_wasm_test_garbage(&mut engine);
            assert_eq!(
                string_value(&mut engine, "keeper.fromGlobal().marker"),
                "native-held"
            );
            eval(&mut engine, "keeper.clearGlobal()", "clear native funcrefs").unwrap();
            collect_wasm_test_garbage(&mut engine);
            assert_eq!(
                cached_wasm_functions(&mut engine),
                5,
                "{tier:?}: cleared foreign function"
            );
        }
    }

