    #[test]
    fn blob_url_store_is_shared_by_a_page_and_its_workers() {
        // File API (local w3c/FileAPI@1341d26) #url-model, #blob-url-resolve,
        // #blob-url-obtain-object, #dfn-revokeObjectURL and #lifeTime, with URL
        // #concept-url-parser and Fetch #scheme-fetch: one store for the page's
        // Window and workers; Worker/SharedWorker construction, importScripts,
        // fetch, XHR, <img>, <script> and <iframe> resolve each other's URLs;
        // revocation crosses agents but not partitions; a parsed URL keeps its
        // entry; and a worker's entries leave the store when it ends.
        let (runtime, mut engine, mut task_rx) = worker_test_environment();
        eval(
            &mut engine,
            include_str!("fixtures/worker_blob_urls.mjs"),
            "blob URL store",
        )
        .unwrap();
        let log = pump_page_with_workers(
            &runtime,
            &mut engine,
            &mut task_rx,
            "blobDone",
            "blobLog.join('|')",
            Duration::from_secs(30),
        );
        assert_eq!(
            log,
            "worker-from-revoked-url|worker-used:from-window,from-window,7,nested-ok|\
             worker-url-origin:true:true|window-fetch:from-worker:from-worker|\
             window-worker:worker-made-worker|\
             worker-after-window-revoke:TypeError|window-after-worker-revoke:TypeError|\
             races:race-request,race-xhr,race-fetch,TypeError|shared:shared-ok|\
             partition:TypeError:true:TypeError|held:held"
        );
        let store = engine.ctx().host_mut::<HostState>().unwrap().blobs.clone();
        let held = string_value(&mut engine, "heldURL");
        let kept = string_value(&mut engine, "keptURL");
        assert!(store.resolve(&held).is_some() && store.resolve(&kept).is_some());
        eval(&mut engine, "blobWorker.terminate()", "end the worker").unwrap();
        let deadline = Instant::now() + Duration::from_secs(10);
        while store.resolve(&held).is_some() {
            assert!(Instant::now() < deadline, "the ended worker's entry stayed");
            pump_page_for(
                &runtime,
                &mut engine,
                &mut task_rx,
                Duration::from_millis(20),
            );
        }
        assert!(
            store.resolve(&kept).is_some(),
            "the Window's own entries remain"
        );
    }

    #[test]
    fn blob_urls_of_selected_files_stay_unread_until_consumed() {
        // File API #blob-url-entry and #snapshot-state: a URL for a selected
        // file keeps the file's range, not its bytes. A worker reads it
        // lazily through the page's store; once the file changes on disk,
        // every later read fails instead of serving a stale copy.
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("picked.txt");
        std::fs::write(&path, b"dropped!").unwrap();
        let (runtime, mut engine, mut task_rx) = worker_test_environment();
        let file = crate::file_select::SelectedFile::from_path(&path, String::new()).unwrap();
        let id = engine
            .ctx()
            .host_mut::<HostState>()
            .unwrap()
            .user_files
            .register(&file)
            .unwrap();
        eval(
            &mut engine,
            &format!(
                r#"
            if (!document.documentElement) document.appendChild(document.createElement('html'));
            if (!document.body) document.documentElement.appendChild(document.createElement('body'));
            globalThis.zone = document.createElement('div');
            document.body.appendChild(zone);
            for (const type of ['dragenter', 'dragover']) zone.addEventListener(type, e => e.preventDefault());
            zone.addEventListener('drop', e => {{ e.preventDefault(); globalThis.picked = e.dataTransfer.files[0]; }});
            __trust.fileDrag('enter', ['text/plain']);
            __trust.fileDrag('over', zone.__id, 5, 5, 5, 5, 0);
            __trust.fileDrag('drop', zone.__id, 6, 6, 6, 6, 0, [[{id}, 'picked.txt', 'text/plain', 8, 0, '', false]]);
            globalThis.fileURL = URL.createObjectURL(picked);
            globalThis.fileLog = [];
            globalThis.reader = new Worker(URL.createObjectURL(new Blob([`
                onmessage = async (event) => {{
                    try {{ postMessage(await (await fetch(event.data)).text()); }}
                    catch (error) {{ postMessage(error.name); }}
                }};
            `], {{type: 'text/javascript'}})));
            reader.onmessage = event => fileLog.push('worker:' + event.data);
            reader.postMessage(fileURL);
            "#
            ),
            "selected file blob URL",
        )
        .unwrap();
        let url = string_value(&mut engine, "fileURL");
        let store = engine.ctx().host_mut::<HostState>().unwrap().blobs.clone();
        let entry = store
            .resolve(&url)
            .expect("the store has the selected file's entry");
        assert!(
            matches!(
                entry.parts.as_slice(),
                [crate::blob_url_store::BlobPart::File(range)] if range.len() == 8
            ),
            "the entry keeps an unread range"
        );
        let log = pump_page_with_workers(
            &runtime,
            &mut engine,
            &mut task_rx,
            "fileLog.length === 1",
            "fileLog.join('|')",
            Duration::from_secs(20),
        );
        assert_eq!(log, "worker:dropped!");
        // A changed file no longer matches the selection's snapshot state.
        std::fs::write(&path, b"changed!").unwrap();
        let file = std::fs::File::options().write(true).open(&path).unwrap();
        file.set_modified(std::time::SystemTime::UNIX_EPOCH + Duration::from_secs(86_400))
            .unwrap();
        eval(
            &mut engine,
            r#"
            fetch(fileURL).then(r => r.text()).then(t => fileLog.push('window:' + t), e => fileLog.push('window:' + e.name));
            reader.postMessage(fileURL);
            "#,
            "changed file",
        )
        .unwrap();
        let log = pump_page_with_workers(
            &runtime,
            &mut engine,
            &mut task_rx,
            "fileLog.length === 3",
            "fileLog.slice(1).sort().join('|')",
            Duration::from_secs(20),
        );
        // Fetch #concept-body-consume-body rejects with the Blob stream's
        // error (File API #blob-get-stream: the read's NotReadableError).
        assert_eq!(log, "window:NotReadableError|worker:NotReadableError");
        eval(&mut engine, "reader.terminate()", "cleanup").unwrap();
    }

    #[test]
    fn nested_worker_requests_use_the_owning_workers_referrer() {
        // HTML #dom-worker and #fetch-a-classic-worker-script: a nested
        // worker's script request has the owning worker's settings as its
        // client, so Fetch #determine-requests-referrer uses that worker's URL
        // under its referrer policy (HTML #run-a-worker: from the script
        // response, Referrer-Policy #parse-referrer-policy-from-header, or
        // inherited for a blob: script URL). A worker's own fetches use its
        // own URL; a blob: URL is a local scheme and sends no referrer.
        use tokio::io::{AsyncReadExt as _, AsyncWriteExt as _};
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .enable_all()
            .build()
            .unwrap();
        let listener = runtime
            .block_on(tokio::net::TcpListener::bind("127.0.0.1:0"))
            .unwrap();
        let base = format!("http://{}", listener.local_addr().unwrap());
        let page = url::Url::parse(&format!("{base}/page.html")).unwrap();
        let outer = r#"
            const tag = location.pathname.includes("origin") ? "origin" : "outer";
            fetch("/" + tag + "-data").then(() => {
                const nested = new Worker("/inner.js?" + tag);
                nested.onmessage = () => {
                    if (tag !== "origin") { postMessage(tag + "-done"); return; }
                    const local = new Worker(URL.createObjectURL(new Blob(
                        ["fetch(self.origin + '/blob-data').then(() => postMessage('blob-done'))"], {type: "text/javascript"})));
                    local.onmessage = () => postMessage(tag + "-done");
                };
            });
        "#;
        let inner =
            r#"fetch("/inner-data" + location.search).then(() => postMessage("inner-done"));"#;
        let seen = Arc::new(std::sync::Mutex::new(Vec::<String>::new()));
        let record = seen.clone();
        let server = runtime.spawn(async move {
            for _ in 0..9 {
                let (mut stream, _) =
                    tokio::time::timeout(Duration::from_secs(20), listener.accept())
                        .await
                        .unwrap()
                        .unwrap();
                let mut request = Vec::new();
                let mut bytes = [0; 4096];
                while !request.windows(4).any(|part| part == b"\r\n\r\n") {
                    let count = tokio::time::timeout(Duration::from_secs(20), stream.read(&mut bytes))
                        .await
                        .unwrap()
                        .unwrap();
                    assert_ne!(count, 0);
                    request.extend_from_slice(&bytes[..count]);
                }
                let head = String::from_utf8_lossy(&request).into_owned();
                let path = head.split_whitespace().nth(1).unwrap_or("").to_string();
                let referer = head
                    .lines()
                    .find_map(|line| {
                        line.split_once(':')
                            .filter(|(name, _)| name.eq_ignore_ascii_case("referer"))
                            .map(|(_, value)| value.trim().to_string())
                    })
                    .unwrap_or_else(|| String::from("none"));
                record.lock().unwrap().push(format!("{path} {referer}"));
                let (mime, body, policy) = match path.as_str() {
                    "/outer.js" => ("text/javascript", outer, ""),
                    "/outer-origin.js" => ("text/javascript", outer, "Referrer-Policy: origin\r\n"),
                    p if p.starts_with("/inner.js") => ("text/javascript", inner, ""),
                    _ => ("text/plain", "data", ""),
                };
                let response = format!(
                    "HTTP/1.1 200 OK\r\nContent-Type: {mime}\r\nContent-Length: {}\r\n{policy}Cache-Control: no-store\r\nConnection: close\r\n\r\n{body}",
                    body.len()
                );
                stream.write_all(response.as_bytes()).await.unwrap();
            }
        });
        let (task_tx, mut task_rx) = tokio::sync::mpsc::unbounded_channel();
        let mut state = HostState::new(
            Rc::new(RefCell::new(Dom::new())),
            Rc::new(RealmClock::new()),
        );
        state.enable_network(
            page.clone(),
            runtime.handle().clone(),
            Arc::default(),
            task_tx,
        );
        let mut engine = configured_engine(state, page.as_str());
        eval(
            &mut engine,
            r#"
            globalThis.refLog = [];
            globalThis.refWorkers = ['/outer.js', '/outer-origin.js'].map(url => {
                const worker = new Worker(url);
                worker.onmessage = event => refLog.push(event.data);
                worker.onerror = event => refLog.push('error:' + event.message);
                return worker;
            });
            "#,
            "referrer workers",
        )
        .unwrap();
        let log = pump_page_with_workers(
            &runtime,
            &mut engine,
            &mut task_rx,
            "refLog.length === 2",
            "refLog.slice().sort().join('|')",
            Duration::from_secs(30),
        );
        assert_eq!(log, "origin-done|outer-done");
        runtime.block_on(server).unwrap();
        let mut seen = seen.lock().unwrap().clone();
        seen.sort();
        assert_eq!(
            seen,
            [
                String::from("/blob-data none"),
                format!("/inner-data?origin {base}/inner.js?origin"),
                format!("/inner-data?outer {base}/inner.js?outer"),
                format!("/inner.js?origin {base}/"),
                format!("/inner.js?outer {base}/outer.js"),
                format!("/origin-data {base}/"),
                format!("/outer-data {base}/outer.js"),
                format!("/outer-origin.js {base}/page.html"),
                format!("/outer.js {base}/page.html"),
            ]
        );
        eval(
            &mut engine,
            "refWorkers.forEach(worker => worker.terminate())",
            "cleanup",
        )
        .unwrap();
    }

    fn worker_test_environment() -> (
        tokio::runtime::Runtime,
        lumen::Engine,
        tokio::sync::mpsc::UnboundedReceiver<LumenHostTask>,
    ) {
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .enable_all()
            .build()
            .unwrap();
        let page = url::Url::parse(DEFAULT_URL).unwrap();
        let (task_tx, task_rx) = tokio::sync::mpsc::unbounded_channel();
        let mut state = HostState::new(
            Rc::new(RefCell::new(Dom::new())),
            Rc::new(RealmClock::new()),
        );
        state.enable_network(
            page.clone(),
            runtime.handle().clone(),
            Arc::new(crate::http::PageCache::default()),
            task_tx,
        );
        (runtime, configured_engine(state, page.as_str()), task_rx)
    }

    #[test]
    fn shared_workers_connect_matching_constructors_through_message_ports() {
        // HTML #shared-workers-and-the-sharedworker-interface and
        // #shared-workers-and-the-sharedworkerglobalscope-interface (local
        // whatwg/html@e5071a2): constructors with the same origin, URL and name
        // share one global, each connecting with a fresh port and a connect event;
        // a type mismatch fires error and does not connect.
        let (runtime, mut engine, mut task_rx) = worker_test_environment();
        eval(
            &mut engine,
            r#"
            globalThis.sharedResults = [];
            const url = URL.createObjectURL(new Blob([`
                let connections = 0;
                onconnect = event => {
                    const port = event.ports[0];
                    connections++;
                    port.postMessage([connections, self instanceof SharedWorkerGlobalScope,
                        self instanceof WorkerGlobalScope, typeof postMessage, typeof onmessage, self.name,
                        event.source === port, event.data, Object.isFrozen(event.ports), event.isTrusted,
                        event instanceof MessageEvent].join());
                    port.onmessage = message => port.postMessage('echo:' + message.data);
                };
            `], {type: 'text/javascript'}));
            const check = (ok, message) => { if (!ok) throw Error(message); };
            check(typeof SharedWorker === 'function' && SharedWorker.length === 1, 'SharedWorker interface');
            check(Object.getPrototypeOf(SharedWorker) === EventTarget, 'SharedWorker inherits EventTarget');
            check(Object.prototype.toString.call(SharedWorker.prototype) === '[object SharedWorker]', 'tag');
            try { new SharedWorker('https://[bad'); throw Error('invalid URL accepted'); }
            catch (error) { check(error.name === 'SyntaxError', 'invalid URL: ' + error.name); }
            try { new SharedWorker(url, {type: 'shared'}); throw Error('invalid type accepted'); }
            catch (error) { check(error.name === 'TypeError', 'invalid type: ' + error.name); }
            const first = new SharedWorker(url, 'counter');
            const second = new SharedWorker(url, {name: 'counter'});
            const other = new SharedWorker(url, {name: 'other'});
            const mismatch = new SharedWorker(url, {name: 'counter', type: 'module'});
            check(first.port instanceof MessagePort && first.port === first.port && first.port !== second.port,
                'per-object outside ports');
            check(Object.getOwnPropertyNames(first).length === 0, 'no own SharedWorker properties');
            first.port.onmessage = event => sharedResults.push('first:' + event.data);
            second.port.onmessage = event => sharedResults.push('second:' + event.data);
            other.port.onmessage = event => sharedResults.push('other:' + event.data);
            mismatch.onerror = event => sharedResults.push('mismatch:' + event.type + ':' + event.isTrusted);
            mismatch.port.onmessage = event => sharedResults.push('mismatch-message');
            "#,
            "shared workers",
        )
        .unwrap();
        let deadline = Instant::now() + Duration::from_secs(20);
        let mut echoed = false;
        loop {
            let log = string_value(&mut engine, "sharedResults.join('|')");
            if !echoed && log.matches("first:").count() == 1 && log.contains("second:") {
                eval(&mut engine, "first.port.postMessage('ping')", "shared ping").unwrap();
                echoed = true;
            }
            if log.contains("first:echo:ping")
                && log.contains("other:")
                && log.contains("mismatch:")
            {
                break;
            }
            assert!(Instant::now() < deadline, "shared workers stalled: {log}");
            if matches!(
                engine_call_trust_method(&mut engine, "hasPlatformTask", &[]),
                Ok(Value::Bool(true))
            ) {
                engine_call_trust_method(&mut engine, "runPlatformTask", &[]).unwrap_or_else(
                    |error| panic!("{}", describe_eval_error(&mut engine, error, "shared task")),
                );
            } else if let Ok(Some(task)) = runtime.block_on(async {
                tokio::time::timeout(Duration::from_millis(200), task_rx.recv()).await
            }) {
                dispatch_host_task(&mut engine, task).unwrap();
            }
            run_microtask_checkpoint(&mut engine);
        }
        let log = string_value(&mut engine, "sharedResults.join('|')");
        let mut entries: Vec<_> = log.split('|').collect();
        entries.sort_unstable();
        assert_eq!(
            entries,
            [
                "first:1,true,true,undefined,undefined,counter,true,,true,true,true",
                "first:echo:ping",
                "mismatch:error:true",
                "other:1,true,true,undefined,undefined,other,true,,true,true,true",
                "second:2,true,true,undefined,undefined,counter,true,,true,true,true",
            ],
            "{log}"
        );
        let workers = engine
            .ctx()
            .host_mut::<HostState>()
            .unwrap()
            .workers
            .as_ref()
            .unwrap()
            .workers
            .len();
        assert_eq!(workers, 2, "one global per origin, URL and name");
    }

    #[test]
    fn workers_have_no_count_quota_and_release_resources_on_close_and_terminate() {
        // WHATWG HTML snapshot e5071a20 (2026-09-06), #worker-processing-model:
        // every constructor creates an independent agent; self.close() and
        // terminate() retire its realm and queued work. Keep >16 agents live at
        // once so a lifetime counter or the former simultaneous quota cannot pass.
        let (runtime, mut engine, mut task_rx) = worker_test_environment();
        eval(
            &mut engine,
            r#"
            globalThis.pool = [];
            globalThis.replies = [];
            globalThis.workerErrors = [];
            const url = URL.createObjectURL(new Blob([
                'onmessage = e => { if (e.data === "close") close(); else postMessage(e.data); };'
            ], {type:'text/javascript'}));
            for (let index = 0; index < 32; index++) {
                const worker = new Worker(url);
                worker.onmessage = event => replies.push(event.data);
                worker.onerror = event => workerErrors.push(event.message);
                pool.push(worker);
                worker.postMessage(index);
            }
            URL.revokeObjectURL(url);
        "#,
            "uncapped workers",
        )
        .unwrap();
        let scopes = engine
            .ctx()
            .host_mut::<HostState>()
            .unwrap()
            .workers
            .as_ref()
            .unwrap()
            .workers
            .values()
            .map(|worker| Arc::downgrade(&worker.tasks))
            .collect::<Vec<_>>();
        assert_eq!(scopes.len(), 32);
        for _ in 0..32 {
            let task = runtime
                .block_on(async {
                    tokio::time::timeout(Duration::from_secs(30), task_rx.recv()).await
                })
                .expect("every worker replies")
                .unwrap();
            assert!(matches!(
                task,
                LumenHostTask::Worker {
                    event: crate::js::WorkerOut::Message(_),
                    ..
                }
            ));
            dispatch_host_task(&mut engine, task).unwrap();
            run_microtask_checkpoint(&mut engine);
        }
        assert_eq!(string_value(&mut engine, "workerErrors.join('|')"), "");
        assert_eq!(
            string_value(&mut engine, "replies.sort((a,b) => a-b).join(',')"),
            (0..32).map(|i| i.to_string()).collect::<Vec<_>>().join(",")
        );
        eval(
            &mut engine,
            r#"
            pool.forEach((worker, index) => {
                if (index % 2) worker.terminate();
                else worker.postMessage('close');
            });
        "#,
            "worker cleanup",
        )
        .unwrap();
        for _ in 0..32 {
            let task = runtime
                .block_on(async {
                    tokio::time::timeout(Duration::from_secs(15), task_rx.recv()).await
                })
                .expect("every worker exits")
                .unwrap();
            assert!(matches!(task, LumenHostTask::WorkerExited { .. }));
            dispatch_host_task(&mut engine, task).unwrap();
        }
        assert!(
            engine
                .ctx()
                .host_mut::<HostState>()
                .unwrap()
                .workers
                .as_ref()
                .unwrap()
                .workers
                .is_empty()
        );
        assert!(scopes.iter().all(|scope| scope.upgrade().is_none()));
        assert_eq!(
            string_value(&mut engine, "String(Object.keys(__trust.workers).length)"),
            "0",
            "closed agents must not retain their Worker wrappers and listeners"
        );
    }

    #[test]
    fn worker_default_stack_supports_deep_execution_and_startup_errors_are_async() {
        let (runtime, mut engine, mut task_rx) = worker_test_environment();
        WORKER_SPAWN_FAILURE.set(Some(std::io::ErrorKind::WouldBlock));
        eval(&mut engine, r#"
            globalThis.workerErrors = [];
            globalThis.broken = new Worker('data:text/javascript,');
            broken.onerror = event => {
                event.preventDefault();
                workerErrors.push([event.isTrusted, event.target === broken,
                    event instanceof ErrorEvent, event.message.includes('worker thread creation failed')].join('|'));
            };
        "#, "OS worker resource exhaustion").unwrap();
        assert_eq!(string_value(&mut engine, "workerErrors.join(',')"), "");
        for _ in 0..2 {
            let task = task_rx
                .try_recv()
                .expect("startup failure queues error then exit");
            dispatch_host_task(&mut engine, task).unwrap();
            run_microtask_checkpoint(&mut engine);
        }
        assert_eq!(
            string_value(&mut engine, "workerErrors.join(',')"),
            "true|true|true|true"
        );
        assert_eq!(
            string_value(&mut engine, "String(Object.keys(__trust.workers).length)"),
            "0"
        );
        assert!(
            engine
                .ctx()
                .host_mut::<HostState>()
                .unwrap()
                .workers
                .as_ref()
                .unwrap()
                .workers
                .is_empty()
        );

        // A subsequent worker still starts. Non-tail recursion needs on-demand
        // stack segments rather than a 64 MiB reservation on every idle thread.
        eval(
            &mut engine,
            r#"
            globalThis.deepResult = '';
            globalThis.deep = new Worker(URL.createObjectURL(new Blob([
                'function recurse(n) { return n === 0 ? 0 : 1 + recurse(n - 1); }' +
                'postMessage(recurse(2048)); close();'
            ], {type:'text/javascript'})));
            deep.onmessage = event => { deepResult = String(event.data); };
            deep.onerror = event => { deepResult = event.message; };
        "#,
            "on-demand worker execution stack",
        )
        .unwrap();
        for _ in 0..2 {
            let task = runtime
                .block_on(async {
                    tokio::time::timeout(Duration::from_secs(30), task_rx.recv()).await
                })
                .expect("deep worker completes")
                .unwrap();
            dispatch_host_task(&mut engine, task).unwrap();
            run_microtask_checkpoint(&mut engine);
        }
        assert_eq!(string_value(&mut engine, "deepResult"), "2048");
    }

    #[test]
    fn worker_startup_failure_and_exit_cleanup_belong_to_the_constructor_realm() {
        let (_runtime, mut engine, mut task_rx) = worker_test_environment();
        WORKER_SPAWN_FAILURE.set(Some(std::io::ErrorKind::OutOfMemory));
        eval(
            &mut engine,
            r#"
            const html = document.createElement('html'), body = document.createElement('body');
            document.appendChild(html); html.appendChild(body);
            const frame = document.createElement('iframe');
            frame.srcdoc = '<body>worker owner</body>';
            body.appendChild(frame);
            __trust.hydrateFrames();
            globalThis.ownerWindow = frame.contentWindow;
            ownerWindow.eval(`
                globalThis.errorResult = '';
                globalThis.broken = new Worker('data:text/javascript,');
                broken.onerror = event => {
                    event.preventDefault();
                    errorResult = [event.isTrusted, event.target === broken,
                        event instanceof ErrorEvent].join('|');
                };
            `);
        "#,
            "iframe worker resource failure",
        )
        .unwrap();
        assert_eq!(string_value(&mut engine, "ownerWindow.errorResult"), "");
        for _ in 0..2 {
            dispatch_host_task(&mut engine, task_rx.try_recv().unwrap()).unwrap();
            run_microtask_checkpoint(&mut engine);
        }
        assert_eq!(
            string_value(&mut engine, "ownerWindow.errorResult"),
            "true|true|true"
        );
        assert_eq!(
            string_value(
                &mut engine,
                "ownerWindow.eval('String(Object.keys(__trust.workers).length)')"
            ),
            "0"
        );
        WORKER_SPAWN_FAILURE.set(Some(std::io::ErrorKind::WouldBlock));
        eval(
            &mut engine,
            r#"
            ownerWindow.eval(`
                globalThis.cancelled = new Worker('data:text/javascript,');
                cancelled.onerror = () => { errorResult = 'unexpected error after termination'; };
                cancelled.terminate();
            `);
        "#,
            "terminate before startup error dispatch",
        )
        .unwrap();
        for _ in 0..2 {
            dispatch_host_task(&mut engine, task_rx.try_recv().unwrap()).unwrap();
            run_microtask_checkpoint(&mut engine);
        }
        assert_eq!(
            string_value(&mut engine, "ownerWindow.errorResult"),
            "true|true|true"
        );
    }

    #[test]
    fn worker_termination_aborts_a_pending_script_fetch_without_cancelling_its_owner() {
        let (runtime, mut engine, mut task_rx) = worker_test_environment();
        let listener = runtime
            .block_on(tokio::net::TcpListener::bind("127.0.0.1:0"))
            .unwrap();
        let page = url::Url::parse(&format!("http://{}/", listener.local_addr().unwrap())).unwrap();
        // Keep the response pending: termination must release the waiting worker
        // through its own I/O scope, not a network timeout or page cancellation.
        let (accepted_tx, accepted_rx) = tokio::sync::oneshot::channel();
        let server = runtime.spawn(async move {
            let (stream, _) = listener.accept().await.unwrap();
            accepted_tx.send(()).unwrap();
            std::future::pending::<()>().await;
            drop(stream);
        });
        let state = engine.ctx().host_mut::<HostState>().unwrap();
        state.base = page.clone();
        state.window_request_urls.insert(0, page.clone());
        state.window_cookie_contexts.clear();
        eval(
            &mut engine,
            &format!(
                "globalThis.waiting = new Worker({});",
                serde_json::to_string(page.join("pending.js").unwrap().as_str()).unwrap()
            ),
            "pending worker fetch",
        )
        .unwrap();
        runtime
            .block_on(async { tokio::time::timeout(Duration::from_secs(15), accepted_rx).await })
            .expect("worker requested its script")
            .unwrap();
        eval(
            &mut engine,
            "waiting.terminate()",
            "terminate fetching worker",
        )
        .unwrap();
        loop {
            let task = runtime
                .block_on(async {
                    tokio::time::timeout(Duration::from_secs(5), task_rx.recv()).await
                })
                .expect("termination interrupts the fetch wait")
                .unwrap();
            let exited = matches!(task, LumenHostTask::WorkerExited { .. });
            dispatch_host_task(&mut engine, task).unwrap();
            if exited {
                break;
            }
        }
        let tasks = engine
            .ctx()
            .host_mut::<HostState>()
            .unwrap()
            .workers
            .as_ref()
            .unwrap()
            .tasks
            .clone();
        let (sent, received) = tokio::sync::oneshot::channel();
        tasks.spawn(runtime.handle(), async move {
            let _ = sent.send(());
        });
        runtime
            .block_on(async { tokio::time::timeout(Duration::from_secs(5), received).await })
            .expect("owner can still schedule work")
            .unwrap();
        server.abort();
    }

    #[test]
    fn workers_use_lumen_realms_and_preserve_task_microtask_order() {
        // HTML §10.2.4/§10.2.6 and §8.1.7: each Worker gets a distinct dedicated agent;
        // incoming port messages and timers are tasks with a microtask checkpoint between them.
        // MessagePort post-message steps clone immediately and dispatch trusted MessageEvents with
        // an empty origin. Module workers run as modules and importScripts() rejects there.
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .enable_all()
            .build()
            .unwrap();
        let page = url::Url::parse(DEFAULT_URL).unwrap();
        let cache = Arc::new(crate::http::PageCache::default());
        let (task_tx, mut task_rx) = tokio::sync::mpsc::unbounded_channel();
        let clock = Rc::new(RealmClock::new());
        let mut state = HostState::new(Rc::new(RefCell::new(Dom::new())), clock);
        state.enable_network(page.clone(), runtime.handle().clone(), cache, task_tx);
        let mut engine = configured_engine(state, page.as_str());

        let classic_source = r#"
            var workerOrder = [];
            var workerWasm = new WebAssembly.Instance(new WebAssembly.Module(new Uint8Array([
                0,97,115,109,1,0,0,0,1,5,1,96,0,1,127,3,2,1,0,7,10,1,6,
                97,110,115,119,101,114,0,0,10,6,1,4,0,65,42,11
            ]))).exports.answer();
            addEventListener('message', function (event) { workerOrder.push('listener'); });
            onmessage = function (event) {
                workerOrder.push('handler');
                var receivedAnswer = new WebAssembly.Instance(event.data.module).exports.answer();
                setTimeout(function () {
                    postMessage({ kind: 'timer1', cycle: event.data === event.data.self,
                        workerOrder: workerOrder.join(','), trusted: event.isTrusted,
                        origin: event.origin, workerName: self.name, wasm: workerWasm,
                        receivedAnswer: receivedAnswer, module: event.data.module });
                    Promise.resolve().then(function () { postMessage({ kind: 'micro' }); });
                }, 0);
                setTimeout(function () { postMessage({ kind: 'timer2' }); }, 0);
            };
        "#;
        let module_source = r#"
            export const answer = 42;
            var importError = '';
            try { importScripts('data:text/javascript,'); }
            catch (error) { importError = error.name; }
            postMessage({ kind: 'module', answer: answer, importError: importError });
        "#;
        let data_url = |source: &str| {
            // A data URL is not form-urlencoded: `+` is a literal plus, not a
            // space. Percent-encode every source byte so the Fetch data-URL
            // processor reconstructs the script exactly.
            let encoded = source
                .as_bytes()
                .iter()
                .map(|byte| format!("%{byte:02X}"))
                .collect::<Vec<_>>()
                .join("");
            format!("data:text/javascript,{}", encoded)
        };
        let classic_url = serde_json::to_string(&data_url(classic_source)).unwrap();
        let module_url = serde_json::to_string(&data_url(module_source)).unwrap();
        let spinner_url = serde_json::to_string(&data_url("while (true) {}")).unwrap();
        eval(
            &mut engine,
            &format!(
                r#"
                globalThis.workerLog = [];
                globalThis.workerTrusted = true;
                globalThis.workerOrigins = [];
                globalThis.workerErrors = 0;
                try {{ new Worker('http://['); }} catch (error) {{ workerLog.push('bad-url:' + error.name); }}
                try {{ new Worker('data:text/javascript,', {{ type: 'invalid' }}); }} catch (error) {{ workerLog.push('bad-type:' + error.name); }}

                globalThis.classicWorker = new Worker({classic_url}, {{ name: 'echo' }});
                classicWorker.addEventListener('message', function (event) {{
                    workerLog.push('listener:' + event.data.kind);
                    workerTrusted = workerTrusted && event.isTrusted;
                    workerOrigins.push(event.origin);
                }});
                classicWorker.onmessage = function (event) {{
                    workerLog.push('handler:' + event.data.kind);
                    if (event.data.kind === 'timer1') globalThis.timer1 = event.data;
                }};
                classicWorker.onerror = function () {{ workerErrors++; }};
                var cyclic = {{ value: 41, module: new WebAssembly.Module(new Uint8Array([
                    0,97,115,109,1,0,0,0,1,5,1,96,0,1,127,3,2,1,0,7,10,1,6,
                    97,110,115,119,101,114,0,0,10,6,1,4,0,65,42,11
                ])) }}; cyclic.self = cyclic;
                classicWorker.postMessage(cyclic);

                globalThis.moduleWorker = new Worker({module_url}, {{ type: 'module' }});
                moduleWorker.onmessage = function (event) {{
                    workerLog.push('module:' + event.data.answer + ':' + event.data.importError);
                    workerTrusted = workerTrusted && event.isTrusted;
                    workerOrigins.push(event.origin);
                }};
                moduleWorker.onerror = function () {{ workerErrors++; }};

                globalThis.spinnerWorker = new Worker({spinner_url});
                spinnerWorker.onerror = function () {{ workerErrors++; }};
                spinnerWorker.terminate();
                "#
            ),
            "Worker setup",
        )
        .unwrap();

        for _ in 0..12 {
            let log = string_value(&mut engine, "workerLog.join('|')");
            if log.contains("handler:timer2") && log.contains("module:42:TypeError") {
                break;
            }
            let task = runtime
                .block_on(async {
                    tokio::time::timeout(Duration::from_secs(15), task_rx.recv()).await
                })
                .expect("Worker task completes")
                .expect("Worker task channel remains open");
            dispatch_host_task(&mut engine, task).unwrap();
            run_microtask_checkpoint(&mut engine);
        }

        let log = string_value(&mut engine, "workerLog.join('|')");
        assert_eq!(
            string_value(
                &mut engine,
                "[timer1.receivedAnswer, timer1.module instanceof WebAssembly.Module, new WebAssembly.Instance(timer1.module).exports.answer()].join('|')"
            ),
            "42|true|42"
        );
        assert!(
            log.starts_with("bad-url:SyntaxError|bad-type:TypeError"),
            "{log}"
        );
        assert!(log.contains("module:42:TypeError"), "{log}");
        let timer1 = log.find("listener:timer1|handler:timer1").unwrap();
        let microtask = log.find("listener:micro|handler:micro").unwrap();
        let timer2 = log.find("listener:timer2|handler:timer2").unwrap();
        assert!(
            timer1 < microtask && microtask < timer2,
            "one timer task and its microtasks must precede the next timer task: {log}"
        );
        assert_eq!(string_value(&mut engine, "String(timer1.cycle)"), "true");
        assert_eq!(
            string_value(&mut engine, "timer1.workerOrder"),
            "listener,handler"
        );
        assert_eq!(string_value(&mut engine, "String(timer1.trusted)"), "true");
        assert_eq!(string_value(&mut engine, "timer1.origin"), "");
        assert_eq!(string_value(&mut engine, "timer1.workerName"), "echo");
        assert_eq!(string_value(&mut engine, "String(timer1.wasm)"), "42");
        assert_eq!(string_value(&mut engine, "String(workerTrusted)"), "true");
        assert_eq!(string_value(&mut engine, "workerOrigins.join(',')"), ",,,");
        assert_eq!(string_value(&mut engine, "String(workerErrors)"), "0");

        eval(
            &mut engine,
            "classicWorker.terminate(); moduleWorker.terminate();",
            "Worker cleanup",
        )
        .unwrap();
    }

    #[test]
    fn websocket_boundary_negotiates_and_delivers_ordered_protocol_tasks() {
        websocket_round_trip(false);
    }

    #[test]
    fn websocket_interface_follows_the_websockets_standard() {
        // WebSockets #interface-definition in a Window and a worker: Web IDL
        // conversions ([Clamp] close code, (DOMString or sequence<DOMString>)
        // protocols, the BinaryType enumeration), prototype attributes and
        // constants, and a connection that cannot be established failing
        // with error and a 1006 close event from a task.
        platform_fixture_in_window_and_worker(
            "WebSocket interface",
            r#"
            const tasks = async () => { for (let i = 0; i < 3; i++) await new Promise(r => setTimeout(r, 0)); };
            const events = [];
            const socket = new WebSocket('ws://example.invalid/chat?x');
            check(socket.readyState === 0 && socket.url === 'ws://example.invalid/chat?x' && socket.protocol === '' &&
                socket.extensions === '' && socket.binaryType === 'blob' && socket.bufferedAmount === 0, 'initial state');
            check(Object.getOwnPropertyNames(socket).length === 0 && WebSocket.CLOSING === 2 && socket.OPEN === 1 &&
                !Object.getOwnPropertyDescriptor(WebSocket.prototype, 'CLOSED').writable, 'attributes and constants');
            socket.onerror = event => events.push('error:' + socket.readyState + ':' + event.isTrusted);
            socket.onclose = event => events.push('close:' + event.code + ':' + event.wasClean + ':' + (event instanceof CloseEvent));
            socket.binaryType = 'text';
            check(socket.binaryType === 'blob', 'BinaryType ignores other values');
            throws(() => new WebSocket(), 'TypeError', 'url is required');
            throws(() => new WebSocket('ws://example.invalid/#'), 'SyntaxError', 'an empty fragment');
            throws(() => new WebSocket('ftp://example.invalid/'), 'SyntaxError', 'scheme');
            throws(() => new WebSocket('ws://example.invalid/', ['a', 'a']), 'SyntaxError', 'duplicate protocol');
            throws(() => new WebSocket('ws://example.invalid/', 'a b'), 'SyntaxError', 'protocol token');
            throws(() => new WebSocket('ws://example.invalid/', {}), 'SyntaxError', 'a non-iterable object is a DOMString');
            const relative = new WebSocket('/path', new Set(['chat']));
            check(relative.url === 'wss://' + location.host + '/path', 'http(s) schemes map to ws(s): ' + relative.url);
            throws(() => socket.close(2999), 'InvalidAccessError', 'close code range');
            throws(() => socket.close(1000, 'x'.repeat(124)), 'SyntaxError', 'close reason length');
            throws(() => socket.send(), 'TypeError', 'send requires data');
            throws(() => socket.send('x'), 'InvalidStateError', 'send while connecting');
            const closing = new WebSocket('ws://example.invalid/');
            closing.close(999.5);
            check(closing.readyState === 2, 'close() rounds a [Clamp] code half to even and fails a connecting socket');
            await tasks();
            check(events.join() === 'error:3:true,close:1006:false:true', 'failure events: ' + events.join());
            check(closing.readyState === 3 && relative.readyState === 3, 'closed');
            closing.send(new Uint8Array(5));
            closing.send('é');
            check(closing.bufferedAmount === 7, 'bufferedAmount counts sends after close');
            "#,
        );
    }

    #[test]
    fn worker_websockets_use_the_same_boundary_and_task_source() {
        // WebSocket is [Exposed=(Window,Worker)]: a worker's connection events
        // are host tasks of the worker's own event loop.
        websocket_round_trip(true);
    }

    fn websocket_round_trip(worker: bool) {
        // WebSockets §2.2/§4 and RFC 6455 §4.1: the opening response proves receipt of
        // the nonce, selects one offered subprotocol, and every open/message/send-complete/close
        // notification returns to the page as an ordered WebSocket-task-source task.
        use tokio::io::{AsyncReadExt as _, AsyncWriteExt as _};

        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .enable_all()
            .build()
            .unwrap();
        let listener = runtime
            .block_on(tokio::net::TcpListener::bind("127.0.0.1:0"))
            .unwrap();
        let port = listener.local_addr().unwrap().port();
        let server = runtime.spawn(async move {
            let (mut stream, _) = listener.accept().await.unwrap();
            let mut request = Vec::new();
            let mut chunk = [0u8; 1024];
            while !request.windows(4).any(|window| window == b"\r\n\r\n") {
                let read = stream.read(&mut chunk).await.unwrap();
                assert_ne!(read, 0, "client closed during opening handshake");
                request.extend_from_slice(&chunk[..read]);
            }
            let request = String::from_utf8(request).unwrap();
            assert!(
                request.contains("Sec-WebSocket-Protocol: chat, superchat\r\n"),
                "{request}"
            );
            let key = request
                .lines()
                .find_map(|line| line.strip_prefix("Sec-WebSocket-Key:").map(str::trim))
                .unwrap();
            let accept = crate::ws::websocket_accept(key);
            stream
                .write_all(
                    format!(
                        "HTTP/1.1 101 Switching Protocols\r\n\
                         Upgrade: websocket\r\n\
                         Connection: keep-alive, Upgrade\r\n\
                         Sec-WebSocket-Accept: {accept}\r\n\
                         Sec-WebSocket-Protocol: chat\r\n\r\n"
                    )
                    .as_bytes(),
                )
                .await
                .unwrap();

            let text = read_test_client_frame(&mut stream).await;
            let binary = read_test_client_frame(&mut stream).await;
            assert_eq!(text, (0x1, "hé".as_bytes().to_vec()));
            assert_eq!(binary, (0x2, vec![0, 0x80, 0xff]));
            write_test_server_frame(&mut stream, 0x1, b"reply").await;
            write_test_server_frame(&mut stream, 0x2, &[0, 0x80, 0xff]).await;

            let close = read_test_client_frame(&mut stream).await;
            assert_eq!(close.0, 0x8);
            assert_eq!(&close.1[..2], &1000u16.to_be_bytes());
            assert_eq!(&close.1[2..], b"bye");
            write_test_server_frame(&mut stream, 0x8, &close.1).await;
        });

        let page = url::Url::parse(&format!("http://127.0.0.1:{port}/page")).unwrap();
        let cache = Arc::new(crate::http::PageCache::default());
        let (task_tx, mut task_rx) = tokio::sync::mpsc::unbounded_channel();
        let clock = Rc::new(RealmClock::new());
        let mut state = HostState::new(Rc::new(RefCell::new(Dom::new())), clock.clone());
        let mut engine = if worker {
            let script = page.join("worker.js").unwrap();
            state.base = script.clone();
            let (events, _) = tokio::sync::mpsc::unbounded_channel();
            state.worker_self = Some(LumenWorkerSelf {
                id: 1,
                events: LumenTaskSender::Page(events),
                closed: false,
                origin: script.clone(),
                secure_context: true,
                settings_origin: script.origin(),
                referrer_policy: Default::default(),
            });
            state.enable_websockets(
                page.clone(),
                runtime.handle(),
                &cache,
                LumenTaskSender::Page(task_tx),
            );
            let mut engine = lumen::Engine::new();
            let origin = clock.origin_ms;
            engine.set_wall_clock(move || clock.now_ms());
            engine
                .ctx()
                .op_state()
                .put_retained_memory_with_external_memory(state);
            install_lumen_worker_boundary(&mut engine);
            eval(
                &mut engine,
                &format!("globalThis.__worker_cfg={{url:'{script}',timeOrigin:{origin}}}"),
                "worker config",
            )
            .unwrap();
            assert!(eval_lumen_worker_platform_setup(&mut engine).unwrap());
            engine
        } else {
            state.enable_network(page.clone(), runtime.handle().clone(), cache, task_tx);
            configured_engine(state, page.as_str())
        };
        eval(
            &mut engine,
            &format!(
                r#"
                globalThis.wsLog = [];
                globalThis.wsErrors = 0;
                globalThis.wsEventsTrusted = true;
                try {{ new WebSocket('ftp://example.test/'); }} catch (error) {{ wsLog.push('bad-url:' + error.name); }}
                try {{ new WebSocket('/duplicate', ['chat', 'chat']); }} catch (error) {{ wsLog.push('bad-protocol:' + error.name); }}
                globalThis.socket = new WebSocket('http://127.0.0.1:{port}/echo', ['chat', 'superchat']);
                socket.binaryType = 'arraybuffer';
                socket.binaryType = 'invalid';
                wsLog.push('binary-type:' + socket.binaryType);
                wsLog.push('shape:' + [Object.getOwnPropertyNames(socket).length, WebSocket.OPEN, socket.CLOSED,
                    Object.getOwnPropertyDescriptor(WebSocket, 'OPEN').writable].join(','));
                try {{ socket.send('too-soon'); }} catch (error) {{ wsLog.push('connecting-send:' + error.name); }}
                try {{ socket.close(2000); }} catch (error) {{ wsLog.push('bad-close:' + error.name); }}
                try {{ socket.close(1000, 'é'.repeat(62)); }} catch (error) {{ wsLog.push('long-reason:' + error.name); }}
                globalThis.openListenerCount = 0;
                socket.addEventListener('open', function (event) {{ openListenerCount++; wsLog.push('open-listener'); wsEventsTrusted = wsEventsTrusted && event.isTrusted; }});
                socket.onopen = function (event) {{
                    wsEventsTrusted = wsEventsTrusted && event.isTrusted;
                    wsLog.push('open:' + socket.protocol);
                    socket.send('hé');
                    socket.send(new Uint8Array([0, 128, 255]));
                    globalThis.bufferedDuringOpen = socket.bufferedAmount;
                }};
                globalThis.messageCount = 0;
                socket.onmessage = function (event) {{
                    wsEventsTrusted = wsEventsTrusted && event.isTrusted;
                    messageCount++;
                    if (typeof event.data === 'string') wsLog.push('text:' + event.data + ':' + event.origin);
                    else wsLog.push('binary:' + Array.from(new Uint8Array(event.data)).join(','));
                    if (messageCount === 2) socket.close(1000, 'bye');
                }};
                socket.onerror = function () {{ wsErrors++; }};
                socket.onclose = function (event) {{
                    wsEventsTrusted = wsEventsTrusted && event.isTrusted;
                    wsLog.push('close:' + event.code + ':' + event.reason + ':' + event.wasClean);
                    socket.send('z');
                    globalThis.bufferedAfterClose = socket.bufferedAmount;
                    globalThis.wsClosed = true;
                }};
                "#
            ),
            "WebSocket setup",
        )
        .unwrap();

        for _ in 0..12 {
            if string_value(&mut engine, "String(globalThis.wsClosed === true)") == "true" {
                break;
            }
            let task = runtime
                .block_on(async {
                    tokio::time::timeout(Duration::from_secs(2), task_rx.recv()).await
                })
                .expect("WebSocket task completes")
                .expect("WebSocket task channel remains open");
            dispatch_host_task(&mut engine, task).unwrap();
            run_microtask_checkpoint(&mut engine);
        }
        runtime.block_on(server).unwrap();

        let log = string_value(&mut engine, "wsLog.join('|')");
        assert!(log.contains("bad-url:SyntaxError"), "{log}");
        assert!(log.contains("bad-protocol:SyntaxError"), "{log}");
        assert!(log.contains("binary-type:arraybuffer"), "{log}");
        assert!(log.contains("shape:0,1,3,false"), "{log}");
        assert!(log.contains("connecting-send:InvalidStateError"), "{log}");
        assert!(log.contains("bad-close:InvalidAccessError"), "{log}");
        assert!(log.contains("long-reason:SyntaxError"), "{log}");
        assert!(log.contains("open-listener|open:chat"), "{log}");
        assert_eq!(log.matches("open:chat").count(), 1, "{log}");
        assert!(
            log.contains(&format!("text:reply:ws://127.0.0.1:{port}")),
            "{log}"
        );
        assert!(log.contains("binary:0,128,255"), "{log}");
        assert!(log.contains("close:1000:bye:true"), "{log}");
        assert_eq!(string_value(&mut engine, "String(openListenerCount)"), "1");
        assert_eq!(string_value(&mut engine, "String(wsErrors)"), "0");
        assert_eq!(string_value(&mut engine, "String(wsEventsTrusted)"), "true");
        assert_eq!(string_value(&mut engine, "String(bufferedDuringOpen)"), "6");
        assert_eq!(string_value(&mut engine, "String(bufferedAfterClose)"), "1");
        assert_eq!(
            string_value(&mut engine, "socket.url"),
            format!("ws://127.0.0.1:{port}/echo")
        );
    }

    #[test]
    fn injected_scripts_modules_and_stylesheets_complete_as_resource_tasks() {
        // HTML §4.12.1.1: a connected inline classic executes during post-connection, while
        // external classic/module scripts execute when their fetched result is ready. HTML
        // §4.2.4.3 attaches a successfully obtained CSS sheet before firing the link's load event.
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .enable_all()
            .build()
            .unwrap();
        let page = url::Url::parse(DEFAULT_URL).unwrap();
        let cache = Arc::new(crate::http::PageCache::default());
        let seed = |path: &str, content_type: &str, body: &[u8]| {
            let url = page.join(path).unwrap();
            cache.seed_with_headers(
                url.to_string(),
                200,
                content_type.to_string(),
                vec![(String::from("content-type"), content_type.to_string())],
                body.to_vec(),
            );
        };
        seed(
            "chunk.js",
            "text/javascript",
            br#"
                resourceOrder.push('classic-exec');
                globalThis.classicCurrent = document.currentScript === document.getElementById('classic');
                import('./classic-dep.js').then(function (dependency) {
                    globalThis.classicImport = dependency.answer;
                    resourceOrder.push('classic-import:' + dependency.answer);
                });
                Promise.resolve().then(function () {
                    globalThis.classicMicroCurrent = document.currentScript === document.getElementById('classic');
                    resourceOrder.push('classic-micro');
                });
            "#,
        );
        seed(
            "classic-dep.js",
            "text/javascript",
            b"export const answer = 17;",
        );
        seed(
            "module.js",
            "text/javascript",
            br#"
                import { answer } from 'data:text/javascript,export%20const%20answer%20%3D%2042%3B';
                globalThis.moduleAnswer = answer;
                resourceOrder.push('module-exec');
            "#,
        );
        seed(
            "chunk.css",
            "text/css",
            b"#resource-target { display: grid; grid-template-columns: 90px 110px; }",
        );
        let (task_tx, mut task_rx) = tokio::sync::mpsc::unbounded_channel();
        let clock = Rc::new(RealmClock::new());
        let mut state = HostState::new(Rc::new(RefCell::new(Dom::new())), clock);
        state.enable_network(page, runtime.handle().clone(), cache, task_tx);
        let mut engine = configured_engine(state, DEFAULT_URL);

        eval(
            &mut engine,
            r#"
                globalThis.resourceOrder = [];
                const html = document.createElement('html');
                const head = document.createElement('head');
                const body = document.createElement('body');
                document.appendChild(html); html.appendChild(head); html.appendChild(body);
                const target = document.createElement('div');
                target.id = 'resource-target';
                document.body.appendChild(target);

                const inline = document.createElement('script');
                globalThis.inlineElement = inline;
                inline.textContent = "globalThis.inlineCurrent = document.currentScript === globalThis.inlineElement; resourceOrder.push('inline-exec'); Promise.resolve().then(function () { resourceOrder.push('inline-micro'); })";
                document.body.appendChild(inline);
                resourceOrder.push('after-inline');

                const emptyModule = document.createElement('script');
                emptyModule.type = 'module';
                emptyModule.onload = function () { resourceOrder.push('inline-module-load'); };
                emptyModule.onerror = function () { resourceOrder.push('inline-module-error'); };
                document.body.appendChild(emptyModule);

                const link = document.createElement('link');
                link.rel = 'stylesheet'; link.href = '/chunk.css';
                link.onload = function () { resourceOrder.push('style-load:' + getComputedStyle(target).display); };
                link.onerror = function () { resourceOrder.push('style-error'); };
                document.head.appendChild(link);

                const classic = document.createElement('script');
                classic.id = 'classic'; classic.src = '/chunk.js';
                classic.onload = function () { resourceOrder.push('classic-load'); };
                classic.onerror = function () { resourceOrder.push('classic-error'); };
                document.body.appendChild(classic);

                const module = document.createElement('script');
                module.type = 'module'; module.src = '/module.js';
                module.onload = function () { resourceOrder.push('module-load:' + moduleAnswer); };
                module.onerror = function () { resourceOrder.push('module-error'); };
                document.body.appendChild(module);
                resourceOrder.push('after-external-insert');
            "#,
            "insert dynamic resources",
        )
        .unwrap();
        run_microtask_checkpoint(&mut engine);
        assert_eq!(
            string_value(&mut engine, "resourceOrder.slice(0, 4).join('|')"),
            "inline-exec|after-inline|after-external-insert|inline-micro"
        );
        assert_eq!(string_value(&mut engine, "String(inlineCurrent)"), "true");
        assert_eq!(
            engine
                .ctx()
                .host_mut::<HostState>()
                .map(|state| state.pending_resources),
            Some(4)
        );

        // Four inserted resources plus the classic script's asynchronous dynamic-import fetch.
        // The latter does not delay the classic script element's load event, but its promise must
        // still settle in a later networking task.
        for _ in 0..8 {
            let resources_done = engine
                .ctx()
                .host_mut::<HostState>()
                .is_some_and(|state| state.pending_resources == 0);
            if resources_done
                && string_value(&mut engine, "String(globalThis.classicImport)") == "17"
            {
                break;
            }
            let task = runtime
                .block_on(async {
                    tokio::time::timeout(Duration::from_secs(2), task_rx.recv()).await
                })
                .expect("resource task completes")
                .expect("resource task channel remains open");
            dispatch_host_task(&mut engine, task).unwrap();
            run_microtask_checkpoint(&mut engine);
        }
        let order = string_value(&mut engine, "resourceOrder.join('|')");
        assert!(order.contains("style-load:grid"), "{order}");
        assert!(order.contains("classic-exec"), "{order}");
        assert!(order.contains("classic-micro"), "{order}");
        assert!(order.contains("classic-import:17"), "{order}");
        assert!(order.contains("classic-load"), "{order}");
        assert!(order.contains("inline-module-load"), "{order}");
        assert!(order.contains("module-exec"), "{order}");
        assert!(order.contains("module-load:42"), "{order}");
        assert!(!order.contains("-error"), "{order}");
        assert_eq!(order.matches("style-load:grid").count(), 1, "{order}");
        assert_eq!(order.matches("classic-load").count(), 1, "{order}");
        assert_eq!(order.matches("inline-module-load").count(), 1, "{order}");
        assert_eq!(order.matches("module-load:42").count(), 1, "{order}");
        assert!(
            order.find("classic-exec") < order.find("classic-micro")
                && order.find("classic-micro") < order.find("classic-load"),
            "classic script cleanup/load ordering: {order}"
        );
        assert!(
            order.find("classic-load") < order.find("classic-import:17"),
            "dynamic import must not delay classic-script load completion: {order}"
        );
        assert_eq!(string_value(&mut engine, "String(classicCurrent)"), "true");
        assert_eq!(string_value(&mut engine, "String(classicImport)"), "17");
        assert_eq!(
            string_value(&mut engine, "String(classicMicroCurrent)"),
            "true"
        );
        assert_eq!(
            engine
                .ctx()
                .host_mut::<HostState>()
                .map(|state| state.pending_resources),
            Some(0)
        );
    }

    #[test]
    fn injected_stylesheets_resolve_urls_against_their_response_url() {
        // CSS Values 4 #relative-urls: a style sheet's own URL, after
        // redirects, is the base of its url() tokens and @import rules,
        // whether the parser or a script inserted its <link>.
        use std::io::{Read as _, Write as _};
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let origin = format!("http://{}", listener.local_addr().unwrap());
        let page = url::Url::parse(&format!("{origin}/page/index.html")).unwrap();
        std::thread::spawn(move || {
            for mut stream in listener.incoming().flatten() {
                let _ = stream.set_read_timeout(Some(Duration::from_secs(10)));
                let mut request = Vec::new();
                let mut bytes = [0; 4096];
                while !request.windows(4).any(|part| part == b"\r\n\r\n") {
                    match stream.read(&mut bytes) {
                        Ok(0) | Err(_) => break,
                        Ok(count) => request.extend_from_slice(&bytes[..count]),
                    }
                }
                let head = String::from_utf8_lossy(&request);
                let path = head.split_whitespace().nth(1).unwrap_or("");
                let (status, location, body) = match path {
                    "/old/frame.css" => (302, "Location: /a/sheets/frame.css\r\n", ""),
                    "/a/sheets/frame.css" => (
                        200,
                        "",
                        "@import 'deep/child.css'; #t { background-image: url('../g.png') }",
                    ),
                    "/a/sheets/deep/child.css" => (200, "", "#u { background-image: url(c.png) }"),
                    _ => (404, "", ""),
                };
                let _ = write!(
                    stream,
                    "HTTP/1.1 {status} Status\r\n{location}Content-Type: text/css\r\n\
                     Content-Length: {}\r\nConnection: close\r\n\r\n{body}",
                    body.len()
                );
            }
        });
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .enable_all()
            .build()
            .unwrap();
        let (task_tx, mut task_rx) = tokio::sync::mpsc::unbounded_channel();
        let mut state = HostState::new(
            Rc::new(RefCell::new(Dom::new())),
            Rc::new(RealmClock::new()),
        );
        state.enable_network(
            page.clone(),
            runtime.handle().clone(),
            Arc::default(),
            task_tx,
        );
        let mut engine = configured_engine(state, page.as_str());
        eval(
            &mut engine,
            r#"
                const html = document.createElement('html');
                const head = document.createElement('head');
                const body = document.createElement('body');
                document.appendChild(html); html.appendChild(head); html.appendChild(body);
                for (const id of ['t', 'u']) {
                    const target = document.createElement('div');
                    target.id = id;
                    body.appendChild(target);
                }
                globalThis.sheetEvents = [];
                const link = document.createElement('link');
                link.rel = 'stylesheet'; link.href = '/old/frame.css';
                link.onload = () => sheetEvents.push('load');
                link.onerror = () => sheetEvents.push('error');
                head.appendChild(link);
            "#,
            "insert a stylesheet",
        )
        .unwrap();
        run_microtask_checkpoint(&mut engine);
        while engine
            .ctx()
            .host_mut::<HostState>()
            .is_some_and(|state| state.pending_resources > 0)
        {
            let task = runtime
                .block_on(async {
                    tokio::time::timeout(Duration::from_secs(10), task_rx.recv()).await
                })
                .expect("stylesheet task completes")
                .expect("resource task channel remains open");
            dispatch_host_task(&mut engine, task).unwrap();
            run_microtask_checkpoint(&mut engine);
        }
        assert_eq!(string_value(&mut engine, "sheetEvents.join()"), "load");
        let image = |engine: &mut lumen::Engine, id: &str| {
            string_value(
                engine,
                &format!("getComputedStyle(document.getElementById('{id}')).backgroundImage"),
            )
        };
        let sheet = image(&mut engine, "t");
        assert!(sheet.contains(&format!("{origin}/a/g.png")), "{sheet}");
        let imported = image(&mut engine, "u");
        assert!(
            imported.contains(&format!("{origin}/a/sheets/deep/c.png")),
            "{imported}"
        );
    }

    #[test]
    fn preload_destinations_and_types_follow_html() {
        // HTML #translate-a-preload-destination and #match-preload-type.
        assert_eq!(preload_destination("STYLE"), Some("style"));
        assert_eq!(preload_destination("fetch"), Some(""));
        assert_eq!(preload_destination("worker"), None);
        assert_eq!(preload_destination(""), None);
        assert!(preload_type_matches("", "style"));
        assert!(preload_type_matches("text/CSS; charset=utf-8", "style"));
        assert!(!preload_type_matches("text/plain", "style"));
        assert!(!preload_type_matches("nonsense", "style"));
        assert!(preload_type_matches("anything/at-all", ""));
        assert!(preload_type_matches("text/javascript", "script"));
        assert!(!preload_type_matches("text/css", "script"));
        assert!(preload_type_matches("font/woff2", "font"));
        assert!(preload_type_matches("image/webp", "image"));
        assert!(!preload_type_matches("image/x-unknown", "image"));
        assert!(preload_type_matches("text/vtt", "track"));
    }

    #[test]
    fn iframe_stylesheet_sweep_does_not_switch_embedding_window_globals() {
        // HTML's browsing-context creation assigns an independent Window
        // Realm. A resource sweep must not temporarily turn the embedding
        // global into the child's Window, even while calling author accessors.
        for tier in [Tier::Interp, Tier::Bytecode, Tier::Jit] {
            let mut engine = platform_engine();
            engine.set_tier(tier);
            engine.set_tier_threshold(0);
            assert_eq!(
                string_value(
                    &mut engine,
                    r##"
                    (function () {
                        const html = document.createElement('html'), body = document.createElement('body');
                        document.appendChild(html); html.appendChild(body);
                        const parentDocument = document, observed = [];
                        const request = requestAnimationFrame;
                        Object.defineProperty(globalThis, 'frameElement', { value: 'parent-owned' });
                        Object.defineProperty(globalThis, 'lockedParentValue', { value: 73 });
                        Object.defineProperty(globalThis, 'requestAnimationFrame', {
                            configurable: true,
                            get() { observed.push(document === parentDocument); return request; },
                            set(value) {}
                        });
                        const frame = document.createElement('iframe');
                        frame.srcdoc = '<body><p>child</p></body>';
                        body.appendChild(frame); __trust.hydrateFrames();
                        if (!observed.every(Boolean)) throw Error('parent accessor observed the child Document');
                        if (document !== parentDocument || frameElement !== 'parent-owned' || lockedParentValue !== 73)
                            throw Error('parent global was changed');
                        const child = frame.contentWindow;
                        if (child.document === parentDocument || child.frameElement !== frame ||
                            Object.hasOwn(child, 'lockedParentValue')) throw Error('child global was contaminated');
                        return 'stylesheet-sweep-globals-ok';
                    })()
                    "##
                ),
                "stylesheet-sweep-globals-ok",
                "{tier:?}"
            );
        }
    }

    #[test]
    fn iframe_stylesheet_and_load_tasks_run_in_their_relevant_realms() {
        // HTML §8.1.7.2 queues asynchronous element work against the
        // element's relevant global, and the iframe load-event steps run only
        // after the child Window's load task. A stylesheet fetched for a
        // child Document must consequently settle the child listener registry
        // before the owner-Document iframe element fires load.
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .enable_all()
            .build()
            .unwrap();
        let page = url::Url::parse(DEFAULT_URL).unwrap();
        let stylesheet_url = page.join("frame.css").unwrap();
        let cache = Arc::new(crate::http::PageCache::default());
        cache.seed_with_headers(
            stylesheet_url.to_string(),
            200,
            String::from("text/css"),
            vec![(String::from("content-type"), String::from("text/css"))],
            b"#realm-style-target { display: grid; }".to_vec(),
        );
        let (task_tx, mut task_rx) = tokio::sync::mpsc::unbounded_channel();
        let clock = Rc::new(RealmClock::new());
        let mut state = HostState::new(Rc::new(RefCell::new(Dom::new())), clock);
        state.enable_network(page, runtime.handle().clone(), cache, task_tx);
        let mut engine = configured_engine(state, DEFAULT_URL);

        eval(
            &mut engine,
            r##"
                const html = document.createElement("html");
                const body = document.createElement("body");
                document.appendChild(html); html.appendChild(body);
                globalThis.frameLifecycleOrder = [];
                const frame = document.createElement("iframe");
                frame.onload = function () { frameLifecycleOrder.push("frame"); };
                frame.srcdoc = '<head><link id="child-style" rel="stylesheet" href="/frame.css"></head>' +
                    '<body><div id="realm-style-target"></div><script>' +
                    'document.getElementById("child-style").addEventListener("load", function () {' +
                    'parent.frameLifecycleOrder.push("style:" + getComputedStyle(' +
                    'document.getElementById("realm-style-target")).display);' +
                    '});' +
                    'window.addEventListener("load", function () {' +
                    'parent.frameLifecycleOrder.push("window");' +
                    '});' +
                    '<\/script></body>';
                body.appendChild(frame);
                __trust.hydrateFrames();
                globalThis.stylesheetFrame = frame;
            "##,
            "iframe stylesheet Realm task setup",
        )
        .unwrap();
        run_microtask_checkpoint(&mut engine);

        let task = runtime
            .block_on(async { tokio::time::timeout(Duration::from_secs(2), task_rx.recv()).await })
            .expect("iframe stylesheet completes")
            .expect("resource task channel remains open");
        dispatch_host_task(&mut engine, task).unwrap();
        run_microtask_checkpoint(&mut engine);

        for _ in 0..8 {
            let has_task = engine_call_trust_method(&mut engine, "hasPlatformTask", &[])
                .map(|value| engine.ctx().to_boolean(&value))
                .unwrap_or(false);
            if !has_task {
                break;
            }
            assert!(
                engine_call_trust_method(&mut engine, "runPlatformTask", &[])
                    .is_ok_and(|value| engine.ctx().to_boolean(&value))
            );
            run_microtask_checkpoint(&mut engine);
        }
        let errors = string_value(&mut engine, "__trust.takeErrors()");
        let logs = string_value(&mut engine, "__trust.takeLogs()");
        assert_eq!(
            string_value(&mut engine, "frameLifecycleOrder.join('|')"),
            "style:grid|window|frame",
            "errors={errors}; logs={logs}"
        );
        assert_eq!(
            string_value(&mut engine, "stylesheetFrame.contentDocument.readyState",),
            "complete"
        );
        assert_eq!(errors, "");
    }

    #[test]
    fn top_level_await_delays_module_load_completion() {
        // HTML §4.12.1: running a module script waits for its evaluation promise. In particular,
        // top-level await must delay both the script element's load event and the document's load
        // event until the awaited dynamic-import graph finishes evaluating.
        let runtime = tokio::runtime::Builder::new_multi_thread()
            .worker_threads(2)
            .enable_all()
            .build()
            .unwrap();
        let page = url::Url::parse(DEFAULT_URL).unwrap();
        let cache = Arc::new(crate::http::PageCache::default());
        cache.seed(
            page.join("dep.js").unwrap().to_string(),
            200,
            String::from("text/javascript"),
            b"globalThis.awaitedModuleBody = 'done'; export default 1;".to_vec(),
        );
        let (task_tx, mut task_rx) = tokio::sync::mpsc::unbounded_channel();
        let clock = Rc::new(RealmClock::new());
        let mut state = HostState::new(Rc::new(RefCell::new(Dom::new())), clock);
        state.enable_network(page, runtime.handle().clone(), cache, task_tx);
        let mut engine = configured_engine(state, DEFAULT_URL);
        eval(
            &mut engine,
            r#"
                const html = document.createElement('html');
                const body = document.createElement('body');
                document.appendChild(html); html.appendChild(body);
                const script = document.createElement('script');
                script.id = 'entry';
                globalThis.awaitedModuleEvent = 'pending';
                script.onload = () => awaitedModuleEvent = 'load';
                script.onerror = () => awaitedModuleEvent = 'error';
                body.appendChild(script);
            "#,
            "module event target",
        )
        .unwrap();
        let node_id = engine
            .ctx()
            .host_mut::<HostState>()
            .and_then(|state| state.dom.borrow().get_by_id("entry"))
            .expect("module event target exists");

        run_injected_module_task(
            &mut engine,
            node_id,
            DEFAULT_URL,
            "await import('./dep.js'); globalThis.awaitedEntryBody = 'done';",
        )
        .unwrap();
        assert_eq!(string_value(&mut engine, "awaitedModuleEvent"), "pending");
        assert_eq!(
            engine
                .ctx()
                .host_mut::<HostState>()
                .map(|state| state.pending_resources),
            Some(1)
        );

        loop {
            let task = runtime
                .block_on(async {
                    tokio::time::timeout(Duration::from_secs(2), task_rx.recv()).await
                })
                .expect("dynamic module task completes")
                .expect("dynamic module channel remains open");
            let started = matches!(&task, LumenHostTask::DynamicModuleStart { .. });
            dispatch_host_task(&mut engine, task).unwrap();
            run_microtask_checkpoint(&mut engine);
            if !started {
                break;
            }
        }

        assert_eq!(string_value(&mut engine, "awaitedModuleBody"), "done");
        assert_eq!(string_value(&mut engine, "awaitedEntryBody"), "done");
        assert_eq!(string_value(&mut engine, "awaitedModuleEvent"), "load");
        assert_eq!(
            engine
                .ctx()
                .host_mut::<HostState>()
                .map(|state| state.pending_resources),
            Some(0)
        );
    }

    #[test]
    fn core_dom_boundary_runs_through_the_shared_prelude() {
        // WHATWG DOM §4.2.3 insertion, §4.4 Node, and §4.5 Document/adoptNode; WHATWG HTML's
        // DOMParser HTML-document parsing steps. This intentionally enters through the exposed JS
        // objects rather than testing Rust adapters in isolation.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r##"
            const root = document.createElement("SECTION");
            root.setAttribute("DATA-X", "one");
            const text = document.createTextNode("hello");
            const comment = document.createComment("marker");
            root.appendChild(text);
            root.insertBefore(comment, text);
            const span = document.createElement("span");
            span.textContent = "child";
            root.appendChild(span);
            const fragment = document.createDocumentFragment();
            const bold = document.createElement("b");
            bold.textContent = "frag";
            fragment.appendChild(bold);
            root.appendChild(fragment);

            document.appendChild(root);
            const connectedBeforeAdoption = root.isConnected;
            let cycleError = "none";
            try { span.appendChild(root); } catch (error) { cycleError = error.name; }

            const parsed = new DOMParser().parseFromString(
                "<!doctype html><html><head><title>x</title></head><body><p>y</p></body></html>",
                "text/html"
            );
            const parsedHtml = Array.from(parsed.childNodes).find(node => node.nodeType === 1);
            const parsedSections = Array.from(parsedHtml.children).map(node => node.localName).join(",");
            const adopted = parsed.adoptNode(root);

            const foreignParent = document.createElement("aside");
            const foreignChild = document.createElement("em");
            foreignParent.appendChild(foreignChild);
            const rejected = document.createElement("i");
            let insertError = "none", removeError = "none";
            try { root.insertBefore(rejected, foreignChild); }
            catch (error) { insertError = error.name; }
            try { root.removeChild(foreignChild); }
            catch (error) { removeError = error.name; }

            globalThis.coreDomResult = [
                root.localName,
                root.getAttribute("data-x"),
                root.getAttributeNames().join(","),
                comment.nextSibling === text,
                text.previousSibling === comment,
                root.textContent,
                cycleError,
                connectedBeforeAdoption,
                adopted === root,
                root.ownerDocument === parsed,
                root.parentNode === null,
                root.isConnected,
                parsedHtml.localName,
                parsedSections,
                insertError,
                rejected.parentNode === null,
                removeError,
                foreignChild.parentNode === foreignParent
            ].join("|");
            "##,
            "core DOM boundary",
        )
        .unwrap();

        assert_eq!(
            string_value(&mut engine, "coreDomResult"),
            "section|one|data-x|true|true|hellochildfrag|HierarchyRequestError|true|true|true|true|false|html|head,body|NotFoundError|true|NotFoundError|true"
        );
    }

