    #[test]
    fn selectors_serialization_shadow_templates_css_and_url_share_the_live_arena() {
        // DOM scope-match/clone algorithms, HTML fragment parsing and serialization, Shadow DOM
        // host/root relationships, CSS selector parsing, and WHATWG URL component setters.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r##"
            const html = document.createElement("html");
            const body = document.createElement("body");
            document.appendChild(html);
            html.appendChild(body);
            body.innerHTML = '<section id="a" class="x"><template><b>inside</b></template>'
                + '<div id="host"></div></section>';
            const section = body.querySelector("section.x");
            section.insertAdjacentHTML("beforeend", '<p data-k="v">tail</p>');
            const paragraph = section.querySelector("p[data-k=v]");
            const clone = section.cloneNode(true);
            const template = section.querySelector("template");
            const host = section.querySelector("#host");
            const shadow = host.attachShadow({ mode: "open" });
            shadow.innerHTML = '<slot></slot><i class="shadow-item">shade</i>';

            const style = document.createElement("style");
            style.textContent = "p { color: red } @media (min-width: 1px) { b { display: block } }";
            body.appendChild(style);
            const url = new URL("/a", "https://example.com/base");
            url.pathname = "c%20d";
            url.search = "?q=1";
            url.hash = "#h";

            globalThis.extendedDomResult = [
                document.documentElement === html,
                section.matches("section.x"),
                body.querySelectorAll("section > p").length,
                paragraph.getAttribute("data-k"),
                clone !== section && clone.querySelector("p").textContent,
                template.content.firstElementChild.localName,
                host.shadowRoot === shadow,
                shadow.querySelector("i.shadow-item").textContent,
                CSS.supports("selector(section.x > p)"),
                style.sheet.cssRules.length,
                body.innerHTML.includes('data-k="v"'),
                url.href
            ].join("|");
            "##,
            "extended synchronous DOM boundary",
        )
        .unwrap();

        assert_eq!(
            string_value(&mut engine, "extendedDomResult"),
            "true|true|1|v|tail|b|true|shade|true|2|true|https://example.com/c%20d?q=1#h"
        );
    }

    #[test]
    fn query_selector_all_returns_a_static_lazy_nodelist() {
        // DOM §4.2.10.1 and ParentNode.querySelectorAll: the result is a new,
        // static NodeList with supported indexed properties and iterable<Node>.
        // Retaining native IDs until consumption is unobservable, but a
        // length-only query must not manufacture wrappers for every result.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r##"
            const root = document.createElement("section");
            document.appendChild(root);
            root.innerHTML = '<span id="old-a">a</span><span id="old-b">b</span>';
            const before = __trust.nodeWrapperCacheState()[0];
            const list = root.querySelectorAll("span");
            const length = list.length;
            const afterLength = __trust.nodeWrapperCacheState()[0];

            // Static membership survives replacement; the first indexed read
            // lazily creates exactly one wrapper for the now-detached node.
            root.innerHTML = '<span id="new">new</span>';
            const oldFirst = list[0];
            const afterFirst = __trust.nodeWrapperCacheState()[0];
            let callbackShape = "";
            list.forEach((node, index, owner) => {
                callbackShape += node.textContent + index + (owner === list ? "t" : "f");
            });
            const iterated = Array.from(list, node => node.id).join(",");
            const entries = Array.from(list.entries(), pair => pair[0] + ":" + pair[1].id).join(",");
            const keys = Array.from(list.keys()).join(",");
            const ownKeys = Object.keys(list).join(",");
            list[0] = null;
            let constructorError = "";
            try { new NodeList(); } catch (error) { constructorError = error.name; }
            let missingItemError = "";
            try { list.item(); } catch (error) { missingItemError = error.name; }
            let indexedDefineError = "";
            try { Object.defineProperty(list, "99", { value: null }); }
            catch (error) { indexedDefineError = error.name; }
            const deleteSupported = delete list[0];
            const deleteUnsupported = delete list[99];
            let preventExtensionsError = "";
            try { Object.preventExtensions(list); }
            catch (error) { preventExtensionsError = error.name; }
            const syntaxErrors = [];
            for (const operation of [
                () => root.querySelector("["),
                () => root.querySelectorAll("["),
                () => root.matches("["),
                () => root.closest("[")
            ]) {
                try { operation(); } catch (error) { syntaxErrors.push(error.name); }
            }

            globalThis.staticNodeListResult = [
                list instanceof NodeList,
                Array.isArray(list),
                Object.prototype.toString.call(list),
                typeof list.map,
                length,
                before === afterLength,
                afterFirst === before + 1,
                oldFirst.textContent,
                list.item(0) === oldFirst,
                list.item(99) === null,
                list[99] === undefined,
                list[0] === oldFirst,
                callbackShape,
                iterated,
                entries,
                keys,
                ownKeys,
                root.querySelectorAll("span") !== root.querySelectorAll("span"),
                constructorError,
                missingItemError,
                indexedDefineError,
                deleteSupported,
                deleteUnsupported,
                Object.isExtensible(list),
                preventExtensionsError,
                syntaxErrors.join(",")
            ].join("|");
            "##,
            "static lazy NodeList",
        )
        .unwrap();

        assert_eq!(
            string_value(&mut engine, "staticNodeListResult"),
            "true|false|[object NodeList]|undefined|2|true|true|a|true|true|true|true|a0tb1t|old-a,old-b|0:old-a,1:old-b|0,1|0,1|true|TypeError|TypeError|TypeError|false|true|true|TypeError|SyntaxError,SyntaxError,SyntaxError,SyntaxError"
        );
    }

    #[test]
    fn slotted_events_follow_the_assigned_slot_through_shadow_buttons() {
        // DOM §§2.2, 2.9, 4.2.2.3, and 4.4: a slottable's event parent is
        // its assigned slot rather than its light-tree parent. This is what
        // lets a click targeting a component's projected label reach the
        // shadow button that contains <slot>. Closed roots remain in the
        // internal path but are hidden by assignedSlot/composedPath outside.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r##"
            const html = document.createElement("html");
            const body = document.createElement("body");
            document.appendChild(html);
            html.appendChild(body);
            const names = (path) => path.map((node) => node === window ? "window"
                : node.localName || (node.nodeType === 9 ? "#document" : "#fragment")).join(",");

            const openHost = document.createElement("x-open");
            body.appendChild(openHost);
            const openRoot = openHost.attachShadow({ mode: "open" });
            openRoot.innerHTML = '<button><slot name="label"></slot></button>';
            const openButton = openRoot.querySelector("button");
            const openSlot = openRoot.querySelector("slot");
            const openLabel = document.createElement("span");
            openLabel.setAttribute("slot", "label");
            openLabel.textContent = "Weekly views";
            openHost.appendChild(openLabel);
            let openReached = false, openTarget = "", openPath = "", documentTarget = "";
            openButton.addEventListener("click", (event) => {
                openReached = true;
                openTarget = event.target.localName;
                openPath = names(event.composedPath());
            });
            document.addEventListener("click", (event) => { documentTarget = event.target.localName; });
            openLabel.dispatchEvent(new MouseEvent("click", { bubbles: true, composed: true }));

            const closedHost = document.createElement("x-closed-slot");
            body.appendChild(closedHost);
            const closedRoot = closedHost.attachShadow({ mode: "closed" });
            closedRoot.innerHTML = '<button><slot name="label"></slot></button>';
            const closedButton = closedRoot.querySelector("button");
            const closedLabel = document.createElement("span");
            closedLabel.setAttribute("slot", "label");
            closedHost.appendChild(closedLabel);
            let closedReached = false, closedInsidePath = "", closedOutsidePath = "";
            closedButton.addEventListener("click", (event) => {
                closedReached = true;
                closedInsidePath = names(event.composedPath());
            });
            closedHost.addEventListener("click", (event) => {
                closedOutsidePath = names(event.composedPath());
            });
            closedLabel.dispatchEvent(new MouseEvent("click", { bubbles: true, composed: true }));

            const textHost = document.createElement("x-text-slot");
            body.appendChild(textHost);
            const textRoot = textHost.attachShadow({ mode: "open" });
            textRoot.innerHTML = "<slot></slot>";
            const projectedText = document.createTextNode("projected");
            textHost.appendChild(projectedText);

            globalThis.slottedEventResult = [
                openLabel.parentNode === openHost,
                openLabel.assignedSlot === openSlot,
                openReached,
                openTarget,
                documentTarget,
                openPath,
                closedLabel.assignedSlot === null,
                closedReached,
                closedInsidePath,
                closedOutsidePath,
                projectedText.assignedSlot === textRoot.querySelector("slot")
            ].join("|");
            "##,
            "assigned-slot event parent",
        )
        .unwrap();

        assert_eq!(
            string_value(&mut engine, "slottedEventResult"),
            "true|true|true|span|span|span,slot,button,#fragment,x-open,body,html,#document,window|true|true|span,slot,button,#fragment,x-closed-slot,body,html,#document,window|span,x-closed-slot,body,html,#document,window|true"
        );
    }

    #[test]
    fn hyperlink_activation_uses_the_click_event_path() {
        // DOM §2.9 chooses the first activation-behavior object while building
        // the click event path. It can therefore be an ancestor of a Text or
        // Element target, can be reached through an assigned slot, and remains
        // the activation target even if a listener removes it before the
        // default action runs. HTML links with an empty href are hyperlinks too.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r##"
            const html = document.createElement("html");
            const body = document.createElement("body");
            document.appendChild(html);
            html.appendChild(body);

            const direct = document.createElement("a");
            direct.href = "/details/direct";
            const label = document.createElement("span");
            label.textContent = "direct";
            direct.appendChild(label);
            body.appendChild(direct);
            const text = label.firstChild;

            const host = document.createElement("x-link");
            const root = host.attachShadow({ mode: "closed" });
            root.innerHTML = '<a href="/details/slotted"><slot></slot></a>';
            const slotted = document.createElement("img");
            host.appendChild(slotted);
            body.appendChild(host);

            const removed = document.createElement("a");
            removed.href = "/details/removed";
            const removedLabel = document.createElement("span");
            removed.appendChild(removedLabel);
            body.appendChild(removed);
            removed.addEventListener("click", () => {
                removedLabel.remove();
                removed.remove();
            });
            const removedPrevented = __trust.click(removedLabel.__id);
            const removedDefault = __trust.followAnchorDefault(removedLabel.__id);

            const canceled = document.createElement("a");
            canceled.href = "/details/canceled";
            const canceledImage = document.createElement("img");
            canceled.appendChild(canceledImage);
            body.appendChild(canceled);
            canceled.addEventListener("click", event => event.preventDefault());

            const empty = document.createElement("a");
            empty.setAttribute("href", "");
            body.appendChild(empty);

            globalThis.hyperlinkActivationResult = [
                __trust.followAnchorDefault(text.__id),
                __trust.followAnchorDefault(slotted.__id),
                removedPrevented,
                removedDefault,
                __trust.click(canceledImage.__id),
                __trust.followAnchorDefault(empty.__id)
            ].join("|");
            "##,
            "hyperlink activation target",
        )
        .unwrap();

        assert_eq!(
            string_value(&mut engine, "hyperlinkActivationResult"),
            "https://example.com/details/direct|https://example.com/details/slotted|false|https://example.com/details/removed|true|https://example.com/"
        );
    }

    #[test]
    fn listener_discovery_tracks_once_abort_connection_and_child_retirement() {
        // DOM #add-an-event-listener, #remove-an-event-listener and
        // #concept-event-listener-invoke. Discovery caches must follow the
        // actual lists, including removal before a once callback is invoked.
        for tier in [Tier::Interp, Tier::Bytecode, Tier::Jit] {
            let mut engine = platform_engine();
            engine.set_tier(tier);
            engine.set_tier_threshold(0);
            eval(
                &mut engine,
                r#"
                const html = document.createElement('html');
                const body = document.createElement('body');
                document.appendChild(html); html.appendChild(body);
                const button = document.createElement('button'); body.appendChild(button);
                const has = (kind, el) => __trust[kind]().includes(el.__id);
                const check = (value, label) => { if (!value) throw Error(label); };
                check(!has('clickables', button) && !has('hoverables', button), 'empty');
                const click = () => {};
                button.addEventListener('click', click);
                button.addEventListener('click', click, {once:true});
                button.click();
                check(has('clickables', button), 'duplicate must not change once');
                __trust.clickables().length = 0;
                check(has('clickables', button), 'returned list is a snapshot');
                button.removeEventListener('click', click, true);
                check(has('clickables', button), 'capture mismatch');
                button.removeEventListener('click', click);
                check(!has('clickables', button), 'explicit removal');
                // Event types are exact strings. Network/keyboard listener
                // churn must preserve both presentation projections while
                // the corresponding event callbacks still run normally.
                button.addEventListener('Click', click);
                check(!has('clickables', button), 'event type is case sensitive');
                button.removeEventListener('Click', click);
                button.addEventListener('click', click);
                button.addEventListener('pointermove', click);
                check(has('clickables', button) && has('hoverables', button), 'warm both projections');
                let otherEvents = 0;
                const other = () => { otherEvents++; };
                const xhr = new XMLHttpRequest();
                xhr.addEventListener('readystatechange', other, {once:true});
                button.addEventListener('keydown', other);
                xhr.dispatchEvent(new Event('readystatechange'));
                button.dispatchEvent(new Event('keydown'));
                button.removeEventListener('keydown', other);
                check(otherEvents === 2 && has('clickables', button) && has('hoverables', button),
                    'unrelated event lists remain independent');
                button.removeEventListener('click', click);
                check(!has('clickables', button) && has('hoverables', button), 'remove only click');
                button.addEventListener('mouseenter', click);
                button.removeEventListener('pointermove', click);
                check(has('hoverables', button), 'another hover type retains membership');
                button.removeEventListener('mouseenter', click);
                check(!has('hoverables', button), 'remove only hover');
                button.addEventListener('click', () => {
                    check(!has('clickables', button), 'once removed before callback');
                }, {once:true});
                check(has('clickables', button), 'once addition'); button.click();
                const abort = new AbortController();
                button.addEventListener('pointermove', click, {signal:abort.signal});
                button.addEventListener('click', click, {signal:abort.signal});
                check(has('hoverables', button) && has('clickables', button), 'signal addition');
                abort.abort();
                check(!has('hoverables', button) && !has('clickables', button), 'abort removal');
                button.addEventListener('click', click, {signal:abort.signal});
                check(!has('clickables', button), 'already aborted');
                button.addEventListener('mouseover', click);
                button.addEventListener('click', click);
                check(has('hoverables', button) && has('clickables', button), 'connected');
                button.remove();
                check(!has('hoverables', button) && !has('clickables', button), 'detached');
                button.addEventListener('pointermove', other);
                button.removeEventListener('mouseover', click);
                check(!has('hoverables', button), 'detached registration is not a render target');
                body.appendChild(button);
                check(has('hoverables', button) && has('clickables', button), 'reattached');
                button.removeEventListener('pointermove', other);
                check(!has('hoverables', button) && has('clickables', button), 'reattached list is current');
                button.onpointerenter = click;
                check(has('hoverables', button), 'event handler property adds membership');
                button.onpointerenter = null;
                check(!has('hoverables', button), 'event handler property removes membership');
                const frame = document.createElement('iframe'); body.appendChild(frame);
                const child = frame.contentDocument.createElement('button');
                frame.contentDocument.body.appendChild(child);
                __trust.clickables(); __trust.hoverables();
                child.addEventListener('click', click);
                child.addEventListener('mouseenter', click);
                check(has('clickables', child) && has('hoverables', child), 'child registration');
                child.removeEventListener('click', click);
                check(!has('clickables', child) && has('hoverables', child), 'child removal');
                frame.remove();
                check(!has('clickables', child) && !has('hoverables', child), 'child retirement');
                globalThis.discoveryResult = 'ok';
                "#,
                "listener discovery",
            )
            .unwrap();
            assert_eq!(
                string_value(&mut engine, "discoveryResult"),
                "ok",
                "{tier:?}"
            );
            assert_eq!(
                string_value(&mut engine, "__trust.takeErrors()"),
                "",
                "{tier:?}"
            );
        }
    }

    #[test]
    fn detached_node_listeners_remain_observable_without_staying_render_roots() {
        // DOM removal does not erase a Node's event listener list: retained
        // detached nodes still dispatch, and reinsertion restores them to the
        // rendered event-target census. The host registry must hold detached
        // targets weakly so it does not become their only lifetime owner.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r##"
            const html = document.createElement("html");
            const body = document.createElement("body");
            document.appendChild(html); html.appendChild(body);
            const button = document.createElement("button");
            body.appendChild(button);
            let hits = 0;
            button.addEventListener("click", () => hits++);
            const id = button.__id;
            button.remove();
            button.click();
            const detachedIsRendered = __trust.clickables().indexOf(id) >= 0;
            body.appendChild(button);
            const reinsertedIsRendered = __trust.clickables().indexOf(id) >= 0;
            button.click();
            globalThis.detachedListenerResult = [
                hits, detachedIsRendered, reinsertedIsRendered
            ].join("|");
            "##,
            "detached event-listener retention",
        )
        .unwrap();

        assert_eq!(
            string_value(&mut engine, "detachedListenerResult"),
            "2|false|true"
        );
    }

