    #[test]
    fn checkbox_and_radio_click_activation_follows_dom_and_html_ordering() {
        // WHATWG DOM §2.9 runs legacy-pre-activation before click listeners and
        // canceled activation after a prevented click. HTML §4.10.5 defines
        // checkbox/radio state changes plus the subsequent input/change events.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r##"
            const html = document.createElement("html");
            const body = document.createElement("body");
            document.appendChild(html); html.appendChild(body);

            const box = document.createElement("input");
            box.type = "checkbox";
            box.indeterminate = true;
            body.appendChild(box);
            const boxEvents = [];
            box.addEventListener("click", () => {
                boxEvents.push(`click:${box.checked}:${box.indeterminate}`);
                box.click(); // The click-in-progress flag suppresses recursion.
            });
            box.addEventListener("input", event => boxEvents.push(`input:${box.checked}:${event.composed}:${event.isTrusted}`));
            box.addEventListener("change", event => boxEvents.push(`change:${box.checked}:${event.isTrusted}`));
            box.click();

            const canceled = document.createElement("input");
            canceled.type = "checkbox";
            canceled.checked = true;
            canceled.indeterminate = true;
            body.appendChild(canceled);
            const canceledEvents = [];
            canceled.addEventListener("click", event => {
                canceledEvents.push(`click:${canceled.checked}:${canceled.indeterminate}`);
                event.preventDefault();
            });
            canceled.addEventListener("input", () => canceledEvents.push("input"));
            canceled.addEventListener("change", () => canceledEvents.push("change"));
            canceled.click();

            const first = document.createElement("input");
            const second = document.createElement("input");
            first.type = second.type = "radio";
            first.name = second.name = "group";
            first.checked = true;
            body.appendChild(first); body.appendChild(second);
            const radioEvents = [];
            second.addEventListener("click", () => radioEvents.push(`click:${first.checked}:${second.checked}`));
            second.addEventListener("input", () => radioEvents.push("input"));
            second.addEventListener("change", () => radioEvents.push("change"));
            second.click();

            const disabled = document.createElement("input");
            disabled.type = "checkbox";
            disabled.disabled = true;
            body.appendChild(disabled);
            let disabledClicks = 0;
            disabled.addEventListener("click", () => disabledClicks++);
            disabled.click();

            globalThis.inputClickActivationResult = [
                boxEvents.join(","), box.checked, box.indeterminate,
                canceledEvents.join(","), canceled.checked, canceled.indeterminate,
                radioEvents.join(","), first.checked, second.checked,
                disabledClicks, disabled.checked
            ].join("|");
            "##,
            "input click activation",
        )
        .unwrap();

        assert_eq!(
            string_value(&mut engine, "inputClickActivationResult"),
            "click:true:false,input:true:true:true,change:true:true|true|false|click:false:false|true|true|click:false:true,input,change|false|true|0|false"
        );
    }

    #[test]
    fn quirks_mode_css_style_declarations_accept_quirky_lengths() {
        // CSS Values 4 #deprecated-quirky-length: a quirks-mode Document's
        // inline styles and sheets read a number as px in the listed
        // properties, as old DHTML scripts expect (`el.style.left = x`).
        // Shorthands, functions and CSS.supports() keep the ordinary grammar.
        for quirks in [true, false] {
            let source = format!(
                "{}<style>#a {{ top: 20 }}</style><div id=a style='left: 30'></div>",
                if quirks { "" } else { "<!doctype html>" }
            );
            let dom = Rc::new(RefCell::new(Dom::parse_document(&source)));
            let mut engine =
                configured_engine(HostState::new(dom, Rc::new(RealmClock::new())), DEFAULT_URL);
            let expected = if quirks {
                "200px|60px|5px 10px||30px|20px|20px|7px|false"
            } else {
                "||||||auto||false"
            };
            assert_eq!(
                string_value(
                    &mut engine,
                    r#"(() => {
                    const a = document.getElementById('a');
                    a.style.left = 200;
                    a.style.setProperty('width', '60');
                    a.style.margin = '5 10';
                    a.style.padding = 'calc(5)';
                    a.style.inset = '1 2 3 4';
                    const parsed = document.createElement('div');
                    parsed.setAttribute('style', 'left: 30');
                    const sheet = document.styleSheets[0];
                    const rule = sheet.cssRules[0];
                    sheet.insertRule('#b { right: 7 }', 1);
                    return [a.style.left, a.style.width, a.style.margin, a.style.bottom,
                        parsed.style.left, rule.style.top, getComputedStyle(a).top,
                        sheet.cssRules[1].style.right, CSS.supports('top', '5')].join('|');
                })()"#
                ),
                expected,
                "quirks: {quirks}"
            );
        }
    }

    #[test]
    fn font_face_attributes_parse_as_font_face_descriptors() {
        // CSS Font Loading 3 #fontface-interface / #font-face-constructor:
        // attributes hold the serialization of their parsed @font-face
        // descriptor; an invalid one throws SyntaxError, and an invalid
        // constructor argument makes the face an error face.
        let mut engine = platform_engine();
        assert_eq!(
            string_value(
                &mut engine,
                r#"(() => {
                const face = new FontFace("Test Face", "url(a.woff2) format('woff2')", {
                    weight: "700 700", stretch: "Condensed", style: "oblique 10deg 10deg",
                    display: "SWAP", sizeAdjust: "90%", featureSettings: "'liga' on",
                });
                let thrown = "";
                try { face.weight = "bolder"; } catch (e) { thrown = e.name; }
                face.ascentOverride = "80%";
                const bad = new FontFace("Bad", "url(a.woff2)", { weight: "lighter" });
                return [face.family, face.weight, face.stretch, face.width, face.style,
                    face.display, face.sizeAdjust, face.featureSettings, face.ascentOverride,
                    face.unicodeRange, face.status, thrown, bad.status, bad.weight === ""].join("|");
            })()"#
            ),
            "Test Face|700|condensed|condensed|oblique 10deg|swap|90%|\"liga\"|80%|U+0-10FFFF|unloaded|SyntaxError|error|true"
        );
    }

    #[test]
    fn css_style_declaration_rejects_unitless_nonzero_lengths() {
        // CSSOM §6.7.1 + CSS Values 4 §6: assigning a JS number to a length
        // property stringifies it, but the resulting nonzero <number> is not a
        // <length> and must leave the declaration block unchanged.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r##"
            const html = document.createElement("html");
            const head = document.createElement("head");
            const body = document.createElement("body");
            document.appendChild(html);
            html.appendChild(head);
            html.appendChild(body);
            const style = document.createElement("style");
            style.textContent = "#frame { height: 100%; }";
            head.appendChild(style);
            const frame = document.createElement("iframe");
            frame.id = "frame";
            body.appendChild(frame);
            frame.style.height = innerHeight;
            const invalidProperty = frame.style.height;
            frame.style.width = 0;
            globalThis.cssLengthAssignmentResult = [
                invalidProperty,
                document.styleSheets[0].cssRules[0].style.height,
                getComputedStyle(frame).height,
                frame.style.width,
                CSS.supports("height", "518"),
                CSS.supports("height", "0")
            ].join("|");
            "##,
            "CSSStyleDeclaration length validation",
        )
        .unwrap();
        assert_eq!(
            string_value(&mut engine, "cssLengthAssignmentResult"),
            // CSSOM #resolved-values: a zero-width iframe still has a box.
            // Its auto-containing-block percentage height uses the 150px
            // default replaced height; the original declaration stays 100%.
            "|100%|150px|0|false|true"
        );
    }

