    #[test]
    fn hyperlink_url_components_update_href_with_url_setter_semantics() {
        // HTML §4.6.3 (HyperlinkElementUtils): component setters parse with the
        // URL state override and then update the href content attribute. SCM
        // Music Player uses an <a> as a URL builder before creating its iframe;
        // a no-op pathname setter sends that iframe to script.js instead of the
        // player document.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r##"
            const a = document.createElement("a");
            a.href = "/script.js";
            const absent = document.createElement("a");
            absent.pathname = "/should-not-create-a-url";
            a.pathname = "player";
            a.search = "hostBridge=1";
            a.hash = "destination";
            const area = document.createElement("area");
            area.href = "https://example.test/old";
            area.pathname = "/new";
            // HTML "API for hyperlink elements": username and password.
            const credentials = document.createElement("a");
            credentials.href = "https://user:secret@example.test/";
            const credentialsBefore = credentials.username + ":" + credentials.password;
            credentials.username = "me";
            credentials.password = "";
            const mail = document.createElement("a");
            mail.href = "mailto:you@example.net";
            mail.username = "me";
            globalThis.hyperlinkSetterResult = [
                a.href,
                a.getAttribute("href"),
                a.pathname,
                a.search,
                a.hash,
                area.href,
                absent.hasAttribute("href"),
                absent.protocol,
                credentialsBefore,
                credentials.href,
                mail.href,
                absent.username === "" && absent.password === ""
            ].join("|");
            "##,
            "hyperlink URL component setters",
        )
        .unwrap();

        assert_eq!(
            string_value(&mut engine, "hyperlinkSetterResult"),
            "https://example.com/player?hostBridge=1#destination|https://example.com/player?hostBridge=1#destination|/player|?hostBridge=1|#destination|https://example.test/new|false|:|\
             user:secret|https://me@example.test/|mailto:you@example.net|true"
        );
    }

    #[test]
    fn html_global_attributes_reflect_access_key_autofocus_and_dir() {
        // HTML #dom-accesskey, #dom-fe-autofocus, #dom-dir and
        // #dom-document-dir (local whatwg/html@e5071a2): DOMString, boolean
        // and limited-to-only-known-values enumerated reflection.
        let mut engine = platform_engine();
        assert_eq!(
            string_value(
                &mut engine,
                r#"(() => {
                const div = document.createElement('div');
                const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
                const results = [JSON.stringify(div.accessKey), div.autofocus, svg.autofocus, JSON.stringify(div.dir)];
                div.accessKey = null; div.autofocus = 1; svg.autofocus = true;
                results.push(div.getAttribute('accesskey'), div.getAttribute('autofocus') === '',
                    svg.hasAttribute('autofocus'));
                div.autofocus = 0;
                results.push(div.hasAttribute('autofocus'));
                for (const value of ['LTR', 'rtl', 'Auto', 'foo', '', 'ltr ']) {
                    div.setAttribute('dir', value);
                    results.push(JSON.stringify(div.dir));
                }
                div.dir = 'RTL';
                results.push(div.getAttribute('dir'));
                if (document.documentElement) document.documentElement.remove();
                document.dir = 'rtl';
                results.push(JSON.stringify(document.dir));
                document.appendChild(document.createElement('html')).setAttribute('dir', 'RTL');
                results.push(document.dir);
                document.dir = 'bogus';
                results.push(JSON.stringify(document.dir), document.documentElement.getAttribute('dir'));
                const enumerable = Object.getOwnPropertyDescriptor(HTMLElement.prototype, 'accessKey').enumerable;
                results.push(enumerable, 'autofocus' in HTMLElement.prototype && 'autofocus' in SVGElement.prototype);
                return results.join('|');
            })()"#
            ),
            "\"\"|false|false|\"\"|null|true|true|false|\"ltr\"|\"rtl\"|\"auto\"|\"\"|\"\"|\"\"|RTL|\"\"|rtl|\"\"|bogus|true|true"
        );
    }

    #[test]
    fn dom_token_list_uses_an_ordered_set_and_validates_tokens() {
        // DOM #interface-domtokenlist (local whatwg/dom@a2331a4): the token
        // set parses as an ordered set on ASCII whitespace, mutations validate
        // tokens and run the update steps, and classList is [PutForwards=value].
        let mut engine = platform_engine();
        assert_eq!(
            string_value(
                &mut engine,
                r#"(() => {
                const el = document.createElement('div');
                const list = el.classList, results = [];
                el.className = '   a  a b c ';
                results.push(list.length, list.item(1), list.contains('b c'));
                list.add('c');
                results.push(el.className);
                const bare = document.createElement('div');
                bare.classList.remove('a');
                bare.classList.toggle('x', false);
                results.push(bare.hasAttribute('class'));
                bare.classList.add();
                results.push(bare.hasAttribute('class'));
                for (const f of [() => list.add(''), () => list.remove('a b'), () => list.toggle('\t'),
                                 () => list.replace('a', ''), () => list.replace('a', 'x y')]) {
                    try { f(); results.push('none'); } catch (e) { results.push(e.name); }
                }
                el.className = 'a b a c';
                results.push(list.toggle('a', true), el.className);
                results.push(list.replace('c', 'b'), el.className, list.replace('zz', 'q'));
                el.classList = 'p q';
                results.push(el.className, list === el.classList);
                return results.join('|');
            })()"#
            ),
            "2|b\u{a0}c|true|a b\u{a0}c c|false|false|SyntaxError|InvalidCharacterError|InvalidCharacterError|\
             SyntaxError|InvalidCharacterError|true|a b a c|true|a b|false|p q|true"
        );
    }

