    #[test]
    fn bookmark_storage_policy_blocks_third_party_frames_and_hides_host_capabilities() {
        let _guard = crate::http::COOKIE_TEST_LOCK.lock().unwrap();
        crate::http::set_cookies_enabled(true);
        let mut engine = configured_engine(
            HostState::new(
                Rc::new(RefCell::new(Dom::new())),
                Rc::new(RealmClock::new()),
            ),
            "https://bookmark-policy.example/",
        );
        eval(&mut engine, r#"
            const html = document.createElement('html'), body = document.createElement('body');
            document.appendChild(html); html.appendChild(body);
            document.cookie = 'storagePolicy=top; Path=/';
            function createStoragePolicyRealm(url) {
                const frame = document.createElement('iframe'); body.appendChild(frame);
                __dom_load_frame(frame.__id, '<body></body>', url);
                frame.__contentDoc = undefined;
                return __dom_create_window_realm(__dom_allocate_job_context(), frame.__id, url,
                    __trust_cfg, window, window, frame, 0, '');
            }
            const third = createStoragePolicyRealm('https://third.example.net/');
            third.eval(`
                globalThis.policyResult = [];
                try { localStorage; policyResult.push('exposed'); }
                catch (e) { policyResult.push(e.name, e instanceof DOMException); }
                document.__id = 0;
                document.cookie = 'storagePolicy=attack; Path=/';
                policyResult.push(document.cookie, typeof __cookie_get, typeof __cookie_set,
                    typeof __storage_get, typeof __storage_set, typeof __storage_allowed);
            `);
            const sibling = createStoragePolicyRealm('https://sibling.bookmark-policy.example/');
            sibling.eval(`localStorage.marker = 'sibling'; document.cookie = 'child=visible; Path=/'; globalThis.policyResult = localStorage.marker + ':' + document.cookie;`);
            const insecure = createStoragePolicyRealm('http://bookmark-policy.example/');
            insecure.eval(`try { localStorage; globalThis.policyResult = 'exposed'; } catch (e) { globalThis.policyResult = e.name; }`);
            globalThis.bookmarkStoragePolicyResult = third.policyResult.join('|') + '|' + sibling.policyResult + '|' + insecure.policyResult + '|' + document.cookie;
            globalThis.fakeCookieDocument = new Document(0).cookie;
        "#, "bookmark storage policy").unwrap();
        assert_eq!(
            string_value(&mut engine, "bookmarkStoragePolicyResult"),
            "SecurityError|true||undefined|undefined|undefined|undefined|undefined|sibling:child=visible|SecurityError|storagePolicy=top"
        );
        assert_eq!(string_value(&mut engine, "fakeCookieDocument"), "");
    }

    #[test]
    fn challenge_cookie_context_follows_nested_realms_and_worker_context() {
        let _guard = crate::http::COOKIE_TEST_LOCK.lock().unwrap();
        crate::http::set_cookies_enabled(true);
        let mut engine = configured_engine(
            HostState::new(
                Rc::new(RefCell::new(Dom::new())),
                Rc::new(RealmClock::new()),
            ),
            "https://frame-challenge-owner.test/",
        );
        eval(
            &mut engine,
            r#"
            const frame = document.createElement('iframe');
            document.appendChild(frame); frame.__contentDoc = undefined;
            __dom_load_frame(frame.__id, '<body></body>', 'https://challenges.cloudflare.com/cdn-cgi/challenge-platform/frame-test');
            const third = __dom_create_window_realm(__dom_allocate_job_context(), frame.__id,
                'https://challenges.cloudflare.com/cdn-cgi/challenge-platform/frame-test',
                __trust_cfg, window, window, frame, 0, '');
            third.eval(`
                const frame = document.createElement('iframe');
                document.documentElement.appendChild(frame); frame.__contentDoc = undefined;
                __dom_load_frame(frame.__id, '<body></body>', 'https://nested.example.net/');
                __dom_create_window_realm(__dom_allocate_job_context(), frame.__id,
                    'https://nested.example.net/', __trust_cfg, window, top, frame, 0, '');
                document.cookie = 'cf_chl_script=still-blocked; Secure; SameSite=None';
                globalThis.cookieVisibility = document.cookie;
                try { localStorage; cookieVisibility += 'exposed'; }
                catch (e) { cookieVisibility += e.name; }
            `);
            globalThis.challengeCookieVisibility = third.cookieVisibility;
        "#,
            "challenge cookie context inheritance",
        )
        .unwrap();
        assert_eq!(
            string_value(&mut engine, "challengeCookieVisibility"),
            "SecurityError"
        );
        let contexts: Vec<_> = engine
            .ctx()
            .host_mut::<HostState>()
            .unwrap()
            .window_cookie_contexts
            .values()
            // Insertion also creates the initial about:blank documents.
            .filter(|(_, document_url, _)| document_url.scheme() == "https")
            .map(|(_, _, context)| context.clone())
            .collect();
        assert_eq!(contexts.len(), 2);
        for context in &contexts {
            assert!(context.cross_site_ancestor);
            assert_eq!(
                context.top_level_site.as_deref(),
                Some("https://frame-challenge-owner.test")
            );
        }
        let context = contexts
            .into_iter()
            .find(|c| {
                c.client
                    .as_ref()
                    .is_some_and(|url| url.host_str() == Some("challenges.cloudflare.com"))
            })
            .unwrap();
        let endpoint = context.client.clone().unwrap();
        let mut request =
            crate::http::Request::subresource(endpoint.clone(), &endpoint, "empty", None);
        request.cookie_context = Some(context.clone());
        request.fetch_policy = Some(crate::http::FetchPolicy {
            origin: endpoint.clone(),
            mode: crate::http::RequestMode::Cors,
            credentials: crate::http::CredentialsMode::SameOrigin,
        });
        crate::http::response_cookie(
            &request,
            "cf_clearance=frame; Secure; HttpOnly; SameSite=None; Path=/cdn-cgi/challenge-platform/frame-test",
        );
        assert_eq!(crate::http::request_cookies(&request), "cf_clearance=frame");

        // run_lumen_worker installs the launch owner's cookie context at id 0.
        // Test that retrieval keeps that owner rather than using the worker URL.
        let mut worker = platform_engine();
        worker
            .ctx()
            .host_mut::<HostState>()
            .unwrap()
            .window_cookie_contexts
            .insert(0, (DOCUMENT, endpoint.clone(), context));
        request.cookie_context = Some(cookie_context_for_id(worker.ctx(), 0));
        assert_eq!(crate::http::request_cookies(&request), "cf_clearance=frame");
        assert_eq!(
            request
                .cookie_context
                .as_ref()
                .unwrap()
                .top_level_site
                .as_deref(),
            Some("https://frame-challenge-owner.test")
        );
    }

