    #[test]
    fn clipboard_writes_need_transient_activation_and_a_frontend_clipboard() {
        // Clipboard API #check-clipboard-write-permission: with transient
        // activation the write reaches the frontend, whose answer settles it.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r#"
            const html = document.createElement('html'), body = document.createElement('body');
            document.append(html); html.append(body);
            globalThis.clipButton = document.createElement('button'); body.append(clipButton);
            globalThis.activate = () => {
                __trust.pointerButton(clipButton.__id, true, 5, 6);
                __trust.pointerButton(clipButton.__id, false, 5, 6);
            };
            globalThis.clipResults = [];
            globalThis.record = promise => promise.then(() => clipResults.push('ok'),
                error => clipResults.push(error.name));
            activate();
            record(navigator.clipboard.writeText('copied'));
            record(navigator.clipboard.writeText('refused'));
            record(navigator.clipboard.write([new ClipboardItem({'text/html': '<b>x</b>',
                'text/plain': Promise.resolve('item text')})]));
            record(navigator.clipboard.write([new ClipboardItem({'image/png': new Blob(['x'], {type: 'image/png'})})]));
            "#,
            "clipboard writes",
        )
        .unwrap();
        for _ in 0..20 {
            run_microtask_checkpoint(&mut engine);
            if string_value(&mut engine, "__trust.hasPlatformTask()") != "true" {
                break;
            }
            eval(&mut engine, "__trust.runPlatformTask()", "clipboard task").unwrap();
        }
        let requests = std::mem::take(
            &mut engine
                .ctx()
                .host_mut::<HostState>()
                .unwrap()
                .clipboard_requests,
        );
        assert_eq!(
            requests
                .iter()
                .map(|(_, text)| text.as_str())
                .collect::<Vec<_>>(),
            ["copied", "refused", "item text"]
        );
        assert_eq!(
            string_value(&mut engine, "clipResults.join()"),
            "NotAllowedError"
        );
        for ((request, _), ok) in requests.into_iter().zip([true, false, true]) {
            assert!(settle_clipboard_request(engine.ctx(), request, ok).is_ok());
        }
        for _ in 0..20 {
            run_microtask_checkpoint(&mut engine);
            if string_value(&mut engine, "__trust.hasPlatformTask()") != "true" {
                break;
            }
            eval(&mut engine, "__trust.runPlatformTask()", "clipboard result").unwrap();
        }
        assert_eq!(
            string_value(&mut engine, "clipResults.join()"),
            "NotAllowedError,ok,NotAllowedError,ok"
        );
        assert!(
            engine
                .ctx()
                .host_mut::<HostState>()
                .unwrap()
                .clipboard_settlers
                .is_empty()
        );
    }

    #[test]
    fn permissions_query_brands_cross_realms_and_checks_retired_documents() {
        let mut engine = platform_engine();
        eval(&mut engine, r#"
            const html=document.createElement('html'), body=document.createElement('body');
            document.appendChild(html); html.appendChild(body);
            const frame=document.createElement('iframe'); body.appendChild(frame);
            const foreign=frame.contentWindow, permissions=foreign.navigator.permissions;
            const getter=Object.getOwnPropertyDescriptor(Navigator.prototype,'permissions').get;
            if (getter.call(foreign.navigator)!==permissions) throw Error('foreign Navigator getter');
            let reads=0;
            const borrow=Permissions.prototype.query.call(permissions,{get name(){reads++;return 'unsupported';}});
            if (reads!==1) throw Error('cross-Realm Permissions not branded');
            frame.remove();
            let inactiveRead=false;
            const inactive=permissions.query({get name(){inactiveRead=true;return 'unsupported';}});
            const invalidObject=permissions.query(null);
            globalThis.permissionRealmResult='pending';
            Promise.all([borrow.catch(e=>e.name),inactive.catch(e=>e.name+':'+(e instanceof foreign.DOMException)),
                invalidObject.catch(e=>e.name)]).then(values=> {
                    permissionRealmResult=values.join('|')+'|'+inactiveRead;
                });
        "#, "permission Realm ownership").unwrap();
        run_microtask_checkpoint(&mut engine);
        assert_eq!(
            string_value(&mut engine, "permissionRealmResult"),
            "TypeError|InvalidStateError:true|TypeError|false"
        );
    }

    #[test]
    fn history_delta_methods_preserve_receiver_conversion_and_async_state() {
        // HTML #delta-traverse / #restore-the-history-object-state;
        // Web IDL #js-long. The frontend chooses a valid target asynchronously.
        for tier in [Tier::Interp, Tier::Bytecode, Tier::Jit] {
            let mut engine = configured_engine(
                HostState::new(
                    Rc::new(RefCell::new(Dom::parse_document("<body></body>"))),
                    Rc::new(RealmClock::new()),
                ),
                "https://example.test/start",
            );
            engine.set_tier(tier);
            engine.set_tier_threshold(0);
            eval(&mut engine, r#"
                const check=(ok,msg)=>{if(!ok)throw Error(msg)};
                const throws=(f,name)=>{try{f()}catch(e){check(e.name===name,'wrong error '+e);return}throw Error('missing '+name)};
                const frame=document.createElement('iframe');document.body.append(frame);
                const childHistory=frame.contentWindow.history, borrowedGo=childHistory.go;
                history.pushState({n:1},'', '#one');
                history.state.n=99;
                history.pushState({n:2},'', '#two');
                history.pushState({n:3},'', '#three');
                let events=[];
                addEventListener('popstate',e=>{events.push('pop:'+e.state.n);check(e.isTrusted,'trusted popstate')});
                addEventListener('hashchange',()=>events.push('hash'));
                frame.remove();
                borrowedGo.call(history, -2.8);
                check(location.hash==='#three'&&history.state.n===3&&!events.length,'traversal must be asynchronous');
                __trust.traverseHistory('https://example.test/start#one',-2);
                check(history.state.n===1&&location.hash==='#one','restore serialized state');
                check(events.join(',')==='pop:1','popstate before queued hashchange');
                __trust.runPlatformTask();
                check(events.join(',')==='pop:1,hash','queued hashchange');
                history.forward(); history.back(); history.go(4294967295);
                let converted=false;
                throws(()=>borrowedGo.call({}, {valueOf(){converted=true;return 1}}),'TypeError');
                check(!converted,'brand before conversion');
                throws(()=>borrowedGo.call(childHistory, Symbol()),'TypeError');
                throws(()=>borrowedGo.call(childHistory, -1),'SecurityError');
                throws(()=>history.go(1n),'TypeError');
                for(const value of [undefined,null,NaN,Infinity,0]){
                    history.go(value);
                    const request=__trust.takeNavigationRequest();
                    check(request&&request[0]===location.href&&request[1]==='reload','zero delta reload');
                }
            "#, "history delta methods").unwrap();
            let pending = &engine
                .ctx()
                .host_mut::<HostState>()
                .unwrap()
                .history_traversals;
            assert_eq!(pending, &[(0, -2), (0, 1), (0, -1), (0, -1)], "{tier:?}");
        }
    }

    #[test]
    fn history_interface_exposes_router_compatible_prototype() {
        // WHATWG HTML #the-history-interface and Web IDL #js-interfaces /
        // #interface-object / #interface-prototype-object: History is exposed
        // as a non-constructible interface object even though its instance is
        // supplied by Window.history. Framer and similar routers borrow
        // History.prototype.replaceState during startup.
        for tier in [Tier::Interp, Tier::Bytecode, Tier::Jit] {
            let mut engine = configured_engine(
                HostState::new(
                    Rc::new(RefCell::new(Dom::parse_document("<body></body>"))),
                    Rc::new(RealmClock::new()),
                ),
                "https://example.test/blog/article",
            );
            engine.set_tier(tier);
            engine.set_tier_threshold(0);
            assert_eq!(
                string_value(
                    &mut engine,
                    r#"(() => {
                    const check = (ok, message) => { if (!ok) throw Error(message); };
                    check(typeof window.History === 'function', 'History interface missing');
                    check(window.history instanceof window.History, 'history brand missing');
                    check(Object.getPrototypeOf(window.history) === window.History.prototype,
                        'history prototype missing');
                    check(window.History.prototype.replaceState === window.history.replaceState,
                        'replaceState is not inherited');
                    window.History.prototype.replaceState.call(window.history, {route:'article'}, '', null);
                    const updates = JSON.parse(__trust.takeHistoryUpdates());
                    check(updates.length === 1 && updates[0].replace, 'borrowed replaceState failed');
                    check(window.history.state.route === 'article', 'history state missing');
                    check(window.history.scrollRestoration === 'auto', 'default restoration mode');
                    window.history.scrollRestoration = 'manual';
                    check(window.history.scrollRestoration === 'manual', 'restoration setter failed');
                    let threw = false;
                    try { new window.History(); } catch (error) { threw = error instanceof TypeError; }
                    check(threw, 'History must not be constructible');
                    return 'history-interface-ok';
                })()"#,
                ),
                "history-interface-ok",
                "{tier:?}"
            );
        }
    }

    #[test]
    fn history_state_methods_use_the_receiver_across_window_realms() {
        // Local WHATWG HTML snapshot e5071a20 (2026-09-06):
        // #shared-history-push/replace-state-steps, #can-have-its-url-rewritten,
        // #restore-the-history-object-state; Web IDL #dfn-create-operation-function.
        for tier in [Tier::Interp, Tier::Bytecode, Tier::Jit] {
            let mut engine = configured_engine(
                HostState::new(
                    Rc::new(RefCell::new(Dom::parse_document(
                        "<!doctype html><html><head><base href='/search/'></head><body></body></html>",
                    ))),
                    Rc::new(RealmClock::new()),
                ),
                "https://example.test/home",
            );
            engine.set_tier(tier);
            engine.set_tier_threshold(0);
            eval(&mut engine, r#"
                const check = (condition, message) => { if (!condition) throw Error(message); };
                const throws = (f, name) => {
                    try { f(); } catch (e) { check(e.name === name, 'expected '+name+', got '+e); return; }
                    throw Error('missing '+name);
                };
                const frame = document.createElement('iframe'); document.body.appendChild(frame);
                const child = frame.contentWindow, childHistory = child.history;
                const borrowedPush = childHistory.pushState, borrowedReplace = childHistory.replaceState;
                const originalPush = history.pushState, originalReplace = history.replaceState;
                const initialLength = history.length;
                let events = 0;
                addEventListener('popstate', () => events++);
                addEventListener('hashchange', () => events++);
                const input = {query: ['rust']}; input.self = input;
                borrowedPush.call(history, input, '', 'results?q=rust#list');
                check(location.href === 'https://example.test/search/results?q=rust#list', 'receiver base URL');
                check(document.URL === location.href, 'Document URL updated');
                check(history.length === initialLength + 1, 'receiver history length');
                check(history.state !== input && history.state.self === history.state, 'state cloned with cycles');
                check(history.state.query instanceof Array, 'state uses receiver Realm');
                check(child.location.href === 'about:blank' && childHistory.state === null, 'child untouched');
                input.query[0] = 'changed'; check(history.state.query[0] === 'rust', 'state detached');

                originalReplace.call(childHistory, {child: true}, '', null);
                check(childHistory.state.child && childHistory.state instanceof child.Object, 'reverse borrow targets child');
                check(history.state.query[0] === 'rust', 'reverse borrow leaves parent untouched');
                frame.remove();
                borrowedReplace.call(history, {search: 'next'}, '', '/results?q=next');
                check(location.pathname === '/results' && history.state.search === 'next', 'removed source Realm method');
                check(history.length === initialLength + 1, 'replace preserves length');
                const saved = history.state, href = location.href;
                for (const url of ['https://other.test/', 'http://example.test/', 'https://user@example.test/']) {
                    throws(() => borrowedReplace.call(history, {bad: true}, '', url), 'SecurityError');
                    check(history.state === saved && location.href === href, 'rejection must be atomic');
                }
                throws(() => originalPush.call(childHistory, {}, '', null), 'SecurityError');
                let converted = false;
                throws(() => borrowedPush.call({}, {}, {toString(){converted=true;return '';}}, '/x'), 'TypeError');
                check(!converted, 'receiver checked before arguments');
                for (const receiver of [null, undefined, Object.create(history), new Proxy(history, {})])
                    throws(() => borrowedReplace.call(receiver, {}, ''), 'TypeError');
                throws(() => borrowedReplace.call(history, {}), 'TypeError');
                throws(() => borrowedReplace.call(history, {}, Symbol()), 'TypeError');
                throws(() => borrowedReplace.call(history, {}, '', Symbol()), 'TypeError');
                throws(() => borrowedReplace.call(history, () => {}, '', '/x'), 'DataCloneError');
                check(history.state === saved && location.href === href, 'clone failure must be atomic');
                for (const url of [undefined, null, '']) {
                    borrowedReplace.call(history, {url}, '', url);
                    check(location.href === href, 'empty URL keeps Document URL despite base element');
                }
                check(events === 0, 'history state update does not fire navigation events');
                const updates = JSON.parse(__trust.takeHistoryUpdates());
                check(updates[0].url === 'https://example.test/search/results?q=rust#list' && !updates[0].replace,
                    'host receives parent push');
                check(updates[1].url === href && updates[1].replace, 'host receives parent replace');
                check(updates.length === 5, 'no failed or child update delivered as parent history');
            "#, "borrowed History operations").unwrap();
        }
    }

    #[test]
    fn storage_apis_indexed_db_rejects_opaque_origin_at_the_operation_boundary() {
        // Indexed Database #dom-idbfactory-open / -deletedatabase / -databases:
        // open/delete throw synchronously, databases returns a rejected promise.
        // Invalid version conversion precedes the storage-key security check.
        let mut engine = configured_engine(
            HostState::new(
                Rc::new(RefCell::new(Dom::new())),
                Rc::new(RealmClock::new()),
            ),
            "data:text/html,",
        );
        eval(
            &mut engine,
            r#"
            const errors = [];
            for (const op of [() => indexedDB.open('x', 0),
                () => indexedDB.open('x'), () => indexedDB.deleteDatabase('x')]) {
                try { op(); errors.push('allowed'); }
                catch(e) { errors.push(e.name); }
            }
            globalThis.result = 'pending';
            indexedDB.databases().then(() => result = 'allowed', e => {
                result = errors.join('|') + '|' + e.name + '|' + (e instanceof DOMException);
            });
        "#,
            "opaque database storage security",
        )
        .unwrap();
        run_microtask_checkpoint(&mut engine);
        assert_eq!(
            string_value(&mut engine, "result"),
            "TypeError|SecurityError|SecurityError|SecurityError|true"
        );
    }

    #[test]
    fn referrer_policy_reflections_and_request_init_follow_html_and_fetch() {
        // HTML #referrer-policy-attributes: a, area, img, iframe, link and script reflect
        // referrerpolicy limited to the known values (missing and invalid are ""). Fetch
        // #dom-request: RequestInit.referrerPolicy must be a ReferrerPolicy enumeration value.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r##"
            const out = [];
            for (const tag of ["a", "area", "img", "iframe", "link", "script"]) {
                const element = document.createElement(tag);
                const missing = element.referrerPolicy;
                element.setAttribute("referrerpolicy", "NO-REFERRER");
                const upper = element.referrerPolicy;
                element.setAttribute("referrerpolicy", "never");
                const invalid = element.referrerPolicy;
                element.referrerPolicy = "origin";
                out.push([tag, JSON.stringify(missing), upper, JSON.stringify(invalid),
                    element.getAttribute("referrerpolicy")].join(":"));
            }
            out.push(new Request("https://example.test/", {referrerPolicy: "same-origin"}).referrerPolicy);
            out.push(JSON.stringify(new Request("https://example.test/").referrerPolicy));
            try { new Request("https://example.test/", {referrerPolicy: "never"}); out.push("accepted"); }
            catch (error) { out.push(error.name); }
            globalThis.reflectionResult = out.join("|");
            "##,
            "referrer policy reflections",
        )
        .unwrap();
        assert_eq!(
            string_value(&mut engine, "reflectionResult"),
            [
                r#"a:"":no-referrer:"":origin"#,
                r#"area:"":no-referrer:"":origin"#,
                r#"img:"":no-referrer:"":origin"#,
                r#"iframe:"":no-referrer:"":origin"#,
                r#"link:"":no-referrer:"":origin"#,
                r#"script:"":no-referrer:"":origin"#,
                "same-origin",
                r#""""#,
                "TypeError",
            ]
            .join("|")
        );
    }

    #[test]
    fn blob_module_scripts_are_obtained_for_their_partition_with_a_javascript_type() {
        // HTML #fetch-a-single-module-script with Fetch #scheme-fetch "blob": the entry is
        // obtained for the module's settings object (File API
        // #check-for-same-partition-blob-url-usage), its type must be a JavaScript MIME type,
        // and an import map's integrity metadata applies to its bytes.
        let store = crate::js::BlobMap::default();
        let source = b"export default 1;".to_vec();
        store.add_bytes("blob:https://a.test/1", source.clone(), "text/javascript");
        store.add_bytes("blob:https://a.test/2", source.clone(), "text/plain");
        let environment = |key: &str| ModuleFetchEnvironment {
            blobs: store.clone(),
            storage_key: key.to_string(),
            referrer_policy: Default::default(),
        };
        let url = url::Url::parse("blob:https://a.test/1").unwrap();
        assert_eq!(
            environment("https://a.test").blob_module(&url, ""),
            Some((url.to_string(), String::from("export default 1;")))
        );
        assert_eq!(environment("https://b.test").blob_module(&url, ""), None);
        let text = url::Url::parse("blob:https://a.test/2").unwrap();
        assert_eq!(environment("https://a.test").blob_module(&text, ""), None);
        assert_eq!(
            environment("https://a.test")
                .blob_module(&url, "sha256-AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA="),
            None
        );
        let gone = url::Url::parse("blob:https://a.test/3").unwrap();
        assert_eq!(environment("https://a.test").blob_module(&gone, ""), None);
    }

    #[test]
    fn binary_storage_cookie_blob_and_popover_hosts_follow_the_platform_prelude() {
        // Encoding §7.4, Web Crypto §14.3.5, Compression Streams §4, Web Storage, cookies, File
        // API blob URLs, and HTML popover state all enter through the shared browser surface.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r##"
            const hex = value => Array.from(new Uint8Array(value))
                .map(byte => byte.toString(16).padStart(2, "0")).join("");
            const encoded = new TextEncoder().encode("Aé🙂");
            globalThis.binaryResult = [Array.from(encoded).join(",")];

            const source = new Uint8Array([0, 97, 98, 99, 0]);
            crypto.subtle.digest("SHA-256", source.subarray(1, 4))
                .then(value => binaryResult.push(hex(value)));
            crypto.subtle.digest("SHA-256", new DataView(source.buffer, 1, 3))
                .then(value => binaryResult.push(hex(value)));

            const compression = new CompressionStream("gzip");
            const writer = compression.writable.getWriter();
            const reader = compression.readable.getReader();
            writer.write(new TextEncoder().encode("hello"));
            writer.close();
            // The streaming gzip context emits the RFC 1952 header as its first chunk.
            reader.read().then(result => binaryResult.push(
                result.value[0] + "," + result.value[1] + "," + (result.value.byteLength >= 10)
            ));

            localStorage.clear();
            localStorage.setItem("alpha", "one");
            localStorage.setItem("beta", "two");
            const stored = [localStorage.length, localStorage.getItem("alpha")].join(":");
            localStorage.removeItem("beta");
            document.cookie = "lumen_port_cookie=ready; Path=/";

            const blobUrl = URL.createObjectURL(new Blob([
                new Uint8Array([0, 128, 255])
            ], { type: "application/x-lumen-port" }));
            globalThis.blobPortUrl = blobUrl;

            const popover = document.createElement("div");
            popover.setAttribute("popover", "auto");
            document.appendChild(popover);
            popover.showPopover();
            const open = popover.matches(":popover-open");
            popover.hidePopover();
            globalThis.hostStateResult = [
                stored,
                localStorage.length,
                document.cookie.includes("lumen_port_cookie=ready"),
                open,
                popover.matches(":popover-open")
            ].join("|");
            "##,
            "binary and stateful host boundary",
        )
        .unwrap();
        drain_platform_tasks(&mut engine, "__trust");

        assert_eq!(
            string_value(&mut engine, "binaryResult.join('|')"),
            // SubtleCrypto settles its promises in crypto task source tasks, after the
            // compression stream's read resolves in a microtask.
            "65,195,169,240,159,153,130|31,139,true|ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad|ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
        );
        assert_eq!(
            string_value(&mut engine, "hostStateResult"),
            "2:one|1|true|true|false"
        );

        let blob_url = string_value(&mut engine, "blobPortUrl");
        let blobs = engine
            .ctx()
            .host_mut::<HostState>()
            .expect("host state")
            .blobs
            .clone();
        let entry = blobs
            .resolve(&blob_url)
            .expect("the blob URL store has the entry");
        assert_eq!(
            (entry.read().unwrap(), entry.content_type.as_str()),
            (vec![0, 128, 255], "application/x-lumen-port")
        );
    }

    #[test]
    fn web_crypto_registered_algorithms_follow_the_web_cryptography_api() {
        // Web Cryptography API (local w3c/webcrypto@811c24c): #cryptokey-interface,
        // #SubtleCrypto-methods and every registered algorithm's operations, with
        // RFC 8032 / RFC 7748 / RFC 3394 / RFC 5869 / RFC 6070 / SP 800-38A vectors;
        // Web IDL #quotaexceedederror.
        platform_fixture_in_window_and_secure_worker(
            "web crypto",
            r#"
            const subtle = crypto.subtle;
            const hex = b => Array.from(new Uint8Array(b), x => x.toString(16).padStart(2, "0")).join("");
            const bytes = h => Uint8Array.from(h.match(/../g) || [], p => parseInt(p, 16));
            const b64 = h => bytes(h).toBase64({alphabet: "base64url", omitPadding: true});
            const text = s => new TextEncoder().encode(s);
            const message = text("Web Crypto");

            // Promises settle in tasks on the crypto task source.
            let settled = false;
            const pending = subtle.digest("SHA-256", new Uint8Array(0)).then(() => settled = true);
            await Promise.resolve();
            check(!settled, "settled before a task ran");
            await pending;
            await rejects(subtle.digest("MD5", message), "NotSupportedError", "unregistered digest");

            // CryptoKey: internal slots only, cached attribute objects, HMAC bit lengths.
            const hmac = await subtle.generateKey({name: "hmac", hash: "sha-256", length: 77}, true, ["sign"]);
            check(Reflect.ownKeys(hmac).length === 0 && hmac.algorithm === hmac.algorithm && hmac.usages === hmac.usages, "CryptoKey slots");
            const hmacRaw = new Uint8Array(await subtle.exportKey("raw", hmac));
            check(hmac.algorithm.name === "HMAC" && hmac.algorithm.length === 77 && hmacRaw.length === 10 && (hmacRaw[9] & 7) === 0, "HMAC length bits");
            throws(() => new CryptoKey(), "TypeError", "CryptoKey constructor");

            // RSA: generation, PKCS1 and PSS signatures, OAEP, SPKI/PKCS #8/JWK.
            const rsaAlgorithm = {name: "RSASSA-PKCS1-v1_5", modulusLength: 1024, publicExponent: new Uint8Array([1, 0, 1]), hash: "SHA-256"};
            const rsa = await subtle.generateKey(rsaAlgorithm, true, ["sign", "verify"]);
            check(Object.keys(rsa).join() === "privateKey,publicKey", "CryptoKeyPair");
            check(rsa.publicKey.algorithm.modulusLength === 1024 && hex(rsa.publicKey.algorithm.publicExponent) === "010001"
                && rsa.publicKey.algorithm.hash.name === "SHA-256", "RSA algorithm");
            check(rsa.publicKey.usages.join() === "verify" && rsa.privateKey.usages.join() === "sign" && rsa.publicKey.extractable, "RSA usages");
            const pkcs1 = await subtle.sign("RSASSA-PKCS1-v1_5", rsa.privateKey, message);
            check(pkcs1.byteLength === 128 && await subtle.verify("RSASSA-PKCS1-v1_5", rsa.publicKey, pkcs1, message), "PKCS1");
            check(!(await subtle.verify("RSASSA-PKCS1-v1_5", rsa.publicKey, pkcs1, text("other"))), "PKCS1 other data");
            await rejects(subtle.sign("RSASSA-PKCS1-v1_5", rsa.publicKey, message), "InvalidAccessError", "sign with a public key");
            const spki = await subtle.exportKey("spki", rsa.publicKey);
            const pkcs8 = await subtle.exportKey("pkcs8", rsa.privateKey);
            const jwk = await subtle.exportKey("jwk", rsa.privateKey);
            check(Object.keys(jwk).join() === "alg,d,dp,dq,e,ext,key_ops,kty,n,p,q,qi" && jwk.alg === "RS256" && jwk.e === "AQAB", "RSA JWK");
            const pss = await subtle.importKey("pkcs8", pkcs8, {name: "RSA-PSS", hash: "SHA-256"}, false, ["sign"]);
            const pssPublic = await subtle.importKey("jwk", {kty: "RSA", n: jwk.n, e: jwk.e}, {name: "RSA-PSS", hash: "SHA-256"}, true, ["verify"]);
            for (const saltLength of [0, 32, 94]) {
                const signature = await subtle.sign({name: "RSA-PSS", saltLength}, pss, message);
                check(await subtle.verify({name: "RSA-PSS", saltLength}, pssPublic, signature, message), "PSS salt " + saltLength);
            }
            await rejects(subtle.sign({name: "RSA-PSS", saltLength: 95}, pss, message), "OperationError", "PSS salt too long");
            check(hex(await subtle.exportKey("spki", pssPublic)) === hex(spki), "canonical SPKI");
            const dOnly = await subtle.importKey("jwk", {kty: "RSA", n: jwk.n, e: jwk.e, d: jwk.d}, {name: "RSASSA-PKCS1-v1_5", hash: "SHA-256"}, true, ["sign"]);
            check(hex(await subtle.sign("RSASSA-PKCS1-v1_5", dOnly, message)) === hex(pkcs1), "JWA 6.3.2 private key without CRT members");
            await rejects(subtle.importKey("jwk", {kty: "RSA", n: jwk.n, e: jwk.e, d: jwk.d, p: jwk.p}, {name: "RSASSA-PKCS1-v1_5", hash: "SHA-256"}, true, ["sign"]), "DataError", "partial CRT members");
            await rejects(subtle.importKey("jwk", {...jwk, alg: "RS384"}, {name: "RSASSA-PKCS1-v1_5", hash: "SHA-256"}, true, ["sign"]), "DataError", "JWK alg and hash");
            await rejects(subtle.importKey("jwk", {kty: "RSA", n: jwk.n, e: "AAEAAQ"}, {name: "RSASSA-PKCS1-v1_5", hash: "SHA-256"}, true, ["verify"]), "DataError", "non-minimal Base64urlUInt");
            await rejects(subtle.generateKey({...rsaAlgorithm, publicExponent: new Uint8Array([2])}, true, ["sign"]), "OperationError", "even exponent");
            await rejects(subtle.generateKey({...rsaAlgorithm, publicExponent: [1, 0, 1]}, true, ["sign"]), "TypeError", "BigInteger");
            await rejects(subtle.generateKey(rsaAlgorithm, true, ["encrypt"]), "SyntaxError", "RSA usages");
            const oaep = await subtle.generateKey({name: "RSA-OAEP", modulusLength: 1024, publicExponent: new Uint8Array([1, 0, 1]), hash: "SHA-1"},
                true, ["encrypt", "decrypt"]);
            const label = text("label");
            const ciphertext = await subtle.encrypt({name: "RSA-OAEP", label}, oaep.publicKey, message);
            check(hex(await subtle.decrypt({name: "RSA-OAEP", label}, oaep.privateKey, ciphertext)) === hex(message), "OAEP");
            await rejects(subtle.decrypt({name: "RSA-OAEP"}, oaep.privateKey, ciphertext), "OperationError", "OAEP label");

            // ECDSA and ECDH over P-256, P-384 and P-521.
            for (const [namedCurve, size] of [["P-256", 64], ["P-384", 96], ["P-521", 132]]) {
                const ec = await subtle.generateKey({name: "ECDSA", namedCurve}, true, ["sign", "verify"]);
                const signature = await subtle.sign({name: "ECDSA", hash: "SHA-384"}, ec.privateKey, message);
                check(signature.byteLength === size && await subtle.verify({name: "ECDSA", hash: "SHA-384"}, ec.publicKey, signature, message), "ECDSA " + namedCurve);
                const raw = new Uint8Array(await subtle.exportKey("raw", ec.publicKey));
                const compressed = new Uint8Array([2 + (raw[raw.length - 1] & 1), ...raw.subarray(1, 1 + (raw.length - 1) / 2)]);
                const decompressed = await subtle.importKey("raw", compressed, {name: "ECDSA", namedCurve}, true, ["verify"]);
                check(hex(await subtle.exportKey("raw", decompressed)) === hex(raw), "compressed point " + namedCurve);
                const ecJwk = await subtle.exportKey("jwk", ec.privateKey);
                check(Object.keys(ecJwk).join() === "crv,d,ext,key_ops,kty,x,y" && ecJwk.crv === namedCurve, "EC JWK " + namedCurve);
                await rejects(subtle.importKey("jwk", ecJwk, {name: "ECDSA", namedCurve: namedCurve === "P-256" ? "P-384" : "P-256"}, true, ["sign"]), "DataError", "crv mismatch");
            }
            await rejects(subtle.importKey("raw", new Uint8Array(65), {name: "ECDSA", namedCurve: "P-256"}, true, ["verify"]), "DataError", "invalid point");
            await rejects(subtle.generateKey({name: "ECDSA", namedCurve: "P-192"}, true, ["sign"]), "NotSupportedError", "unregistered curve");
            const alice = await subtle.generateKey({name: "ECDH", namedCurve: "P-256"}, false, ["deriveBits", "deriveKey"]);
            const bob = await subtle.generateKey({name: "ECDH", namedCurve: "P-256"}, false, ["deriveBits"]);
            check(alice.publicKey.usages.length === 0, "ECDH public usages");
            const ab = await subtle.deriveBits({name: "ECDH", public: bob.publicKey}, alice.privateKey, 256);
            const ba = await subtle.deriveBits({name: "ECDH", public: alice.publicKey}, bob.privateKey, null);
            check(ab.byteLength === 32 && hex(ab) === hex(ba), "ECDH agreement");
            const partial = new Uint8Array(await subtle.deriveBits({name: "ECDH", public: bob.publicKey}, alice.privateKey, 12));
            check(partial.length === 2 && partial[0] === new Uint8Array(ab)[0] && (partial[1] & 15) === 0, "first length bits");
            await rejects(subtle.deriveBits({name: "ECDH", public: bob.publicKey}, alice.privateKey, 264), "OperationError", "ECDH length");
            await rejects(subtle.deriveBits({name: "ECDH", public: bob.privateKey}, alice.privateKey, 256), "InvalidAccessError", "ECDH public member");
            const derived = await subtle.deriveKey({name: "ECDH", public: bob.publicKey}, alice.privateKey, {name: "AES-GCM", length: 128}, true, ["encrypt"]);
            check(hex(await subtle.exportKey("raw", derived)) === hex(ab).slice(0, 32), "deriveKey");

            // Ed25519 (RFC 8032 §7.1 TEST 1) and X25519 (RFC 7748 §6.1).
            const edSecret = "9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60";
            const edPublic = "d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a";
            const edSignature = "e5564300c360ac729086e2cc806e828a84877f1eb8e5d974d873e065224901555fb8821590a33bacc61e39701cf9b46bd25bf5f0595bbe24655141438e7a100b";
            const edPrivate = await subtle.importKey("jwk", {kty: "OKP", crv: "Ed25519", d: b64(edSecret), x: b64(edPublic)}, "Ed25519", true, ["sign"]);
            check(hex(await subtle.sign("Ed25519", edPrivate, new Uint8Array(0))) === edSignature, "Ed25519 sign");
            const edKey = await subtle.importKey("raw", bytes(edPublic), {name: "Ed25519"}, true, ["verify"]);
            check(await subtle.verify("Ed25519", edKey, bytes(edSignature), new Uint8Array(0)), "Ed25519 verify");
            const smallOrder = await subtle.importKey("raw", new Uint8Array(32), "Ed25519", true, ["verify"]);
            check(!(await subtle.verify("Ed25519", smallOrder, new Uint8Array(64), new Uint8Array(0))), "small-order key");
            check(hex(await subtle.exportKey("pkcs8", edPrivate)) === "302e020100300506032b657004220420" + edSecret, "RFC 8410 PKCS #8");
            const edJwk = await subtle.exportKey("jwk", edPrivate);
            check(Object.keys(edJwk).join() === "alg,crv,d,ext,key_ops,kty,x" && edJwk.alg === "Ed25519", "OKP JWK");
            await rejects(subtle.importKey("jwk", {kty: "OKP", crv: "Ed25519", d: b64(edSecret), x: b64(edSecret)}, "Ed25519", true, ["sign"]), "DataError", "x does not match d");
            const xAlice = "77076d0a7318a57d3c16c17251b26645df4c2f87ebc0992ab177fba51db92c2a";
            const xAlicePublic = "8520f0098930a754748b7ddcb43ef75a0dbf3a0d26381af4eba4a98eaa9b4e6a";
            const xBobPublic = "de9edb7d7b7dc1b4d35b61c2ece435373f8343c85b78674dadfc7e146f882b4f";
            const xShared = "4a5d9d5ba4ce2de1728e3bf480350f25e07e21c947d19e3376f09b3c1e161742";
            const xPrivate = await subtle.importKey("jwk", {kty: "OKP", crv: "X25519", d: b64(xAlice), x: b64(xAlicePublic)}, "X25519", false, ["deriveBits"]);
            const xPublic = await subtle.importKey("raw", bytes(xBobPublic), "X25519", true, []);
            check(hex(await subtle.deriveBits({name: "X25519", public: xPublic}, xPrivate, 256)) === xShared, "X25519");
            const zero = await subtle.importKey("raw", new Uint8Array(32), "X25519", true, []);
            await rejects(subtle.deriveBits({name: "X25519", public: zero}, xPrivate, 256), "OperationError", "all-zero secret");
            await rejects(subtle.importKey("raw", bytes(xBobPublic), "X25519", true, ["deriveBits"]), "SyntaxError", "X25519 public usages");

            // AES-CBC (SP 800-38A F.2.1), AES-KW (RFC 3394 §4.1), wrapKey and unwrapKey.
            const cbcKey = await subtle.importKey("raw", bytes("2b7e151628aed2a6abf7158809cf4f3c"), "AES-CBC", true, ["encrypt", "decrypt"]);
            const iv = bytes("000102030405060708090a0b0c0d0e0f");
            const cbc = await subtle.encrypt({name: "AES-CBC", iv}, cbcKey, bytes("6bc1bee22e409f96e93d7e117393172a"));
            check(cbc.byteLength === 32 && hex(cbc).startsWith("7649abac8119b246cee98e9b12e9197d"), "AES-CBC");
            check(hex(await subtle.decrypt({name: "AES-CBC", iv}, cbcKey, cbc)) === "6bc1bee22e409f96e93d7e117393172a", "AES-CBC decrypt");
            await rejects(subtle.decrypt({name: "AES-CBC", iv}, cbcKey, cbc.slice(0, 16)), "OperationError", "PKCS #7 padding");
            const kek = await subtle.importKey("raw", bytes("000102030405060708090a0b0c0d0e0f"), "AES-KW", false, ["wrapKey", "unwrapKey"]);
            const dataKey = await subtle.importKey("raw", bytes("00112233445566778899aabbccddeeff"), "AES-GCM", true, ["encrypt"]);
            const wrapped = await subtle.wrapKey("raw", dataKey, kek, "AES-KW");
            check(hex(wrapped) === "1fa68b0a8112b447aef34bd8fb5a7b829d3e862371d2cfe5", "RFC 3394 wrap");
            const unwrapped = await subtle.unwrapKey("raw", wrapped, kek, "AES-KW", "AES-GCM", false, ["encrypt"]);
            check(unwrapped.algorithm.name === "AES-GCM" && !unwrapped.extractable && unwrapped.usages.join() === "encrypt", "unwrapKey");
            await rejects(subtle.wrapKey("raw", unwrapped, kek, "AES-KW"), "InvalidAccessError", "wrap a non-extractable key");
            const wrapper = await subtle.generateKey({name: "AES-GCM", length: 256}, false, ["wrapKey", "unwrapKey"]);
            const gcmIv = new Uint8Array(12);
            const wrappedJwk = await subtle.wrapKey("jwk", dataKey, wrapper, {name: "AES-GCM", iv: gcmIv});
            // #concept-parse-a-jwk runs JSON.parse "in the context of a new global object".
            Object.defineProperty(Object.prototype, "kty", {get() { throw Error("author prototype read"); }, configurable: true});
            let unwrappedJwk;
            try {
                unwrappedJwk = await subtle.unwrapKey("jwk", wrappedJwk, wrapper, {name: "AES-GCM", iv: gcmIv}, "AES-GCM", true, ["encrypt"]);
            } finally { delete Object.prototype.kty; }
            check(hex(await subtle.exportKey("raw", unwrappedJwk)) === "00112233445566778899aabbccddeeff", "JWK wrapping through encrypt");

            // HKDF (RFC 5869 A.1) and PBKDF2 (RFC 6070 test 2).
            const ikm = await subtle.importKey("raw", new Uint8Array(22).fill(11), "HKDF", false, ["deriveBits"]);
            check(hex(await subtle.deriveBits({name: "HKDF", hash: "SHA-256", salt: bytes("000102030405060708090a0b0c"),
                info: bytes("f0f1f2f3f4f5f6f7f8f9")}, ikm, 336)) === "3cb25f25faacd57a90434f64d0362f2a2d2d0a90cf1a5a4c5db02d56ecc4c5bf34007208d5b887185865", "HKDF");
            await rejects(subtle.importKey("raw", new Uint8Array(1), "HKDF", true, ["deriveBits"]), "SyntaxError", "extractable HKDF key");
            const password = await subtle.importKey("raw", text("password"), "PBKDF2", false, ["deriveBits", "deriveKey"]);
            check(hex(await subtle.deriveBits({name: "PBKDF2", hash: "SHA-1", salt: text("salt"), iterations: 2}, password, 160))
                === "ea6c014dc72d6f8ccd1ed92ace1d41f0d8de8957", "PBKDF2");
            await rejects(subtle.deriveBits({name: "PBKDF2", hash: "SHA-1", salt: text("salt"), iterations: 0}, password, 160), "OperationError", "zero iterations");
            await rejects(subtle.exportKey("raw", password), "NotSupportedError", "PBKDF2 keys do not export");

            // #cryptokey-interface serialization keeps non-extractable keys usable.
            const clone = structuredClone({key: xPrivate}).key;
            check(clone instanceof CryptoKey && clone !== xPrivate && !clone.extractable && clone.usages.join() === "deriveBits", "CryptoKey clone");
            check(hex(await subtle.deriveBits({name: "X25519", public: xPublic}, clone, 256)) === xShared, "cloned key");

            // Web IDL #quotaexceedederror.
            try { crypto.getRandomValues(new Uint8Array(65537)); fails.push("no QuotaExceededError"); }
            catch (error) {
                check(error instanceof QuotaExceededError && error instanceof DOMException && error.code === 22
                    && error.quota === null && error.requested === null, "getRandomValues quota");
            }
            const quota = new QuotaExceededError("over", {quota: 1, requested: 2});
            check(quota.name === "QuotaExceededError" && quota.message === "over" && quota.quota === 1 && quota.requested === 2, "QuotaExceededError options");
            throws(() => new QuotaExceededError("m", {quota: 2, requested: 1}), "RangeError", "requested below quota");
            throws(() => new QuotaExceededError("m", {quota: NaN}), "TypeError", "restricted double");
            const quotaClone = structuredClone(quota);
            check(quotaClone instanceof QuotaExceededError && quotaClone.quota === 1 && quotaClone.requested === 2, "QuotaExceededError serialization");
            "#,
        );
    }

    #[test]
    fn broadcast_channel_serializes_at_post_and_delivers_to_same_key_channels() {
        // HTML #broadcasting-to-other-browsing-contexts (local whatwg/html@e5071a2):
        // StructuredSerialize at postMessage, every other open same-name channel
        // of the storage key in creation order, closed channels skipped, and
        // MessageEvents (#the-messageevent-interface) carrying the source origin.
        let source = r#"
            globalThis.result = undefined;
            const a = new BroadcastChannel("chan"), b = new BroadcastChannel("chan");
            const c = new BroadcastChannel("other"), d = new BroadcastChannel("chan");
            const log = [];
            const fails = [];
            const check = (condition, message) => { if (!condition) fails.push(message); };
            check(Reflect.ownKeys(a).length === 0 && a.name === "chan" && String(a) === "[object BroadcastChannel]", "slots");
            try { new BroadcastChannel(); fails.push("no name"); } catch (e) { check(e instanceof TypeError, "name required"); }
            a.onmessage = () => log.push("self");
            b.onmessage = e => log.push(["b", e.data.value, e.data.map.get(1), e.isTrusted, e instanceof MessageEvent,
                e.origin, e.source === null, e.ports.length, Object.isFrozen(e.ports)].join(":"));
            c.onmessage = () => log.push("other");
            d.addEventListener("message", e => log.push("d:" + e.data.value));
            const payload = {value: 1, map: new Map([[1, "one"]])};
            a.postMessage(payload);
            payload.value = 2;
            d.close();
            try { a.postMessage(() => {}); fails.push("function cloned"); } catch (e) { check(e.name === "DataCloneError", "DataCloneError " + e.name); }
            a.close();
            try { a.postMessage(1); fails.push("closed post"); } catch (e) { check(e.name === "InvalidStateError", "closed " + e.name); }
            const event = new MessageEvent("message", {data: 5, origin: "x", lastEventId: "7"});
            check(event.data === 5 && event.origin === "x" && event.lastEventId === "7" && event.source === null
                && event.ports.length === 0 && Reflect.ownKeys(event).every(key => !["data", "origin", "ports"].includes(key)), "MessageEvent init");
            try { new MessageEvent("message", {source: {}}); fails.push("bad source"); } catch (e) { check(e instanceof TypeError, "source brand"); }
            globalThis.finish = () => {
                check(log.join("|") === "b:1:one:true:true:" + (self.origin || location.origin) + ":true:0:true", "delivery " + log.join("|"));
                globalThis.result = fails.length ? fails.join(" | ") : "ok";
            };
        "#;
        for worker in [false, true] {
            let mut engine = if worker {
                worker_platform_engine()
            } else {
                platform_engine()
            };
            eval(&mut engine, source, "broadcast channel").unwrap();
            let control = if worker { "__wkr" } else { "__trust" };
            for _ in 0..100 {
                run_microtask_checkpoint(&mut engine);
                let port = if worker {
                    "__wkr.hasPortTask()"
                } else {
                    "__trust.hasMessageTask()"
                };
                if string_value(&mut engine, &format!("String({port})")) == "true" {
                    let run = if worker {
                        "__wkr.runPortTask()"
                    } else {
                        "__trust.runMessageTask()"
                    };
                    eval(&mut engine, run, "port task").unwrap();
                    continue;
                }
                if string_value(&mut engine, &format!("String({control}.hasPlatformTask())"))
                    == "true"
                {
                    eval(
                        &mut engine,
                        &format!("{control}.runPlatformTask()"),
                        "platform task",
                    )
                    .unwrap();
                    continue;
                }
                break;
            }
            eval(&mut engine, "finish()", "finish").unwrap();
            assert_eq!(
                string_value(&mut engine, "String(result)"),
                "ok",
                "worker={worker}"
            );
        }
    }

    #[test]
    fn exceptions_are_reported_as_error_events_at_the_global() {
        // HTML #report-an-exception, #dom-reporterror and the event handler
        // processing algorithm's OnErrorEventHandler branch; #the-errorevent-interface
        // and WebSockets #the-closeevent-interface (local whatwg/html@e5071a2).
        platform_fixture_in_window_and_worker(
            "report an exception",
            r#"
            const seen = [], handlerArguments = [];
            self.onerror = function (message, source, lineno, colno, error) {
                handlerArguments.push([typeof message, typeof source, typeof lineno, typeof colno, String(error && error.message)].join(","));
                return !!error && error.message === "handled";
            };
            const listener = e => seen.push([e instanceof ErrorEvent, e.message, e.error && e.error.message,
                e.cancelable, e.isTrusted, e.defaultPrevented].join(":"));
            addEventListener("error", listener);
            reportError(new Error("handled"));
            reportError("plain");
            throws(() => reportError(), "TypeError", "reportError arity");
            const target = new EventTarget();
            let later = false;
            target.addEventListener("x", () => { throw new TypeError("listener"); });
            target.addEventListener("x", () => { later = true; });
            target.dispatchEvent(new Event("x"));
            check(later, "later listeners still run");
            queueMicrotask(() => { throw new RangeError("microtask"); });
            await Promise.resolve();
            setTimeout(() => { throw new SyntaxError("timer"); }, 0);
            await new Promise(resolve => setTimeout(resolve, 1));
            removeEventListener("error", listener);
            self.onerror = null;
            check(seen.join("|") === [
                "true:Uncaught Error: handled:handled:true:true:true",
                "true:Uncaught plain::true:true:false",
                "true:Uncaught TypeError: listener:listener:true:true:false",
                "true:Uncaught RangeError: microtask:microtask:true:true:false",
                "true:Uncaught SyntaxError: timer:timer:true:true:false"].join("|"), "reports " + seen.join("|"));
            check(handlerArguments.length === 5 && handlerArguments[0] === "string,string,number,number,handled", "onerror arguments " + handlerArguments.join("|"));

            const error = new ErrorEvent("error", {message: "m", filename: "\uD800f", lineno: 2 ** 32 + 3, colno: -1, error: 0});
            check(error.message === "m" && error.filename === "\uFFFDf" && error.lineno === 3 && error.colno === 4294967295
                && error.error === 0 && new ErrorEvent("e").error === undefined && Reflect.ownKeys(error).every(key => key !== "message"), "ErrorEvent");
            throws(() => ErrorEvent("e"), "TypeError", "ErrorEvent needs new");
            const close = new CloseEvent("close", {code: 65537, reason: "\uD800", wasClean: 1});
            check(close.code === 1 && close.reason === "\uFFFD" && close.wasClean === true && new CloseEvent("c").code === 0, "CloseEvent");
            check(Object.getOwnPropertyDescriptor(MessageEvent.prototype, "data").get && MessageEvent.length === 1, "MessageEvent attributes");
            "#,
        );
    }

    #[test]
    fn web_crypto_hmac_vectors_key_permissions_and_native_digests() {
        // Web Crypto #hmac-operations, RFC 4231 §4.2. A wrong MAC must fail,
        // metadata cannot grant new usages, and key input/export bytes copy.
        let mut engine = platform_engine();
        eval(&mut engine,r#"
        globalThis.cryptoResult='pending';
        (async()=>{
            const hex=b=>Array.from(new Uint8Array(b),x=>x.toString(16).padStart(2,'0')).join('');
            const results=[];
            for(const hash of ['SHA-256','SHA-384','SHA-512']) {
                const source=new Uint8Array(22).fill(11);
                const key=await crypto.subtle.importKey('raw',source.subarray(1,21),{name:'hmac',hash},true,['verify','sign','sign']);
                source.fill(0);
                const data=new TextEncoder().encode('Hi There');
                const signed=await crypto.subtle.sign('HMAC',key,data);
                results.push(hex(signed));
                results.push(await crypto.subtle.verify('HMAC',key,signed,data));
                new Uint8Array(signed)[0]^=1;
                results.push(await crypto.subtle.verify('HMAC',key,signed,data));
                const jwk=await crypto.subtle.exportKey('jwk',key);
                const copy=await crypto.subtle.importKey('jwk',jwk,{name:'HMAC',hash},true,['sign']);
                results.push(hex(await crypto.subtle.sign('HMAC',copy,data))===results[results.length-3]);
                const raw=await crypto.subtle.exportKey('raw',key);new Uint8Array(raw).fill(0);
                results.push(new Uint8Array(await crypto.subtle.exportKey('raw',key))[0]===11);
                copy.algorithm.name='AES-CTR';copy.algorithm.hash.name='SHA-1';
                results.push((await crypto.subtle.sign('HMAC',copy,data)).byteLength===signed.byteLength);
                try{await crypto.subtle.verify('HMAC',copy,signed,data);results.push('bad permission')}catch(e){results.push(e.name)}
            }
            for(const hash of ['SHA-1','SHA-256','SHA-384','SHA-512']) {
                const bytes=new TextEncoder().encode('!abc?');
                results.push(hex(await crypto.subtle.digest(hash,new DataView(bytes.buffer,1,3))));
            }
            const generated=await crypto.subtle.generateKey({name:'HMAC',hash:{name:'SHA-512'}},true,['sign','verify']);
            const jwk=await crypto.subtle.exportKey('jwk',generated);
            results.push([generated.type,generated.algorithm.length,jwk.alg,jwk.kty,jwk.ext,jwk.key_ops.join(',')].join(':'));
            const protectedKey=await crypto.subtle.generateKey({name:'HMAC',hash:'SHA-256'},false,['sign']);
            try{await crypto.subtle.exportKey('raw',protectedKey);results.push('bad export')}catch(e){results.push(e.name)}
            for(const fn of [()=>crypto.subtle.generateKey({name:'HMAC',hash:'SHA-256'},true,[]),
                ()=>crypto.subtle.generateKey({name:'HMAC',hash:'SHA-256',length:0},true,['sign']),
                ()=>crypto.subtle.importKey('jwk',{...jwk,alg:'HS256'},{name:'HMAC',hash:'SHA-512'},true,['sign']),
                ()=>crypto.subtle.digest('SHA-512',{})]) {
                try{await fn();results.push('bad validation')}catch(e){results.push(e.name)}
            }
            cryptoResult=JSON.stringify(results);
        })().catch(e=>cryptoResult='ERROR:'+e.stack);
        "#,"HMAC and native digests").unwrap();
        drain_platform_tasks(&mut engine, "__trust");
        let actual = string_value(&mut engine, "cryptoResult");
        let got: Vec<serde_json::Value> =
            serde_json::from_str(&actual).unwrap_or_else(|e| panic!("{e}: {actual}"));
        for (index,expected) in [
            "b0344c61d8db38535ca8afceaf0bf12b881dc200c9833da726e9376c2e32cff7",
            "afd03944d84895626b0825f4ab46907f15f9dadbe4101ec682aa034c7cebc59cfaea9ea9076ede7f4af152e8b2fa9cb6",
            "87aa7cdea5ef619d4ff0b4241a1d6cb02379f4e2ce4ec2787ad0b30545e17cdedaa833b7d6b8a702038b274eaea3f4e4be9d914eeb61f1702e696c203a126854"
        ].into_iter().enumerate() {
            assert_eq!(got[index*7],expected);
            assert_eq!(serde_json::Value::from(got[index*7+1..index*7+7].to_vec()),serde_json::json!([true,false,true,true,true,"InvalidAccessError"]));
        }
        for (index,expected) in [
            "a9993e364706816aba3e25717850c26c9cd0d89d",
            "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad",
            "cb00753f45a35e8bb5a03d699ac65007272c32ab0eded1631a8b605a43ff5bed8086072ba1e7cc2358baeca134c825a7",
            "ddaf35a193617abacc417349ae20413112e6fa4e89a97ea20a9eeee64b55d39a2192992a274fc1a836ba3c23a3feebbd454d4423643ce80e2a9ac94fa54ca49f"
        ].into_iter().enumerate(){assert_eq!(got[21+index],expected);}
        assert_eq!(
            serde_json::Value::from(got[25..].to_vec()),
            serde_json::json!([
                "secret:1024:HS512:oct:true:sign,verify",
                "InvalidAccessError",
                "SyntaxError",
                "OperationError",
                "DataError",
                "TypeError"
            ])
        );
    }

    #[test]
    fn web_crypto_random_views_use_os_entropy_and_preserve_bounds() {
        let mut engine = platform_engine();
        eval(&mut engine,r#"
            Math.random=()=>{throw Error('insecure random path')};
            const bytes=new Uint8Array(40).fill(123),view=new Uint16Array(bytes.buffer,4,16);
            const same=crypto.getRandomValues(view)===view;
            const bounds=bytes.slice(0,4).every(x=>x===123)&&bytes.slice(36).every(x=>x===123);
            const changed=bytes.slice(4,36).some(x=>x!==123);
            const errors=[];
            for(const value of [new Float32Array(4),new DataView(new ArrayBuffer(8)),[],new Uint8Array(65537)]) {
                try{crypto.getRandomValues(value);errors.push('missing error')}catch(e){errors.push(e.name)}
            }
            const wide=new BigUint64Array(3);crypto.getRandomValues(wide);
            const uuid=crypto.randomUUID();
            globalThis.randomResult=[same,bounds,changed,wide.some(x=>x!==0n),
                /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(uuid),...errors].join('|');
        "#,"secure random views").unwrap();
        assert_eq!(
            string_value(&mut engine, "randomResult"),
            // An Array is not an ArrayBufferView: Web IDL conversion throws a TypeError.
            "true|true|true|true|true|TypeMismatchError|TypeMismatchError|TypeError|QuotaExceededError"
        );
    }

    #[test]
    fn web_crypto_aes_gcm_vectors_views_and_key_lifecycle() {
        // Web Crypto #aes-gcm-operations and #algorithm-normalization:
        // BufferSources copy their selected bytes before returning, key
        // metadata cannot change private permissions, and results are buffers.
        let mut engine = platform_engine();
        let vectors = include_str!("../tests/fixtures/webcrypto/aes-gcm-nist.json");
        let source = format!("const fixture = {vectors};\n")
            + r#"
        globalThis.gcmResult = 'pending';
        (async () => {
            const assert = (ok, label) => { if (!ok) throw Error(label); };
            const hex = b => Array.from(new Uint8Array(b), x => x.toString(16).padStart(2, '0')).join('');
            const fromHex = s => Uint8Array.from(s.match(/../g) || [], p => parseInt(p, 16));
            const padded = s => fromHex('aa' + s + 'bb');
            for (const vector of fixture.vectors) {
                const keyData = padded(vector.key);
                const pendingKey = crypto.subtle.importKey('raw', new DataView(keyData.buffer, 1, keyData.length - 2),
                    {name:'aEs-gCm'}, true, ['decrypt', 'encrypt', 'encrypt']);
                keyData.fill(0);
                const key = await pendingKey;
                assert(key instanceof CryptoKey && key.type === 'secret', 'CryptoKey');
                assert(key.algorithm.name === 'AES-GCM' && key.algorithm.length === vector.key.length * 4, 'algorithm');
                assert(key.usages.join(',') === 'encrypt,decrypt' && key.usages === key.usages, 'usages');
                assert(hex(await crypto.subtle.exportKey('raw', key)) === vector.key, 'key copy');
                const jwk = await crypto.subtle.exportKey('jwk', key);
                assert(jwk.alg === 'A' + vector.key.length * 4 + 'GCM' && jwk.ext && jwk.kty === 'oct', 'JWK');
                const imported = await crypto.subtle.importKey('jwk', jwk, 'AES-GCM', true, ['encrypt', 'decrypt']);
                assert(hex(await crypto.subtle.exportKey('raw', imported)) === vector.key, 'JWK roundtrip');
                key.algorithm.name = 'AES-CTR'; key.algorithm.length = 7;
                for (const tagLength of [32, 64, 96, 104, 112, 120, undefined]) {
                    const iv = padded(vector.iv), aad = padded(vector.aad), plain = padded(vector.pt);
                    const params = {name:'AES-GCM', iv:new DataView(iv.buffer, 1, iv.length - 2),
                        additionalData:aad.subarray(1, aad.length - 1), tagLength};
                    const pending = crypto.subtle.encrypt(params, key, plain.subarray(1, plain.length - 1));
                    iv.fill(0); aad.fill(0); plain.fill(0); params.tagLength = 8;
                    const result = await pending;
                    assert(result instanceof ArrayBuffer, 'ArrayBuffer result');
                    assert(hex(result) === vector.ct + vector.tag.slice(0, (tagLength || 128) / 4), 'known answer');
                    const decrypted = await crypto.subtle.decrypt({name:'AES-GCM', iv:fromHex(vector.iv),
                        additionalData:fromHex(vector.aad), tagLength}, imported, result);
                    assert(hex(decrypted) === vector.pt, 'decrypt');
                }
            }
            for (const length of [128, 192, 256]) {
                const key = await crypto.subtle.generateKey({name:'AES-GCM', length:length + .9}, true, ['encrypt', 'decrypt']);
                const raw = await crypto.subtle.exportKey('raw', key);
                assert(raw.byteLength === length / 8 && new Uint8Array(raw).some(x => x !== 0), 'generated key');
                new Uint8Array(raw).fill(0);
                assert(new Uint8Array(await crypto.subtle.exportKey('raw', key)).some(x => x !== 0), 'export copy');
            }
            gcmResult = 'ok';
        })().catch(e => gcmResult = e.name + ':' + e.message);
        "#;
        eval(&mut engine, &source, "Web Crypto AES-GCM vectors and keys").unwrap();
        drain_platform_tasks(&mut engine, "__trust");
        assert_eq!(string_value(&mut engine, "gcmResult"), "ok");
    }

    #[test]
    fn web_crypto_aes_gcm_rejects_bad_parameters_and_authentication() {
        // Web Crypto #aes-gcm-operations: validation errors are rejected
        // promises with the specified types; bad authentication exposes no data.
        let mut engine = platform_engine();
        eval(&mut engine, r#"
        globalThis.gcmErrors = 'pending';
        (async () => {
            const assert = (ok, label) => { if (!ok) throw Error(label); };
            const reject = async (name, fn) => {
                const promise = fn();
                assert(promise instanceof Promise, 'must return Promise');
                try { await promise; } catch (error) {
                    assert(error.name === name, 'expected ' + name + ', got ' + error.name);
                    assert(name === 'TypeError' || error instanceof DOMException, 'DOMException');
                    return;
                }
                throw Error('expected rejection: ' + name);
            };
            const raw = new Uint8Array(32), iv = new Uint8Array(12), data = new Uint8Array([1,2,3]);
            const key = await crypto.subtle.importKey('raw', raw, 'AES-GCM', true, ['encrypt', 'decrypt']);
            const encryptionKey = await crypto.subtle.importKey('raw', raw, 'AES-GCM', false, ['encrypt']);
            const ctrKey = await crypto.subtle.importKey('raw', raw, 'AES-CTR', false, ['encrypt']);
            const params = {name:'AES-GCM', iv};
            for (const bad of [0, 8, 31, 33, 65, 127, 129, 255, null]) {
                await reject('OperationError', () => crypto.subtle.encrypt({...params, tagLength:bad}, key, data));
            }
            for (const bad of [-1, 256, NaN, Infinity, 128n, {valueOf:() => 128n}]) {
                await reject('TypeError', () => crypto.subtle.encrypt({...params, tagLength:bad}, key, data));
            }
            for (const algorithm of ['AES-GCM', {name:'AES-GCM'}, {...params, iv:null}, {...params, additionalData:null}]) {
                await reject('TypeError', () => crypto.subtle.encrypt(algorithm, key, data));
            }
            await reject('TypeError', () => crypto.subtle.encrypt(params, key, {}));
            await reject('OperationError', () => crypto.subtle.encrypt({...params, iv:new Uint8Array(0)}, key, data));
            await reject('InvalidAccessError', () => crypto.subtle.encrypt(params, ctrKey, data));
            await reject('InvalidAccessError', () => crypto.subtle.decrypt(params, encryptionKey, data));
            await reject('InvalidAccessError', () => crypto.subtle.exportKey('raw', encryptionKey));
            await reject('InvalidAccessError', () => crypto.subtle.exportKey('jwk', encryptionKey));
            for (const tagLength of [32, 64, 96, 104, 112, 120, 128]) {
                const algorithm = {...params, additionalData:data, tagLength};
                const encrypted = new Uint8Array(await crypto.subtle.encrypt(algorithm, key, data));
                const changedIv = iv.slice(); changedIv[0] = 1;
                await reject('OperationError', () => crypto.subtle.decrypt({...algorithm, iv:changedIv}, key, encrypted));
                await reject('OperationError', () => crypto.subtle.decrypt({...algorithm, additionalData:new Uint8Array(0)}, key, encrypted));
                for (const index of [0, encrypted.length - 1]) {
                    const damaged = encrypted.slice(); damaged[index] ^= 1;
                    await reject('OperationError', () => crypto.subtle.decrypt(algorithm, key, damaged));
                }
                await reject('OperationError', () => crypto.subtle.decrypt(algorithm, key, encrypted.slice(0, tagLength / 8 - 1)));
            }
            for (const length of [0, 15, 17, 23, 25, 31, 33]) {
                await reject('DataError', () => crypto.subtle.importKey('raw', new Uint8Array(length), 'AES-GCM', false, ['encrypt']));
            }
            await reject('SyntaxError', () => crypto.subtle.importKey('raw', raw, 'AES-GCM', false, []));
            await reject('SyntaxError', () => crypto.subtle.importKey('raw', raw, 'AES-GCM', false, ['sign']));
            await reject('TypeError', () => crypto.subtle.importKey('raw', raw, 'AES-GCM', false, ['invalid']));
            await reject('NotSupportedError', () => crypto.subtle.importKey('spki', raw, 'AES-GCM', false, ['encrypt']));
            await reject('NotSupportedError', () => crypto.subtle.exportKey('spki', key));
            await reject('OperationError', () => crypto.subtle.generateKey({name:'AES-GCM', length:129}, false, ['encrypt']));
            await reject('TypeError', () => crypto.subtle.generateKey({name:'AES-GCM'}, false, ['encrypt']));
            await reject('TypeError', () => crypto.subtle.generateKey({name:'AES-GCM', length:65536}, false, ['encrypt']));
            await reject('SyntaxError', () => crypto.subtle.generateKey({name:'AES-GCM', length:128}, false, []));
            const jwk = await crypto.subtle.exportKey('jwk', key);
            for (const change of [{kty:'RSA'}, {k:'!'}, {k:'A'}, {k:''}, {alg:'A128GCM'}, {use:'sig'},
                {ext:false}, {key_ops:['decrypt']}, {key_ops:['encrypt','encrypt']}]) {
                await reject('DataError', () => crypto.subtle.importKey('jwk', {...jwk,...change}, 'AES-GCM', true, ['encrypt']));
            }
            await reject('TypeError', () => crypto.subtle.importKey('jwk', {...jwk,key_ops:7}, 'AES-GCM', true, ['encrypt']));
            const iterable = await crypto.subtle.importKey('jwk', {...jwk, key_ops:new Set(['encrypt'])}, 'AES-GCM', false, ['encrypt']);
            assert(iterable.usages.join(',') === 'encrypt', 'JWK iterable');
            gcmErrors = 'ok';
        })().catch(e => gcmErrors = e.name + ':' + e.message);
        "#, "Web Crypto AES-GCM rejection semantics").unwrap();
        drain_platform_tasks(&mut engine, "__trust");
        assert_eq!(string_value(&mut engine, "gcmErrors"), "ok");
    }

    #[test]
    fn web_crypto_aes_gcm_worker_boundary_and_buffer_brands() {
        let mut engine = lumen::Engine::new();
        let mut state = HostState::new(
            Rc::new(RefCell::new(Dom::new())),
            Rc::new(RealmClock::new()),
        );
        state.test_hooks.internals = true;
        engine
            .ctx()
            .op_state()
            .put_retained_memory_with_external_memory(state);
        install_lumen_worker_boundary(&mut engine);
        eval(
            &mut engine,
            "globalThis.__worker_cfg = { crossOriginIsolated: true, secureContext: true };",
            "isolation",
        )
        .unwrap();
        eval_test_bootstrap(
            &mut engine,
            crate::js::worker_prelude(),
            "AES-GCM worker prelude",
            true,
        )
        .unwrap();
        eval(&mut engine, r#"
        globalThis.workerGcm = 'pending';
        (async () => {
            const keyBytes = new Uint8Array(16), iv = new Uint8Array(12), data = new Uint8Array(0);
            for (const view of [keyBytes, iv, data]) {
                for (const property of ['buffer','byteOffset','byteLength']) {
                    Object.defineProperty(view, property, {get() { throw Error('author buffer property read'); }});
                }
            }
            const key = await crypto.subtle.importKey('raw', keyBytes, 'AES-GCM', false, ['encrypt','decrypt']);
            const encrypted = await crypto.subtle.encrypt({name:'AES-GCM', iv}, key, data);
            const hex = Array.from(new Uint8Array(encrypted), x => x.toString(16).padStart(2,'0')).join('');
            const decrypted = await crypto.subtle.decrypt({name:'AES-GCM', iv}, key, encrypted);
            const shared = new Uint8Array(new SharedArrayBuffer(12));
            let errors = [];
            for (const fn of [() => crypto.subtle.encrypt({name:'AES-GCM', iv:shared}, key, data),
                () => crypto.subtle.encrypt({name:'AES-GCM', iv}, key, shared)]) {
                try { await fn(); errors.push('missing'); } catch (e) { errors.push(e.name); }
            }
            const detached = new ArrayBuffer(16); detached.transfer();
            try { await crypto.subtle.importKey('raw', detached, 'AES-GCM', false, ['encrypt']); }
            catch (e) { errors.push(e.name); }
            workerGcm = hex + '|' + decrypted.byteLength + '|' + errors.join(',');
        })().catch(e => workerGcm = e.name + ':' + e.message);
        "#, "AES-GCM worker and BufferSource conversions").unwrap();
        drain_platform_tasks(&mut engine, "__wkr");
        assert_eq!(
            string_value(&mut engine, "workerGcm"),
            "58e2fccefa7e3061367f1d57a4e7455a|0|TypeError,TypeError,DataError"
        );
    }

    #[test]
    fn web_crypto_aes_gcm_normalizes_before_key_checks_and_copies_after_getters() {
        let mut engine = platform_engine();
        eval(&mut engine, r#"
        globalThis.gcmOrder = 'pending';
        (async () => {
            const events = [], iv = new Uint8Array(12), aad = new Uint8Array([1]);
            const key = await crypto.subtle.importKey('raw', new Uint8Array(16), 'AES-GCM', false, ['encrypt']);
            const algorithm = {
                get name() { events.push('name'); return 'AES-GCM'; },
                get additionalData() { events.push('aad'); return aad; },
                get iv() { events.push('iv'); return iv; },
                get tagLength() { events.push('tag'); iv[0] = 1; aad[0] = 2; return 128.9; }
            };
            const result = await crypto.subtle.encrypt(algorithm, key, new Uint8Array(0));
            const expected = await crypto.subtle.encrypt({name:'AES-GCM', iv, additionalData:aad}, key, new Uint8Array(0));
            const same = Array.from(new Uint8Array(result)).join(',') === Array.from(new Uint8Array(expected)).join(',');
            let error;
            try { await crypto.subtle.encrypt({name:'AES-GCM', iv, tagLength:256}, {}, new Uint8Array(0)); }
            catch (e) { error = e.name; }
            gcmOrder = events.join(',') + '|' + same + '|' + error;
        })().catch(e => gcmOrder = e.name + ':' + e.message);
        "#, "AES-GCM normalization ordering").unwrap();
        drain_platform_tasks(&mut engine, "__trust");
        assert_eq!(
            string_value(&mut engine, "gcmOrder"),
            "name,name,aad,iv,tag|true|TypeError"
        );
    }

    #[test]
    fn web_crypto_aes_ctr_import_and_decrypt_matches_standard_vector() {
        // Web Cryptography Level 2 §27.7: AES-CTR uses a 16-byte counter,
        // increments its rightmost counter bits as a big-endian integer, and
        // exposes raw 128/192/256-bit keys through importKey().
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r##"
            const fromHex = value => new Uint8Array(value.match(/../g).map(pair => parseInt(pair, 16)));
            const toHex = value => Array.from(new Uint8Array(value))
                .map(byte => byte.toString(16).padStart(2, "0")).join("");
            globalThis.aesCtrResult = "pending";
            crypto.subtle.importKey(
                "raw",
                fromHex("2b7e151628aed2a6abf7158809cf4f3c"),
                "AES-CTR",
                false,
                ["decrypt"]
            ).then(key => crypto.subtle.decrypt(
                { name: "AES-CTR", counter: fromHex("f0f1f2f3f4f5f6f7f8f9fafbfcfdfeff"), length: 128 },
                key,
                fromHex("874d6191b620e3261bef6864990db6ce")
            )).then(value => { aesCtrResult = toHex(value); })
              .catch(error => { aesCtrResult = "ERROR:" + error.name + ":" + error.message; });
            "##,
            "Web Crypto AES-CTR",
        )
        .unwrap();
        drain_platform_tasks(&mut engine, "__trust");

        assert_eq!(
            string_value(&mut engine, "aesCtrResult"),
            "6bc1bee22e409f96e93d7e117393172a"
        );
    }

    #[test]
    fn cache_storage_follows_query_vary_and_deleted_cache_lifetime_algorithms() {
        // Service Workers §5.4–§5.5: Cache matching excludes fragments, honors
        // queries and Vary by default, returns fresh Response objects, and a
        // deleted name does not invalidate an already-referenced Cache object.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r##"
            globalThis.cacheStorageResult = "pending";
            (async function () {
                const sameObject = caches === caches;
                const cache = await caches.open("conformance");
                const stored = new Response("hello", {
                    headers: { "content-type": "text/plain", "vary": "accept-language" }
                });
                await cache.put(new Request("https://example.com/item?q=1#original", {
                    headers: { "accept-language": "en" }
                }), stored);

                const hit = await cache.match(new Request("https://example.com/item?q=1#other", {
                    headers: { "accept-language": "en" }
                }));
                const miss = await cache.match(new Request("https://example.com/item?q=1", {
                    headers: { "accept-language": "fr" }
                }));
                const ignored = await cache.match(new Request("https://example.com/item?q=2", {
                    headers: { "accept-language": "fr" }
                }), { ignoreSearch: true, ignoreVary: true });
                const keys = await cache.keys();
                const namesBefore = await caches.keys();
                const removedName = await caches.delete("conformance");
                const retained = await cache.match(new Request("https://example.com/item?q=1", {
                    headers: { "accept-language": "en" }
                }));
                const replacement = await caches.open("conformance");
                const replacementMiss = await replacement.match("https://example.com/item?q=1");
                const firstDelete = await cache.delete("https://example.com/item?q=1", {
                    ignoreVary: true
                });
                const secondDelete = await cache.delete("https://example.com/item?q=1", {
                    ignoreVary: true
                });

                cacheStorageResult = [
                    typeof Cache, typeof CacheStorage,
                    cache instanceof Cache, sameObject,
                    await hit.text(), miss === undefined,
                    await ignored.text(), keys.length,
                    keys[0].url.endsWith("#original"),
                    namesBefore.join(","), removedName,
                    await retained.text(), replacementMiss === undefined,
                    firstDelete, secondDelete, stored.bodyUsed
                ].join("|");
            })().catch(function (error) {
                cacheStorageResult = "ERROR:" + error.name + ":" + error.message +
                    (error.stack ? "\n" + error.stack : "");
            });
            "##,
            "CacheStorage conformance",
        )
        .unwrap();
        run_microtask_checkpoint(&mut engine);

        assert_eq!(
            string_value(&mut engine, "cacheStorageResult"),
            "function|function|true|true|hello|true|hello|1|true|conformance|true|hello|true|true|false|true"
        );
    }

