    #[test]
    fn iframe_classic_scripts_share_their_global_lexical_environment() {
        // HTML §8.1.4.4 runs a classic script through ECMA-262
        // ScriptEvaluation. Each Script Record uses its Realm's [[GlobalEnv]]
        // for both environments, so a function from an earlier script can
        // resolve a top-level lexical declared by a later script. Speedometer's
        // Perf Dashboard does this when mockAPIs() reads `const RemoteAPI`
        // from its subsequently loaded bundle.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r##"
            const html = document.createElement("html");
            const body = document.createElement("body");
            document.appendChild(html); html.appendChild(body);
            const frame = document.createElement("iframe");
            frame.srcdoc = '<body><script>' +
                'function readLaterFrameLexical() {' +
                'document.body.setAttribute("data-result", LaterFrameLexical.value);' +
                '}' +
                '<\/script><script>' +
                'const LaterFrameLexical = { value: "visible" };' +
                'readLaterFrameLexical();' +
                '<\/script></body>';
            body.appendChild(frame);
            __trust.hydrateFrames();
            globalThis.frameGlobalLexicalResult =
                frame.contentDocument.body.getAttribute("data-result");
            "##,
            "iframe classic ScriptEvaluation",
        )
        .unwrap();
        assert_eq!(
            string_value(&mut engine, "String(frameGlobalLexicalResult)"),
            "visible"
        );
    }

    #[test]
    fn iframe_animation_frame_override_is_scoped_to_its_window() {
        // HTML §8.12 associates AnimationFrameProvider state with a target
        // object, and HTML §7.2 gives every browsing context its own Window
        // behind a stable WindowProxy. A child may replace its writable rAF
        // method without replacing the parent's method; later calls through
        // contentWindow must still enter the child Window.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r##"
            const html = document.createElement("html");
            const body = document.createElement("body");
            document.appendChild(html); html.appendChild(body);
            const topRequestAnimationFrame = requestAnimationFrame;
            const frame = document.createElement("iframe");
            frame.srcdoc = '<body><script>' +
                'requestAnimationFrame = function (callback) {' +
                'callback(123); return 77; };' +
                'function callChildRAF() {' +
                'return requestAnimationFrame(function (timestamp) {' +
                'document.body.setAttribute("data-timestamp", timestamp); });' +
                '}' +
                '<\/script></body>';
            body.appendChild(frame);
            __trust.hydrateFrames();
            const parentPreservedBefore = requestAnimationFrame === topRequestAnimationFrame;
            const childHandle = frame.contentWindow.callChildRAF();
            globalThis.frameAnimationOverrideResult = [
                parentPreservedBefore,
                requestAnimationFrame === topRequestAnimationFrame,
                childHandle,
                frame.contentDocument.body.getAttribute("data-timestamp")
            ].join("|");
            "##,
            "iframe AnimationFrameProvider isolation",
        )
        .unwrap();
        assert_eq!(
            string_value(&mut engine, "frameAnimationOverrideResult"),
            "true|true|77|123"
        );
    }

    #[test]
    fn iframe_documents_create_filtered_tree_walkers_and_node_iterators() {
        // DOM §4.5 and §6: every Document creates traversal objects retaining
        // the supplied root, whatToShow mask, and filter. Lit creates a
        // TreeWalker from its benchmark iframe's Document while stamping
        // template parts, so the nested-document surface is observable.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r##"
            const html = document.createElement("html");
            const body = document.createElement("body");
            document.appendChild(html); html.appendChild(body);
            const frame = document.createElement("iframe");
            frame.srcdoc = '<main><section><span>A</span><!--marker--><span>B</span></section></main>' +
                '<scr' + 'ipt>' +
                'const root = document.body;' +
                'const filter = { acceptNode(node) {' +
                'return node.localName === "span" ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP; }};' +
                'const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT, filter);' +
                'const walked = []; let node; while ((node = walker.nextNode())) walked.push(node.textContent);' +
                'const iterator = document.createNodeIterator(root, NodeFilter.SHOW_ELEMENT,' +
                'node => node.localName === "span" ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT);' +
                'const iterated = []; while ((node = iterator.nextNode())) iterated.push(node.textContent);' +
                'const previous = iterator.previousNode();' +
                'root.setAttribute("data-result", [' +
                'walker.root === root, walker.whatToShow === NodeFilter.SHOW_ELEMENT,' +
                'walker.filter === filter, walked.join(","), iterated.join(","),' +
                'previous && previous.textContent, iterator.pointerBeforeReferenceNode].join("|"));' +
                '</scr' + 'ipt>';
            body.appendChild(frame);
            __trust.hydrateFrames();
            globalThis.frameTraversalResult =
                frame.contentDocument.body.getAttribute("data-result");
            "##,
            "iframe Document traversal",
        )
        .unwrap();
        assert_eq!(
            string_value(&mut engine, "frameTraversalResult"),
            "true|true|true|A,B|A,B|B|true"
        );
    }

    #[test]
    fn document_point_queries_follow_paint_order_and_nested_document_scope() {
        // CSSOM View §5: hit-test boxes in topmost-first paint order, exclude
        // boxes that are not pointer targets, keep iframe Documents scoped to
        // their own viewport, and append the relevant root element last.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r##"
            const html = document.createElement("html");
            const head = document.createElement("head");
            const body = document.createElement("body");
            document.appendChild(html); html.appendChild(head); html.appendChild(body);
            const style = document.createElement("style");
            style.textContent = `
                html, body { margin: 0; padding: 0; }
                #under, #over, #ignored { position: absolute; left: 10px; top: 10px; width: 80px; height: 60px; }
                #under { z-index: 1; }
                #over { z-index: 2; }
                #ignored { z-index: 3; pointer-events: none; }
                iframe { position: absolute; left: 120px; top: 10px; width: 160px; height: 90px; border: 0; }
            `;
            head.appendChild(style);
            for (const id of ["under", "over", "ignored"]) {
                const node = document.createElement("div"); node.id = id; body.appendChild(node);
            }
            const frame = document.createElement("iframe");
            frame.srcdoc = '<style>html,body{margin:0;width:100%;height:100%}#child{width:100%;height:100%}</style><div id="child"></div>';
            body.appendChild(frame);
            __trust.hydrateFrames();

            const top = document.elementsFromPoint(20, 20);
            const frameRect = frame.getBoundingClientRect();
            const parentAtFrame = document.elementFromPoint(frameRect.left + 10, frameRect.top + 10);
            const childDoc = frame.contentDocument;
            const child = childDoc.elementsFromPoint(10, 10);
            let missingThrows = false, infinityThrows = false;
            try { document.elementFromPoint(1); } catch (error) { missingThrows = error instanceof TypeError; }
            try { document.elementFromPoint(Infinity, 1); } catch (error) { infinityThrows = error instanceof TypeError; }
            globalThis.pointQueryResult = [
                top[0] && top[0].id, top.some(node => node.id === "ignored"),
                top[top.length - 1] === document.documentElement,
                parentAtFrame === frame,
                child[0] && child[0].id,
                child[child.length - 1] === childDoc.documentElement,
                document.elementFromPoint(-1, 0) === null,
                document.elementsFromPoint(0, -1).length,
                missingThrows, infinityThrows
            ].join("|");
            "##,
            "CSSOM View point queries",
        )
        .unwrap();
        assert_eq!(
            string_value(&mut engine, "pointQueryResult"),
            "over|false|true|true|child|true|true|0|true|true"
        );
    }

    #[test]
    fn offset_parent_stays_within_its_document_and_follows_containing_blocks() {
        // CSSOM View §7 and CSS Positioned Layout §2.1: offsetParent walks the
        // element's own flat tree, returns null for roots/body/fixed elements
        // without a fixed containing block, and selects the nearest ancestor
        // establishing the applicable positioning containing block.  In
        // particular, an iframe Document must not cross into its owner page or
        // cycle back into its body during CodeMirror's clipping-ancestor walk.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r##"
            const html = document.createElement("html");
            const body = document.createElement("body");
            document.appendChild(html); html.appendChild(body);
            const frame = document.createElement("iframe");
            frame.srcdoc = '<style>html,body{margin:0}#positioned{position:relative;border:3px solid black}' +
                '#absolute{position:absolute;left:7px;top:9px}#fixed{position:fixed}' +
                '#hidden{display:none}</style><main id="static"><div id="positioned">' +
                '<span id="absolute">absolute</span><span id="fixed">fixed</span>' +
                '<span id="hidden">hidden</span></div></main>';
            body.appendChild(frame);
            __trust.hydrateFrames();

            const childDocument = frame.contentDocument;
            const staticNode = childDocument.getElementById("static");
            const positioned = childDocument.getElementById("positioned");
            const absolute = childDocument.getElementById("absolute");
            const fixed = childDocument.getElementById("fixed");
            const hidden = childDocument.getElementById("hidden");
            let ancestor = absolute, steps = 0;
            while (ancestor && ancestor !== childDocument.body && steps++ < 12) {
                const style = getComputedStyle(ancestor);
                ancestor = style.position === "absolute" || style.position === "fixed"
                    ? ancestor.offsetParent : ancestor.parentNode;
            }
            globalThis.offsetParentResult = [
                absolute.ownerDocument === childDocument,
                childDocument.documentElement.ownerDocument === childDocument,
                frame.ownerDocument === document,
                staticNode.offsetParent === childDocument.body,
                absolute.offsetParent === positioned,
                fixed.offsetParent === null,
                hidden.offsetParent === null,
                childDocument.body.offsetParent === null,
                childDocument.documentElement.offsetParent === null,
                ancestor === childDocument.body && steps < 12,
                Number.isInteger(absolute.offsetTop),
                Number.isInteger(absolute.offsetLeft),
                childDocument.body.offsetTop === 0,
                childDocument.body.offsetLeft === 0
            ].join("|");
            "##,
            "CSSOM View offset parent",
        )
        .unwrap();
        assert_eq!(
            string_value(&mut engine, "offsetParentResult"),
            "true|true|true|true|true|true|true|true|true|true|true|true|true|true"
        );
    }

    #[test]
    fn offset_geometry_uses_live_canonical_style_without_author_style_calls() {
        // CSSOM View §7 queries computed values directly; it never invokes the
        // replaceable Window.getComputedStyle operation. Keep synchronous style
        // and tree changes visible, including child-Document roots and slots.
        for tier in [Tier::Interp, Tier::Bytecode, Tier::Jit] {
            let mut engine = platform_engine();
            engine.set_tier(tier);
            engine.set_tier_threshold(0);
            let result = eval_value(&mut engine, r##"
                document.append(document.createElement('html'));
                document.documentElement.innerHTML = '<head><style>html,body{margin:0} ' +
                    '#parent{position:relative;border:3px solid;padding:9px}' +
                    '#child{position:absolute;left:7px;top:11px;width:20px;height:15px}' +
                    '#fixed{position:fixed;width:10px;height:10px}</style></head>' +
                    '<body><div id="parent"><div id="child"></div><div id="fixed"></div></div></body>';
                const parent = document.getElementById('parent');
                const child = document.getElementById('child');
                const fixed = document.getElementById('fixed');
                function check(value, message) { if (!value) throw Error(message); }
                window.getComputedStyle = () => { throw Error('author style operation invoked'); };
                for (let i=0; i<50; ++i) {
                    check(child.offsetParent === parent, 'positioned ancestor');
                    check(child.offsetLeft === 7 && child.offsetTop === 11, 'padding edge');
                }
                check(fixed.offsetParent === null, 'viewport fixed');
                for (const declaration of ['transform:translateX(0)', 'filter:brightness(1)',
                    'contain:layout', 'contain:paint']) {
                    parent.style.cssText = declaration;
                    check(fixed.offsetParent === parent, 'fixed containing block ' + declaration);
                    parent.style.cssText = '';
                    check(fixed.offsetParent === null, 'removed containing block');
                }
                parent.style.position = 'static';
                check(child.offsetParent === document.body, 'live inline style');
                document.styleSheets[0].insertRule('#parent{position:relative!important}', 0);
                check(child.offsetParent === parent, 'live stylesheet');
                document.documentElement.style.filter = 'brightness(1)';
                check(fixed.offsetParent === null, 'document root filter exception');
                document.documentElement.style.transform = 'translateX(0)';
                check(fixed.offsetParent === document.documentElement, 'root transform');
                document.documentElement.style.cssText = '';
                parent.remove();
                check(child.offsetParent === null && child.offsetLeft === 0, 'detached');
                document.body.append(parent);
                check(child.offsetParent === parent, 'reattached');
                const host = document.createElement('div');
                document.body.append(host);
                host.attachShadow({mode:'open'}).innerHTML = '<section style="position:relative"><slot></slot></section>';
                host.append(child);
                check(child.offsetParent === host.shadowRoot.firstChild, 'flat tree ancestor');
                const frame = document.createElement('iframe');
                frame.srcdoc = '<style>html{filter:brightness(1)}#fixed{position:fixed}</style><div id="fixed">x</div>';
                document.body.append(frame); __trust.hydrateFrames();
                check(frame.contentDocument.getElementById('fixed').offsetParent === null, 'child root filter exception');
                check(__trust.takeErrors().length === 0, 'platform errors');
                'offset-style-ok'
            "##, "canonical offset styles").unwrap();
            assert!(
                matches!(result, Value::Str(ref s) if s.as_ref() == "offset-style-ok"),
                "{tier:?}"
            );
        }
    }

    #[test]
    fn collapsed_table_offsets_use_the_used_half_borders() {
        // CSSOM View #dom-htmlelement-offsetleft measures from the offset
        // parent's padding edge, which lies inside its USED border: in the
        // collapsing border model (CSS 2.2 §17.6.2) a table's is half its
        // outer collapsed border and a cell's border box holds half of each
        // collapsed border, not the computed border-width.
        let mut engine = platform_engine();
        let result = eval_value(
            &mut engine,
            r##"
            document.append(document.createElement('html'));
            document.documentElement.innerHTML = '<head><style>html,body{margin:0}' +
                'table{border-collapse:collapse;border:6px solid}' +
                'td{border:2px solid;padding:0;width:20px;height:20px}</style></head>' +
                '<body><table id="t"><tr><td id="a"></td><td id="b"></td></tr></table></body>';
            const t = document.getElementById('t');
            const a = document.getElementById('a');
            const b = document.getElementById('b');
            const left = e => e.getBoundingClientRect().left - t.getBoundingClientRect().left;
            [t.clientLeft, t.clientTop, t.offsetWidth, t.offsetHeight,
             a.offsetParent === t, a.offsetLeft, a.offsetTop, left(a), a.clientLeft, a.offsetWidth,
             b.offsetLeft, b.offsetTop, left(b), b.clientLeft, b.offsetWidth].join()
        "##,
            "collapsed offsets",
        )
        .unwrap();
        let Value::Str(result) = result else {
            panic!("collapsed offsets did not return a string");
        };
        assert_eq!(result.as_ref(), "3,3,54,32,true,0,0,3,3,24,24,0,27,1,24");
    }

    #[test]
    fn outer_html_setter_replaces_the_element_with_parsed_markup() {
        // HTML #dom-element-outerhtml: parse in the parent's context and
        // replace this element (DOM #concept-node-replace, one childList
        // record); a parentless element is left alone and a Document parent
        // throws NoModificationAllowedError. Webring widgets replace their
        // own script with `document.currentScript.outerHTML = ...`.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r#""use strict";
            const html = document.createElement("html");
            const body = document.createElement("body");
            document.appendChild(html); html.appendChild(body);
            const box = document.createElement("div");
            body.appendChild(box);
            const a = document.createElement("span");
            box.append("x", a, "y");
            globalThis.records = [];
            new MutationObserver((list) => {
                for (const r of list) records.push([r.target === box, r.addedNodes.length,
                    r.removedNodes.length, r.removedNodes[0] === a,
                    r.previousSibling && r.previousSibling.data,
                    r.nextSibling && r.nextSibling.data].join());
            }).observe(box, { childList: true });
            a.outerHTML = '<b id=b1>1</b><i>2</i><script>globalThis.ran = true<\/script>';
            const detached = document.createElement("p");
            detached.outerHTML = "<b>ignored</b>";
            let threw = "";
            try { html.outerHTML = "<p>"; } catch (e) { threw = e.name; }
            const fragment = document.createDocumentFragment();
            const em = document.createElement("em");
            fragment.appendChild(em);
            em.outerHTML = "<u>u</u>";
            const script = document.createElement("script");
            script.textContent = "document.currentScript.outerHTML = '<div id=rep>replaced</div>'";
            body.appendChild(script);
            const replacement = document.getElementById("rep");
            globalThis.outerResult = [
                box.innerHTML,
                a.parentNode === null,
                typeof Object.getOwnPropertyDescriptor(Element.prototype, "outerHTML").set,
                detached.outerHTML,
                threw,
                typeof globalThis.ran,
                fragment.childNodes.length + ":" + fragment.firstChild.nodeName,
                !!replacement && replacement.parentNode === body && script.parentNode === null,
            ].join("|");
            "#,
            "outerHTML setter",
        )
        .unwrap();
        run_microtask_checkpoint(&mut engine);
        assert_eq!(
            string_value(&mut engine, "outerResult"),
            "x<b id=\"b1\">1</b><i>2</i><script>globalThis.ran = true</script>y|true|function|\
             <p></p>|NoModificationAllowedError|undefined|1:U|true"
        );
        assert_eq!(
            string_value(&mut engine, "records.join(';')"),
            "true,3,1,true,x,y"
        );
    }

    #[test]
    fn outer_html_setter_updates_live_ranges_in_replace_order() {
        // DOM #concept-node-replace removes the element (#concept-node-remove
        // moves boundaries inside it to its index and pulls later offsets
        // down), then inserts the parsed nodes before its next sibling
        // (#concept-node-insert pushes offsets past that index up).
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r#"
            const html = document.createElement("html");
            const body = document.createElement("body");
            document.appendChild(html); html.appendChild(body);
            body.innerHTML = '<div id=r1><i>x</i><span>a</span><i>y</i></div>' +
                '<div id=r2><span>abc</span><i>y</i></div><div id=r3><i>x</i><span>a</span></div>';
            const [r1, r2, r3] = ["r1", "r2", "r3"].map((id) => document.getElementById(id));
            const at = (node, offset) => {
                const range = document.createRange();
                range.setStart(node, offset); range.setEnd(node, offset);
                return range;
            };
            const show = (range) => (range.startContainer.id || range.startContainer.nodeName) + "," +
                range.startOffset + "-" + (range.endContainer.id || range.endContainer.nodeName) + "," +
                range.endOffset;
            const ranges = [at(r1, 1), at(r1, 2), at(r1, 3)];
            r1.children[1].outerHTML = "<b>1</b><b>2</b>";
            const text = r2.firstChild.firstChild;
            const inside = document.createRange();
            inside.setStart(text, 1); inside.setEnd(text, 2);
            const around = document.createRange();
            around.setStart(r2, 0); around.setEnd(r2, 1);
            r2.firstChild.outerHTML = "<b>1</b><b>2</b>";
            const tail = at(r3, 2);
            r3.lastChild.outerHTML = "";
            globalThis.rangeResult = [...ranges, inside, around, tail].map(show).join(" ");
            "#,
            "outerHTML ranges",
        )
        .unwrap();
        assert_eq!(
            string_value(&mut engine, "rangeResult"),
            "r1,1-r1,1 r1,1-r1,1 r1,4-r1,4 r2,0-r2,0 r2,0-r2,0 r3,1-r3,1"
        );
    }

    #[test]
    fn fragment_parsing_uses_the_context_elements_namespace() {
        // HTML #html-fragment-parsing-algorithm: the context element, not
        // just its local name, is the adjusted current node. Inside SVG the
        // markup is foreign content (with SVG's case-adjusted names), an
        // HTML integration point (foreignObject, or annotation-xml whose
        // encoding attribute is text/html) and a MathML text integration
        // point (mi) parse HTML. insertAdjacentHTML, the outerHTML setter and
        // innerHTML all parse this way.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r#"
            const html = document.createElement("html");
            const body = document.createElement("body");
            document.appendChild(html); html.appendChild(body);
            body.innerHTML = '<svg><g><circle id=c1 r=1 /></g><g><circle id=c2 r=1 /></g>' +
                '<g id=g3></g><foreignObject><span id=fs>x</span></foreignObject></svg>' +
                '<math><mi id=mi>x</mi><annotation-xml encoding="text/html"><span id=as>a</span>' +
                '</annotation-xml></math>';
            const name = (id) => {
                const element = document.getElementById(id);
                return element ? element.namespaceURI.split("/").pop() + ":" + element.localName : "missing";
            };
            document.getElementById("c1").outerHTML = "<rect id=r1></rect><linearGradient id=lg></linearGradient>";
            document.getElementById("c2").insertAdjacentHTML("afterend", "<rect id=r2></rect>");
            document.getElementById("g3").innerHTML = "<rect id=r3></rect>";
            document.getElementById("fs").outerHTML = "<p id=fp>p</p>";
            document.getElementById("mi").insertAdjacentHTML("beforeend", "<mn id=mn>1</mn>");
            document.getElementById("as").outerHTML = "<div id=ad>d</div><svg id=asv></svg>";
            globalThis.namespaceResult = ["r1", "lg", "r2", "r3", "fp", "mn", "ad", "asv"]
                .map(name).join(" ");
            "#,
            "fragment parsing context namespace",
        )
        .unwrap();
        assert_eq!(
            string_value(&mut engine, "namespaceResult"),
            "svg:rect svg:linearGradient svg:rect svg:rect xhtml:p xhtml:mn xhtml:div svg:svg"
        );
    }

    #[test]
    fn inner_html_descendants_are_queryable_synchronously_after_insertion() {
        // HTML §13.3 appends text in script-data/raw-text parents literally
        // during fragment serialization; normal text is escaped. DOM §4.2.6
        // querySelectorAll then returns the static result of scope-matching at
        // call time. Backbone/Underscore stores item markup in precisely this
        // `<script type="text/template">` shape.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r#"
            const html = document.createElement("html");
            const body = document.createElement("body");
            const list = document.createElement("ul");
            document.appendChild(html); html.appendChild(body); body.appendChild(list);
            const source = '<div class="view"><input class="toggle"><button class="destroy"></button></div>';
            const template = document.createElement("script");
            template.setAttribute("type", "text/template");
            template.textContent = source;
            body.appendChild(template);
            for (let i = 0; i < 100; i++) {
                const item = document.createElement("li");
                item.innerHTML = template.innerHTML;
                list.appendChild(item);
            }
            const normal = document.createElement("div");
            normal.textContent = "<b>&";
            const hidden = document.createElement("aside");
            hidden.hidden = true; hidden.textContent = "kept"; body.appendChild(hidden);
            const host = document.createElement("x-serialization-host");
            host.innerHTML = '<i class="light">light</i>';
            host.attachShadow({ mode: "open" }).innerHTML = '<b class="shadow">shadow</b>';
            body.appendChild(host);
            globalThis.synchronousQueryResult = [
                template.innerHTML === source,
                template.outerHTML.includes(source),
                normal.innerHTML === "&lt;b&gt;&amp;",
                hidden.outerHTML.includes("kept"),
                host.outerHTML.includes('class="light"') && !host.outerHTML.includes('class="shadow"'),
                document.querySelectorAll("li").length,
                document.querySelectorAll(".toggle").length,
                document.querySelectorAll(".destroy").length
            ].join("|");
            "#,
            "synchronous innerHTML query",
        )
        .unwrap();
        assert_eq!(
            string_value(&mut engine, "synchronousQueryResult"),
            "true|true|true|true|true|100|100|100"
        );
    }

