    #[test]
    fn text_decoder_supports_utf16_labels_boms_streaming_and_fatal_errors() {
        // Encoding §4.2/§7.2 and §14.2: UTF-16 labels, BOM precedence, and
        // replacement versus fatal handling are part of the browser API. The
        // one-byte streaming case checks that a decoder carries an incomplete
        // code unit into the next decode call.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r#"
            const leBytes = new Uint8Array([0xff, 0xfe, 0x48, 0x00, 0x3d, 0xd8, 0x00, 0xde]);
            const beBytes = new Uint8Array([0xfe, 0xff, 0x00, 0x48, 0xd8, 0x3d, 0xde, 0x00]);
            const le = new TextDecoder('utf-16', { fatal: false });
            const be = new TextDecoder('utf-16be');
            const keptBom = new TextDecoder('utf-16le', { ignoreBOM: true });
            const streamed = new TextDecoder('utf-16le');
            let fatal = false;
            try { new TextDecoder('utf-16le', { fatal: true }).decode(new Uint8Array([0x48])); }
            catch (error) { fatal = error instanceof TypeError; }
            globalThis.textDecoderResult = [
                le.encoding, le.decode(leBytes).codePointAt(1) === 0x1f600,
                be.encoding, be.decode(beBytes) === 'H😀',
                keptBom.decode(leBytes).charCodeAt(0) === 0xfeff,
                streamed.decode(new Uint8Array([0x48]), { stream: true }) === '',
                streamed.decode(new Uint8Array([0])) === 'H',
                le.decode(new Uint8Array([0x48])) === '�', fatal
            ].join('|');
            "#,
            "TextDecoder UTF-16",
        )
        .unwrap();
        assert_eq!(
            string_value(&mut engine, "textDecoderResult"),
            "utf-16le|true|utf-16be|true|true|true|true|true|true"
        );
    }

    #[test]
    fn text_encoder_encode_into_observes_utf8_boundaries_and_surrogates() {
        // Encoding §7.4: encodeInto reports UTF-16 code units read and never emits a partial
        // scalar value when the destination is too small.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r#"
            const target = new Uint8Array(5);
            const partial = new TextEncoder().encodeInto('Aé😀', target);
            const lone = new Uint8Array(3);
            const replacement = new TextEncoder().encodeInto('\ud800', lone);
            globalThis.textEncoderResult = [
                partial.read, partial.written, Array.from(target).slice(0, partial.written).join(','),
                replacement.read, replacement.written, Array.from(lone).slice(0, replacement.written).join(',')
            ].join('|');
            "#,
            "TextEncoder encodeInto",
        )
        .unwrap();
        assert_eq!(
            string_value(&mut engine, "textEncoderResult"),
            "2|3|65,195,169|1|3|239,191,189"
        );
    }

    #[test]
    fn dom_strings_keep_lone_surrogates_and_plane_16_characters() {
        // DOM §4.10/§4.9 and Web IDL §3.2.10: DOM strings are code-unit sequences, so lone
        // surrogates set from script round-trip exactly; the host keeps them as Lumen engine
        // text. Characters in U+10F800..U+10FFFF stay characters, including parsed markup.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r#"
            const u = s => Array.from({length: s.length}, (_, i) => s.charCodeAt(i).toString(16)).join(' ');
            const text = document.createTextNode('a\ud800b');
            text.appendData('\udfff');
            const comment = document.createComment('\udc00');
            const el = document.createElement('div');
            el.setAttribute('data-x', 'x\udbff');
            el.textContent = '\u{10FFFD}\ud800';
            const host = document.createElement('section');
            host.innerHTML = '<p title="\udfff">\ud83d\u{10F800}</p>';
            const split = document.createTextNode('🌠');
            split.deleteData(1, 1);
            el.style.setProperty('--v', '"\ud800\u{10FFFD}"');
            globalThis.domResult = [
                u(text.data), u(comment.data), u(el.getAttribute('data-x')), u(el.textContent),
                u(host.firstChild.getAttribute('title')), u(host.firstChild.textContent),
                u(host.innerHTML), u(split.data), u(el.style.getPropertyValue('--v')),
                u(new DOMParser().parseFromString('<b>\udbff\u{10FFFF}</b>', 'text/html').body.textContent),
            ].join('|');
            "#,
            "DOM strings",
        )
        .unwrap();
        assert_eq!(
            string_value(&mut engine, "domResult"),
            "61 d800 62 dfff|dc00|78 dbff|dbff dffd d800|dfff|d83d dbfe dc00|\
             3c 70 20 74 69 74 6c 65 3d 22 dfff 22 3e d83d dbfe dc00 3c 2f 70 3e|d83c|\
             22 d800 dbff dffd 22|dbff dbff dfff"
        );
        // Decoded markup is Rust text: its private-use characters reach script as characters.
        let html = "<!doctype html><p id=p title=\"\u{10F800}\">x\u{10FFFD}</p><pre id=o></pre>\
            <script>const u = s => Array.from({length: s.length}, (_, i) => s.charCodeAt(i).toString(16)).join(' ');\
            const p = document.getElementById('p');\
            document.getElementById('o').textContent = [u(p.textContent), u(p.title), p.textContent.length].join('|');</script>";
        let (output, outcome) = crate::js::transform(html, &crate::js::PageEnv::bare(DEFAULT_URL));
        assert!(outcome.errors.is_empty(), "{:?}", outcome.errors);
        let result = output
            .split("<pre id=\"o\">")
            .nth(1)
            .and_then(|rest| rest.split("</pre>").next())
            .unwrap_or_default();
        assert_eq!(result, "78 dbff dffd|dbfe dc00|3", "{output}");
    }

    #[test]
    fn utf8_codecs_carry_plane_16_private_use_characters() {
        // Encoding §7.4/§8.1: U+10F800..U+10FFFF are ordinary scalar values. Lumen stores lone
        // surrogates in that range, so the host boundary must encode and decode these characters
        // as themselves, while TextEncoder still replaces a lone surrogate with U+FFFD.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r#"
            const units = s => Array.from({length: s.length}, (_, i) => s.charCodeAt(i).toString(16)).join(' ');
            const bytes = s => Array.from(new TextEncoder().encode(s), b => b.toString(16)).join(' ');
            const decoded = new TextDecoder().decode(new Uint8Array([0xf4, 0x8f, 0xbf, 0xbd, 0x41, 0xf4, 0x8f, 0xa0, 0x80]));
            globalThis.plane16Result = [
                bytes('\u{10FFFD}'), bytes('\u{10F800}'), bytes('\ud800'), bytes('\udbff\udffd'),
                units(decoded), decoded === '\u{10FFFD}A\u{10F800}',
                units(new TextDecoder().decode(new TextEncoder().encode('\u{10BFF}\u{10FFFD}'))),
            ].join('|');
            "#,
            "plane-16 UTF-8 codecs",
        )
        .unwrap();
        assert_eq!(
            string_value(&mut engine, "plane16Result"),
            "f4 8f bf bd|f4 8f a0 80|ef bf bd|f4 8f bf bd|dbff dffd 41 dbfe dc00|true|d802 dfff dbff dffd"
        );
    }

    #[test]
    fn html_task_microtask_and_timer_order_is_preserved() {
        // HTML §8.1.7.3: the host performs a microtask checkpoint after the script task and after
        // each timer task. A timer queued by the first callback follows already-queued timers.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r#"
            __trust.oneShot = true;
            globalThis.order = ["script"];
            Promise.resolve().then(() => order.push("script-microtask"));
            setTimeout(() => {
                order.push("timer-1");
                Promise.resolve().then(() => order.push("timer-1-microtask"));
                setTimeout(() => order.push("nested-timer"), 0);
            }, 0);
            setTimeout(() => order.push("timer-2"), 0);
            "#,
            "ordering setup",
        )
        .unwrap();

        assert_eq!(string_value(&mut engine, "order.join(',')"), "script");
        run_microtask_checkpoint(&mut engine);
        assert_eq!(
            string_value(&mut engine, "order.join(',')"),
            "script,script-microtask"
        );

        for expected in [
            "script,script-microtask,timer-1,timer-1-microtask",
            "script,script-microtask,timer-1,timer-1-microtask,timer-2",
            "script,script-microtask,timer-1,timer-1-microtask,timer-2,nested-timer",
        ] {
            assert!(matches!(
                call_trust_method(&mut engine, "tick", &[]),
                Value::Bool(true)
            ));
            run_microtask_checkpoint(&mut engine);
            assert_eq!(string_value(&mut engine, "order.join(',')"), expected);
        }
        assert!(matches!(
            call_trust_method(&mut engine, "tick", &[]),
            Value::Bool(false)
        ));
    }

    #[test]
    fn location_same_url_navigation_is_not_a_fragment_noop() {
        // WHATWG HTML: navigate-fragid-step, navigate-convert-to-replace,
        // dom-location-hash. The target fragment must be non-null to avoid a
        // cross-document navigation; only hash's setter suppresses repeats.
        let mut engine = platform_engine();
        eval(&mut engine, r#"
            globalThis.navigationCases = [];
            function record(fn) {
                __trust.navigation = null; __trust.navigationReplace = false;
                __trust.scrollFragment = null;
                fn();
                navigationCases.push([__trust.navigation,__trust.navigationReplace,__trust.scrollFragment]);
            }
            record(()=>location.replace(location.href));
            record(()=>location.assign(location.href));
            record(()=>{location.href=location.href});
            record(()=>{location.pathname=location.pathname});
            record(()=>location.assign('#chapter'));
            record(()=>location.assign(location.href));
            record(()=>{location.hash='#chapter'});
            record(()=>{location.hash=''});
            record(()=>{location.hash=''});
            record(()=>location.assign('https://example.com/'));
            record(()=>location.assign('/different'));
        "#, "same-URL navigation").unwrap();
        assert_eq!(
            string_value(&mut engine, "JSON.stringify(navigationCases)"),
            r#"[["https://example.com/",true,null],["https://example.com/",true,null],["https://example.com/",true,null],["https://example.com/",true,null],[null,false,"chapter"],[null,false,"chapter"],[null,false,null],[null,false,""],[null,false,null],["https://example.com/",false,null],["https://example.com/different",false,null]]"#
        );
        assert_eq!(
            string_value(
                &mut engine,
                r#"JSON.stringify(['assign','replace'].map(k=>{
            try { location[k](); return 'missed'; } catch(e) { return e.name; }
        }))"#
            ),
            r#"["TypeError","TypeError"]"#
        );
        assert_eq!(
            string_value(
                &mut engine,
                r#"(()=>{try{location.assign('http://[');return 'missed'}catch(e){return e.name}})()"#
            ),
            "SyntaxError"
        );
    }

    #[test]
    fn intersection_observer_records_then_notifies_on_its_task_source() {
        // Intersection Observer §§3.2.4–3.2.6: the rendering update queues
        // entries and one IntersectionObserver task; it does not synchronously
        // invoke callbacks. `takeRecords()` drains queued entries before that
        // task, and repeated geometry updates with no threshold crossing do not
        // duplicate a record.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r#"
            globalThis.ioResult = { callbacks: 0, entries: 0 };
            const target = document.createElement('div');
            const observer = new IntersectionObserver(function (entries) {
                ioResult.callbacks++;
                ioResult.entries += entries.length;
            });
            observer.observe(target);
            ioResult.firstQueued = __trust.updateIntersections();
            ioResult.callbackWasSync = ioResult.callbacks !== 0;
            ioResult.hadTask = __trust.hasPlatformTask();
            ioResult.taken = observer.takeRecords().length;

            observer.unobserve(target);
            observer.observe(target);
            ioResult.secondQueued = __trust.updateIntersections();
            ioResult.duplicateQueued = __trust.updateIntersections();
            ioResult.ranTask = __trust.runPlatformTask();
            "#,
            "IntersectionObserver task source",
        )
        .unwrap();

        assert_eq!(
            string_value(
                &mut engine,
                "[ioResult.firstQueued, ioResult.callbackWasSync, ioResult.hadTask, ioResult.taken, ioResult.secondQueued, ioResult.duplicateQueued, ioResult.ranTask, ioResult.callbacks, ioResult.entries].join(',')"
            ),
            "1,false,true,1,1,0,true,1,1"
        );
    }

    #[test]
    fn rendering_frame_discovery_filters_nodes_without_changing_shadow_tree_order() {
        for tier in [Tier::Interp, Tier::Bytecode, Tier::Jit] {
            let mut engine = platform_engine();
            engine.set_tier(tier);
            engine.set_tier_threshold(0);
            assert_eq!(
                string_value(
                    &mut engine,
                    r#"(function(){
                    const html=document.createElement('html'), body=document.createElement('body');
                    document.appendChild(html); html.appendChild(body);
                    const host=document.createElement('div'); body.appendChild(host);
                    const shadow=host.attachShadow({mode:'closed'});
                    const first=document.createElement('iframe'), second=document.createElement('iframe');
                    const detached=document.createElement('iframe');
                    shadow.appendChild(first); body.appendChild(second);
                    for(let i=0;i<128;i++)body.appendChild(document.createElement('span'));
                    const order=[], a=first.contentWindow, b=second.contentWindow;
                    function ids(){return __dom_rendering_frames(document.__id).join();}
                    if(ids()!==[first.__id,second.__id].join())throw Error('shadow order '+ids());
                    a.requestAnimationFrame(()=>order.push('a'));
                    b.requestAnimationFrame(()=>order.push('b'));
                    __trust.runRenderingFrame(__trust.now());
                    if(order.join()!=='a,b')throw Error('callback order '+order);
                    // A non-tree edit invalidates the epoch without altering containers.
                    host.setAttribute('data-state','typing');
                    if(ids()!==[first.__id,second.__id].join())throw Error('attribute edit');
                    body.insertBefore(second,host);
                    if(ids()!==[second.__id,first.__id].join())throw Error('move order '+ids());
                    host.remove();
                    if(ids()!==String(second.__id))throw Error('retired shadow subtree '+ids());
                    if(__dom_rendering_frames(-1).length)throw Error('invalid root');
                    return __trust.takeErrors() || 'ok';
                })()"#
                ),
                "ok",
                "{tier:?}"
            );
        }
    }

    #[test]
    fn rendering_frame_snapshots_documents_and_defers_reentrant_callbacks() {
        for tier in [Tier::Interp, Tier::Bytecode, Tier::Jit] {
            let mut engine = platform_engine();
            engine.set_tier(tier);
            engine.set_tier_threshold(0);
            assert_eq!(
                string_value(
                    &mut engine,
                    r#"(function(){
                const html=document.createElement('html'), body=document.createElement('body');
                document.appendChild(html); html.appendChild(body);
                const a=document.createElement('iframe'), b=document.createElement('iframe');
                body.appendChild(a); body.appendChild(b);
                const aw=a.contentWindow, bw=b.contentWindow, order=[], times=[];
                // A move keeps b's navigable (insertBefore() would replace
                // it, HTML #the-iframe-element) while reordering the frames.
                body.moveBefore(b,a);
                aw.requestAnimationFrame(()=>order.push('retired'));
                bw.requestAnimationFrame(t=>{
                    order.push('b'); times.push(bw.performance.timeOrigin+t);
                    bw.requestAnimationFrame(()=>order.push('b2'));
                });
                requestAnimationFrame(t=>{
                    order.push('root'); times.push(performance.timeOrigin+t);
                    a.remove();
                    requestAnimationFrame(()=>order.push('root2'));
                    const c=document.createElement('iframe'); body.appendChild(c);
                    c.contentWindow.requestAnimationFrame(()=>order.push('new-child'));
                });
                __trust.runRenderingFrame(__trust.now());
                if(order.join()!=='root,b')throw Error('first frame '+order);
                if(Math.abs(times[0]-times[1])>1)throw Error('frame timestamps '+times);
                __trust.runRenderingFrame(__trust.now());
                if(order.join()!=='root,b,root2,b2,new-child')throw Error('second frame '+order);
                return __trust.takeErrors() || 'ok';
            })()"#
                ),
                "ok",
                "{tier:?}"
            );
        }
    }

    #[test]
    fn rendering_observers_include_child_realms_in_document_order() {
        // HTML #update-the-rendering visits fully active Documents in
        // shadow-including container order. IO §3.2 queues notifications;
        // ResizeObserver §3.4 broadcasts during the rendering opportunity.
        let mut engine = configured_engine(
            HostState::new(
                Rc::new(RefCell::new(Dom::parse_document(
                    "<!doctype html><html><body></body></html>",
                ))),
                Rc::new(RealmClock::new()),
            ),
            DEFAULT_URL,
        );
        eval(
            &mut engine,
            r#"
            globalThis.observerOrder = [];
            function frame(container, before) {
                const f = document.createElement('iframe');
                f.style.cssText = 'width:300px;height:200px;border:0';
                container.insertBefore(f, before || null);
                return f;
            }
            const second = frame(document.body);
            const host = document.createElement('div');
            document.body.insertBefore(host, second);
            const first = frame(host.attachShadow({mode:'closed'}));
            const a = first.contentWindow, b = second.contentWindow;
            a.eval(`const nested = document.createElement('iframe');
                nested.style.cssText='width:150px;height:100px;border:0';
                document.body.appendChild(nested); globalThis.nestedWindow=nested.contentWindow;`);
            const grandchild = a.nestedWindow;
            function observe(w, label) {
                w.observerLabel = label;
                w.eval(`globalThis.box = document.createElement('div');
                    box.style.cssText='width:120px;height:10px';
                    document.body.insertBefore(box,document.body.firstChild);
                    globalThis.ioCalls=0;
                    globalThis.io=new IntersectionObserver(entries=>{
                        ioCalls++; globalThis.visible=entries[0].isIntersecting;
                    }); io.observe(box);
                    globalThis.ro=new ResizeObserver(()=>top.observerOrder.push(observerLabel));
                    ro.observe(box);`);
            }
            observe(a,'first'); observe(grandchild,'grandchild'); observe(b,'second');
            globalThis.childRequestedRender=__trust.hasRenderingUpdate();
            globalThis.childKeepsObserver=__trust.hasResizeObserver();
            observe(window,'parent');
            globalThis.resized=__trust.updateResizes();
            globalThis.queued=__trust.updateIntersections();
            globalThis.wasSync=[ioCalls,a.ioCalls,grandchild.ioCalls,b.ioCalls].join(',');
            globalThis.again=[__trust.updateResizes(),__trust.updateIntersections(),
                __trust.hasRenderingUpdate()].join(',');
            for(let i=0;i<64&&__trust.hasPlatformTask();i++) __trust.runPlatformTask();
            globalThis.notified=[ioCalls,a.ioCalls,grandchild.ioCalls,b.ioCalls,
                a.visible,grandchild.visible,b.visible].join(',');
            // Removing an embedding node retires its Window's observers/tasks.
            b.io.unobserve(b.box); b.io.observe(b.box);
            __trust.updateIntersections();
            second.remove(); b.box.style.width='130px';
            __trust.updateResizes();
            for(let i=0;i<64&&__trust.hasPlatformTask();i++) __trust.runPlatformTask();
            globalThis.retiredCalls=b.ioCalls;
            // A parent's ResizeObserver may retire an entire later subtree
            // after the Document list was snapshotted for this phase.
            const discard=new ResizeObserver(()=>host.remove()); discard.observe(box);
            box.style.width='130px'; a.box.style.width='140px'; grandchild.box.style.width='140px';
            globalThis.retirementBroadcasts=__trust.updateResizes();
        "#,
            "nested rendering observers",
        )
        .unwrap();
        assert_eq!(
            string_value(&mut engine, "String(childRequestedRender)"),
            "true"
        );
        assert_eq!(
            string_value(&mut engine, "String(childKeepsObserver)"),
            "true"
        );
        assert_eq!(
            string_value(&mut engine, "observerOrder.join(',')"),
            "parent,first,grandchild,second,parent"
        );
        assert_eq!(
            string_value(&mut engine, "String(retirementBroadcasts)"),
            "2"
        );
        assert_eq!(
            string_value(
                &mut engine,
                "[resized,queued,wasSync,again,notified,retiredCalls].join('|')"
            ),
            "4|4|0,0,0,0|0,0,false|1,1,1,1,true,true,true|1"
        );
    }

    #[test]
    fn observer_initial_updates_request_rendering_without_timer_tasks() {
        // Resize Observer §3.4 and Intersection Observer §3.2.4 integrate with
        // HTML's update-the-rendering algorithm. Registering even a large set
        // requests one host rendering opportunity and queues no timer tasks.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r#"
            const io = new IntersectionObserver(function () {});
            const ro = new ResizeObserver(function () {});
            for (let i = 0; i < 128; i++) {
                const target = document.createElement('div');
                io.observe(target);
                ro.observe(target);
            }
            globalThis.observerQueuesBefore = __trust.taskQueueState();
            globalThis.observerRenderingBefore = __trust.hasRenderingUpdate();
            __trust.updateResizes();
            __trust.updateIntersections();
            globalThis.observerQueuesAfter = __trust.taskQueueState();
            globalThis.observerRenderingAfter = __trust.hasRenderingUpdate();
            "#,
            "observer initial update coalescing",
        )
        .unwrap();

        let before = string_value(&mut engine, "observerQueuesBefore");
        assert!(before.contains("timers=0(once=0,interval=0)"), "{before}");
        assert_eq!(
            string_value(&mut engine, "String(observerRenderingBefore)"),
            "true"
        );
        let after = string_value(&mut engine, "observerQueuesAfter");
        assert!(after.contains("timers=0(once=0,interval=0)"), "{after}");
        assert!(after.contains("intersection=1"), "{after}");
        assert_eq!(
            string_value(&mut engine, "String(observerRenderingAfter)"),
            "false"
        );
    }

    #[test]
    fn native_platform_callback_captures_keep_live_values_without_rooting_dead_cycles() {
        // ECMA-262 #sec-liveness (e28783d5) preserves an observable captured
        // value, not an otherwise unreachable cycle. Explicit host collection
        // below is an engine lifetime test, not a promise of prompt Web GC.
        // Web IDL #invoke-a-callback-function (8f182624) also requires the native
        // boundary to preserve the original receiver/argument behavior.
        let mut engine = lumen::Engine::new();
        let owner = eval_value(
            &mut engine,
            "(() => { const owner = {value: 42}; owner.operation = function(source, receiver, args) { return owner.value + receiver.extra + args[0]; }; return owner; })()",
            "native callback capture cycle",
        )
        .unwrap();
        let Value::Obj(object) = &owner else {
            panic!("fixture must produce an object");
        };
        let weak_owner = Rc::downgrade(object);
        let operation = engine
            .ctx()
            .member_get(&owner, "operation")
            .unwrap_or_else(|_| panic!("fixture operation getter must succeed"));
        let callback = host_callback_api(
            engine.ctx(),
            Value::Undefined,
            &[
                operation,
                Value::from_string(String::from("captureTest")),
                Value::Num(1.),
            ],
        )
        .unwrap_or_else(|_| panic!("native callback creation must succeed"));
        engine
            .ctx()
            .member_set(&owner, "callback", callback.clone())
            .unwrap_or_else(|_| panic!("fixture callback assignment must succeed"));
        drop(owner);
        run_microtask_checkpoint(&mut engine);
        engine.collect_garbage_at_idle();
        assert!(
            weak_owner.upgrade().is_some(),
            "live native callback lost its capture"
        );
        let receiver = eval_value(&mut engine, "({extra: 1})", "callback receiver").unwrap();
        let result = engine
            .ctx()
            .invoke(callback.clone(), receiver, &[Value::Num(7.)])
            .unwrap_or_else(|_| panic!("live callback invocation must succeed"));
        assert_eq!(result.as_num_opt(), Some(50.));
        drop(result);
        drop(callback);
        run_microtask_checkpoint(&mut engine);
        for _ in 0..3 {
            engine.collect_garbage_at_idle();
            run_microtask_checkpoint(&mut engine);
        }
        assert!(
            weak_owner.upgrade().is_none(),
            "native callback kept an unreachable capture cycle alive"
        );
    }

    #[test]
    fn iframe_native_callback_captures_release_retired_realms_but_keep_borrowed_functions() {
        // HTML #discard-a-document explicitly allows a destroyed Document to
        // remain script-accessible. ECMA-262 #sec-liveness preserves a borrowed
        // function and its Realm until its last observable reference is gone;
        // navigation must not forcibly clear the callable's captured operation.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r#"
                var captureHtml = document.createElement('html');
                var captureBody = document.createElement('body');
                document.appendChild(captureHtml); captureHtml.appendChild(captureBody);
                var captureFrame = document.createElement('iframe');
                captureFrame.srcdoc = '<body>first';
                captureBody.appendChild(captureFrame);
                __trust.hydrateFrames();
                var borrowedPost = captureFrame.contentWindow.postMessage;
                var captureMessages = [];
                addEventListener('message', e => captureMessages.push(e.data));
            "#,
            "native callback iframe lifetime setup",
        )
        .unwrap();
        let mut retired = Vec::new();
        for navigation in 0..5 {
            // Native/rendering event delivery can enter the parent's dispatcher
            // with a child Document. Even an empty listener lookup must not
            // leave that target in an immortal parent-Realm registry.
            eval(
                &mut engine,
                "EventTarget.prototype.dispatchEvent.call(captureFrame.contentDocument, new Event('retirement-probe'));",
                "parent dispatcher visits child Document",
            )
            .unwrap();
            {
                let state = engine.ctx().host_mut::<HostState>().unwrap();
                assert_eq!(state.window_realms.len(), 1);
                let Value::Obj(window) = state.window_realms.values().next().unwrap() else {
                    panic!("Window Realm must have an object global");
                };
                retired.push(Rc::downgrade(window));
            }
            eval(
                &mut engine,
                &format!(
                    r#"captureFrame.srcdoc = '<body>replacement {navigation}<script>' +
                        'class Widget {{ constructor(node) {{ this.node = node; node.widget = this; }} read() {{ return this.node; }} }}' +
                        'window.widget = new Widget(document.body);' +
                        'for (let i = 0; i < 100; i++) {{ const node = document.createElement("div"); document.body.appendChild(node); new Widget(node); }}' +
                        '<\/script>'; __trust.hydrateFrames();"#
                ),
                "native callback iframe replacement",
            )
            .unwrap();
            run_microtask_checkpoint(&mut engine);
            engine.collect_garbage_at_idle();
        }
        // Removal, unlike replacement navigation, does not pass through the
        // old frame Window's reset hook. Empty dispatch in the parent must
        // not turn the final child Document into an immortal strong Map key.
        eval(
            &mut engine,
            "EventTarget.prototype.dispatchEvent.call(captureFrame.contentDocument, new Event('retirement-probe'));",
            "parent dispatcher visits final child Document",
        )
        .unwrap();
        {
            let state = engine.ctx().host_mut::<HostState>().unwrap();
            let Value::Obj(window) = state.window_realms.values().next().unwrap() else {
                panic!("Window Realm must have an object global");
            };
            retired.push(Rc::downgrade(window));
        }
        eval(
            &mut engine,
            "captureFrame.remove(); captureFrame = null; while (__trust.hasPlatformTask()) __trust.runPlatformTask(); /parent-match/.test('parent-match');",
            "native callback iframe removal",
        )
        .unwrap();
        // Replace the engine's single deferred legacy-RegExp match, which
        // deliberately retains its constructor until another match. This
        // test isolates target/callback ownership from that bounded cache.
        for _ in 0..3 {
            run_microtask_checkpoint(&mut engine);
            engine.collect_garbage_at_idle();
        }
        assert!(
            retired[0].upgrade().is_some(),
            "borrowed function lost its Realm"
        );
        for window in &retired[1..] {
            assert!(
                window.upgrade().is_none(),
                "unreachable retired Window remained rooted"
            );
        }
        assert_eq!(
            string_value(
                &mut engine,
                "borrowedPost.call(window, 'still callable', '*'); while (__trust.hasPlatformTask()) __trust.runPlatformTask(); captureMessages.join('|')"
            ),
            "still callable"
        );
        eval(
            &mut engine,
            "borrowedPost = null",
            "release borrowed native callback",
        )
        .unwrap();
        for _ in 0..3 {
            run_microtask_checkpoint(&mut engine);
            engine.collect_garbage_at_idle();
        }
        assert!(
            retired[0].upgrade().is_none(),
            "released borrowed function rooted its Realm"
        );
        assert_eq!(string_value(&mut engine, "__trust.takeErrors()"), "");
    }

    #[test]
    fn event_listener_cycles_are_owned_by_the_target_not_the_registry() {
        let mut engine = platform_engine();
        let target = eval_value(
            &mut engine,
            r#"(() => {
                const target = new EventTarget();
                target.calls = 0;
                const handler = () => { target.calls++; };
                target.addEventListener('click', handler, true);
                target.addEventListener('mouseover', handler);
                return target;
            })()"#,
            "unreachable listener target cycle",
        )
        .unwrap();
        let weak = Rc::downgrade(target.as_obj().unwrap());
        let dispatch = engine
            .ctx()
            .member_get(&target, "dispatchEvent")
            .unwrap_or_else(|_| panic!("missing dispatchEvent"));
        let event = eval_value(&mut engine, "new Event('click')", "listener cycle event").unwrap();
        engine
            .ctx()
            .invoke(dispatch, target.clone(), &[event])
            .unwrap_or_else(|_| panic!("dispatchEvent failed"));
        assert_eq!(
            engine
                .ctx()
                .member_get(&target, "calls")
                .unwrap_or_else(|_| panic!("missing calls"))
                .as_num_opt(),
            Some(1.)
        );
        drop(target);
        for _ in 0..3 {
            run_microtask_checkpoint(&mut engine);
            engine.collect_garbage_at_idle();
        }
        assert!(
            weak.upgrade().is_none(),
            "listener/discovery tables retained a dead target cycle"
        );
    }

    #[test]
    fn event_listener_finalization_preserves_live_targets_and_capture_accounting() {
        // DOM #concept-event-listener ownership and ECMA-262
        // #sec-cleanup-finalization-registry: cleanup must not retain the
        // target through its held value, discard a live listener, or subtract
        // already-removed capture listeners a second time.
        for tier in [Tier::Interp, Tier::Bytecode, Tier::Jit] {
            let mut engine = platform_engine();
            engine.set_tier(tier);
            engine.set_tier_threshold(0);
            eval(
                &mut engine,
                r#"
                    globalThis.listenerWeakTargets = [];
                    globalThis.listenerLog = [];
                    globalThis.listenerLiveTarget = document.createElement('button');
                    (() => {
                        const html = document.createElement('html');
                        const body = document.createElement('body');
                        document.appendChild(html); html.appendChild(body);
                        body.appendChild(listenerLiveTarget);
                    })();
                    document.body.addEventListener('probe', () => listenerLog.push('capture'), true);
                    listenerLiveTarget.addEventListener('probe', () => listenerLog.push('target'));
                    listenerLiveTarget.addEventListener('click', () => listenerLog.push('click'));
                    listenerLiveTarget.addEventListener('mouseover', () => listenerLog.push('hover'));
                    globalThis.listenerLiveState = __trust.listenerRegistryState().join(',');
                    // Live callbacks must not share the lexical environment
                    // containing the supposedly unreachable test targets.
                    (() => {
                        for (let i = 0; i < 32; i++) {
                            const target = new EventTarget();
                            const handler = () => target.dispatchEvent(new Event('unused'));
                            target.addEventListener('click', handler, true);
                            target.addEventListener('mouseover', handler);
                            if (i % 2) target.removeEventListener('click', handler, true);
                            listenerWeakTargets.push(new WeakRef(target));
                        }
                        // A disconnected Document is itself a DOM tree root,
                        // so it enters discovery without a remove-child hook.
                        // Its callback cycle must not be rooted by that index.
                        const doc = document.implementation.createHTMLDocument('unreachable');
                        doc.addEventListener('click', () => doc.title, true);
                        doc.addEventListener('mouseover', () => doc.title);
                        listenerWeakTargets.push(new WeakRef(doc));
                    })();
                "#,
                "listener lifetime and capture cleanup setup",
            )
            .unwrap();
            for _ in 0..3 {
                run_microtask_checkpoint(&mut engine);
                engine.collect_garbage_at_idle();
            }
            run_microtask_checkpoint(&mut engine);
            assert_eq!(
                string_value(
                    &mut engine,
                    "listenerWeakTargets.every(reference => reference.deref() === undefined)"
                ),
                "true",
                "{tier:?}: unreachable listener cycle"
            );
            assert_eq!(
                string_value(&mut engine, "__trust.listenerRegistryState().join(',')"),
                string_value(&mut engine, "listenerLiveState"),
                "{tier:?}: dead-target bookkeeping or double decrement"
            );
            assert_eq!(
                string_value(
                    &mut engine,
                    r#"
                        listenerLiveTarget.dispatchEvent(new Event('probe'));
                        listenerLiveTarget.remove();
                        listenerLiveTarget.dispatchEvent(new Event('click'));
                        listenerLiveTarget.dispatchEvent(new Event('mouseover'));
                        listenerLog.join(',')
                    "#
                ),
                "capture,target,click,hover",
                "{tier:?}: live capture path or detached listeners changed"
            );
            assert_eq!(string_value(&mut engine, "__trust.takeErrors()"), "");
        }
    }

