    #[test]
    fn native_wrapper_cache_preserves_identity_without_javascript_weak_reads() {
        // Web IDL 8f182624 #interface-to-js and DOM a2331a45 #concept-node-tree.
        // The private cache is not an author WeakRef: its reads need no
        // observable method dispatch or second kept-alive object graph.
        for tier in [Tier::Interp, Tier::Bytecode, Tier::Jit] {
            let mut engine = platform_engine();
            engine.set_tier(tier);
            engine.set_tier_threshold(0);
            let result = string_value(
                &mut engine,
                r#"(() => {
                const root=document.createElement('main');
                document.appendChild(root);
                const node=document.createElement('span'); node.id='same';
                node.expando={marker:42}; root.appendChild(node);
                const original=WeakRef.prototype.deref;
                let weakReads=0, same=true;
                WeakRef.prototype.deref=function(){weakReads++;return original.call(this)};
                try {
                    for(let i=0;i<100;++i) {
                        same = same && root.firstChild===node && document.getElementById('same')===node;
                        same = same && root.firstChild.expando.marker===42;
                    }
                } finally { WeakRef.prototype.deref=original; }
                return [same,weakReads,typeof globalThis.__dom_cached_wrapper,
                    typeof globalThis.__dom_register_wrapper].join('|');
            })()"#,
            );
            let parts: Vec<_> = result.split('|').collect();
            assert_eq!(parts[0], "true", "{tier:?}: {result}");
            assert_eq!(&parts[2..], &["undefined", "undefined"]);
            if native_wrapper_cache_enabled() {
                assert_eq!(parts[1], "0", "{tier:?}: {result}");
            } else {
                assert!(parts[1].parse::<usize>().unwrap() > 0);
            }
        }
    }

    #[test]
    fn native_wrapper_cache_retires_with_the_mixed_heap() {
        let mut engine = platform_engine();
        let result = eval_value(
            &mut engine,
            "globalThis.retireWrapper=document.createElement('p');retireWrapper.__id",
            "native wrapper retirement",
        )
        .unwrap();
        let id = result.as_num_opt().unwrap() as usize;
        if native_wrapper_cache_enabled() {
            assert!(
                engine
                    .ctx()
                    .host_mut::<HostState>()
                    .unwrap()
                    .dom_gc
                    .wrappers
                    .contains_key(&id)
            );
        }
        eval(&mut engine, "retireWrapper=null", "release native wrapper").unwrap();
        run_microtask_checkpoint(&mut engine);
        for _ in 0..3 {
            engine.collect_garbage_at_idle();
            run_microtask_checkpoint(&mut engine);
        }
        assert!(matches!(
            host_cached_dom_wrapper(engine.ctx(), Value::Undefined, &[Value::Num(id as f64)]),
            Ok(Value::Null)
        ));
        let state = engine.ctx().host_mut::<HostState>().unwrap();
        assert!(!state.dom_gc.wrappers.contains_key(&id));
        assert!(!state.dom.borrow().is_valid(id));
        for (&node, identity) in &state.dom_gc.wrappers {
            let owner = state
                .dom_gc
                .owners
                .get(identity)
                .expect("index never outlives owner");
            assert!(matches!(owner.kind, DomGcOwnerKind::Wrapper));
            assert_eq!(owner.nodes, [node]);
            assert!(state.dom.borrow().is_valid(node));
        }
    }

    #[test]
    fn native_wrapper_cache_keeps_same_agent_identity_through_adoption() {
        if !native_wrapper_cache_enabled() {
            return; // The old per-Realm JS directories are the diagnostic control.
        }
        let mut engine = platform_engine();
        let result = string_value(
            &mut engine,
            r##"(() => {
            const html=document.createElement('html'), body=document.createElement('body');
            document.appendChild(html); html.appendChild(body);
            const frame=document.createElement('iframe');
            frame.srcdoc='<body><div id=foreign></div><script>globalThis.saved=document.getElementById("foreign");saved.marker=42;<\/script>';
            body.appendChild(frame); __trust.hydrateFrames();
            const foreign=frame.contentDocument.getElementById('foreign');
            const same=foreign===frame.contentWindow.saved;
            const prototype=Object.getPrototypeOf(foreign);
            document.adoptNode(foreign); body.appendChild(foreign);
            return [same,foreign.marker,document.getElementById('foreign')===foreign,
                foreign.ownerDocument===document,Object.getPrototypeOf(foreign)===prototype].join('|');
        })()"##,
        );
        assert_eq!(result, "true|42|true|true|true");
    }

    #[test]
    fn detached_node_wrapper_cache_does_not_root_unreachable_wrappers() {
        // Web IDL wrapper identity applies while a platform object remains
        // observable. The native identity index follows the mixed-heap sweep;
        // the diagnostic control uses weak references and finalizers. Neither
        // directory adds a root for detached components. DOM churn must not
        // retain every transient wrapper for the lifetime of the page.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r#"
            globalThis.keptWrapper = document.createElement("div");
            (function () {
                for (let i = 0; i < 2048; i++) document.createElement("span");
            })();
            globalThis.detachedQueryRoot = document.createElement("div");
            detachedQueryRoot.innerHTML = "<i></i>".repeat(2048);
            (function () {
                detachedQueryRoot.querySelectorAll("i");
            })();
            globalThis.wrapperCacheBefore = __trust.nodeWrapperCacheState().join(",");
            "#,
            "detached wrapper churn",
        )
        .unwrap();
        run_microtask_checkpoint(&mut engine);

        for _ in 0..3 {
            engine.collect_garbage_at_idle();
            run_microtask_checkpoint(&mut engine);
        }
        let before = string_value(&mut engine, "wrapperCacheBefore")
            .split_once(',')
            .unwrap()
            .0
            .parse::<usize>()
            .unwrap();
        let after = string_value(&mut engine, "__trust.nodeWrapperCacheState().join(',')")
            .split_once(',')
            .unwrap()
            .0
            .parse::<usize>()
            .unwrap();

        assert!(before >= 2048, "cache did not observe the churn: {before}");
        assert!(
            after < before / 4,
            "unreachable wrappers remained rooted: before={before}, after={after}"
        );
        assert_eq!(
            string_value(
                &mut engine,
                "String(keptWrapper === keptWrapper && document === document)"
            ),
            "true"
        );
    }

    #[test]
    fn dom_gc_detached_descendants_preserve_ancestor_sibling_state_and_listeners() {
        // DOM #concept-tree-parent / #concept-tree-sibling and Web IDL
        // #interface-to-js preserve the same platform objects through any live node.
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r#"
            globalThis.peerEvents = 0;
            (() => {
                const parent = document.createElement('div');
                const sibling = document.createElement('i');
                const child = document.createElement('b');
                parent.append(sibling, child);
                parent.expando = {value: 41};
                sibling.expando = {value: 42};
                sibling.addEventListener('peer', () => {peerEvents++;});
                globalThis.keptDescendant = child;
                globalThis.oldParent = new WeakRef(parent);
                globalThis.oldSibling = new WeakRef(sibling);
            })();
        "#,
            "detached native graph",
        )
        .unwrap();
        run_microtask_checkpoint(&mut engine);
        for _ in 0..3 {
            engine.collect_garbage_at_idle();
            run_microtask_checkpoint(&mut engine);
        }
        assert_eq!(
            string_value(
                &mut engine,
                r#"
            const parent = keptDescendant.parentNode;
            const sibling = keptDescendant.previousSibling;
            sibling.dispatchEvent(new Event('peer'));
            [parent === oldParent.deref(), sibling === oldSibling.deref(),
                parent.expando.value, sibling.expando.value, peerEvents].join(':');
        "#
            ),
            "true:true:41:42:1"
        );
    }

    #[test]
    fn dom_gc_raw_allocation_and_async_task_leases_bridge_wrapper_publication() {
        let mut engine = platform_engine();
        let dom = engine.ctx().host_mut::<HostState>().unwrap().dom.clone();
        let newborn = dom.borrow_mut().create_element("span");
        engine.collect_garbage_at_idle();
        assert!(
            dom.borrow().is_valid(newborn),
            "raw new-node ID lost before publication"
        );
        HostGc::end_job(engine.ctx().host_mut::<HostState>().unwrap());
        engine.collect_garbage_at_idle();
        assert!(
            !dom.borrow().is_valid(newborn),
            "unpublished lease survived the job boundary"
        );

        let task_node = dom.borrow_mut().create_element("script");
        let lease = {
            let state = engine.ctx().host_mut::<HostState>().unwrap();
            state.dom_gc.start_resource(task_node);
            HostGc::end_job(state);
            state.dom_gc.resource_lease(task_node)
        };
        engine.collect_garbage_at_idle();
        assert!(
            dom.borrow().is_valid(task_node),
            "selected task lost its raw-ID target"
        );
        drop(lease);
        engine.collect_garbage_at_idle();
        assert!(
            !dom.borrow().is_valid(task_node),
            "completed task leaked its target"
        );
    }

    #[test]
    fn dom_gc_constructed_sheet_keeps_its_document_but_not_dead_adopting_roots() {
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r#"(() => {
            const html=document.createElement('html'), body=document.createElement('body');
            document.append(html); html.append(body);
            const frame=document.createElement('iframe'); body.append(frame);
            const initial=frame.contentDocument;
            globalThis.constructorDocumentWeak=new WeakRef(initial);
            globalThis.survivingSheet=new frame.contentWindow.CSSStyleSheet();
            survivingSheet.replaceSync(':host {color: red}');
            const host=initial.createElement('section'), root=host.attachShadow({mode:'open'});
            root.adoptedStyleSheets=[survivingSheet];
            globalThis.adoptingRootWeak=new WeakRef(root);
            frame.srcdoc='<body>replacement</body>'; __trust.hydrateFrames();
        })()"#,
            "constructed sheet lifetime",
        )
        .unwrap();
        run_microtask_checkpoint(&mut engine);
        for _ in 0..3 {
            engine.collect_garbage_at_idle();
            run_microtask_checkpoint(&mut engine);
        }
        assert_eq!(
            string_value(
                &mut engine,
                "[constructorDocumentWeak.deref()!==undefined,adoptingRootWeak.deref()===undefined].join(':')"
            ),
            "true:true"
        );
        eval(
            &mut engine,
            "survivingSheet=null",
            "release constructed sheet",
        )
        .unwrap();
        run_microtask_checkpoint(&mut engine);
        for _ in 0..3 {
            engine.collect_garbage_at_idle();
            run_microtask_checkpoint(&mut engine);
        }
        assert_eq!(
            string_value(
                &mut engine,
                "String(constructorDocumentWeak.deref()===undefined)"
            ),
            "true"
        );
    }

    /// HTML §7.5.1 reuses the initial about:blank Window for the first same-origin navigation
    /// but installs a new Document. A missing-global lookup in that Window first consults the
    /// named properties object (Web IDL #named-properties-object), whose supported-name cache
    /// records the Document it indexed; that cache must not keep the replaced Document alive.
    #[test]
    fn dom_gc_window_named_properties_release_a_replaced_initial_document() {
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r#"(() => {
            const html=document.createElement('html'), body=document.createElement('body');
            document.append(html); html.append(body);
            const frame=document.createElement('iframe'); body.append(frame);
            globalThis.initialDocumentWeak=new WeakRef(frame.contentDocument);
            globalThis.initialWindow=frame.contentWindow;
            // An unresolvable name reaches WindowProperties in the initial Window.
            globalThis.missingName=frame.contentWindow.eval('typeof NoSuchGlobalForNamedAccess');
            frame.srcdoc='<body>replacement</body>'; __trust.hydrateFrames();
            globalThis.reusedWindow=frame.contentWindow===initialWindow;
        })()"#,
            "named properties across Window reuse",
        )
        .unwrap();
        run_microtask_checkpoint(&mut engine);
        for _ in 0..3 {
            engine.collect_garbage_at_idle();
            run_microtask_checkpoint(&mut engine);
        }
        assert_eq!(
            string_value(
                &mut engine,
                "[missingName,reusedWindow,initialDocumentWeak.deref()===undefined].join(':')"
            ),
            "undefined:true:true"
        );
    }

    #[test]
    fn dom_gc_nursery_late_wrappers_for_old_nodes_and_young_detached_peers() {
        let mut engine = platform_engine();
        let dom = engine.ctx().host_mut::<HostState>().unwrap().dom.clone();
        let old = {
            let mut dom = dom.borrow_mut();
            let id = dom.create_element("div");
            dom.set_attr(id, "id", "native-old");
            dom.append(crate::dom::DOCUMENT, id);
            id
        };
        run_microtask_checkpoint(&mut engine);
        engine.collect_garbage_at_idle();
        assert!(!dom.borrow().is_young_gc_node(old));
        eval(
            &mut engine,
            r#"
            (() => {
                const node = document.getElementById('native-old');
                node.expando = 41;
                globalThis.lateOldWrapper = new WeakRef(node);
            })();
            (() => {
                const parent = document.createElement('section');
                const child = document.createTextNode('kept');
                const peer = document.createElement('i');
                parent.append(child,peer);
                parent.expando = 42; peer.expando = 43;
                globalThis.nurseryChild = child;
                globalThis.nurseryParent = new WeakRef(parent);
            })();
        "#,
            "native nursery links",
        )
        .unwrap();
        run_microtask_checkpoint(&mut engine);
        engine.ctx().unstable_collect_young_for_host_tests();
        assert_eq!(
            string_value(
                &mut engine,
                "[lateOldWrapper.deref().expando,nurseryChild.parentNode.expando,nurseryChild.nextSibling.expando,nurseryParent.deref()===nurseryChild.parentNode].join(':')"
            ),
            "41:42:43:true"
        );
        assert!(
            engine
                .ctx()
                .host_mut::<HostState>()
                .unwrap()
                .dom_gc
                .young_owners
                .is_empty()
        );
    }

    #[test]
    fn dom_gc_nursery_unreachable_raw_nodes_are_reclaimed_with_borrow_fallback() {
        let mut engine = platform_engine();
        let dom = engine.ctx().host_mut::<HostState>().unwrap().dom.clone();
        engine.collect_garbage_at_idle();
        let node = dom.borrow_mut().create_element("div");
        HostGc::end_job(engine.ctx().host_mut::<HostState>().unwrap());
        let first_young = dom.borrow().first_young_gc_id();
        {
            let external_reader = dom.borrow();
            engine.ctx().unstable_collect_young_for_host_tests();
            assert!(external_reader.is_valid(node));
            assert_eq!(
                external_reader.first_young_gc_id(),
                first_young,
                "borrow fallback must not promote or clear the native journal"
            );
        }
        engine.ctx().unstable_collect_young_for_host_tests();
        assert!(!dom.borrow().is_valid(node));
        let newborn = dom.borrow_mut().create_text("pending publication");
        engine.ctx().unstable_collect_young_for_host_tests();
        assert!(dom.borrow().is_valid(newborn));
        HostGc::end_job(engine.ctx().host_mut::<HostState>().unwrap());
        // This survivor is now old: only the next major may reclaim it.
        engine.ctx().unstable_collect_young_for_host_tests();
        assert!(dom.borrow().is_valid(newborn));
        engine.collect_garbage_at_idle();
        assert!(!dom.borrow().is_valid(newborn));
    }

    #[test]
    fn dom_gc_nursery_unchanged_host_registry_emits_no_old_dom_graph() {
        #[derive(Default)]
        struct Count {
            internal: usize,
            edges: usize,
            owners: usize,
        }
        impl HostGcVisitor for Count {
            fn supports_native(&self) -> bool {
                true
            }
            fn is_minor(&self) -> bool {
                true
            }
            fn native_old_generation(&mut self, _: &'static str, _: usize, _: usize) -> bool {
                true
            }
            fn internal(&mut self, _: &Value) {
                self.internal += 1;
            }
            fn edge(&mut self, _: &Value, _: &Value) {}
            fn root(&mut self, _: &Value) {}
            fn native_edge(&mut self, _: NativeGcId, _: NativeGcId) {
                self.edges += 1;
            }
            fn js_to_native(&mut self, _: &Value, _: NativeGcId) {
                self.owners += 1;
            }
        }
        let mut engine = platform_engine();
        eval(
            &mut engine,
            r#"
            const tree=document.createElement('main');
            (document.body||document.documentElement||document).appendChild(tree);
            for(let i=0;i<1000;++i) tree.appendChild(document.createElement('p'));
        "#,
            "old native registry",
        )
        .unwrap();
        run_microtask_checkpoint(&mut engine);
        engine.collect_garbage_at_idle();
        let state = engine.ctx().host_mut::<HostState>().unwrap();
        assert!(state.dom_gc.owners.len() >= 1000);
        assert!(state.dom_gc.young_owners.is_empty());
        let mut count = Count::default();
        state.trace_gc(&mut count);
        assert_eq!(
            (count.internal, count.edges, count.owners),
            (0, 0, 0),
            "an unchanged old native heap must not be enumerated during minor collection"
        );
    }

