    #[test]
    fn user_timing_buffers_and_private_slots_release_cleared_entries() {
        for worker_scope in [false, true] {
            let mut engine = if worker_scope {
                worker_platform_engine()
            } else {
                platform_engine()
            };
            eval(
                &mut engine,
                r#"(() => {
            const observer = new PerformanceObserver(() => {});
            observer.observe({type:'mark'});
            const mark = performance.mark('retained',{detail:{bytes:new Uint8Array(4096)}});
            globalThis.performanceObserverWeak = new WeakRef(observer);
            globalThis.performanceMarkWeak = new WeakRef(mark);
            globalThis.performanceDetailWeak = new WeakRef(mark.detail);
            globalThis.unrecordedMarkWeak = new WeakRef(new PerformanceMark('unrecorded'));
            performance.clearMarks();
        })()"#,
                "Performance entry ownership",
            )
            .unwrap();
            run_microtask_checkpoint(&mut engine);
            for _ in 0..3 {
                engine.ctx().collect_garbage_for_host();
                run_microtask_checkpoint(&mut engine);
            }
            assert_eq!(
                string_value(
                    &mut engine,
                    "unrecordedMarkWeak.deref() === undefined && performanceMarkWeak.deref() !== undefined && performanceDetailWeak.deref() !== undefined && performanceObserverWeak.deref() !== undefined"
                ),
                "true"
            );
            eval(
                &mut engine,
                "performanceObserverWeak.deref().disconnect()",
                "drop pending Performance records",
            )
            .unwrap();
            run_microtask_checkpoint(&mut engine);
            for _ in 0..3 {
                engine.ctx().collect_garbage_for_host();
                run_microtask_checkpoint(&mut engine);
            }
            assert_eq!(
                string_value(
                    &mut engine,
                    "performanceMarkWeak.deref() === undefined && performanceDetailWeak.deref() === undefined && performanceObserverWeak.deref() === undefined"
                ),
                "true"
            );
        }
    }

    #[test]
    fn performance_clock_synchronization_never_rewinds_shared_time() {
        // HR-Time #now-method / #dfn-unsafe-shared-current-time: the native
        // fetch clock and the realm clock must keep the same monotonic source.
        // A sampled timer deadline can already be stale when it reaches Rust.
        let clock = RealmClock::new();
        let sampled = crate::performance::now_ms();
        clock.set_epoch_ms(sampled - 100.0);
        assert!(
            clock.now_ms() >= sampled,
            "stale synchronization rewound time"
        );
        let advanced = sampled + 10_000.0;
        clock.set_epoch_ms(advanced);
        assert!(clock.now_ms() >= advanced, "one-shot advancement was lost");
        clock.set_epoch_ms(sampled);
        clock.set_epoch_ms(f64::NAN);
        clock.set_epoch_ms(f64::INFINITY);
        let after = clock.now_ms();
        assert!(after.is_finite() && after >= advanced);
    }

